def _new_gui_project() -> NfitProject:
    """Return the clean initial project shown by the GUI."""

    return NfitProject(data_groups=[DataGroup(name="Workspace1")])


def create_data_group(project: NfitProject, name: str | None = None) -> DataGroup:
    """Add a data group to a project and return it."""

    group = DataGroup(name=next_data_group_name(project.data_groups) if name is None else name)
    if group.name in {existing.name for existing in project.data_groups}:
        raise ValueError(f"duplicate data group name {group.name!r}")
    project.data_groups.append(group)
    return group


def available_data_types() -> list[tuple[str, str]]:
    """Return ``(type, label)`` pairs for every registered data type."""

    return [(name, definition["label"]) for name, definition in DATA_TYPE_DEFINITIONS.items()]


def data_type_label(data_type: str) -> str:
    """Return the human-readable label for a data type."""

    definition = DATA_TYPE_DEFINITIONS.get(data_type)
    return definition["label"] if definition else (data_type or "-")


def data_type_container(data_type: str) -> str:
    """Return the container kind ("mdhisto" or "point_list") for a data type."""

    definition = DATA_TYPE_DEFINITIONS.get(data_type, {})
    return str(definition.get("container", "mdhisto"))


def default_importer_for_data_type(
    data_type: str,
    path: str | Path | None = None,
) -> str | None:
    """Return the default importer name for a data type, or ``None``."""

    specs = importers_for_data_type(data_type)
    if path is not None:
        specs = [spec for spec in specs if spec.can_read(path)]
    return specs[0].name if specs else None


def import_dataset_paths(
    group: DataGroup,
    paths: list[str | Path],
    *,
    data_type: str | None = None,
    importer_name: str | None = None,
    importer_options: dict[str, dict[str, Any]] | None = None,
    into: DatasetGroup | None = None,
    progress_callback: Any | None = None,
) -> list[DatasetEntry]:
    """Add dataset entries for one or more source files.

    Point-list types are loaded eagerly with their importer; MDHisto/``.nxs``
    types stay as lazy placeholders loaded on first view. ``into`` optionally
    places the datasets inside a nested dataset group instead of the group root.
    """

    entries: list[DatasetEntry] = []
    resolved_type = data_type or DEFAULT_DATA_TYPE
    raw_sources = [Path(path) for path in paths if resolved_type == "single_crystal_inelastic" and is_raw_dgs_nexus_file(path)]
    if raw_sources:
        companions = [candidate for candidate in raw_sources[0].parent.glob("van*") if candidate.is_file()]
        normalization = companions[0] if len(companions) == 1 else None
        subgroup = raw_dgs_dataset_group(raw_sources, normalization_path=normalization, mask_path=normalization, progress_callback=progress_callback)
        subgroup.name = _unique_name(subgroup.name, {item.name for item in group.iter_subgroups()})
        (into.subgroups if into is not None else group.subgroups).append(subgroup)
        entries.extend(subgroup.datasets)
    for path in paths:
        source = Path(path)
        if source in raw_sources:
            continue
        if resolved_type == "single_crystal_inelastic" and is_mdevent_file(source):
            subgroup = import_mdevent_dataset_group(
                group, source, into=into, progress_callback=progress_callback
            )
            entries.extend(subgroup.datasets)
            continue
        options = None
        if isinstance(importer_options, dict):
            options = importer_options.get(str(source))
        entry = dataset_entry_from_path(
            source,
            data_type=data_type,
            importer_name=importer_name,
            importer_options=options,
        )
        entry.name = _unique_dataset_name(entry.name, group.dataset_names)
        group.add_dataset(entry, into=into)
        entries.append(entry)
    for entry in entries:
        if entry.data_type in {"single_crystal_inelastic", "powder_inelastic"}:
            entry.parameters.setdefault(
                SPECTRAL_CHANNEL_CONFIG_KEY, default_spectral_channel_config()
            )
    return entries


def parse_dataset_numors(text: str) -> list[int]:
    """Parse comma-separated run numbers and inclusive ``start[:step]:end`` ranges."""

    values: list[int] = []
    seen: set[int] = set()
    for raw_piece in str(text).split(","):
        piece = raw_piece.strip()
        if not piece:
            continue
        parts = [part.strip() for part in piece.split(":")]
        try:
            if len(parts) == 1:
                expanded = [int(parts[0])]
            elif len(parts) == 2:
                start, end = (int(part) for part in parts)
                step = 1 if end >= start else -1
                expanded = list(range(start, end + step, step))
            elif len(parts) == 3:
                start, step, end = (int(part) for part in parts)
                if step == 0 or (end - start) * step < 0:
                    raise ValueError
                expanded = list(range(start, end + (1 if step > 0 else -1), step))
            else:
                raise ValueError
        except ValueError as exc:
            raise ValueError(
                f"invalid run range {piece!r}; use 409981:409995, 409981:3:409995, or comma-separated values"
            ) from exc
        for value in expanded:
            if value not in seen:
                seen.add(value)
                values.append(value)
    if not values:
        raise ValueError("enter at least one run number or range")
    return values


def import_mdevent_dataset_group(
    group: DataGroup,
    path: str | Path,
    *,
    normalization_path: str | Path | None = None,
    mask_path: str | Path | None = None,
    into: DatasetGroup | None = None,
    progress_callback: Any | None = None,
) -> DatasetGroup:
    """Import a Mantid MDEvent file as lightweight run datasets sharing setup."""

    if normalization_path is None and mask_path is None:
        companions = [candidate for candidate in Path(path).parent.glob("van*") if candidate.is_file()]
        if len(companions) == 1:
            normalization_path = companions[0]
            mask_path = companions[0]
    subgroup = mdevent_dataset_group(
        path,
        normalization_path=normalization_path,
        mask_path=mask_path,
        progress_callback=progress_callback,
    )
    names = {item.name for item in group.iter_subgroups()}
    subgroup.name = _unique_name(subgroup.name, names)
    (into.subgroups if into is not None else group.subgroups).append(subgroup)
    if group.lattice_parameters is None:
        group.lattice_parameters = dict(subgroup.metadata["mdevent"]["lattice_parameters"])
    return subgroup


def delete_data_group(project: NfitProject, group: DataGroup) -> None:
    """Remove a data group from a project."""

    project.data_groups.remove(group)


def delete_dataset(group: DataGroup, dataset: DatasetEntry) -> None:
    """Remove a dataset entry from anywhere in the group tree."""

    parent = _dataset_parent_node(group, dataset)
    if parent is None:
        raise ValueError(f"dataset {dataset.name!r} is not in group {group.name!r}")
    for candidate in group.iter_datasets():
        if candidate is dataset:
            continue
        candidate.backgrounds[:] = [
            background
            for background in candidate.backgrounds
            if background.source_dataset_id != dataset.id
        ]
    for node in (group, *group.iter_subgroups()):
        node.backgrounds[:] = [
            background
            for background in node.backgrounds
            if background.source_dataset_id != dataset.id
        ]
    parent.datasets.remove(dataset)


def set_dataset_source(dataset: DatasetEntry, path: str | Path) -> None:
    """Point a dataset entry at a new source file and mark loaded data stale."""

    source = Path(path)
    dataset.metadata["source_file"] = str(source)
    dataset.metadata["import_status"] = "pending"
    dataset.kind = source.suffix.lstrip(".").lower()
    dataset.unload_data()
    if dataset.metadata.get("importer"):
        _load_registered_importer_dataset(dataset)
    elif data_type_container(dataset.data_type) == "point_list":
        _load_point_list_dataset(dataset)


def set_dataset_data_type(
    dataset: DatasetEntry,
    data_type: str,
    *,
    importer_name: str | None = None,
) -> None:
    """Change a dataset's data type and reload/reset its data accordingly."""

    if data_type not in DATA_TYPE_DEFINITIONS:
        raise ValueError(f"unknown data type {data_type!r}")
    dataset.data_type = data_type
    dataset.metadata.pop("import_error", None)
    if data_type in {"single_crystal_inelastic", "powder_inelastic"}:
        dataset.parameters.setdefault(
            SPECTRAL_CHANNEL_CONFIG_KEY, default_spectral_channel_config()
        )
    chosen = importer_name or default_importer_for_data_type(
        data_type, dataset.metadata.get("source_file")
    )
    if chosen is not None:
        dataset.metadata["importer"] = chosen
        dataset.unload_data()
        if dataset.metadata.get("source_file"):
            try:
                _load_registered_importer_dataset(dataset)
            except Exception as exc:
                dataset.unload_data()
                dataset.metadata["import_status"] = "error"
                dataset.metadata["import_error"] = str(exc)
    elif data_type_container(data_type) == "point_list":
        chosen = default_importer_for_data_type(data_type)
        if chosen is not None:
            dataset.metadata["importer"] = chosen
        dataset.unload_data()
        if dataset.metadata.get("source_file"):
            # Reload with the new type's importer, but a mismatched importer must
            # not crash the type switch; record the error for the details panel.
            try:
                _load_point_list_dataset(dataset)
            except Exception as exc:
                dataset.unload_data()
                dataset.metadata["import_status"] = "error"
                dataset.metadata["import_error"] = str(exc)
    elif chosen is None:
        dataset.metadata.pop("importer", None)
        # Fall back to the lazy MDHisto/.nxs loader on next view.
        if not isinstance(dataset.data, MDHistoData):
            dataset.unload_data()
            dataset.metadata["import_status"] = "pending"


def _load_registered_importer_dataset(
    dataset: DatasetEntry,
) -> PointListData | MDHistoData | None:
    """Load a dataset through its registered importer and apply import metadata."""

    source = dataset.metadata.get("source_file") if isinstance(dataset.metadata, dict) else None
    if not source:
        return None
    importer_name = dataset.metadata.get("importer") or default_importer_for_data_type(
        dataset.data_type, source
    )
    if importer_name is None:
        return None
    options = dataset.metadata.get("import_options")
    data = import_with(
        importer_name,
        source,
        options if isinstance(options, dict) else None,
    )
    data = dataset.replace_data(data, source_backed=True)
    dataset.metadata["importer"] = importer_name
    dataset.metadata["import_status"] = "loaded"
    imported_parameters = data.metadata.get("dataset_parameters")
    if (
        isinstance(imported_parameters, dict)
        and not bool(dataset.metadata.get("import_parameters_applied", False))
    ):
        dataset.parameters.update(copy.deepcopy(imported_parameters))
        dataset.metadata["import_parameters_applied"] = True
    if dataset.data_type in {"magnetization", "heat_capacity"}:
        keys = ["sample_mass_mg", "molar_mass_g_mol"]
        if dataset.data_type == "heat_capacity":
            keys.append("atoms_per_formula_unit")
        for key in keys:
            if key not in dataset.parameters and key in data.metadata:
                dataset.parameters[key] = float(data.metadata[key])
    if dataset.data_type == "heat_capacity" and all(
        float(dataset.parameters.get(key, 0.0) or 0.0) > 0.0
        for key in ("sample_mass_mg", "molar_mass_g_mol")
    ):
        dataset.parameters.setdefault("absolute_units", True)
    if not dataset.kind:
        dataset.kind = Path(source).suffix.lstrip(".").lower()
    return data


def _load_point_list_dataset(dataset: DatasetEntry) -> PointListData | None:
    """Load a point-list dataset from its source file using a registered importer."""

    data = _load_registered_importer_dataset(dataset)
    if data is not None and not isinstance(data, PointListData):
        raise TypeError(f"importer for {dataset.data_type!r} did not return point-list data")
    return data


def point_list_config(dataset: DatasetEntry) -> dict[str, Any]:
    """Return the point-list transform configuration, creating defaults if needed."""

    config = dataset.parameters.get(DATASET_POINT_LIST_KEY)
    if not isinstance(config, dict):
        config = {}
        dataset.parameters[DATASET_POINT_LIST_KEY] = config
    data = dataset.data if isinstance(dataset.data, PointListData) else None
    definition = DATA_TYPE_DEFINITIONS.get(dataset.data_type, {})

    if data is not None:
        config.setdefault("coordinate_names", list(data.coordinate_names))
        config.setdefault("channels", copy.deepcopy(data.channels))
    else:
        config.setdefault("coordinate_names", [])
        config.setdefault("channels", [])

    if definition.get("scale"):
        scale = config.get("scale")
        if not isinstance(scale, dict):
            scale = {}
            config["scale"] = scale
        scale.setdefault("factor", 1.0)
        scale.setdefault("units", "")
        default_channel = config["channels"][0]["label"] if config["channels"] else ""
        scale.setdefault("channel", default_channel)
    if definition.get("susceptibility"):
        susc = config.get("susceptibility")
        if not isinstance(susc, dict):
            susc = {}
            config["susceptibility"] = susc
        susc.setdefault("enabled", False)
        field_default = next(
            (name for name in config["coordinate_names"] if "field" in name.lower()),
            (config["coordinate_names"][0] if config["coordinate_names"] else ""),
        )
        susc.setdefault("field", field_default)
        moment_default = config["channels"][0]["label"] if config["channels"] else ""
        susc.setdefault("moment", moment_default)
        susc.setdefault("output_unit", "cm^3/mol")
    if definition.get("susceptibility"):
        # This is deliberately separate from the input moment unit above: the
        # MPMS column is ordinarily a sample moment in emu, while a user may
        # choose to view and fit the same measurement per formula unit.
        dataset.parameters.setdefault("magnetization_output_unit", "emu")
    if definition.get("heat_capacity"):
        hc = config.get("heat_capacity")
        if not isinstance(hc, dict):
            hc = {}
            config["heat_capacity"] = hc
        temperature_default = next(
            (name for name in config["coordinate_names"] if "temp" in name.lower()),
            (config["coordinate_names"][0] if config["coordinate_names"] else ""),
        )
        hc.setdefault("temperature", temperature_default)
        hc.setdefault("source_channel", config["channels"][0]["label"] if config["channels"] else "")
        source_channel = next(
            (item for item in config["channels"] if item.get("label") == hc["source_channel"]),
            None,
        )
        hc.setdefault(
            "source_unit",
            str(source_channel.get("unit", "uJ/K")) if source_channel is not None else "uJ/K",
        )
        hc.setdefault("fit_channel", HEAT_CAPACITY_CHANNEL_LABEL)
    if definition.get("wavelength"):
        wavelength = config.get("wavelength")
        if not isinstance(wavelength, dict):
            wavelength = {}
            config["wavelength"] = wavelength
        wavelength.setdefault("value", 0.0)
        two_theta_default = next(
            (name for name in config["coordinate_names"] if "theta" in name.lower()),
            (config["coordinate_names"][0] if config["coordinate_names"] else ""),
        )
        wavelength.setdefault("two_theta", two_theta_default)
    return config


_PREPARED_POINT_LIST_CACHE: OrderedDict[str, tuple[str, PointListData]] = OrderedDict()
_PREPARED_POINT_LIST_CACHE_LIMIT = 16
_PREPARED_POINT_LIST_CACHE_MAX_BYTES = 128 * 1024**2


def _prepared_point_list_signature(dataset: DatasetEntry) -> str:
    """Cheap identity/config signature for immutable prepared point-list views."""

    data = dataset.data
    columns = getattr(data, "columns", {})
    payload = (
        dataset.data_cache_token,
        tuple((name, id(values), np.asarray(values).shape, str(np.asarray(values).dtype)) for name, values in columns.items()),
        repr(getattr(data, "units", {})),
        repr(getattr(data, "coordinate_names", [])),
        repr(getattr(data, "channels", [])),
        repr(getattr(data, "quantity_types", {})),
        repr(dataset.parameters),
        repr(dataset.transforms),
        dataset.data_type,
    )
    return repr(payload)


def prepared_point_list_data(dataset: DatasetEntry) -> PointListData:
    """Return the point-list data after applying role overrides and transforms."""

    if not isinstance(dataset.data, PointListData):
        raise TypeError("dataset does not contain PointListData")
    cache_key = dataset.id
    signature = _prepared_point_list_signature(dataset)
    cached = _PREPARED_POINT_LIST_CACHE.get(cache_key)
    if cached is not None and cached[0] == signature:
        _PREPARED_POINT_LIST_CACHE.move_to_end(cache_key)
        return cached[1]
    config = point_list_config(dataset)
    base = dataset.data
    columns = {name: np.array(values, dtype=float) for name, values in base.columns.items()}
    units = dict(base.units)
    quantity_types = dict(base.quantity_types)

    coordinate_names = [name for name in config.get("coordinate_names", []) if name in columns]
    if not coordinate_names:
        coordinate_names = list(base.coordinate_names)
    channels = [
        dict(channel)
        for channel in config.get("channels", [])
        if channel.get("value") in columns
    ]
    if not channels:
        channels = [dict(channel) for channel in base.channels]
    for channel in channels:
        value_name = channel.get("value")
        if value_name not in columns:
            continue
        declared_unit = str(channel.get("unit", "") or "")
        declared_type = str(channel.get("quantity_type", "") or "")
        if declared_unit:
            units[value_name] = declared_unit
            error_name = channel.get("error")
            if error_name in columns:
                units[error_name] = declared_unit
        if declared_type:
            quantity_types[value_name] = declared_type
            error_name = channel.get("error")
            if error_name in columns:
                quantity_types[error_name] = declared_type

    definition = DATA_TYPE_DEFINITIONS.get(dataset.data_type, {})

    if definition.get("heat_capacity"):
        hc = config.get("heat_capacity", {})
        temperature_name = str(hc.get("temperature", ""))
        source_label = str(hc.get("source_channel", ""))
        source_channel = next((c for c in channels if c.get("label") == source_label), None)
        if temperature_name in columns and source_channel is not None:
            source_value = str(source_channel.get("value", ""))
            source_error = source_channel.get("error")
            temperature = np.asarray(columns[temperature_name], dtype=float)
            columns[TEMPERATURE_SQUARED_COLUMN] = temperature**2
            units[TEMPERATURE_SQUARED_COLUMN] = "K^2"
            quantity_types[TEMPERATURE_SQUARED_COLUMN] = "unknown"
            if TEMPERATURE_SQUARED_COLUMN not in coordinate_names:
                coordinate_names.append(TEMPERATURE_SQUARED_COLUMN)
            if bool(dataset.parameters.get("absolute_units", False)):
                from .heat_capacity import ppms_heat_capacity_to_molar_mJ

                source_unit = str(hc.get("source_unit") or units.get(source_value, ""))
                conversion = {
                    "source_unit": source_unit,
                    "sample_mass_mg": dataset.parameters.get("sample_mass_mg"),
                    "molar_mass_g_mol": dataset.parameters.get("molar_mass_g_mol"),
                    "atoms_per_formula_unit": dataset.parameters.get("atoms_per_formula_unit"),
                }
                heat_capacity = ppms_heat_capacity_to_molar_mJ(
                    np.asarray(columns[source_value], dtype=float), **conversion
                )
                heat_capacity_error = (
                    None if source_error not in columns
                    else np.abs(ppms_heat_capacity_to_molar_mJ(
                        np.asarray(columns[source_error], dtype=float), **conversion
                    ))
                )
                c_name = f"{HEAT_CAPACITY_CHANNEL_LABEL} value"
                dc_name = f"{HEAT_CAPACITY_CHANNEL_LABEL} error"
                ct_name = f"{HEAT_CAPACITY_OVER_T_CHANNEL_LABEL} value"
                dct_name = f"{HEAT_CAPACITY_OVER_T_CHANNEL_LABEL} error"
                columns[c_name] = heat_capacity
                columns[ct_name] = heat_capacity / temperature
                units[c_name] = "mJ/(mol K)"
                units[ct_name] = "mJ/(mol K^2)"
                quantity_types[c_name] = "heat_capacity"
                quantity_types[ct_name] = "heat_capacity_over_temperature"
                if heat_capacity_error is not None:
                    columns[dc_name] = heat_capacity_error
                    columns[dct_name] = heat_capacity_error / np.abs(temperature)
                    units[dc_name] = "mJ/(mol K)"
                    units[dct_name] = "mJ/(mol K^2)"
                    quantity_types[dc_name] = "heat_capacity"
                    quantity_types[dct_name] = "heat_capacity_over_temperature"
                derived = [
                    {"label": HEAT_CAPACITY_CHANNEL_LABEL, "value": c_name,
                     "error": dc_name if heat_capacity_error is not None else None,
                     "quantity_type": "heat_capacity", "unit": "mJ/(mol K)"},
                    {"label": HEAT_CAPACITY_OVER_T_CHANNEL_LABEL, "value": ct_name,
                     "error": dct_name if heat_capacity_error is not None else None,
                     "quantity_type": "heat_capacity_over_temperature", "unit": "mJ/(mol K^2)"},
                ]
                labels = {item["label"] for item in derived}
                channels = derived + [item for item in channels if item.get("label") not in labels]
                selected = str(hc.get("fit_channel", HEAT_CAPACITY_CHANNEL_LABEL))
                channels.sort(key=lambda item: item.get("label") != selected)

    # Powder wavelength -> q and d-spacing coordinates (created if absent).
    if definition.get("wavelength"):
        wavelength = config.get("wavelength", {})
        value = float(wavelength.get("value", 0.0) or 0.0)
        two_theta = wavelength.get("two_theta")
        if value > 0.0 and two_theta in columns:
            theta = np.deg2rad(columns[two_theta]) / 2.0
            sin_theta = np.sin(theta)
            if Q_COORDINATE_NAME not in columns:
                # q = 4*pi*sin(theta)/lambda, in inverse angstroms.
                columns[Q_COORDINATE_NAME] = 4.0 * np.pi * sin_theta / value
                units[Q_COORDINATE_NAME] = "Å⁻¹"
            if D_SPACING_COORDINATE_NAME not in columns:
                # d = lambda / (2*sin(theta)) = 2*pi/q, in angstroms.
                with np.errstate(divide="ignore", invalid="ignore"):
                    columns[D_SPACING_COORDINATE_NAME] = value / (2.0 * sin_theta)
                units[D_SPACING_COORDINATE_NAME] = "Å"
            # Powder data is one-dimensional: q, d and 2theta are collinear, so
            # make q the single independent coordinate (used for rebin/fits) and
            # leave d and 2theta as viewable columns.
            collinear = {Q_COORDINATE_NAME, D_SPACING_COORDINATE_NAME, str(two_theta)}
            coordinate_names = [Q_COORDINATE_NAME] + [
                name for name in coordinate_names if name not in collinear
            ]

    # Magnetization scale factor + unit relabel applied to value and error.
    if definition.get("scale"):
        scale = config.get("scale", {})
        factor = float(scale.get("factor", 1.0) or 1.0)
        target = scale.get("channel")
        new_units = str(scale.get("units", "") or "")
        if factor != 1.0 or new_units:
            for channel in channels:
                if channel.get("label") != target:
                    continue
                value_name = channel.get("value")
                error_name = channel.get("error")
                if value_name in columns:
                    columns[value_name] = columns[value_name] * factor
                    if new_units:
                        units[value_name] = new_units
                if error_name in columns:
                    columns[error_name] = columns[error_name] * abs(factor)
                    if new_units:
                        units[error_name] = new_units

    # Magnetization susceptibility: moment / field (value and error divided by field).
    if definition.get("susceptibility"):
        susc = config.get("susceptibility", {})
        field_name = str(susc.get("field", ""))
        if field_name in columns and susc.get("field_unit"):
            units[field_name] = str(susc["field_unit"])
            quantity_types[field_name] = "magnetic_field"
        moment_label = susc.get("moment")
        moment_channel = next((c for c in channels if c.get("label") == moment_label), None)
        if moment_channel is not None:
            source_value = moment_channel.get("value")
            if source_value in columns and susc.get("moment_unit"):
                units[source_value] = str(susc["moment_unit"])
                quantity_types[source_value] = "magnetic_moment"
                source_error = moment_channel.get("error")
                if source_error in columns:
                    units[source_error] = units[source_value]
                    quantity_types[source_error] = "magnetic_moment"
        if susc.get("enabled"):
            if moment_channel is not None and field_name in columns:
                moment = columns[moment_channel["value"]]
                field = columns[field_name]
                moment_error_name = moment_channel.get("error")
                moment_error = columns.get(moment_error_name) if moment_error_name else None
                moment_unit = units.get(moment_channel["value"], "")
                field_unit = units.get(field_name, "")
                absolute = bool(dataset.parameters.get("absolute_units", False))
                if absolute:
                    from .quantities import convert_quantity

                    mass_g = float(dataset.parameters.get("sample_mass_mg", 0.0) or 0.0) / 1000.0
                    molar_mass = float(dataset.parameters.get("molar_mass_g_mol", 0.0) or 0.0)
                    if mass_g <= 0.0 or molar_mass <= 0.0:
                        raise ValueError(
                            "absolute susceptibility requires positive sample mass and molar mass"
                        )
                    moles = mass_g / molar_mass
                    moment = convert_quantity(moment, "magnetic_moment", moment_unit, "emu")
                    if moment_error is not None:
                        moment_error = np.abs(
                            convert_quantity(moment_error, "magnetic_moment", moment_unit, "emu")
                        )
                    field = convert_quantity(field, "magnetic_field", field_unit, "Oe")
                    output_unit = str(susc.get("output_unit", "cm^3/mol"))
                    with np.errstate(divide="ignore", invalid="ignore"):
                        susc_value = moment / field / moles
                    if output_unit == "m^3/mol":
                        susc_value = convert_quantity(
                            susc_value, "bulk_susceptibility", "cm^3/mol", output_unit
                        )
                    elif output_unit != "cm^3/mol":
                        raise ValueError(
                            "absolute susceptibility output must be cm^3/mol or m^3/mol"
                        )
                    susc_unit = output_unit
                else:
                    with np.errstate(divide="ignore", invalid="ignore"):
                        susc_value = moment / field
                    susc_unit = f"{moment_unit}/{field_unit}" if moment_unit and field_unit else ""
                with np.errstate(divide="ignore", invalid="ignore"):
                    error_values = (
                        None if moment_error is None else moment_error / np.abs(field)
                    )
                if absolute and error_values is not None:
                    error_values = error_values / moles
                    if susc_unit == "m^3/mol":
                        error_values = convert_quantity(
                            error_values, "bulk_susceptibility", "cm^3/mol", susc_unit
                        )
                value_col = f"{SUSCEPTIBILITY_CHANNEL_LABEL} value"
                columns[value_col] = susc_value
                units[value_col] = susc_unit
                quantity_types[value_col] = "bulk_susceptibility"
                error_col = None
                if error_values is not None:
                    error_col = f"{SUSCEPTIBILITY_CHANNEL_LABEL} error"
                    columns[error_col] = error_values
                    units[error_col] = susc_unit
                    quantity_types[error_col] = "bulk_susceptibility"
                channels.append(
                    {
                        "label": SUSCEPTIBILITY_CHANNEL_LABEL,
                        "value": value_col,
                        "error": error_col,
                        "quantity_type": "bulk_susceptibility",
                        "unit": susc_unit,
                    }
                )
                inverse_unit = {
                    "cm^3/mol": "mol/cm^3",
                    "m^3/mol": "mol/m^3",
                    "emu/Oe": "Oe/emu",
                }.get(susc_unit, f"1/({susc_unit})" if susc_unit else "")
                inverse_value_col = f"{INVERSE_SUSCEPTIBILITY_CHANNEL_LABEL} value"
                inverse_values = np.full(susc_value.shape, np.nan, dtype=float)
                valid_inverse = np.isfinite(susc_value) & (susc_value != 0.0)
                inverse_values[valid_inverse] = 1.0 / susc_value[valid_inverse]
                columns[inverse_value_col] = inverse_values
                units[inverse_value_col] = inverse_unit
                quantity_types[inverse_value_col] = "inverse_bulk_susceptibility"
                inverse_error_col = None
                if error_values is not None:
                    inverse_error_col = f"{INVERSE_SUSCEPTIBILITY_CHANNEL_LABEL} error"
                    inverse_errors = np.full(error_values.shape, np.nan, dtype=float)
                    inverse_errors[valid_inverse] = (
                        np.abs(error_values[valid_inverse])
                        / susc_value[valid_inverse] ** 2
                    )
                    columns[inverse_error_col] = inverse_errors
                    units[inverse_error_col] = inverse_unit
                    quantity_types[inverse_error_col] = "inverse_bulk_susceptibility"
                channels.append(
                    {
                        "label": INVERSE_SUSCEPTIBILITY_CHANNEL_LABEL,
                        "value": inverse_value_col,
                        "error": inverse_error_col,
                        "quantity_type": "inverse_bulk_susceptibility",
                        "unit": inverse_unit,
                    }
                )

        # Convert the displayed/fitted moment after deriving susceptibility so
        # susceptibility always uses the declared *input* moment unit.
        output_unit = str(dataset.parameters.get("magnetization_output_unit", "emu"))
        absolute = bool(dataset.parameters.get("absolute_units", False))
        if moment_channel is not None and output_unit != "emu":
            value_name = str(moment_channel.get("value", ""))
            error_name = moment_channel.get("error")
            if value_name in columns:
                from .quantities import convert_quantity
                from .sum_rules import EMU_PER_MOL_PER_MU_B

                input_unit = units.get(value_name, "emu")
                moment_emu = convert_quantity(
                    columns[value_name], "magnetic_moment", input_unit, "emu"
                )
                error_emu = (
                    None
                    if error_name not in columns
                    else np.abs(convert_quantity(
                        columns[error_name], "magnetic_moment", input_unit, "emu"
                    ))
                )
                if output_unit == "A m^2":
                    columns[value_name] = convert_quantity(
                        moment_emu, "magnetic_moment", "emu", output_unit
                    )
                    if error_emu is not None:
                        columns[error_name] = convert_quantity(
                            error_emu, "magnetic_moment", "emu", output_unit
                        )
                elif output_unit in {"emu/mol", "mu_B/f.u."}:
                    mass_g = float(dataset.parameters.get("sample_mass_mg", 0.0) or 0.0) / 1000.0
                    molar_mass = float(dataset.parameters.get("molar_mass_g_mol", 0.0) or 0.0)
                    if not absolute or mass_g <= 0.0 or molar_mass <= 0.0:
                        raise ValueError(
                            "formula-unit moment normalization requires absolute units and positive sample mass and molar mass"
                        )
                    moles = mass_g / molar_mass
                    divisor = moles
                    if output_unit == "mu_B/f.u.":
                        divisor *= EMU_PER_MOL_PER_MU_B
                    columns[value_name] = moment_emu / divisor
                    if error_emu is not None:
                        columns[error_name] = error_emu / divisor
                else:
                    raise ValueError(f"unsupported magnetization output unit {output_unit!r}")
                units[value_name] = output_unit
                quantity_types[value_name] = "magnetic_moment"
                if error_name in columns:
                    units[error_name] = output_unit
                    quantity_types[error_name] = "magnetic_moment"
                moment_channel["unit"] = output_unit

    result = PointListData(
        columns=columns,
        units=units,
        coordinate_names=coordinate_names,
        channels=channels,
        metadata=dict(base.metadata),
        quantity_types=quantity_types,
    )
    _lru_store(
        _PREPARED_POINT_LIST_CACHE,
        cache_key,
        (_prepared_point_list_signature(dataset), result),
        _PREPARED_POINT_LIST_CACHE_LIMIT,
        _PREPARED_POINT_LIST_CACHE_MAX_BYTES,
    )
    return result


def create_mask(dataset: DatasetEntry, name: str | None = None, *, type: str = "coordinate_range") -> MaskSpec:
    """Add a mask spec to a dataset and return it."""

    if type not in MASK_TYPE_DEFINITIONS:
        raise ValueError(f"unknown mask type {type!r}")
    mask = MaskSpec(
        name=next_mask_name(dataset.masks) if name is None else name,
        type=type,
        parameters=default_mask_parameters(type),
    )
    ensure_coordinate_range_mask_axes(mask, dataset)
    if mask.name in {existing.name for existing in dataset.masks}:
        raise ValueError(f"duplicate mask name {mask.name!r}")
    dataset.masks.append(mask)
    return mask


def create_group_mask(
    subgroup: DatasetGroup,
    reference_dataset: DatasetEntry | None = None,
    name: str | None = None,
    *,
    type: str = "coordinate_range",
) -> MaskSpec:
    """Add a shared mask to a nested dataset group, applied to all descendants."""

    if type not in MASK_TYPE_DEFINITIONS:
        raise ValueError(f"unknown mask type {type!r}")
    mask = MaskSpec(
        name=next_mask_name(subgroup.masks) if name is None else name,
        type=type,
        parameters=default_mask_parameters(type),
    )
    if reference_dataset is not None:
        ensure_coordinate_range_mask_axes(mask, reference_dataset)
    if mask.name in {existing.name for existing in subgroup.masks}:
        raise ValueError(f"duplicate mask name {mask.name!r}")
    subgroup.masks.append(mask)
    return mask


def _group_reference_dataset(subgroup: DatasetGroup) -> DatasetEntry | None:
    """Return the first descendant dataset with MDHisto data, for mask axis inference."""

    for dataset in subgroup.iter_datasets():
        if isinstance(dataset.data, MDHistoData):
            return dataset
    return None


def delete_mask(dataset: DatasetEntry, mask: MaskSpec) -> None:
    """Remove a mask from a dataset."""

    dataset.masks.remove(mask)


def next_dataset_group_name(existing_names: Any) -> str:
    """Return the next available default subgroup name."""

    taken = set(existing_names)
    index = 1
    while f"Group{index}" in taken:
        index += 1
    return f"Group{index}"


def create_dataset_group(
    data_group: DataGroup,
    parent_node: Any,
    name: str | None = None,
) -> DatasetGroup:
    """Create a nested dataset group under ``parent_node`` (a DataGroup or DatasetGroup)."""

    existing = {sub.name for sub in data_group.iter_subgroups()}
    subgroup = DatasetGroup(name=name or next_dataset_group_name(existing))
    if subgroup.name in existing:
        raise ValueError(f"duplicate dataset group name {subgroup.name!r}")
    parent_node.subgroups.append(subgroup)
    return subgroup


def delete_dataset_group(data_group: DataGroup, subgroup: DatasetGroup) -> bool:
    """Remove a nested dataset group (and its contents) from the group tree."""

    def remove_from(node: Any) -> bool:
        if subgroup in node.subgroups:
            node.subgroups.remove(subgroup)
            return True
        return any(remove_from(child) for child in node.subgroups)

    return remove_from(data_group)


def _dataset_group_parent(data_group: DataGroup, subgroup: DatasetGroup) -> Any:
    """Return the node whose ``subgroups`` contains ``subgroup`` (DataGroup or DatasetGroup)."""

    def search(node: Any) -> Any:
        if subgroup in node.subgroups:
            return node
        for child in node.subgroups:
            found = search(child)
            if found is not None:
                return found
        return None

    return search(data_group)


def _dataset_parent_node(root: Any, dataset: DatasetEntry) -> Any:
    """Return the node whose ``datasets`` contains ``dataset`` (DataGroup or DatasetGroup)."""

    if dataset in root.datasets:
        return root
    for subgroup in root.subgroups:
        found = _dataset_parent_node(subgroup, dataset)
        if found is not None:
            return found
    return None


def _dataset_is_effectively_enabled(
    data_group: DataGroup,
    dataset: DatasetEntry,
) -> bool:
    """Return whether a dataset and every containing dataset group are enabled."""

    if not dataset.enabled:
        return False
    node = _dataset_parent_node(data_group, dataset)
    while isinstance(node, DatasetGroup):
        if not node.enabled:
            return False
        node = _dataset_group_parent(data_group, node)
    return True


def _group_contains_node(ancestor: DatasetGroup, node: Any) -> bool:
    """Return True if ``node`` is ``ancestor`` or nested anywhere inside it."""

    return node is ancestor or node in ancestor.iter_subgroups()


def create_model_component(
    group: DataGroup,
    name: str | None = None,
    *,
    type: str = "constant_background",
) -> ModelComponentSpec:
    """Add a model component spec to a data group and return it."""

    if type not in MODEL_TYPE_REGISTRY:
        raise ValueError(f"unknown model type {type!r}")
    model = ModelComponentSpec(
        name=next_model_name(group.models),
        type=type,
        parameters=default_model_parameters(type),
        config=default_model_config(type),
        fit_parameters=default_model_fit_parameters(type),
        sharing={
            name: {"mode": "global", "groups": {}}
            for name in default_model_parameters(type)
        },
    )
    if name is not None:
        model.name = name
    model.name = _unique_name(model.name, list(group.models))
    group.models[model.name] = model
    return model


def ensure_fit_history(group: DataGroup) -> list[FitTimelineEntry]:
    """Ensure a data group has an Initial fit-history state."""

    if not group.fits:
        group.fits.append(
            FitTimelineEntry(
                name="Initial",
                kind="initial",
                snapshot=snapshot_data_group_state(group),
                created_at=_timestamp_now(),
            )
        )
    return group.fits


def create_fit_result_entry(
    group: DataGroup,
    parent: FitTimelineEntry,
    *,
    branch_timeline: bool = False,
    replace_current_state: bool = True,
    goodness: dict[str, Any] | None = None,
    channels: dict[str, dict[str, Any]] | None = None,
    metadata: dict[str, Any] | None = None,
    duration_seconds: float | None = None,
) -> FitTimelineEntry:
    """Insert a fit-result entry snapshotting the current group state."""

    snapshot = snapshot_data_group_state(group)
    result = FitTimelineEntry(
        name=next_fit_result_name(group.fits),
        kind="result",
        snapshot=copy.deepcopy(snapshot),
        created_at=_timestamp_now(),
        duration_seconds=duration_seconds,
        optimizer=str(parent.optimizer or "least_squares"),
        optimizer_config=copy.deepcopy(parent.optimizer_config),
        goodness=(
            {"status": "not run", "message": "The fit has not been executed."}
            if goodness is None
            else dict(goodness)
        ),
        channels={} if channels is None else dict(channels),
        metadata={} if metadata is None else dict(metadata),
    )
    if branch_timeline:
        timeline = FitTimelineEntry(
            name=next_fit_timeline_name(group.fits),
            kind="timeline",
            created_at=_timestamp_now(),
            children=[result],
        )
        parent.children.append(timeline)
    else:
        siblings = _fit_siblings(group.fits, parent)
        if siblings is None:
            siblings = group.fits
        insert_at = siblings.index(parent) + 1 if parent in siblings else len(siblings)
        siblings.insert(insert_at, result)
        if replace_current_state:
            _replace_current_state(siblings, group)
    return result


def run_group_fit(
    group: DataGroup,
    parent: FitTimelineEntry,
    *,
    branch_timeline: bool = False,
    progress_callback: Any | None = None,
) -> FitTimelineEntry:
    """Execute the group's fit and record the outcome in the fit history.

    The optimizer honors masks, disabled datasets/components, fit weights,
    and scale factors. Optimized parameters are written back to the model
    components before the result snapshot is taken, so the stored snapshot
    reproduces the fitted state. Fit and residual channels are evaluated once
    here and saved on the result entry; they are never recomputed on the fly.
    A failed fit still records an entry with the failure in ``goodness``.
    """

    start = time.perf_counter()
    channels: dict[str, dict[str, Any]] = {}
    metadata: dict[str, Any] = {}
    failed = False
    try:
        outcome = perform_group_fit(
            group,
            optimizer_config=parent.optimizer_config,
            progress_callback=progress_callback,
        )
        goodness = outcome["goodness"]
        channels = outcome["channels"]
        metadata = outcome.get("metadata", {})
    except Exception as exc:
        failed = True
        goodness = {"status": "failed", "message": str(exc)}
    duration = time.perf_counter() - start
    result = create_fit_result_entry(
        group,
        parent,
        branch_timeline=branch_timeline,
        replace_current_state=not failed,
        goodness=goodness,
        channels=channels,
        metadata=metadata,
        duration_seconds=duration,
    )
    if failed:
        _current_state_for_failed_fit(group, parent, result)
    return result


def current_state_fit_entry(
    group: DataGroup,
    source: FitTimelineEntry | None = None,
) -> FitTimelineEntry:
    """Return a mutable state snapshot, inheriting its source fit configuration."""

    return FitTimelineEntry(
        name="Current state",
        kind="current",
        snapshot=snapshot_data_group_state(group),
        created_at=_timestamp_now(),
        optimizer=str(source.optimizer or "least_squares") if source is not None else "least_squares",
        optimizer_config=copy.deepcopy(source.optimizer_config) if source is not None else {},
    )


def refresh_current_state_fit_entries(group: DataGroup) -> None:
    """Refresh the top-level Current state node from live GUI state."""

    snapshot = snapshot_data_group_state(group)
    for entry in group.fits:
        if entry.kind == "current":
            entry.snapshot = copy.deepcopy(snapshot)
            entry.created_at = _timestamp_now()


def _named_group_nodes(group: DataGroup) -> list[tuple[str, Any]]:
    """Return ``(key, node)`` pairs for the data group ("") and each subgroup by name."""

    nodes: list[tuple[str, Any]] = [("", group)]
    nodes.extend((subgroup.name, subgroup) for subgroup in group.iter_subgroups())
    return nodes


def _dataset_group_paths(group: DataGroup) -> list[tuple[str, DatasetGroup]]:
    """Return stable name paths for every nested dataset group."""

    nodes: list[tuple[str, DatasetGroup]] = []

    def visit(node: DatasetGroup, path: tuple[str, ...]) -> None:
        nodes.append(("/".join(path), node))
        for subgroup in node.subgroups:
            visit(subgroup, (*path, subgroup.name))

    for subgroup in group.subgroups:
        visit(subgroup, (subgroup.name,))
    return nodes


def snapshot_data_group_state(group: DataGroup) -> dict[str, Any]:
    """Capture serializable dataset mask and model configuration state."""

    return {
        "datasets": [
            {
                "name": dataset.name,
                "data_type": dataset.data_type,
                "parameters": copy.deepcopy(dataset.parameters),
                "enabled": bool(dataset.enabled),
                "fit_weight": float(dataset.fit_weight),
                "scale_factor": float(dataset.scale_factor),
                "scale_factor_vary": bool(dataset.scale_factor_vary),
                "scale_factor_group": dataset.scale_factor_group,
                "masks": [_mask_to_dict(mask) for mask in dataset.masks],
                "backgrounds": [
                    _background_to_dict(background)
                    for background in dataset.backgrounds
                ],
            }
            for dataset in group.iter_datasets()
        ],
        "group_masks": {
            node_name: [_mask_to_dict(mask) for mask in node.masks]
            for node_name, node in _named_group_nodes(group)
        },
        "dataset_group_enabled": {
            path: bool(node.enabled)
            for path, node in _dataset_group_paths(group)
        },
        "group_backgrounds": {
            node_name: [
                _background_to_dict(background) for background in node.backgrounds
            ]
            for node_name, node in _named_group_nodes(group)
        },
        "models": [
            _model_to_dict(model)
            for model in group.models.values()
            if isinstance(model, ModelComponentSpec)
        ],
    }


def restore_data_group_state(group: DataGroup, snapshot: dict[str, Any]) -> None:
    """Restore dataset masks and model component settings from a snapshot."""

    datasets_by_name = {dataset.name: dataset for dataset in group.iter_datasets()}
    for dataset_payload in snapshot.get("datasets", []):
        dataset = datasets_by_name.get(str(dataset_payload.get("name", "")))
        if dataset is None:
            continue
        dataset.data_type = str(
            dataset_payload.get("data_type", dataset.data_type)
        )
        dataset.parameters = dict(dataset_payload.get("parameters", {}))
        dataset.enabled = bool(dataset_payload.get("enabled", dataset.enabled))
        dataset.fit_weight = float(dataset_payload.get("fit_weight", dataset.fit_weight))
        dataset.scale_factor = float(dataset_payload.get("scale_factor", dataset.scale_factor))
        dataset.scale_factor_vary = bool(dataset_payload.get("scale_factor_vary", dataset.scale_factor_vary))
        dataset.scale_factor_group = (
            None
            if dataset_payload.get("scale_factor_group") in (None, "")
            else str(dataset_payload["scale_factor_group"])
        )
        dataset.masks = [_mask_from_dict(mask_payload) for mask_payload in dataset_payload.get("masks", [])]
        dataset.backgrounds = [
            _background_from_dict(background_payload)
            for background_payload in dataset_payload.get("backgrounds", [])
        ]
    by_id = {dataset.id: dataset for dataset in group.iter_datasets()}
    for dataset in by_id.values():
        for background in dataset.backgrounds:
            background.source_entry = by_id.get(background.source_dataset_id)
    dataset_group_enabled = snapshot.get("dataset_group_enabled", {})
    if isinstance(dataset_group_enabled, dict):
        for path, node in _dataset_group_paths(group):
            if path in dataset_group_enabled:
                node.enabled = bool(dataset_group_enabled[path])
    group_masks = snapshot.get("group_masks", {})
    if isinstance(group_masks, dict):
        for node_name, node in _named_group_nodes(group):
            if node_name in group_masks:
                node.masks = [_mask_from_dict(mask_payload) for mask_payload in group_masks[node_name]]
    group_backgrounds = snapshot.get("group_backgrounds", {})
    if isinstance(group_backgrounds, dict):
        for node_name, node in _named_group_nodes(group):
            if node_name in group_backgrounds:
                node.backgrounds = [
                    _background_from_dict(background_payload)
                    for background_payload in group_backgrounds[node_name]
                ]
    _link_group_backgrounds(group)
    for model_payload in snapshot.get("models", []):
        name = str(model_payload.get("name", ""))
        existing = group.models.get(name)
        if not isinstance(existing, ModelComponentSpec):
            continue
        existing.type = str(model_payload.get("type", existing.type))
        existing.parameters = dict(model_payload.get("parameters", {}))
        existing.config = dict(model_payload.get("config", {}))
        existing.fit_parameters = {
            str(key): bool(value)
            for key, value in dict(model_payload.get("fit_parameters", {})).items()
        }
        existing.sharing = _sharing_from_payload(model_payload.get("sharing"))
        existing.limits = dict(model_payload.get("limits", {}) or {})
        existing.constraints = [
            dict(constraint) for constraint in model_payload.get("constraints", []) or []
        ]
        existing.applies_to = _applies_to_from_payload(model_payload.get("applies_to"))
        existing.enabled = bool(model_payload.get("enabled", existing.enabled))
        existing.metadata = dict(model_payload.get("metadata", {}))
        reconcile_model_orbit_parameters(existing)


def delete_fit_entry(group: DataGroup, fit_entry: FitTimelineEntry) -> bool:
    """Delete a fit-history entry from a group unless it is the only Initial state."""

    if fit_entry.kind == "initial" and len(group.fits) == 1:
        return False
    siblings = _fit_siblings(group.fits, fit_entry)
    if siblings is None:
        return False
    siblings.remove(fit_entry)
    if not group.fits:
        ensure_fit_history(group)
    return True


def delete_model_component(group: DataGroup, model: ModelComponentSpec) -> None:
    """Remove a model component spec from a data group."""

    for name, existing in list(group.models.items()):
        if existing is model:
            del group.models[name]
            return
    raise ValueError(f"model {model.name!r} is not in data group {group.name!r}")


# Tree-item roles that support deletion. A batch delete is restricted to a
# single logical role so that a range selection of, for example, fit results
# never sweeps in the enclosing workspace or folder headers.
_DELETABLE_TREE_ROLES = frozenset(
    {
        "group", "dataset", "mask", "background", "group_background",
        "dataset_group", "group_mask", "model", "fit", "fit_timeline",
        "analysis", "plot",
    }
)

# Roles that should be treated as interchangeable when deciding which items a
# multi-selection delete may touch together.
_DELETABLE_ROLE_GROUP: dict[str, frozenset[str]] = {
    "fit": frozenset({"fit", "fit_timeline"}),
    "fit_timeline": frozenset({"fit", "fit_timeline"}),
}


def copy_mask_to_dataset(mask: MaskSpec, dataset: DatasetEntry) -> MaskSpec:
    """Copy a mask spec to another dataset, choosing a non-conflicting name."""

    copied = copy.deepcopy(mask)
    copied.name = _unique_name(copied.name, [existing.name for existing in dataset.masks])
    dataset.masks.append(copied)
    return copied


def _move_mask_within_dataset(
    dataset: DatasetEntry,
    mask: MaskSpec,
    target_mask: MaskSpec | None,
) -> bool:
    if mask not in dataset.masks:
        return False
    old_index = dataset.masks.index(mask)
    if target_mask is mask:
        return False
    dataset.masks.pop(old_index)
    if target_mask is None or target_mask not in dataset.masks:
        new_index = len(dataset.masks)
    else:
        new_index = dataset.masks.index(target_mask)
    dataset.masks.insert(new_index, mask)
    return old_index != new_index


def _move_items_within_list(items: list[Any], moving: list[Any], insert_index: int) -> bool:
    """Move selected objects inside one ordered list, preserving selection order."""

    moving_ids = {id(item) for item in moving}
    original = list(items)
    insert_index = max(0, min(insert_index, len(items)))
    insert_index -= sum(1 for index, item in enumerate(items) if id(item) in moving_ids and index < insert_index)
    items[:] = [item for item in items if id(item) not in moving_ids]
    for offset, item in enumerate(moving):
        items.insert(insert_index + offset, item)
    return items != original


def copy_dataset_to_group(dataset: DatasetEntry, group: DataGroup) -> DatasetEntry:
    """Copy a dataset entry to another data group, choosing a non-conflicting name."""

    copied = copy.deepcopy(dataset).copy()
    copied.name = _unique_name(copied.name, group.dataset_names)
    group.add_dataset(copied)
    return copied


def available_mask_types() -> list[str]:
    """Return registered mask type names."""

    return list(MASK_TYPE_DEFINITIONS)


def default_mask_parameters(type: str) -> dict[str, Any]:
    """Return default parameter values for a registered mask type."""

    return {
        name: copy.deepcopy(metadata["default"])
        for name, metadata in MASK_TYPE_DEFINITIONS[type]["parameters"].items()
    }


def ensure_coordinate_range_mask_axes(mask: MaskSpec, dataset: DatasetEntry | None) -> None:
    """Ensure a coordinate-range mask has one coordinate-axis vector per dataset dimension."""

    if mask.type != "coordinate_range" or dataset is None:
        return
    specs = _coordinate_range_axis_specs(dataset.data)
    if not specs:
        return
    stale_keys = [
        key
        for key in mask.parameters
        if key.startswith(COORDINATE_RANGE_AXIS_PREFIX)
        and key[len(COORDINATE_RANGE_AXIS_PREFIX) :].isdigit()
        and int(key[len(COORDINATE_RANGE_AXIS_PREFIX) :]) >= len(specs)
    ]
    for key in stale_keys:
        mask.parameters.pop(key, None)
    for index, spec in enumerate(specs):
        key = f"{COORDINATE_RANGE_AXIS_PREFIX}{index}"
        value = mask.parameters.get(key)
        if not _is_vector_length(value, len(spec["vector"])):
            mask.parameters[key] = copy.deepcopy(spec["vector"])


def mask_parameter_tooltip(type: str, parameter_name: str) -> str:
    """Return standard hover text for a mask parameter editor."""

    if type == "coordinate_range" and parameter_name.startswith(COORDINATE_RANGE_AXIS_PREFIX):
        axis_number = parameter_name.removeprefix(COORDINATE_RANGE_AXIS_PREFIX)
        return "\n".join(
            [
                f"Parameter: {parameter_name}",
                f"Description: Physical coordinate vector for source bin axis {axis_number}. It uses the same axis direction shown by the rebinner.",
                "Allowed values: A list of N finite numbers, where N is the number of dataset dimensions.",
                "Data type: list[float]",
                "Default: the corresponding source bin-axis vector, including projected directions such as [1, -1, 0, 0].",
                "Example: [1, -1, 0, 0]",
            ]
        )
    metadata = MASK_TYPE_DEFINITIONS[type]["parameters"][parameter_name]
    return "\n".join(
        [
            f"Parameter: {parameter_name}",
            f"Description: {metadata['description']}",
            f"Allowed values: {metadata['allowed']}",
            f"Data type: {metadata['type']}",
            f"Default: {_parameter_to_text(metadata['default'])}",
            f"Example: {metadata['example']}",
        ]
    )


def _mask_parameter_names(mask: MaskSpec, dataset: DatasetEntry | None = None) -> list[str]:
    names = list(MASK_TYPE_DEFINITIONS[mask.type]["parameters"])
    if mask.type != "coordinate_range":
        return names
    ensure_coordinate_range_mask_axes(mask, dataset)
    axis_names = sorted(
        (
            key
            for key in mask.parameters
            if key.startswith(COORDINATE_RANGE_AXIS_PREFIX)
            and key[len(COORDINATE_RANGE_AXIS_PREFIX) :].isdigit()
        ),
        key=lambda key: int(key[len(COORDINATE_RANGE_AXIS_PREFIX) :]),
    )
    return [*names, *axis_names]


def model_parameter_names(model: ModelComponentSpec) -> list[str]:
    """Return all parameter names of a model, static plus config-derived.

    Models such as ``heisenberg_rpa`` emit one exchange parameter per bond
    orbit in their configuration; this mirrors
    :func:`nfit.fit_config.component_parameter_names` for the GUI.
    """

    from .fit_config import component_parameter_names

    return list(component_parameter_names(model))


def _model_parameter_from_qualified_name(
    group: DataGroup, qualified: str
) -> tuple[ModelComponentSpec, str]:
    for model in group.models.values():
        if not isinstance(model, ModelComponentSpec):
            continue
        for parameter in model_parameter_names(model):
            if qualified_parameter_name(model.name, parameter) == qualified:
                return model, parameter
    raise ValueError(f"unknown model parameter {qualified!r}")


def _rename_model_constraint_references(
    group: DataGroup,
    renamed: ModelComponentSpec,
    old_name: str,
    new_name: str,
) -> None:
    replacements = {
        qualified_parameter_name(old_name, parameter): qualified_parameter_name(new_name, parameter)
        for parameter in model_parameter_names(renamed)
    }
    for model in group.models.values():
        if not isinstance(model, ModelComponentSpec):
            continue
        for constraint in model.constraints:
            reference = constraint.get("reference")
            if isinstance(reference, str) and reference in replacements:
                constraint["reference"] = replacements[reference]
            expression = constraint.get("expression")
            if not isinstance(expression, str):
                continue
            for old, new in replacements.items():
                expression = expression.replace(f"`{old}`", f"`{new}`")
                expression = re.sub(
                    rf"(?<![A-Za-z0-9_.]){re.escape(old)}(?![A-Za-z0-9_.])",
                    new,
                    expression,
                )
            constraint["expression"] = expression


def _validate_model_constraints(group: DataGroup) -> None:
    """Validate workspace constraints without requiring loaded fit datasets."""

    available = {
        qualified_parameter_name(model.name, parameter)
        for model in group.models.values()
        if isinstance(model, ModelComponentSpec)
        for parameter in model_parameter_names(model)
    }
    exact_dependencies: dict[str, tuple[str, ...]] = {}
    targets: set[str] = set()
    for model in group.models.values():
        if not isinstance(model, ModelComponentSpec):
            continue
        for constraint in model.constraints:
            parameter = str(constraint.get("parameter", ""))
            target = qualified_parameter_name(model.name, parameter)
            if target not in available:
                raise ValueError(f"constraint target {target!r} is not a model parameter")
            if target in targets:
                raise ValueError(f"parameter {target!r} has more than one constraint")
            targets.add(target)
            if not bool(model.fit_parameters.get(parameter, False)):
                raise ValueError(f"dependent parameter {target!r} must be enabled for fitting")
            if sharing_mode(model, parameter) != "global":
                raise ValueError(f"dependent parameter {target!r} must use global sharing")
            lower, upper = _model_limit_texts(model, parameter)
            if lower or upper:
                raise ValueError(f"constrained parameter {target!r} cannot also have min/max bounds")
            op = str(constraint.get("op", "="))
            if op == "=":
                expression = str(constraint.get("expression", "")).strip()
                dependencies = parameter_expression_names(expression)
                unknown = [name for name in dependencies if name not in available]
                if unknown:
                    raise ValueError(f"constraint on {target!r} references unknown parameter {unknown[0]!r}")
                for dependency in dependencies:
                    dependency_model, dependency_parameter = _model_parameter_from_qualified_name(
                        group, dependency
                    )
                    if sharing_mode(dependency_model, dependency_parameter) != "global":
                        raise ValueError(
                            f"constraint reference {dependency!r} must use global sharing"
                        )
                exact_dependencies[target] = dependencies
            elif op in (">=", "<="):
                reference = constraint.get("reference")
                if isinstance(reference, str) and reference not in available:
                    raise ValueError(f"constraint on {target!r} references unknown parameter {reference!r}")
                if isinstance(reference, str):
                    reference_model, reference_parameter = _model_parameter_from_qualified_name(
                        group, reference
                    )
                    if sharing_mode(reference_model, reference_parameter) != "global":
                        raise ValueError(
                            f"constraint reference {reference!r} must use global sharing"
                        )
                if not isinstance(reference, (str, int, float)):
                    raise ValueError(f"constraint on {target!r} requires one parameter or numeric constant")
            else:
                raise ValueError(f"unsupported constraint relation {op!r}")

    visiting: set[str] = set()
    visited: set[str] = set()

    def visit(name: str) -> None:
        if name in visiting:
            raise ValueError(f"cyclic exact constraint involving {name!r}")
        if name in visited:
            return
        visiting.add(name)
        for dependency in exact_dependencies.get(name, ()):
            if dependency in exact_dependencies:
                visit(dependency)
        visiting.remove(name)
        visited.add(name)

    for target in exact_dependencies:
        visit(target)

    values = {
        qualified_parameter_name(model.name, parameter): float(model.parameters.get(parameter, 0.0))
        for model in group.models.values()
        if isinstance(model, ModelComponentSpec)
        for parameter in model_parameter_names(model)
    }
    pending = dict(exact_dependencies)
    while pending:
        for target, dependencies in list(pending.items()):
            if any(dependency in pending for dependency in dependencies):
                continue
            model, parameter = _model_parameter_from_qualified_name(group, target)
            constraint = next(item for item in model.constraints if item.get("parameter") == parameter)
            values[target] = evaluate_parameter_expression(str(constraint["expression"]), values)
            del pending[target]
            break


DEFAULT_BOND_CUTOFF_ANGSTROM = 6.0


class _NoChange(Exception):
    """Signals that a model-config mutation left the state untouched."""


def model_crystal_config(model: ModelComponentSpec) -> dict[str, Any]:
    """Return (creating if needed) the nested crystal config of a model.

    Shape: ``{"lattice": {"a", "b", "c", "alpha", "beta", "gamma"},
    "spacegroup": str, "sites": [{"label", "element", "position", "ion"}],
    "provenance": {...}}``. Provenance is optional. The dict lives inside
    ``model.config`` and is plain JSON data, so it serializes with the project.
    """

    crystal = model.config.get("crystal")
    if not isinstance(crystal, dict):
        crystal = {}
        model.config["crystal"] = crystal
    lattice = crystal.setdefault(
        "lattice",
        {"a": 5.0, "b": 5.0, "c": 5.0, "alpha": 90.0, "beta": 90.0, "gamma": 90.0},
    )
    for name, fallback in (
        ("a", 5.0), ("b", 5.0), ("c", 5.0),
        ("alpha", 90.0), ("beta", 90.0), ("gamma", 90.0),
    ):
        lattice.setdefault(name, fallback)
    crystal.setdefault("spacegroup", "P 1")
    crystal.setdefault("sites", [])
    return crystal


def _mark_tight_binding_crystal_manual(
    model: ModelComponentSpec, crystal: dict[str, Any]
) -> None:
    """Prevent a manually edited structure script from reloading stale CIF data."""

    if model.type == "tight_binding":
        crystal["provenance"] = {"source": "manual"}


def _refresh_tight_binding_builder(model: ModelComponentSpec) -> None:
    """Regenerate builder-derived onsite data after crystal or orbital edits."""

    if model.type != "tight_binding" or not model.config.get("orbital_manifolds"):
        return
    from .electronic_builder import regenerate_tight_binding_onsite_terms

    regenerate_tight_binding_onsite_terms(model)


# Default starting values for the non-orbit dynamic parameters (all others
# default to 0.0). Zeeman parameters must be nonzero to have any effect.
_MODEL_PARAMETER_DEFAULTS = {
    "g_factor": 2.0,
    "chi_perp_ratio": 1.0,
    "gamma_perp_ratio": 1.0,
    "m2_total": 1.0,
    "mode_coupling_u": 0.0,
    "total_amplitude": 1.0,
}


def reconcile_model_orbit_parameters(model: ModelComponentSpec) -> None:
    """Align a model's fit parameters with its configuration-derived terms.

    Tight binding delegates to its builder-state synchronizer. For Heisenberg
    RPA this covers exchange orbits plus enabled tensor, dipole, and Zeeman
    terms. Values of parameters whose names persist are kept; parameters of
    removed terms are dropped with their fit flags, limits, and sharing.
    """

    if model.type == "tight_binding":
        from .electronic_builder import (
            ensure_tight_binding_onsite_terms,
            reconcile_tight_binding_parameters,
        )

        ensure_tight_binding_onsite_terms(model)
        reconcile_tight_binding_parameters(model)
        return

    names = list(component_parameter_names(model))
    keep = set(names)
    for mapping in (
        model.parameters,
        model.fit_parameters,
        model.limits,
        model.sharing,
    ):
        if isinstance(mapping, dict):
            for key in [name for name in mapping if name not in keep]:
                mapping.pop(key)
    static = set(model_definition(model.type).parameters)
    for name in names:
        if name in static:
            continue
        model.parameters.setdefault(name, _MODEL_PARAMETER_DEFAULTS.get(name, 0.0))
        model.fit_parameters.setdefault(name, False)
        model.sharing.setdefault(name, {"mode": "global", "groups": {}})


def set_model_crystal(
    model: ModelComponentSpec,
    crystal: dict[str, Any],
    *,
    group: DataGroup | None = None,
    periodic_axes: Sequence[int] | None = None,
) -> dict[str, Any]:
    """Install validated shared crystal geometry on a model component.

    Electronic models default a newly installed crystal to three-dimensional
    periodicity. Heisenberg models clear selections and derived bond data whose
    indices belonged to the previous crystal. The optional data group receives
    the same lattice, space group, and crystal metadata.
    """

    from .crystal import validate_crystal

    payload = copy.deepcopy(crystal)
    validate_crystal(payload)
    model.config["crystal"] = payload
    if model.type == "tight_binding":
        axes = (0, 1, 2) if periodic_axes is None else tuple(
            int(axis) for axis in periodic_axes
        )
        if not axes or len(set(axes)) != len(axes) or any(
            axis not in (0, 1, 2) for axis in axes
        ):
            raise ValueError(
                "periodic_axes must contain one to three unique indices from 0, 1, 2"
            )
        model.config["periodic_axes"] = list(axes)
        if (
            axes == (0, 1, 2)
            and payload.get("sites")
            and str(
                model.config.get("band_path_convention", "hinuma")
            ) in {"hinuma", "setyawan_curtarolo"}
        ):
            from .brillouin_zone import set_tight_binding_standard_path

            set_tight_binding_standard_path(
                model,
                str(model.config.get("band_path_convention", "hinuma")),
            )
        for name in ("spatial_orbits", "expanded_crystal_sites"):
            model.config.pop(name, None)
        if model.config.get("orbital_manifolds"):
            available = {
                str(site.get("label", "")) for site in payload.get("sites", ())
            }
            used = {
                str(item.get("site_label", ""))
                for item in model.config.get("orbital_manifolds", ())
            }
            if used.issubset(available):
                _refresh_tight_binding_builder(model)
            else:
                model.config["orbital_manifolds"] = []
                model.config["onsite_terms"] = []
                model.config["hopping_cutoff_angstrom"] = 0.0
                model.config["hopping_candidates"] = []
                model.config["hopping_terms"] = []
                model.config["spatial_orbits"] = []
                model.config["site_positions"] = []
                model.config["expanded_crystal_sites"] = []
                model.config["model_data"] = {}
                model.config["model_digest"] = ""
                from .electronic_builder import reconcile_tight_binding_parameters

                reconcile_tight_binding_parameters(model)
    elif model.type == "heisenberg_rpa":
        model.config["magnetic_sites"] = []
        for name in ("orbits", "site_positions", "site_rotations"):
            model.config.pop(name, None)
        model.config.pop("anisotropy", None)
        model.config.pop("sia", None)
        reconcile_model_orbit_parameters(model)
    if group is not None:
        group.lattice_parameters = dict(payload["lattice"])
        group.spacegroup = str(payload["spacegroup"])
        group.metadata["crystal"] = copy.deepcopy(payload)
    return payload


def import_cif_into_model(
    model: ModelComponentSpec, path: str, *, group: DataGroup | None = None
) -> dict[str, Any]:
    """Load a CIF file into a model's crystal config (and optionally its group).

    Model-specific derived geometry whose indices referred to the previous
    crystal is cleared. Returns the imported crystal dict.
    """

    from .crystal import crystal_from_cif

    imported = crystal_from_cif(path)
    return set_model_crystal(model, imported, group=group)


def generate_model_bond_orbits(model: ModelComponentSpec) -> list[str]:
    """Generate symmetry-distinct bond orbits from a model's crystal config.

    Writes ``config["orbits"]`` and ``config["site_positions"]`` (the expanded
    magnetic sites the bond indices refer to), reconciles the exchange
    parameters, and returns the orbit labels.
    """

    from .crystal import (
        generate_bond_orbits,
        orbits_to_config,
        site_rotations_to_config,
        sites_to_config,
    )

    crystal = model_crystal_config(model)
    magnetic = [str(label) for label in model.config.get("magnetic_sites", [])]
    if not magnetic:
        raise ValueError(
            "select at least one magnetic site (check 'Magnetic') before "
            "generating bond orbits"
        )
    cutoff = float(model.config.get("bond_cutoff_angstrom", DEFAULT_BOND_CUTOFF_ANGSTROM))
    sites, orbits = generate_bond_orbits(crystal, magnetic, cutoff)
    model.config["site_positions"] = sites_to_config(sites)
    model.config["site_rotations"] = site_rotations_to_config(sites)
    model.config["orbits"] = orbits_to_config(orbits)
    # Re-generating the network invalidates the snapshotted tensor bases (they
    # depend on the specific bonds/sites); drop them so they are regenerated.
    model.config.pop("anisotropy", None)
    model.config.pop("sia", None)
    reconcile_model_orbit_parameters(model)
    return [orbit.label for orbit in orbits]


def set_model_anisotropic_exchange(model: ModelComponentSpec, enabled: bool) -> None:
    """Enable/disable symmetry-allowed anisotropic exchange on every bond orbit.

    When enabling, projects the allowed rank-2 tensor basis of each orbit and
    snapshots it into ``config["anisotropy"]``; orbits with no allowed
    anisotropy contribute nothing. Reconciles the ``<orbit>_S1``/``_D1`` fit
    parameters either way.
    """

    if not enabled:
        model.config.pop("anisotropy", None)
        reconcile_model_orbit_parameters(model)
        return
    from .crystal import (
        expand_magnetic_sites,
        orbits_from_config,
        symmetry_allowed_exchange_basis,
    )

    crystal = model_crystal_config(model)
    magnetic = [str(label) for label in model.config.get("magnetic_sites", [])]
    sites = expand_magnetic_sites(crystal, magnetic)
    orbits = orbits_from_config(model.config.get("orbits", []))
    anisotropy: dict[str, Any] = {}
    for orbit in orbits:
        basis = symmetry_allowed_exchange_basis(crystal, sites, orbit)
        if basis:
            anisotropy[orbit.label] = {"enabled": True, "basis": basis}
    model.config["anisotropy"] = anisotropy
    reconcile_model_orbit_parameters(model)


def set_model_single_ion_anisotropy(model: ModelComponentSpec, enabled: bool) -> None:
    """Enable/disable symmetry-allowed single-ion anisotropy on every site class."""

    if not enabled:
        model.config.pop("sia", None)
        reconcile_model_orbit_parameters(model)
        return
    from .crystal import expand_magnetic_sites, symmetry_allowed_sia_basis

    crystal = model_crystal_config(model)
    magnetic = [str(label) for label in model.config.get("magnetic_sites", [])]
    sites = expand_magnetic_sites(crystal, magnetic)
    sia: dict[str, Any] = {}
    for label in magnetic:
        basis = symmetry_allowed_sia_basis(crystal, label)
        if basis:
            indices = [i for i, site in enumerate(sites) if site.label.startswith(f"{label}_")]
            sia[label] = {"enabled": True, "sites": indices, "basis": basis}
    model.config["sia"] = sia
    reconcile_model_orbit_parameters(model)


def set_model_dipole(model: ModelComponentSpec, enabled: bool) -> None:
    """Enable/disable Ewald dipole-dipole coupling (one fitted ``D_dip``)."""

    model.config["dipole"] = {"enabled": bool(enabled)}
    if enabled:
        from .dipole import dipole_coupling_constant

        model.parameters.setdefault("D_dip", dipole_coupling_constant())
    reconcile_model_orbit_parameters(model)


def set_model_zeeman(model: ModelComponentSpec, enabled: bool) -> None:
    """Enable/disable the Zeeman (applied-field) term (g_factor + ratios)."""

    model.config["zeeman"] = {"enabled": bool(enabled)}
    reconcile_model_orbit_parameters(model)


# Default closure config seeded when a mode is first selected.
_CLOSURE_CONFIG_DEFAULTS = {
    "mode": "none",
    "energy_cutoff_mev": 100.0,
    "bz_grid": 16,
    "omega_points": 200,
    "moment_mode": "fixed",
    "moment_target": 1.0,
}


def set_model_closure(model: ModelComponentSpec, updates: dict[str, Any]) -> None:
    """Merge closure settings into ``config["closure"]`` and reconcile params.

    ``updates`` carries any of the closure keys (``mode``, ``energy_cutoff_mev``,
    ``bz_grid``, ``omega_points``, ``moment_mode``, ``moment_target``). Selecting
    mode ``"none"`` drops the section entirely so the component takes the exact
    legacy code path; any other mode seeds the defaults and adds the closure's
    dynamic fit parameters (``m2_total``/``mode_coupling_u``/``total_amplitude``).
    """

    closure = dict(_CLOSURE_CONFIG_DEFAULTS)
    closure.update(model.config.get("closure") or {})
    closure.update(updates)
    if str(closure.get("mode", "none")).lower() == "none":
        model.config.pop("closure", None)
    else:
        model.config["closure"] = closure
    reconcile_model_orbit_parameters(model)


def dataset_details_text(dataset: DatasetEntry, *, group: DataGroup | None = None) -> str:
    """Return a human-readable summary of one imported dataset."""

    lines: list[str] = []
    for title, section_lines in dataset_detail_sections(dataset, group=group):
        if lines:
            lines.append("")
        lines.append(title)
        lines.extend(section_lines)
    return "\n".join(lines)


def fit_details_text(fit_entry: FitTimelineEntry) -> str:
    """Return a human-readable summary of one fit-history entry."""

    lines = [
        f"Type: {fit_entry.kind}",
        f"Created: {fit_entry.created_at or '-'}",
        f"Optimizer: {fit_entry.optimizer or '-'}",
        f"Duration: {_format_number(fit_entry.duration_seconds) + ' s' if fit_entry.duration_seconds is not None else '-'}",
    ]
    lines.extend(_fit_chi_squared_summary_lines(fit_entry))
    if fit_entry.optimizer_config:
        lines.extend(["", "Optimizer config"])
        lines.extend(_mapping_lines(fit_entry.optimizer_config))
    if fit_entry.goodness:
        lines.extend(["", "Goodness of fit"])
        lines.extend(_mapping_lines(fit_entry.goodness))
    if fit_entry.channels:
        lines.extend(["", f"Stored fit channels: {', '.join(sorted(fit_entry.channels))}"])
    snapshot = fit_entry.snapshot or {}
    lines.extend(
        [
            "",
            "Snapshot",
            f"Datasets: {len(snapshot.get('datasets', []))}",
            f"Models: {len(snapshot.get('models', []))}",
        ]
    )
    if fit_entry.children:
        lines.extend(["", f"Timeline entries: {len(fit_entry.children)}"])
    return "\n".join(lines)


def _fit_chi_squared_summary_lines(fit_entry: FitTimelineEntry) -> list[str]:
    """Return compact goodness-of-fit rows for a completed fit result."""

    if fit_entry.kind != "result":
        return []
    goodness = fit_entry.goodness if isinstance(fit_entry.goodness, dict) else {}

    def formatted(key: str) -> str:
        try:
            return _format_number(float(goodness[key]))
        except (KeyError, TypeError, ValueError):
            return "-"

    return [f"Chi^2: {formatted('chi2')}", f"Reduced Chi^2: {formatted('reduced_chi2')}"]


def dataset_detail_sections(
    dataset: DatasetEntry,
    *,
    group: DataGroup | None = None,
) -> list[tuple[str, list[str]]]:
    """Return ordered dataset detail sections for text and GUI rendering."""

    axes_lines, data_lines = _dataset_axes_and_data_lines(dataset.data)
    data_lines.extend(_dataset_fit_summary_lines(dataset, group=group))
    data_lines.append(f"Masks: {len(dataset.masks)}")
    data_lines.append(f"Backgrounds: {len(dataset.backgrounds)}")
    source_lines = _dataset_source_lines(dataset)
    metadata_lines = _dataset_metadata_lines(dataset)
    if dataset.parameters:
        metadata_lines = [*metadata_lines, "", "Parameters", *_mapping_lines(dataset.parameters)]
    return [
        (
            "Dataset",
            [
                f"Name: {dataset.name}",
                "Dataset",
                f"Data type: {data_type_label(dataset.data_type)}",
                f"Kind: {dataset.kind or '-'}",
                f"Enabled for fitting: {dataset.enabled}",
                f"Fit weight: {_format_number(dataset.fit_weight)}",
                f"Visualization only: {bool(dataset.enabled and dataset.fit_weight == 0.0)}",
                f"Scale factor: {_format_number(dataset.scale_factor)}",
                f"Scale fitted: {bool(dataset.scale_factor_vary)}",
                f"Shared scale: {dataset.scale_factor_group or '-'}",
            ],
        ),
        ("Axes", axes_lines),
        ("Crystal", _dataset_crystal_lines(dataset, group)),
        ("Data", data_lines),
        ("Source", source_lines or ["No source file recorded."]),
        ("Metadata", metadata_lines or ["No additional metadata."]),
    ]


def effective_dataset_masks(group: DataGroup, dataset: DatasetEntry) -> list[MaskSpec]:
    """Return masks inherited from the ancestor group chain of ``dataset``.

    Walks from the data group down through nested dataset groups to the
    dataset's parent, collecting each level's shared masks (outer to inner).
    Returns an empty list when the dataset is not found.
    """

    def search(node: Any) -> list[MaskSpec] | None:
        if dataset in getattr(node, "datasets", []):
            return list(node.masks)
        for subgroup in getattr(node, "subgroups", []):
            below = search(subgroup)
            if below is not None:
                return list(node.masks) + below
        return None

    return search(group) or []


@dataclass(frozen=True)
class _CompositeScope:
    root: DataGroup
    node: DataGroup | DatasetGroup

    @property
    def name(self) -> str:
        return self.node.name

    @property
    def metadata(self) -> dict[str, Any]:
        return self.node.metadata

    @property
    def masks(self) -> list[MaskSpec]:
        masks = list(self.root.masks)
        if self.node is not self.root:
            masks.extend(self.node.masks)
        return masks

    @property
    def backgrounds(self) -> list[BackgroundSpec]:
        backgrounds = list(self.root.backgrounds)
        if self.node is not self.root:
            backgrounds.extend(self.node.backgrounds)
        return backgrounds

    def iter_datasets(self):
        return self.node.iter_datasets()


def _composite_scope(
    root: DataGroup,
    node: DataGroup | DatasetGroup | None = None,
) -> DataGroup | _CompositeScope:
    return root if node is None or node is root else _CompositeScope(root, node)


def _composite_root(group: DataGroup | _CompositeScope) -> DataGroup:
    return group.root if isinstance(group, _CompositeScope) else group


def _composite_cache_key(group: DataGroup | _CompositeScope) -> int:
    return id(group.node) if isinstance(group, _CompositeScope) else id(group)


def data_group_composite_config(group: DataGroup | _CompositeScope) -> dict[str, Any]:
    """Return the group-level composite dataset configuration."""

    config = group.metadata.get(GROUP_COMPOSITE_KEY)
    if not isinstance(config, dict):
        config = {}
        group.metadata[GROUP_COMPOSITE_KEY] = config
    config.setdefault("enabled", False)
    config.setdefault("fractional", True)
    if not isinstance(config.get("symmetry"), dict):
        config["symmetry"] = symmetry_config(SymmetrySpec())
    if config.get(REBIN_RESOLUTION_MODE_KEY) not in {"step", "bins"}:
        config[REBIN_RESOLUTION_MODE_KEY] = "step"
    if config.get("mean_weighting") not in {"inverse_variance", "uniform"}:
        config["mean_weighting"] = "inverse_variance"
    config["minimum_coverage"] = _rebin_minimum_coverage(config)
    try:
        config["max_batch_mb"] = max(int(config.get("max_batch_mb", DEFAULT_REBIN_MAX_BATCH_MB)), 1)
    except (TypeError, ValueError):
        config["max_batch_mb"] = DEFAULT_REBIN_MAX_BATCH_MB
    config["normalize"] = True
    mdevent = group.metadata.get("mdevent") if isinstance(group.metadata, dict) else None
    raw_dgs = group.metadata.get("raw_dgs") if isinstance(group.metadata, dict) else None
    event_config = mdevent if isinstance(mdevent, dict) else raw_dgs if isinstance(raw_dgs, dict) else None
    axes = config.get("axes")
    if isinstance(event_config, dict):
        dimensions = list(event_config.get("dimensions", []))
        hkl_bounds = list(event_config.get("hkl_bounds", []))
        names = ("H", "K", "L", "DeltaE")
        default_axes = []
        for index, name in enumerate(names):
            source_dim = dimensions[index] if index < len(dimensions) else {}
            bounds = hkl_bounds[index] if index < len(hkl_bounds) else None
            lower = float(bounds[0] if bounds is not None else source_dim.get("lower", -5.0 if index < 3 else -50.0))
            upper = float(bounds[1] if bounds is not None else source_dim.get("upper", 5.0 if index < 3 else 50.0))
            default_axes.append({
                "name": name,
                "variable": ("H", "K", "L", "E")[index],
                "vector": _identity_vector(index, 4),
                "lower": lower,
                "upper": upper,
                "num_bins": 50 if index == 3 else 20,
                "step_size": (upper - lower) / (50.0 if index == 3 else 20.0),
            })
    else:
        if not isinstance(axes, list) or not axes:
            reference = _composite_reference_data(group)
            default_axes = _default_rebin_axes(reference) if reference is not None else []
        else:
            default_axes = []
    if not isinstance(axes, list) or not axes:
        # A composite can be restored before its reference data is loaded.
        # Do not create an empty placeholder that would prevent defaults from
        # being generated once a reference becomes available.
        if default_axes:
            config["axes"] = default_axes
    else:
        if len(axes) == len(default_axes):
            sanitized_axes = []
            for axis_config, default_axis in zip(axes, default_axes, strict=True):
                if not isinstance(axis_config, dict):
                    axis_config = {}
                for key, value in default_axis.items():
                    axis_config.setdefault(key, value)
                sanitized_axes.append(_sanitize_rebin_axis_config(axis_config))
            config["axes"] = sanitized_axes
        # Preserve a saved basis if reference data are temporarily unavailable
        # or differ during a refresh. A user edit is the only operation that
        # should replace its coordinate-axis vectors.
    if "auto_rebin" not in config:
        # File-backed MDEvent composites require a complete source scan even
        # when only a few selected events contribute to the current view.
        config["auto_rebin"] = False if isinstance(event_config, dict) else not _composite_rebin_is_large(group, config)
    config.setdefault("stale", False)
    return config


def _composite_source_points(group: DataGroup) -> int:
    mdevent = group.metadata.get("mdevent") if isinstance(group.metadata, dict) else None
    if isinstance(mdevent, dict):
        return int(mdevent.get("event_count", 0) or 0)
    raw_dgs = group.metadata.get("raw_dgs") if isinstance(group.metadata, dict) else None
    if isinstance(raw_dgs, dict):
        return int(raw_dgs.get("event_count", 0) or 0)
    return sum(_dataset_rebin_source_points(dataset) for dataset in _composite_candidates(group))


def _dataset_collection_point_count(node: DataGroup | DatasetGroup) -> int:
    mdevent = node.metadata.get("mdevent") if isinstance(node.metadata, dict) else None
    if isinstance(mdevent, dict):
        return int(mdevent.get("event_count", 0) or 0)
    raw_dgs = node.metadata.get("raw_dgs") if isinstance(node.metadata, dict) else None
    if isinstance(raw_dgs, dict):
        return int(raw_dgs.get("event_count", 0) or 0)
    return sum(_dataset_data_point_count(dataset) for dataset in node.iter_datasets())


def _composite_output_bins(config: dict[str, Any]) -> int:
    total = 1
    axes = config.get("axes", [])
    if not isinstance(axes, list):
        return 0
    for axis in axes:
        if isinstance(axis, dict):
            total *= max(int(axis.get("num_bins", 1) or 1), 1)
    return int(total)


def _composite_estimated_contributions(group: DataGroup, config: dict[str, Any]) -> int:
    ndim = len(config.get("axes", []) or [])
    multiplier = 2**ndim if bool(config.get("fractional", True)) else 1
    return int(_composite_source_points(group) * multiplier)


def _composite_rebin_is_large(group: DataGroup, config: dict[str, Any]) -> bool:
    return (
        _composite_estimated_contributions(group, config) > REBIN_AUTO_MAX_CONTRIBUTIONS
        or _composite_output_bins(config) > REBIN_AUTO_MAX_OUTPUT_BINS
    )


def _composite_rebin_status_text(group: DataGroup, config: dict[str, Any]) -> str:
    if not bool(config.get("enabled", False)):
        return "Composite rebinning is off."
    size_note = "large" if _composite_rebin_is_large(group, config) else "small"
    if bool(config.get("auto_rebin", True)):
        if bool(config.get("stale", False)):
            return f"Automatic composite rebinning is on ({size_note}); pending edits will recompute on the next refresh."
        return f"Automatic composite rebinning is on ({size_note}); edits recompute the cached composite."
    if bool(config.get("stale", False)):
        return f"Manual composite rebinning is on ({size_note}); Rebin now, fit, or open the data viewer to apply pending edits."
    return f"Manual composite rebinning is on ({size_note}); the cached composite is current."


def _composite_auto_enabled(group: DataGroup) -> bool:
    return bool(data_group_composite_config(group).get("auto_rebin", True))


def _composite_rebin_is_stale(group: DataGroup) -> bool:
    return bool(data_group_composite_config(group).get("stale", False))


def _should_defer_composite_rebin(group: DataGroup, *, force_rebin: bool) -> bool:
    return (
        data_group_composite_enabled(group)
        and not force_rebin
        and not _composite_auto_enabled(group)
        and _composite_rebin_is_stale(group)
    )


def data_group_composite_enabled(group: DataGroup) -> bool:
    config = group.metadata.get(GROUP_COMPOSITE_KEY)
    return bool(isinstance(config, dict) and config.get("enabled"))


def _composite_dataset_name(group: DataGroup) -> str:
    return f"{group.name} {GROUP_COMPOSITE_NAME}"


def _composite_candidates(group: DataGroup) -> list[DatasetEntry]:
    node = group.node if isinstance(group, _CompositeScope) else group
    background_ids = {
        background.source_dataset_id
        for background in getattr(group, "backgrounds", [])
        if background.enabled
    }

    def considered_datasets(
        current: DataGroup | DatasetGroup,
    ) -> Iterator[DatasetEntry]:
        if isinstance(current, DatasetGroup) and not current.enabled:
            return
        yield from current.datasets
        for subgroup in current.subgroups:
            yield from considered_datasets(subgroup)

    return [
        dataset
        for dataset in considered_datasets(node)
        if dataset.enabled and dataset.id not in background_ids
    ]


def _dataset_composite_kind(dataset: DatasetEntry) -> str:
    if dataset.kind == "mdevent":
        return "mdevent"
    if dataset.kind == "raw_dgs_nexus":
        return "raw_dgs_nexus"
    if data_type_container(dataset.data_type) == "point_list" or isinstance(dataset.data, PointListData):
        return "point_list"
    if isinstance(dataset.data, MDHistoData) or data_type_container(dataset.data_type) == "mdhisto":
        return "mdhisto"
    if isinstance(dataset.data, PointData4D):
        return "point_data_4d"
    return type(dataset.data).__name__ if dataset.data is not None else "unknown"


def data_group_composite_status(group: DataGroup) -> tuple[bool, str]:
    datasets = _composite_candidates(group)
    if not datasets:
        return False, "No enabled datasets are available to combine."
    kinds = {_dataset_composite_kind(dataset) for dataset in datasets}
    if len(kinds) != 1:
        return False, "Composite datasets require all enabled datasets to hold the same kind of data."
    if next(iter(kinds)) == "raw_dgs_nexus":
        node = group.node if isinstance(group, _CompositeScope) else group
        if not isinstance(node, DatasetGroup):
            return False, "Select the raw TOF dataset group to configure its HKLE composite."
    if next(iter(kinds)) not in {"mdhisto", "point_list", "point_data_4d", "mdevent", "raw_dgs_nexus"}:
        return False, "This dataset kind cannot be composited yet."
    return True, "Ready to combine enabled datasets into one rebinned composite."


def _composite_reference_data(group: DataGroup) -> Any | None:
    ok, _message = data_group_composite_status(group)
    if not ok:
        return None
    dataset = _composite_candidates(group)[0]
    try:
        return _source_data_for_group_composite(group, dataset)
    except Exception:
        return dataset.data


def _ensure_dataset_data_loaded(dataset: DatasetEntry) -> Any:
    """Return canonical loaded data, using one path for all lazy consumers."""

    if dataset.data is not None:
        return dataset.data
    if dataset.kind == "raw_dgs_nexus":
        return None
    if dataset.metadata.get("importer"):
        loaded = _load_registered_importer_dataset(dataset)
        if loaded is not None:
            return loaded
    if data_type_container(dataset.data_type) == "point_list":
        loaded = _load_point_list_dataset(dataset)
        if loaded is not None:
            return loaded
    source = dataset.metadata.get("source_file") if isinstance(dataset.metadata, dict) else None
    if source and Path(source).suffix.lower() in {".nxs", ".h5", ".hdf5", ".npz"}:
        if Path(source).suffix.lower() == ".npz":
            loaded, parameters = _load_nfit_dataset_file(Path(source))
            dataset.parameters.update(parameters)
        elif dataset.kind == "mdevent":
            loaded = load_mdevent_run_points(dataset)
        else:
            loaded = load_mantid_mdhisto_nxs(Path(source), copy_metadata=False)
        loaded = dataset.replace_data(loaded, source_backed=True)
        dataset.kind = dataset.kind or Path(source).suffix.lstrip(".").lower()
        dataset.metadata["import_status"] = "loaded"
        return loaded
    return dataset.data


def _source_data_for_group_composite(group: DataGroup, dataset: DatasetEntry) -> Any:
    data = _ensure_dataset_data_loaded(dataset)
    extra_masks = effective_dataset_masks(_composite_root(group), dataset)
    if isinstance(data, PointListData):
        return prepared_point_list_data(dataset)
    if isinstance(data, MDHistoData):
        return _mdhisto_with_nfit_masks(dataset, data=data, extra_masks=extra_masks)
    if isinstance(data, PointData4D):
        return _point_data_with_nfit_masks(dataset, data, extra_masks=extra_masks)
    return data


def _composite_cache_signature(group: DataGroup) -> str:
    config = data_group_composite_config(group)
    payload = [
        json.dumps(config, sort_keys=True, default=str),
        [
            [
                dataset.name,
                dataset.data_cache_token,
                dataset.data_type,
                dataset.kind,
                bool(dataset.enabled),
                float(dataset.fit_weight),
                float(dataset.scale_factor),
                _mask_signature(getattr(dataset, "masks", None)),
                _mask_signature(effective_dataset_masks(_composite_root(group), dataset)),
            ]
            for dataset in _composite_candidates(group)
        ],
        _mask_signature(getattr(group, "masks", None)),
        [
            [
                background.source_dataset_id,
                bool(background.enabled),
                float(background.scale),
                background.interpolation,
                (
                    background.source_entry.data_cache_token
                    if background.source_entry is not None
                    else None
                ),
            ]
            for background in getattr(group, "backgrounds", [])
        ],
    ]
    return json.dumps(payload, sort_keys=True, default=str)


def composite_dataset_data(
    group: DataGroup,
    *,
    progress_callback: Any | None = None,
) -> MDHistoData | PointListData | PointData4D:
    """Build the group's rebinned composite dataset from enabled members."""

    ok, message = data_group_composite_status(group)
    if not ok:
        raise ValueError(message)
    config = data_group_composite_config(group)
    kind = _dataset_composite_kind(_composite_candidates(group)[0])
    result: MDHistoData | PointListData | PointData4D
    if kind == "mdevent":
        node = group.node if isinstance(group, _CompositeScope) else group
        if not isinstance(node, DatasetGroup):
            raise ValueError("MDEvent composites must be imported inside a dataset group")
        lower, upper, num_bins = _composite_rebin_bounds(config)
        allow_overcommit = bool(config.pop("_allow_memory_overcommit_once", False))
        result = bin_mdevent_group(
            node,
            lower=lower,
            upper=upper,
            num_bins=num_bins,
            step_size=_composite_rebin_step_sizes(config),
            datasets=_composite_candidates(group),
            vectors=[
                axis.get("vector", _identity_vector(index, 4))
                for index, axis in enumerate(config.get("axes", []))
            ],
            axis_names=[
                str(axis.get("name", ("H", "K", "L", "DeltaE")[index]))
                for index, axis in enumerate(config.get("axes", []))
            ],
            max_batch_bytes=_rebin_max_batch_bytes(config),
            enforce_memory_limit=not allow_overcommit,
            progress_callback=progress_callback,
            symmetry_operations=_rebin_symmetry_matrices(config, _composite_root(group).lattice_parameters),
        )
    elif kind == "raw_dgs_nexus":
        node = group.node if isinstance(group, _CompositeScope) else group
        if not isinstance(node, DatasetGroup):
            raise ValueError("raw direct-geometry composites must be imported inside a dataset group")
        lower, upper, num_bins = _composite_rebin_bounds(config)
        result = bin_raw_dgs_group(
            node, lower=lower, upper=upper, num_bins=num_bins,
            step_size=_composite_rebin_step_sizes(config), datasets=_composite_candidates(group),
            vectors=[axis.get("vector", _identity_vector(index, 4)) for index, axis in enumerate(config.get("axes", []))],
            axis_names=[str(axis.get("name", ("H", "K", "L", "DeltaE")[index])) for index, axis in enumerate(config.get("axes", []))],
            max_batch_bytes=_rebin_max_batch_bytes(config), progress_callback=progress_callback,
            symmetry_operations=_rebin_symmetry_matrices(config, _composite_root(group).lattice_parameters),
        )
    elif kind == "mdhisto":
        result = _composite_mdhisto_data(
            group, config, progress_callback=progress_callback
        )
    elif kind == "point_list":
        result = _composite_point_list_data(
            group, config, progress_callback=progress_callback
        )
    elif kind == "point_data_4d":
        result = _composite_point_data(
            group, config, progress_callback=progress_callback
        )
    else:
        raise ValueError(f"unsupported composite dataset kind {kind!r}")
    if isinstance(result, MDHistoData):
        result = _apply_mdhisto_coverage_threshold(result, config)
    return _apply_composite_backgrounds(group, result)


def _apply_mdhisto_coverage_threshold(
    data: MDHistoData,
    config: dict[str, Any],
) -> MDHistoData:
    coverage = mdhisto_coverage_fraction(data)
    coverage_mask = coverage < _rebin_minimum_coverage(config)
    channels = dict(data.auxiliary_channels)
    channels["coverage_fraction"] = MDHistoChannel(
        coverage,
        label="Coverage",
        unit="fraction",
    )
    metadata = dict(data.metadata)
    metadata["coverage_mask_count"] = int(np.count_nonzero(coverage_mask))
    rebin_metadata = dict(metadata.get("rebin", {}))
    rebin_metadata["minimum_coverage"] = _rebin_minimum_coverage(config)
    metadata["rebin"] = rebin_metadata
    return data.with_updates(
        mask=np.asarray(data.mask, dtype=bool) | coverage_mask,
        metadata=metadata,
        auxiliary_channels=channels,
    )


def _apply_composite_backgrounds(
    group: DataGroup | _CompositeScope,
    data: MDHistoData | PointListData | PointData4D,
) -> MDHistoData | PointListData | PointData4D:
    """Apply backgrounds owned by a composite scope after it is combined."""

    backgrounds = list(getattr(group, "backgrounds", []))
    if not backgrounds:
        return data
    if not isinstance(data, MDHistoData):
        raise TypeError("group powder backgrounds require a gridded composite")
    root = _composite_root(group)
    metadata = dict(data.metadata)
    if root.lattice_parameters and not isinstance(
        metadata.get("lattice_parameters"), dict
    ):
        metadata["lattice_parameters"] = dict(root.lattice_parameters)
    result = replace(data, metadata=metadata)
    for background in backgrounds:
        if not background.enabled:
            continue
        source = background.source_entry
        if source is None:
            raise ValueError(
                f"background {background.name!r} refers to a missing dataset"
            )
        source_data = _viewer_data_before_scale(
            source,
            force_rebin=True,
            force_masks=True,
        )
        if not isinstance(source_data, MDHistoData):
            raise TypeError(
                f"background {background.name!r} must refer to gridded powder data"
            )
        result = subtract_powder_background(
            result,
            source_data,
            scale=background.scale,
            interpolation=background.interpolation,
        )
    return result


def _cached_composite_dataset_data(
    group: DataGroup,
    *,
    force_rebin: bool = True,
    progress_callback: Any | None = None,
) -> MDHistoData | PointListData | PointData4D | None:
    signature = _composite_cache_signature(group)
    cache_key = _composite_cache_key(group)
    cached = _COMPOSITE_DATA_CACHE.get(cache_key)
    if cached is not None and cached[0] == signature:
        _COMPOSITE_DATA_CACHE.move_to_end(cache_key)
        return cached[1]
    if cached is not None and _should_defer_composite_rebin(group, force_rebin=force_rebin):
        return cached[1]
    if _should_defer_composite_rebin(group, force_rebin=force_rebin):
        return None
    result = composite_dataset_data(group, progress_callback=progress_callback)
    config = data_group_composite_config(group)
    config["stale"] = False
    signature = _composite_cache_signature(group)
    _lru_store(
        _COMPOSITE_DATA_CACHE,
        cache_key,
        (signature, result),
        _COMPOSITE_DATA_CACHE_LIMIT,
        _COMPOSITE_DATA_CACHE_MAX_BYTES,
    )
    return result


def composite_dataset_entry(
    group: DataGroup,
    *,
    force_rebin: bool = True,
    progress_callback: Any | None = None,
) -> DatasetEntry:
    datasets = _composite_candidates(group)
    first = datasets[0] if datasets else None
    return DatasetEntry(
        name=_composite_dataset_name(group),
        data=_cached_composite_dataset_data(
            group,
            force_rebin=force_rebin,
            progress_callback=progress_callback,
        ),
        kind=(first.kind if first is not None else ""),
        data_type=(first.data_type if first is not None else ""),
        metadata={"source_group": group.name, "composite": True},
        parameters=(
            {
                SPECTRAL_CHANNEL_CONFIG_KEY: copy.deepcopy(
                    first.parameters[SPECTRAL_CHANNEL_CONFIG_KEY]
                )
            }
            if first is not None
            and SPECTRAL_CHANNEL_CONFIG_KEY in first.parameters
            else {}
        ),
        enabled=True,
        fit_weight=1.0,
        scale_factor=1.0,
    )


def _scaled_error_for_weight(dataset: DatasetEntry, errors: np.ndarray) -> np.ndarray:
    return np.asarray(errors, dtype=float) * abs(float(dataset.scale_factor))


def _dataset_statistical_weight(dataset: DatasetEntry, size: int) -> np.ndarray:
    weight = float(dataset.fit_weight)
    if not np.isfinite(weight) or weight <= 0.0:
        return np.zeros(size, dtype=float)
    return np.full(size, weight, dtype=float)


def _composite_rebin_bounds(config: dict[str, Any]) -> tuple[list[float], list[float], list[int]]:
    axes_config = [_sanitize_rebin_axis_config(axis) for axis in config.get("axes", [])]
    return (
        [axis["lower"] for axis in axes_config],
        [axis["upper"] for axis in axes_config],
        [axis["num_bins"] for axis in axes_config],
    )


def _composite_mdhisto_data(
    group: DataGroup,
    config: dict[str, Any],
    *,
    progress_callback: Any | None = None,
) -> MDHistoData:
    lower, upper, num_bins = _composite_rebin_bounds(config)
    axes_config = [_sanitize_rebin_axis_config(axis) for axis in config.get("axes", [])]
    coords_parts: list[np.ndarray] = []
    signal_parts: list[np.ndarray] = []
    error_parts: list[np.ndarray] = []
    weight_parts: list[np.ndarray] = []
    coverage_inputs: list[tuple[MDHistoData, np.ndarray]] = []
    first_data: MDHistoData | None = None
    for dataset in _composite_candidates(group):
        data = _source_data_for_group_composite(group, dataset)
        if not isinstance(data, MDHistoData):
            continue
        if first_data is None:
            first_data = data
        source_grids = np.meshgrid(*(axis.centers for axis in data.axes), indexing="ij")
        coords = np.stack(source_grids, axis=-1)
        coverage_inputs.append((data, coords))
        valid = np.isfinite(data.signal) & np.isfinite(data.errors) & ~np.asarray(data.mask, dtype=bool)
        if data.num_events is not None:
            valid &= mdhisto_measured_bins(data)
        if not np.any(valid):
            continue
        scale = float(dataset.scale_factor)
        signal = np.asarray(data.signal[valid], dtype=float) * scale
        errors = _scaled_error_for_weight(dataset, np.asarray(data.errors[valid], dtype=float))
        weights = _dataset_statistical_weight(dataset, signal.size)
        coords_parts.append(coords[valid])
        signal_parts.append(signal)
        error_parts.append(errors)
        weight_parts.append(weights)
    if first_data is None or not signal_parts:
        raise ValueError("no valid data points remain before compositing")
    coords_all = np.concatenate(coords_parts, axis=0)
    signal_all = np.concatenate(signal_parts)
    errors_all = np.concatenate(error_parts)
    weights_all = np.concatenate(weight_parts)
    result = rebin_nd(
        signal_all,
        coords_all,
        data_errs=errors_all,
        data_weights=weights_all,
        lower=lower,
        upper=upper,
        **_rebin_grid_kwargs(config, axes_config),
        fractional=bool(config.get("fractional", True)),
        normalize=True,
        mean_weighting=_rebin_mean_weighting(config),
        max_batch_bytes=_rebin_max_batch_bytes(config),
        progress_callback=progress_callback,
    )
    if result.binned_data is None or result.binned_data_errs is None or result.n_samples is None or result.bins_list is None:
        raise RuntimeError("composite rebinning did not produce binned data")
    axes = tuple(
        MDHistoAxis(
            name=str(axis_config.get("name") or source_axis.name),
            values=np.asarray(bins, dtype=float),
            units=str(axis_config.get("units") if axis_config.get("units") is not None else source_axis.units),
            kind=source_axis.kind,
            frame=source_axis.frame,
            path=source_axis.path,
            metadata=dict(source_axis.metadata),
        )
        for source_axis, axis_config, bins in zip(first_data.axes, axes_config, result.bins_list, strict=True)
    )
    mask = ~np.isfinite(result.binned_data) | ~np.isfinite(result.binned_data_errs)
    mask |= result.n_samples <= 0.0
    coverage = np.maximum.reduce(
        [
            _rebin_mdhisto_coverage(
                source,
                source_coords,
                config,
                axes_config,
                result.bins_list,
            )
            for source, source_coords in coverage_inputs
        ]
    )
    coverage_mask = coverage < _rebin_minimum_coverage(config)
    mask |= coverage_mask
    metadata = {
        "composite": True,
        "source_group": group.name,
        "source_datasets": [dataset.name for dataset in _composite_candidates(group)],
        "signal_semantics": "density",
        "signal_semantics_source": "nfit_normalized_rebin",
        "coverage_mask_count": int(np.count_nonzero(coverage_mask)),
        "rebin": {
            "lower": lower,
            "upper": upper,
            "step_size": np.asarray(result.step_size, dtype=float).tolist(),
            "num_bins": np.asarray(result.num_bins, dtype=int).tolist(),
            "vectors": [
                _rebin_axis_vector(axis_config, index, len(axes_config)).tolist()
                for index, axis_config in enumerate(axes_config)
            ],
            "fractional": bool(config.get("fractional", True)),
            "normalize": True,
            "mean_weighting": _rebin_mean_weighting(config),
            "minimum_coverage": _rebin_minimum_coverage(config),
            "max_batch_mb": _rebin_max_batch_mb(config),
            "max_batch_bytes": _rebin_max_batch_bytes(config),
            "weighted_by_fit_weight": True,
        },
    }
    for key in (
        "lattice_parameters",
        "oriented_lattice",
        "rlu_to_inv_angstrom_matrix",
        "ub_matrix",
        "orientation_matrix",
    ):
        if key in first_data.metadata:
            metadata[key] = copy.deepcopy(first_data.metadata[key])
    root = _composite_root(group)
    if root.lattice_parameters and "lattice_parameters" not in metadata:
        metadata["lattice_parameters"] = dict(root.lattice_parameters)
    return MDHistoData(
        axes=axes,
        signal=np.asarray(result.binned_data, dtype=float),
        errors=np.asarray(result.binned_data_errs, dtype=float),
        mask=np.asarray(mask, dtype=bool),
        num_events=np.asarray(result.n_samples, dtype=float),
        coordinate_system=first_data.coordinate_system,
        visual_normalization=first_data.visual_normalization,
        metadata=metadata,
        auxiliary_channels={
            "coverage_fraction": MDHistoChannel(
                coverage,
                label="Coverage",
                unit="fraction",
            )
        },
    )


def _composite_point_data(
    group: DataGroup,
    config: dict[str, Any],
    *,
    progress_callback: Any | None = None,
) -> PointData4D:
    lower, upper, num_bins = _composite_rebin_bounds(config)
    axes_config = [_sanitize_rebin_axis_config(axis) for axis in config.get("axes", [])]
    coords_parts: list[np.ndarray] = []
    signal_parts: list[np.ndarray] = []
    error_parts: list[np.ndarray] = []
    weight_parts: list[np.ndarray] = []
    for dataset in _composite_candidates(group):
        data = _source_data_for_group_composite(group, dataset)
        if not isinstance(data, PointData4D):
            continue
        source = data.valid(require_positive_sigma=False)
        if source.size == 0:
            continue
        coords_parts.append(np.column_stack(source.coordinates()))
        scale = float(dataset.scale_factor)
        signal = np.asarray(source.intensity, dtype=float) * scale
        signal_parts.append(signal)
        error_parts.append(_scaled_error_for_weight(dataset, source.sigma))
        weight_parts.append(_dataset_statistical_weight(dataset, source.size))
    if not signal_parts:
        raise ValueError("no valid data points remain before compositing")
    result = rebin_nd(
        np.concatenate(signal_parts),
        np.concatenate(coords_parts, axis=0),
        data_errs=np.concatenate(error_parts),
        data_weights=np.concatenate(weight_parts),
        lower=lower,
        upper=upper,
        **_rebin_grid_kwargs(config, axes_config),
        fractional=bool(config.get("fractional", True)),
        normalize=True,
        mean_weighting=_rebin_mean_weighting(config),
        max_batch_bytes=_rebin_max_batch_bytes(config),
        progress_callback=progress_callback,
    )
    if result.bin_centers_list is None or result.binned_data is None or result.binned_data_errs is None or result.n_samples is None:
        raise RuntimeError("composite rebinning did not produce binned data")
    H_grid, K_grid, L_grid, E_grid = np.meshgrid(*result.bin_centers_list, indexing="ij")
    mask = np.isfinite(result.binned_data) & np.isfinite(result.binned_data_errs) & (result.n_samples > 0.0)
    return PointData4D(
        H_grid.ravel(),
        K_grid.ravel(),
        L_grid.ravel(),
        E_grid.ravel(),
        np.asarray(result.binned_data, dtype=float).ravel(),
        np.asarray(result.binned_data_errs, dtype=float).ravel(),
        mask=mask.ravel(),
        metadata={"composite": True, "source_group": group.name},
    )


def _composite_point_list_data(
    group: DataGroup,
    config: dict[str, Any],
    *,
    progress_callback: Any | None = None,
) -> PointListData:
    datasets = _composite_candidates(group)
    prepared = [_source_data_for_group_composite(group, dataset) for dataset in datasets]
    point_lists = [data for data in prepared if isinstance(data, PointListData)]
    if not point_lists:
        raise ValueError("no point-list datasets are available to composite")
    coordinate_names = list(point_lists[0].coordinate_names)
    channel_label = point_lists[0].channel_labels[0] if point_lists[0].channel_labels else None
    if not coordinate_names or channel_label is None:
        raise ValueError("point-list composites require coordinates and at least one channel")
    for data in point_lists[1:]:
        if list(data.coordinate_names) != coordinate_names or channel_label not in data.channel_labels:
            raise ValueError("point-list composites require matching coordinates and channel labels")
    lower, upper, num_bins = _composite_rebin_bounds(config)
    axes_config = [_sanitize_rebin_axis_config(axis) for axis in config.get("axes", [])]
    coords_parts: list[np.ndarray] = []
    signal_parts: list[np.ndarray] = []
    error_parts: list[np.ndarray] = []
    weight_parts: list[np.ndarray] = []
    for dataset, data in zip(datasets, point_lists, strict=False):
        coords = np.column_stack([data.column(name) for name in coordinate_names])
        finite = np.all(np.isfinite(coords), axis=1)
        values = np.asarray(data.channel_values(channel_label), dtype=float)
        errors = data.channel_errors(channel_label)
        if errors is None:
            errors = np.ones(values.shape, dtype=float)
        valid = finite & np.isfinite(values) & np.isfinite(errors)
        if not np.any(valid):
            continue
        scale = float(dataset.scale_factor)
        coords_parts.append(coords[valid])
        signal_parts.append(values[valid] * scale)
        error_parts.append(_scaled_error_for_weight(dataset, np.asarray(errors[valid], dtype=float)))
        weight_parts.append(_dataset_statistical_weight(dataset, int(np.count_nonzero(valid))))
    if not signal_parts:
        raise ValueError("no valid point-list rows remain before compositing")
    result = rebin_nd(
        np.concatenate(signal_parts),
        np.concatenate(coords_parts, axis=0),
        data_errs=np.concatenate(error_parts),
        data_weights=np.concatenate(weight_parts),
        lower=lower,
        upper=upper,
        **_rebin_grid_kwargs(config, axes_config),
        fractional=bool(config.get("fractional", True)),
        normalize=True,
        mean_weighting=_rebin_mean_weighting(config),
        max_batch_bytes=_rebin_max_batch_bytes(config),
        progress_callback=progress_callback,
    )
    if result.binned_data is None or result.binned_data_errs is None or result.n_samples is None or result.bin_centers_list is None:
        raise RuntimeError("composite rebinning did not produce binned data")
    occupied = result.n_samples > 0.0
    center_grids = np.meshgrid(*result.bin_centers_list, indexing="ij")
    value_name = point_lists[0].channel(channel_label)["value"]
    error_name = point_lists[0].channel(channel_label).get("error") or f"{value_name}_error"
    columns = {name: grid[occupied] for name, grid in zip(coordinate_names, center_grids, strict=True)}
    columns[value_name] = np.asarray(result.binned_data, dtype=float)[occupied]
    columns[error_name] = np.asarray(result.binned_data_errs, dtype=float)[occupied]
    columns["n_samples"] = np.asarray(result.n_samples, dtype=float)[occupied]
    return PointListData(
        columns=columns,
        units={**{name: point_lists[0].unit(name) for name in coordinate_names}, value_name: point_lists[0].unit(value_name), error_name: point_lists[0].unit(error_name)},
        coordinate_names=coordinate_names,
        channels=[{"label": channel_label, "value": value_name, "error": error_name}],
        metadata={"composite": True, "source_group": group.name, "source_datasets": [dataset.name for dataset in datasets]},
        quantity_types={
            name: point_lists[0].quantity_type(name)
            for name in columns
            if name in point_lists[0].columns
        },
    )


def _effective_dataset_entries(
    group: DataGroup,
    node: DataGroup | DatasetGroup,
    *,
    use_composite: bool,
    force_rebin: bool,
    force_masks: bool,
    progress_callback: Any | None,
    include_disabled_groups: bool = True,
):
    if (
        isinstance(node, DatasetGroup)
        and not node.enabled
        and not include_disabled_groups
    ):
        return
    scope = _composite_scope(group, node)
    if use_composite and data_group_composite_enabled(scope):
        yield composite_dataset_entry(
            scope,
            force_rebin=force_rebin,
            progress_callback=progress_callback,
        )
        return
    if isinstance(node, DatasetGroup) and isinstance(node.metadata.get("mdevent"), dict):
        return
    yield from node.datasets
    for subgroup in node.subgroups:
        yield from _effective_dataset_entries(
            group,
            subgroup,
            use_composite=use_composite,
            force_rebin=force_rebin,
            force_masks=force_masks,
            progress_callback=progress_callback,
            include_disabled_groups=include_disabled_groups,
        )


def _composite_scopes(group: DataGroup):
    yield group
    for subgroup in group.iter_subgroups():
        yield _composite_scope(group, subgroup)


def slice_viewer_datasets(
    group: DataGroup,
    *,
    use_composite: bool = True,
    unmask_model: bool = False,
    force_rebin: bool = True,
    force_masks: bool = True,
    progress_callback: Any | None = None,
) -> tuple[list[MDHistoData], list[str]]:
    """Return data and labels for every dataset in the group tree, with shared masks."""

    data: list[MDHistoData] = []
    names: list[str] = []
    model_channels = current_model_channels(
        group,
        force_masks=force_masks,
        unmask_model=unmask_model,
    )
    entries = _effective_dataset_entries(
        group,
        group,
        use_composite=use_composite,
        force_rebin=force_rebin,
        force_masks=force_masks,
        progress_callback=progress_callback,
    )
    for dataset in entries:
        is_composite = bool(dataset.metadata.get("composite"))
        extra_masks = [] if is_composite else effective_dataset_masks(group, dataset)
        view_data = dataset_for_slice_viewer(
            dataset,
            extra_masks=extra_masks,
            force_rebin=force_rebin,
            force_masks=force_masks,
            progress_callback=progress_callback,
        )
        if view_data is not None:
            view_data = attach_fit_channels_to_view(
                group,
                dataset.name,
                view_data,
                fallback_payload=model_channels.get(dataset.name),
            )
            data.append(view_data)
            names.append(dataset.name)
    return data, names


def _waterfall_group_keys(group: DataGroup, names: list[str]) -> list[str]:
    """Return the immediate project data-group key for each viewer dataset."""

    by_name = {dataset.name: "root" for dataset in group.datasets}

    def visit(node: DatasetGroup, path: tuple[str, ...]) -> None:
        key = "/".join(path)
        for dataset in node.datasets:
            by_name[dataset.name] = key
        for subgroup in node.subgroups:
            visit(subgroup, (*path, subgroup.name))

    for subgroup in group.subgroups:
        visit(subgroup, (subgroup.name,))
    return [by_name.get(name, name) for name in names]


def dataset_for_slice_viewer(
    dataset: DatasetEntry,
    *,
    extra_masks: list[MaskSpec] | None = None,
    force_rebin: bool = True,
    force_masks: bool = True,
    progress_callback: Any | None = None,
) -> MDHistoData | PointListData | PointData4D | None:
    """Return a viewer-ready dataset, loading from source metadata if needed.

    ``extra_masks`` are masks inherited from ancestor dataset groups; they are
    applied ahead of the dataset's own masks.
    """

    result = _viewer_data_before_scale(
        dataset,
        extra_masks=extra_masks,
        force_rebin=force_rebin,
        force_masks=force_masks,
        progress_callback=progress_callback,
    )
    if result is None:
        return None
    scaled = _apply_dataset_scale(dataset, result)
    prepared = _apply_spectral_channel_view(dataset, scaled)
    return _with_viewer_dataset_metadata(dataset, prepared)


def _apply_spectral_channel_view(
    dataset: DatasetEntry,
    data: MDHistoData | PointListData | PointData4D,
) -> MDHistoData | PointListData | PointData4D:
    """Apply paired INS channels, falling back to the legacy kinematic path."""

    config = dataset.parameters.get(SPECTRAL_CHANNEL_CONFIG_KEY)
    if (
        isinstance(data, MDHistoData)
        and dataset.data_type in {"single_crystal_inelastic", "powder_inelastic"}
        and isinstance(config, dict)
    ):
        temperature = dataset.parameters.get("temperature", data.metadata.get("temperature"))
        return with_paired_spectral_channels(
            data,
            config,
            temperature_K=None if temperature in (None, "") else float(temperature),
        )
    return _apply_kinematic_normalization_to_view(dataset, data)


def _with_viewer_dataset_metadata(
    dataset: DatasetEntry,
    data: MDHistoData | PointListData | PointData4D,
) -> MDHistoData | PointListData | PointData4D:
    metadata = dict(getattr(data, "metadata", {}) or {})
    metadata["nfit_data_type"] = dataset.data_type
    metadata["nfit_dataset_kind"] = dataset.kind
    if isinstance(data, MDHistoData):
        return replace(data, metadata=metadata)
    if isinstance(data, PointListData):
        return PointListData(
            columns={name: np.array(values, dtype=float) for name, values in data.columns.items()},
            units=dict(data.units),
            coordinate_names=list(data.coordinate_names),
            channels=[dict(channel) for channel in data.channels],
            metadata=metadata,
            quantity_types=dict(data.quantity_types),
        )
    if isinstance(data, PointData4D):
        return data.with_updates(metadata=metadata)
    return data


def _kinematic_energy_metadata(
    dataset: DatasetEntry,
    data_metadata: dict[str, Any] | None = None,
) -> tuple[float | None, float | None]:
    """Find scalar incident/final energies recorded on a dataset or its data."""

    sources = (dataset.parameters, dataset.metadata, data_metadata or {})

    def value_for(names: tuple[str, ...]) -> float | None:
        for source in sources:
            if not isinstance(source, dict):
                continue
            for name in names:
                try:
                    value = float(source[name])
                except (KeyError, TypeError, ValueError):
                    continue
                if np.isfinite(value) and value > 0.0:
                    return value
        return None

    return (
        value_for(("incident_energy", "incident_energy_meV", "Ei", "ei")),
        value_for(("final_energy", "final_energy_meV", "Ef", "ef")),
    )


def _kinematic_kf_ki_factor(
    energy_transfer_meV: Any,
    *,
    incident_energy_meV: float | None,
    final_energy_meV: float | None,
) -> np.ndarray | None:
    """Return ``k_f/k_i`` for ``E = E_i - E_f``, if one energy is known."""

    if incident_energy_meV is None and final_energy_meV is None:
        return None
    energy = np.asarray(energy_transfer_meV, dtype=float)
    if incident_energy_meV is not None:
        ratio_sq = (float(incident_energy_meV) - energy) / float(incident_energy_meV)
    else:
        ratio_sq = float(final_energy_meV) / (float(final_energy_meV) + energy)
    factor = np.full(energy.shape, np.nan, dtype=float)
    np.sqrt(ratio_sq, out=factor, where=np.isfinite(ratio_sq) & (ratio_sq >= 0.0))
    return factor


def _apply_kinematic_normalization_to_view(
    dataset: DatasetEntry,
    data: MDHistoData | PointListData | PointData4D,
) -> MDHistoData | PointListData | PointData4D:
    """Normalize binned data to the cross-section ``k_f/k_i`` convention."""

    if bool(dataset.parameters.get(KINEMATIC_KF_KI_INCLUDED_KEY, True)):
        return data
    if isinstance(data, PointData4D):
        return _apply_kinematic_normalization_to_points(dataset, data)
    if not isinstance(data, MDHistoData):
        return data
    energy_dim = next(
        (index for index, axis in enumerate(data.axes) if axis.kind == "energy"),
        None,
    )
    if energy_dim is None:
        return data
    incident, final = _kinematic_energy_metadata(dataset, data.metadata)
    factor_1d = _kinematic_kf_ki_factor(
        data.axes[energy_dim].centers,
        incident_energy_meV=incident,
        final_energy_meV=final,
    )
    if factor_1d is None:
        return data
    shape = [1] * data.signal.ndim
    shape[energy_dim] = factor_1d.size
    factor = factor_1d.reshape(shape)
    metadata = dict(data.metadata)
    metadata["nfit_kinematic_kf_ki_normalized"] = True
    metadata["nfit_kinematic_kf_ki_source"] = "Ei" if incident is not None else "Ef"
    return replace(
        data,
        signal=np.asarray(data.signal, dtype=float) * factor,
        errors=np.asarray(data.errors, dtype=float) * np.abs(factor),
        metadata=metadata,
    )


def _apply_kinematic_normalization_to_points(
    dataset: DatasetEntry,
    points: PointData4D,
) -> PointData4D:
    """Return fit points in the selected kinematic convention."""

    if bool(dataset.parameters.get(KINEMATIC_KF_KI_INCLUDED_KEY, True)):
        return points
    if points.metadata.get("nfit_kinematic_kf_ki_normalized"):
        return points
    incident, final = _kinematic_energy_metadata(dataset, points.metadata)
    factor = _kinematic_kf_ki_factor(
        points.E,
        incident_energy_meV=incident,
        final_energy_meV=final,
    )
    if factor is None:
        return points
    metadata = dict(points.metadata)
    metadata["nfit_kinematic_kf_ki_normalized"] = True
    metadata["nfit_kinematic_kf_ki_source"] = "Ei" if incident is not None else "Ef"
    return points.with_updates(
        intensity=np.asarray(points.intensity, dtype=float) * factor,
        sigma=np.asarray(points.sigma, dtype=float) * np.abs(factor),
        metadata=metadata,
    )


KINEMATIC_KF_KI_INCLUDED_KEY = "kf_ki_included"


@dataclass
class FitDataBundle:
    """Fit-ready representations of one dataset.

    ``view`` is the masked, scaled data exactly as the data viewer shows it.
    ``points`` flattens every view point into :class:`PointData4D`; the point
    mask is ``False`` where the view masks a point, so the optimizer only sees
    unmasked data while the fitted model can still be evaluated everywhere.
    ``grid_shape`` reshapes point-ordered channel arrays back onto the MDHisto
    grid (``None`` for point lists).
    """

    dataset: DatasetEntry
    view: Any
    points: PointData4D
    grid_shape: tuple[int, ...] | None


def fit_data_bundle(
    group: DataGroup,
    dataset: DatasetEntry,
    *,
    force_rebin: bool = True,
    force_masks: bool = True,
    progress_callback: Any | None = None,
) -> FitDataBundle | None:
    """Build the fit-ready views of one dataset, or ``None`` if unsupported."""

    extra_masks = effective_dataset_masks(group, dataset)
    if dataset.scale_factor_vary:
        raw_view = _viewer_data_before_scale(
            dataset,
            extra_masks=extra_masks,
            force_rebin=force_rebin,
            force_masks=force_masks,
            progress_callback=progress_callback,
        )
        view = (
            _with_viewer_dataset_metadata(
                dataset,
                _apply_spectral_channel_view(dataset, raw_view),
            )
            if raw_view is not None
            else None
        )
    else:
        view = dataset_for_slice_viewer(
            dataset,
            extra_masks=extra_masks,
            force_rebin=force_rebin,
            force_masks=force_masks,
            progress_callback=progress_callback,
        )
    if isinstance(view, MDHistoData):
        points = _point_data_from_mdhisto_view(view)
    elif isinstance(view, PointData4D):
        points = view
    elif isinstance(view, PointListData) and dataset.data_type == "magnetization":
        points = _magnetization_point_data(view, group, dataset)
    elif isinstance(view, PointListData) and dataset.data_type == "heat_capacity":
        points = _heat_capacity_point_data(view, dataset)
    elif isinstance(view, PointListData):
        points = _point_data_from_point_list_view(view)
    else:
        return None
    points = _apply_sample_context_to_points(group, dataset, points)
    # Record the data type so evaluators can branch (e.g. bulk magnetization
    # vs inelastic intensity) without threading it through every call.
    metadata = dict(points.metadata)
    metadata.setdefault("data_type", dataset.data_type)
    points = points.with_updates(metadata=metadata)
    return FitDataBundle(
        dataset=dataset,
        view=view,
        points=points,
        grid_shape=view.shape if isinstance(view, MDHistoData) else None,
    )


def _field_direction_cartesian(group: DataGroup, dataset: DatasetEntry) -> np.ndarray:
    """Unit Cartesian direction of the applied field, defaulting to z-hat.

    Uses the direction stored in ``dataset.parameters["magnetic_field"]`` (uvw
    or hkl frame, oriented with the group lattice); falls back to the c*/z axis
    when no direction or lattice is available (an MPMS scan along the field).
    """

    payload = dataset.parameters.get("magnetic_field")
    lattice = group.lattice_parameters
    if (
        isinstance(payload, dict)
        and payload.get("direction") is not None
        and isinstance(lattice, dict)
        and all(key in lattice for key in ("a", "b", "c"))
    ):
        try:
            vector = magnetic_field_vector(
                1.0, payload["direction"], str(payload.get("frame", "uvw")), lattice
            )
            norm = float(np.linalg.norm(vector))
            if norm > 0:
                return np.asarray(vector, dtype=float) / norm
        except (TypeError, ValueError):
            pass
    return np.array([0.0, 0.0, 1.0])


# Column name fragments that identify the MPMS field sweep axis (in oersted).
_MPMS_FIELD_COLUMN_HINTS = ("magnetic field", "field")
_OERSTED_PER_TESLA = 1.0e4


def _magnetization_point_data(
    view: PointListData, group: DataGroup, dataset: DatasetEntry
) -> PointData4D:
    """Map an MPMS magnetization point list onto fit points.

    Magnetization carries no momentum transfer, so ``H=K=L=E=0``; the
    Temperature column becomes the per-point temperature and the Magnetic
    Field column (oersted) becomes the per-point Cartesian field in tesla,
    oriented along the dataset's field direction. The moment channel is the
    fitted intensity. Absolute-unit sample metadata is forwarded so the
    evaluator can pin the emu/mol normalization.
    """

    if not view.channel_labels:
        raise ValueError("magnetization dataset defines no moment channel")
    config = point_list_config(dataset)
    susc = config.get("susceptibility", {})
    preferred = (
        SUSCEPTIBILITY_CHANNEL_LABEL
        if susc.get("enabled") and SUSCEPTIBILITY_CHANNEL_LABEL in view.channel_labels
        else str(susc.get("moment") or view.channel_labels[0])
    )
    label = preferred if preferred in view.channel_labels else view.channel_labels[0]
    intensity = np.asarray(view.channel_values(label), dtype=float)
    errors = view.channel_errors(label)
    sigma_known = errors is not None
    sigma = (
        np.asarray(errors, dtype=float)
        if sigma_known
        else np.ones(intensity.shape, dtype=float)
    )
    n = intensity.size
    zeros = np.zeros(n, dtype=float)

    def _find_column(hints: tuple[str, ...]) -> tuple[str, np.ndarray] | None:
        for name in view.columns:
            lowered = name.strip().lower()
            if any(hint in lowered for hint in hints):
                return name, np.asarray(view.column(name), dtype=float)
        return None

    temperature_match = _find_column(("temperature",))
    field_match = _find_column(_MPMS_FIELD_COLUMN_HINTS)
    temperature = None if temperature_match is None else temperature_match[1]
    direction = _field_direction_cartesian(group, dataset)
    if field_match is not None:
        from .quantities import convert_quantity

        field_name, field_values = field_match
        field_tesla = convert_quantity(
            field_values, "magnetic_field", view.unit(field_name), "T"
        )
        magnetic_field = field_tesla[:, None] * direction[None, :]
    else:
        magnetic_field = None

    mask = np.isfinite(intensity) & np.isfinite(sigma)
    if sigma_known:
        mask &= sigma > 0.0

    metadata: dict[str, Any] = {
        "fit_channel": label,
        "sigma_known": sigma_known,
        "data_type": "magnetization",
        "quantity_type": view.channel_quantity_type(label),
        "unit": view.unit(view.channel(label)["value"]),
        "field_direction_cartesian": direction.tolist(),
    }
    for key in ("absolute_units", "sample_mass_mg", "molar_mass_g_mol"):
        if key in dataset.parameters:
            metadata[key] = dataset.parameters[key]
    return PointData4D(
        H=zeros, K=zeros, L=zeros, E=zeros,
        intensity=intensity, sigma=sigma, mask=mask,
        temperature=temperature if temperature is not None else dataset.parameters.get("temperature"),
        magnetic_field=magnetic_field,
        metadata=metadata,
    )


def _heat_capacity_point_data(view: PointListData, dataset: DatasetEntry) -> PointData4D:
    """Map a molar heat-capacity or C/T channel onto fit points."""

    config = point_list_config(dataset).get("heat_capacity", {})
    preferred = str(config.get("fit_channel", HEAT_CAPACITY_CHANNEL_LABEL))
    label = preferred if preferred in view.channel_labels else view.channel_labels[0]
    channel = view.channel(label)
    quantity_type = view.channel_quantity_type(label)
    if quantity_type not in {"heat_capacity", "heat_capacity_over_temperature"}:
        raise ValueError("heat-capacity fitting requires a molar C or C/T channel")
    temperature_name = str(config.get("temperature", ""))
    if temperature_name not in view.columns:
        temperature_name = next(
            (name for name in view.columns if "temp" in name.lower() and view.unit(name) == "K"),
            "",
        )
    if not temperature_name:
        raise ValueError("heat-capacity dataset requires a temperature column")
    temperature = np.asarray(view.column(temperature_name), dtype=float)
    intensity = np.asarray(view.channel_values(label), dtype=float)
    errors = view.channel_errors(label)
    sigma_known = errors is not None
    sigma = np.asarray(errors, dtype=float) if sigma_known else np.ones(intensity.shape)
    mask = np.isfinite(temperature) & np.isfinite(intensity) & np.isfinite(sigma)
    if sigma_known:
        mask &= sigma > 0.0
    zeros = np.zeros(intensity.shape, dtype=float)
    return PointData4D(
        H=zeros,
        K=zeros,
        L=zeros,
        E=temperature,
        intensity=intensity,
        sigma=sigma,
        mask=mask,
        temperature=temperature,
        metadata={
            "fit_coordinate_mapping": {"E": temperature_name},
            "fit_channel": label,
            "sigma_known": sigma_known,
            "data_type": "heat_capacity",
            "quantity_type": quantity_type,
            "unit": view.unit(channel["value"]),
        },
    )


def effective_dataset_temperature(
    group: DataGroup, dataset: DatasetEntry
) -> float | None:
    """Return the dataset temperature override in K, or ``None`` if unset.

    ``dataset.parameters["temperature"]`` takes precedence over any
    temperature carried by the imported data itself.
    """

    value = dataset.parameters.get("temperature")
    if value in (None, ""):
        return None
    return float(value)


def effective_dataset_field(
    group: DataGroup, dataset: DatasetEntry
) -> np.ndarray | None:
    """Return the dataset's applied field as a Cartesian Tesla 3-vector.

    Reads ``dataset.parameters["magnetic_field"]`` — a dict with
    ``magnitude_T`` (Tesla), ``direction`` (3-vector), and ``frame`` (``"uvw"``
    for direct-lattice directions, ``"hkl"`` for reciprocal). Returns ``None``
    when no field is set, the magnitude is zero, or the group has no lattice
    parameters to orient the direction with.
    """

    payload = dataset.parameters.get("magnetic_field")
    if not isinstance(payload, dict):
        return None
    try:
        magnitude = float(payload.get("magnitude_T", 0.0) or 0.0)
    except (TypeError, ValueError):
        return None
    if magnitude == 0.0:
        return None
    direction = payload.get("direction")
    lattice = group.lattice_parameters
    if (
        direction is None
        or not isinstance(lattice, dict)
        or not all(key in lattice for key in ("a", "b", "c"))
    ):
        return None
    try:
        return magnetic_field_vector(
            magnitude, direction, str(payload.get("frame", "uvw")), lattice
        )
    except (TypeError, ValueError):
        return None


def _apply_sample_context_to_points(
    group: DataGroup, dataset: DatasetEntry, points: PointData4D
) -> PointData4D:
    """Return fit points with per-dataset temperature, field, and lattice context.

    Physics models read the sample temperature from ``PointData4D.temperature``
    and the applied field from ``PointData4D.magnetic_field`` (Cartesian
    Tesla), and convert HKL to ``|Q|`` through ``rlu_to_inv_angstrom_matrix``
    metadata; all are supplied here so models never depend on GUI state.
    """

    # Per-point temperature/field (e.g. an MPMS sweep) is the physics axis and
    # must not be overwritten by a scalar sample-environment override.
    temperature = points.temperature
    magnetic_field = points.magnetic_field
    metadata = dict(points.metadata)
    if not isinstance(temperature, np.ndarray):
        override = effective_dataset_temperature(group, dataset)
        if override is not None:
            temperature = override
    if not (isinstance(magnetic_field, np.ndarray) and magnetic_field.ndim == 2):
        field_vector = effective_dataset_field(group, dataset)
        if field_vector is not None:
            magnetic_field = field_vector
    if (
        "rlu_to_inv_angstrom_matrix" not in metadata
        and isinstance(group.lattice_parameters, dict)
        and all(key in group.lattice_parameters for key in ("a", "b", "c"))
    ):
        lattice = group.lattice_parameters
        matrix = reciprocal_basis_from_lattice_parameters(
            float(lattice["a"]),
            float(lattice["b"]),
            float(lattice["c"]),
            float(lattice.get("alpha", 90.0)),
            float(lattice.get("beta", 90.0)),
            float(lattice.get("gamma", 90.0)),
        )
        metadata["lattice_parameters"] = {
            "a": float(lattice["a"]),
            "b": float(lattice["b"]),
            "c": float(lattice["c"]),
            "alpha": float(lattice.get("alpha", 90.0)),
            "beta": float(lattice.get("beta", 90.0)),
            "gamma": float(lattice.get("gamma", 90.0)),
            "angle_units": "degree",
            "include_2pi": True,
        }
        metadata["rlu_to_inv_angstrom_matrix"] = matrix.tolist()
    contextual = points.with_updates(
        temperature=temperature,
        magnetic_field=magnetic_field,
        metadata=metadata,
    )
    return _apply_kinematic_normalization_to_points(dataset, contextual)


def _point_data_from_mdhisto_view(data: MDHistoData) -> PointData4D:
    """Flatten a masked MDHisto view into fit points using axis roles."""

    coords = _mdhisto_coordinate_grids(data)
    zeros = np.zeros(data.shape, dtype=float)
    keep = ~np.asarray(data.mask, dtype=bool)
    keep &= mdhisto_measured_bins(data)
    metadata: dict[str, Any] = {
        "fit_coordinates": sorted(
            name for name in ("H", "K", "L", "E", "q_modulus") if name in coords
        ),
    }
    for key in (
        "oriented_lattice",
        "coordinate_units",
        "rlu_to_inv_angstrom_matrix",
        "nfit_kinematic_kf_ki_normalized",
        "nfit_kinematic_kf_ki_source",
        "signal_quantity_type",
        "signal_unit",
        "spectral_observable",
    ):
        if key in data.metadata:
            metadata[key] = data.metadata[key]
    if "signal_quantity_type" in metadata:
        metadata["quantity_type"] = metadata["signal_quantity_type"]
    if "signal_unit" in metadata:
        metadata["unit"] = metadata["signal_unit"]
    temperature = data.metadata.get("temperature")
    powder_q = coords.get("q_modulus")
    powder_only = powder_q is not None and not any(
        axis.role in {"h", "k", "l"} for axis in data.axes
    )
    if powder_only:
        metadata["coordinate_units"] = "1/angstrom"
        metadata["powder_q_modulus_axis"] = True
    return PointData4D(
        # PointData4D has a Cartesian-vector momentum slot. For powder data,
        # place |Q| on x and tag the coordinates as inverse angstroms so
        # q_modulus_inv_angstrom recovers the measured scalar without a lattice.
        H=(
            powder_q
            if powder_only
            else coords.get("H", zeros)
        ).ravel(),
        K=coords.get("K", zeros).ravel(),
        L=coords.get("L", zeros).ravel(),
        E=coords.get("E", zeros).ravel(),
        intensity=np.asarray(data.signal, dtype=float).ravel(),
        sigma=np.asarray(data.errors, dtype=float).ravel(),
        mask=keep.ravel(),
        temperature=float(temperature) if temperature is not None else None,
        metadata=metadata,
    )


def _point_data_from_point_list_view(data: PointListData) -> PointData4D:
    """Map a point-list view onto fit points.

    Columns named ``H``, ``K``, ``L``, or ``E`` (case-insensitive) become the
    matching fit coordinates. When no energy-like column exists, the first
    coordinate column is stored in ``E`` so one-dimensional models have an
    axis to work with; the mapping is recorded in the point metadata.
    """

    if not data.channel_labels:
        raise ValueError("point-list dataset defines no data channels")
    label = data.channel_labels[0]
    intensity = np.asarray(data.channel_values(label), dtype=float)
    errors = data.channel_errors(label)
    sigma_known = errors is not None
    sigma = (
        np.asarray(errors, dtype=float)
        if sigma_known
        else np.ones(intensity.shape, dtype=float)
    )

    columns_by_role: dict[str, np.ndarray] = {}
    mapping: dict[str, str] = {}
    powder_q_name: str | None = None
    for name in data.coordinate_names:
        role = name.strip().upper()
        if role in ("H", "K", "L", "E") and role not in columns_by_role:
            columns_by_role[role] = np.asarray(data.column(name), dtype=float)
            mapping[role] = name
        elif name.strip().lower() in {"q", "|q|", "q_modulus"}:
            powder_q_name = name
            columns_by_role["H"] = np.asarray(data.column(name), dtype=float)
            mapping["q_modulus"] = name
    if "E" not in columns_by_role and data.coordinate_names:
        first = data.coordinate_names[0]
        if first not in mapping.values():
            columns_by_role["E"] = np.asarray(data.column(first), dtype=float)
            mapping["E"] = first

    n = intensity.size
    zeros = np.zeros(n, dtype=float)
    mask = np.isfinite(intensity) & np.isfinite(sigma)
    if sigma_known:
        mask &= sigma > 0.0
    temperature: float | np.ndarray | None = None
    for name in data.columns:
        if name.strip().lower() == "temperature":
            temperature = np.asarray(data.column(name), dtype=float)
            break
    if temperature is None and data.metadata.get("temperature") is not None:
        temperature = float(data.metadata["temperature"])
    metadata: dict[str, Any] = {
        "fit_coordinate_mapping": mapping,
        "fit_channel": label,
        "sigma_known": sigma_known,
    }
    for key in (
        "spectral_observable",
        "signal_quantity_type",
        "signal_unit",
    ):
        if key in data.metadata:
            metadata[key] = data.metadata[key]
    if powder_q_name is not None:
        metadata["coordinate_units"] = "1/angstrom"
        metadata["powder_q_modulus_axis"] = True
    return PointData4D(
        H=columns_by_role.get("H", zeros),
        K=columns_by_role.get("K", zeros),
        L=columns_by_role.get("L", zeros),
        E=columns_by_role.get("E", zeros),
        intensity=intensity,
        sigma=sigma,
        mask=mask,
        temperature=temperature,
        metadata=metadata,
    )


def fit_dataset_inputs(
    group: DataGroup,
    *,
    purpose: str = "all",
    force_rebin: bool = True,
    force_masks: bool = True,
    progress_callback: Any | None = None,
) -> tuple[list[FitDatasetInput], dict[str, FitDataBundle]]:
    """Prepare datasets for fitting, visualization, or both.

    Disabled datasets, datasets inside disabled groups, and non-composite
    datasets with zero fit weight are visualization-only. They are omitted
    entirely when ``purpose="fit"`` and selected exclusively when
    ``purpose="visualization"``. ``purpose="overlay"`` includes both fitted
    and visualization-only datasets. The default retains enabled datasets for
    callers that prepare ordinary data selections.
    """

    if purpose not in {"all", "fit", "visualization", "overlay"}:
        raise ValueError(
            "dataset input purpose must be 'all', 'fit', 'visualization', or 'overlay'"
        )

    inputs: list[FitDatasetInput] = []
    bundles: dict[str, FitDataBundle] = {}
    entries = _effective_dataset_entries(
        group,
        group,
        use_composite=True,
        force_rebin=force_rebin,
        force_masks=force_masks,
        progress_callback=progress_callback,
        include_disabled_groups=purpose in {"visualization", "overlay"},
    )
    for dataset in entries:
        disabled = not _dataset_is_effectively_enabled(group, dataset)
        if disabled and purpose not in {"visualization", "overlay"}:
            continue
        is_composite = bool(dataset.metadata.get("composite"))
        fit_weight = 1.0 if is_composite else float(dataset.fit_weight)
        if not np.isfinite(fit_weight) or fit_weight < 0.0:
            raise ValueError(f"dataset {dataset.name!r} fit weight must be finite and non-negative")
        visualization_only = disabled or (not is_composite and fit_weight == 0.0)
        if purpose == "fit" and visualization_only:
            continue
        if purpose == "visualization" and not visualization_only:
            continue
        bundle = fit_data_bundle(
            group,
            dataset,
            force_rebin=force_rebin,
            force_masks=force_masks,
            progress_callback=progress_callback,
        )
        if bundle is None:
            continue
        inputs.append(
            FitDatasetInput(
                name=dataset.name,
                data=bundle.points,
                weight=0.0 if visualization_only else fit_weight,
                data_type=dataset.data_type or DEFAULT_DATA_TYPE,
                scale_value=(1.0 if is_composite else float(dataset.scale_factor)),
                scale_vary=(False if is_composite else bool(dataset.scale_factor_vary)),
                scale_group=(
                    None if is_composite else dataset.scale_factor_group
                ),
            )
        )
        bundles[dataset.name] = bundle
    return inputs, bundles


_OPTIMIZER_KWARG_NAMES = (
    "max_nfev",
    "xtol",
    "ftol",
    "gtol",
    "loss",
    "f_scale",
    "finite_difference_workers",
)


def _optimizer_kwargs(optimizer_config: dict[str, Any] | None) -> dict[str, Any]:
    config = optimizer_config if isinstance(optimizer_config, dict) else {}
    kwargs: dict[str, Any] = {
        "finite_difference_workers": int(
            config.get("finite_difference_workers", -1)
        )
    }
    for name in _OPTIMIZER_KWARG_NAMES:
        value = config.get(name)
        if value in (None, ""):
            continue
        if name in {"max_nfev", "finite_difference_workers"}:
            kwargs[name] = int(value)
        elif name == "loss":
            kwargs[name] = str(value)
        else:
            kwargs[name] = float(value)
    init_config = config.get("initialization")
    if isinstance(init_config, dict) and init_config.get("enabled", False):
        kwargs["initialization"] = {
            key: value for key, value in init_config.items() if key != "enabled"
        }
        kwargs["initialization"].setdefault("method", "differential_evolution")
    return kwargs


def _covariance_mode(optimizer_config: dict[str, Any] | None) -> str:
    if not isinstance(optimizer_config, dict):
        return "absolute"
    mode = str(optimizer_config.get("covariance_mode", "absolute"))
    if mode not in {"absolute", "residual"}:
        raise ValueError("covariance_mode must be 'absolute' or 'residual'")
    return mode


def _sampler_config(optimizer_config: dict[str, Any] | None) -> SamplerConfig | None:
    if not isinstance(optimizer_config, dict):
        return None
    sampler = optimizer_config.get("sampler")
    if not isinstance(sampler, dict) or not sampler.get("enabled", False):
        return None
    return SamplerConfig(
        method=str(sampler.get("method", "emcee")),
        n_walkers=_optional_int(sampler.get("n_walkers")),
        n_steps=_optional_int(sampler.get("n_steps")) or 1000,
        burn_in=int(sampler.get("burn_in", 0) or 0),
        thin=max(1, int(sampler.get("thin", 1) or 1)),
        random_seed=_optional_int(sampler.get("random_seed")),
        kwargs={
            **(dict(sampler.get("kwargs", {})) if isinstance(sampler.get("kwargs"), dict) else {}),
            **(
                {"workers": int(sampler.get("workers"))}
                if sampler.get("workers") not in (None, "")
                else {}
            ),
        },
    )


def _optional_int(value: Any) -> int | None:
    if value in (None, ""):
        return None
    return int(value)


def read_isaw_ub(path: str | Path) -> tuple[np.ndarray, dict[str, float]]:
    """Read an ISAW ``.mat`` file; its first three rows store ``UB.T``."""

    rows = []
    for line in Path(path).read_text(encoding="utf-8").splitlines():
        values = line.split()
        if values:
            rows.append([float(value) for value in values])
    if len(rows) < 4 or any(len(row) < 3 for row in rows[:3]) or len(rows[3]) < 6:
        raise ValueError("ISAW UB files require three matrix rows and one six-value lattice row")
    ub = np.asarray([row[:3] for row in rows[:3]], dtype=float).T
    lattice = dict(zip(("a", "b", "c", "alpha", "beta", "gamma"), rows[3][:6], strict=True))
    if not np.all(np.isfinite(ub)) or abs(np.linalg.det(ub)) < 1e-14:
        raise ValueError("ISAW UB matrix must be finite and invertible")
    return ub, lattice


def write_isaw_ub(path: str | Path, ub: Any, lattice: dict[str, Any]) -> None:
    """Write UB using the transposed IPNS/ISAW matrix convention."""

    matrix = np.asarray(ub, dtype=float)
    if matrix.shape != (3, 3) or not np.all(np.isfinite(matrix)):
        raise ValueError("UB must be a finite 3 x 3 matrix")
    names = ("a", "b", "c", "alpha", "beta", "gamma")
    values = [float(lattice[name]) for name in names]
    lines = [" ".join(f"{value: .8f}" for value in row) for row in matrix.T]
    alpha, beta, gamma = np.deg2rad(values[3:6])
    volume = values[0] * values[1] * values[2] * np.sqrt(
        max(1.0 + 2.0 * np.cos(alpha) * np.cos(beta) * np.cos(gamma)
            - np.cos(alpha) ** 2 - np.cos(beta) ** 2 - np.cos(gamma) ** 2, 0.0)
    )
    lines.append(" ".join(f"{value:11.4f}" for value in [*values, volume]))
    lines.append(" ".join(f"{0.0:11.4f}" for _ in range(7)))
    Path(path).write_text("\n".join(lines) + "\n", encoding="utf-8")


def ub_from_lattice_orientation(lattice: dict[str, Any], u: Any, v: Any) -> np.ndarray:
    """Build an IPNS-frame UB with ``u`` along beam x and ``u-v`` plane horizontal."""

    basis = reciprocal_basis_from_lattice_parameters(
        *(float(lattice[name]) for name in ("a", "b", "c", "alpha", "beta", "gamma"))
    ) / (2.0 * np.pi)
    q_u = basis @ np.asarray(u, dtype=float)
    q_v = basis @ np.asarray(v, dtype=float)
    if np.linalg.norm(q_u) <= 1e-14 or np.linalg.norm(np.cross(q_u, q_v)) <= 1e-14:
        raise ValueError("u must be nonzero and u/v must define a plane")
    x_axis = q_u / np.linalg.norm(q_u)
    z_axis = np.cross(q_u, q_v)
    z_axis /= np.linalg.norm(z_axis)
    y_axis = np.cross(z_axis, x_axis)
    return np.vstack((x_axis, y_axis, z_axis)) @ basis


class UBSetupDialog:
    """Reusable lattice/orientation editor for single-crystal data scopes."""

    def __init__(self, parent: Any, *, ub: Any, lattice: dict[str, Any] | None, u: Any, v: Any):
        from PySide6 import QtWidgets

        self.dialog = QtWidgets.QDialog(parent)
        self.dialog.setWindowTitle("UB setup")
        self.dialog.setMinimumWidth(620)
        outer = QtWidgets.QVBoxLayout(self.dialog)
        form = QtWidgets.QGridLayout()
        self.lattice_edits = {}
        defaults = {"a": 1.0, "b": 1.0, "c": 1.0, "alpha": 90.0, "beta": 90.0, "gamma": 90.0}
        values = {**defaults, **(lattice or {})}
        for index, name in enumerate(("a", "b", "c", "alpha", "beta", "gamma")):
            row, column = divmod(index, 3)
            form.addWidget(QtWidgets.QLabel(name), row, column * 2)
            edit = QtWidgets.QLineEdit(_format_number(values[name]))
            edit.setObjectName(f"ub_lattice_{name}")
            edit.setToolTip("Unit-cell length in angstrom." if index < 3 else "Unit-cell angle in degrees.")
            form.addWidget(edit, row, column * 2 + 1)
            self.lattice_edits[name] = edit
        self.orientation_edits = {}
        for vector_row, (name, vector) in enumerate((("u", u), ("v", v)), start=2):
            for component, value in enumerate(np.asarray(vector, dtype=float).reshape(3)):
                label = f"{name}{'xyz'[component]}"
                form.addWidget(QtWidgets.QLabel(label), vector_row, component * 2)
                edit = QtWidgets.QLineEdit(_format_number(value))
                edit.setObjectName(f"ub_orientation_{name}_{component}")
                edit.setToolTip("Reciprocal-lattice orientation vector. u points along the incident beam (+x); u and v define the horizontal plane, with +z vertical.")
                form.addWidget(edit, vector_row, component * 2 + 1)
                self.orientation_edits[(name, component)] = edit
        outer.addLayout(form)
        source_row = QtWidgets.QHBoxLayout()
        for text, slot in (("UB from NeXus", self._load_nexus), ("UB from ISAW", self._load_isaw), ("Calculate from lattice and u/v", self._calculate)):
            button = QtWidgets.QPushButton(text)
            button.setToolTip("Load orientation metadata directly from a NeXus file." if "NeXus" in text else "Read or calculate the UB matrix using the displayed convention.")
            button.clicked.connect(slot)
            source_row.addWidget(button)
        outer.addLayout(source_row)
        outer.addWidget(QtWidgets.QLabel("UB matrix (maps column [h,k,l] to Q' in inverse angstrom)"))
        self.matrix_table = QtWidgets.QTableWidget(3, 3)
        self.matrix_table.setObjectName("ub_matrix_table")
        self.matrix_table.horizontalHeader().setVisible(False)
        self.matrix_table.verticalHeader().setVisible(False)
        self.matrix_table.setFixedHeight(132)
        outer.addWidget(self.matrix_table)
        self._set_matrix(np.asarray(ub, dtype=float))
        buttons = QtWidgets.QDialogButtonBox(QtWidgets.QDialogButtonBox.StandardButton.Apply | QtWidgets.QDialogButtonBox.StandardButton.Cancel)
        save = buttons.addButton("Save ISAW", QtWidgets.QDialogButtonBox.ButtonRole.ActionRole)
        save.setToolTip("Save a .mat file with UB transposed on disk, using the IPNS x-beam/z-vertical convention.")
        save.clicked.connect(self._save_isaw)
        buttons.button(QtWidgets.QDialogButtonBox.StandardButton.Apply).clicked.connect(self._accept)
        buttons.rejected.connect(self.dialog.reject)
        outer.addWidget(buttons)
        self.result = None

    def exec(self):
        return self.dialog.exec()

    def _lattice(self):
        return {name: float(edit.text()) for name, edit in self.lattice_edits.items()}

    def _vector(self, name):
        return np.asarray([float(self.orientation_edits[(name, index)].text()) for index in range(3)])

    def _matrix(self):
        return np.asarray([[float(self.matrix_table.item(row, column).text()) for column in range(3)] for row in range(3)])

    def _set_matrix(self, matrix):
        from PySide6 import QtWidgets
        for row in range(3):
            for column in range(3):
                self.matrix_table.setItem(row, column, QtWidgets.QTableWidgetItem(f"{matrix[row, column]:.8g}"))

    def _calculate(self):
        from PySide6 import QtWidgets
        try:
            self._set_matrix(ub_from_lattice_orientation(self._lattice(), self._vector("u"), self._vector("v")))
        except Exception as exc:
            QtWidgets.QMessageBox.warning(self.dialog, "UB setup", f"Could not calculate UB:\n{exc}")

    def _load_isaw(self):
        from PySide6 import QtWidgets
        path, _ = QtWidgets.QFileDialog.getOpenFileName(self.dialog, "Load ISAW UB", "", "ISAW matrix (*.mat);;All files (*)")
        if not path:
            return
        try:
            matrix, lattice = read_isaw_ub(path)
            self._set_matrix(matrix)
            for name, value in lattice.items():
                self.lattice_edits[name].setText(_format_number(value))
        except Exception as exc:
            QtWidgets.QMessageBox.warning(self.dialog, "UB setup", f"Could not read ISAW file:\n{exc}")

    def _load_nexus(self):
        from PySide6 import QtWidgets
        path, _ = QtWidgets.QFileDialog.getOpenFileName(self.dialog, "Load UB from NeXus", "", "NeXus/HDF5 (*.nxs *.h5 *.hdf5);;All files (*)")
        if not path:
            return
        try:
            try:
                info = inspect_mdevent_workspace(path)
                matrix = info.ub_matrix
                lattice = info.lattice_parameters
            except Exception as mdevent_error:
                imported = load_mantid_mdhisto_nxs(path, copy_metadata=True)
                matrix = _dataset_ub_for_editor(imported.metadata)
                lattice = imported.metadata.get("lattice_parameters")
                if matrix is None:
                    raise ValueError(
                        "NeXus file does not contain a UB/orientation matrix"
                    ) from mdevent_error
            self._set_matrix(np.asarray(matrix, dtype=float))
            for name, value in (lattice or {}).items():
                if name not in self.lattice_edits:
                    continue
                self.lattice_edits[name].setText(_format_number(value))
        except Exception as exc:
            QtWidgets.QMessageBox.warning(self.dialog, "UB setup", f"Could not read NeXus orientation:\n{exc}")

    def _save_isaw(self):
        from PySide6 import QtWidgets
        path, _ = QtWidgets.QFileDialog.getSaveFileName(self.dialog, "Save ISAW UB", "UB.mat", "ISAW matrix (*.mat)")
        if path:
            try:
                write_isaw_ub(path, self._matrix(), self._lattice())
            except Exception as exc:
                QtWidgets.QMessageBox.warning(self.dialog, "UB setup", f"Could not save ISAW file:\n{exc}")

    def _accept(self):
        from PySide6 import QtWidgets
        try:
            matrix = self._matrix()
            if matrix.shape != (3, 3) or not np.all(np.isfinite(matrix)) or abs(np.linalg.det(matrix)) < 1e-14:
                raise ValueError("UB matrix must be finite and invertible")
            self.result = {"ub_matrix": matrix.tolist(), "lattice_parameters": self._lattice(), "u": self._vector("u").tolist(), "v": self._vector("v").tolist()}
        except Exception as exc:
            QtWidgets.QMessageBox.warning(self.dialog, "UB setup", f"Invalid UB setup:\n{exc}")
            return
        self.dialog.accept()


def perform_group_fit(
    group: DataGroup,
    *,
    optimizer_config: dict[str, Any] | None = None,
    progress_callback: Any | None = None,
) -> dict[str, Any]:
    """Fit the group's enabled model components to its enabled datasets.

    Masks, active/inactive datasets, fit weights, and scale factors are all
    honored because the fit points come from the same prepared views the data
    viewer shows. Optimized parameter values are written back to the model
    components, and per-dataset fit/residual channels are evaluated once over
    each dataset's full view so they can be stored with the fit result.
    """

    components = [
        model for model in group.models.values() if isinstance(model, ModelComponentSpec)
    ]
    if not any(component.enabled for component in components):
        raise ValueError("the data group has no enabled model components")
    progress_events: list[dict[str, Any]] = []

    def record_progress(event: dict[str, Any]) -> None:
        if len(progress_events) < 200:
            progress_events.append(_progress_event_summary(event))
        if progress_callback is not None:
            progress_callback(event)

    inputs, bundles = fit_dataset_inputs(
        group,
        purpose="fit",
        progress_callback=record_progress,
    )
    if not inputs:
        raise ValueError("no enabled positive-weight dataset could be prepared for fitting")

    compiled = compile_fit_problem(components, inputs, description=group.name)
    config = OptimizationConfig(
        covariance_mode=_covariance_mode(optimizer_config),
        kwargs=_optimizer_kwargs(optimizer_config),
    )

    result = fit_problem_least_squares(
        compiled.problem,
        config=config,
        progress_callback=record_progress,
    )
    sampler_result: SamplingResult | None = None
    sampler_cancelled = False
    sampler = None if result.cancelled else _sampler_config(optimizer_config)
    if sampler is not None:
        try:
            sampler_result = sample_problem_parameters(
                compiled.problem,
                sampler,
                initial_params=result.params,
                require_positive_sigma=config.require_positive_sigma,
                progress_callback=record_progress,
            )
        except SamplingCancelled as exc:
            sampler_result = exc.result
            sampler_cancelled = True
    _write_back_fitted_parameters(group, components, compiled, result)
    channels = _fit_channels_from_result(compiled, result, bundles)
    visualization_error = None
    visualization_names: list[str] = []
    try:
        visualization_channels = _visualization_only_channels(
            group,
            components,
            progress_callback=None if result.cancelled else record_progress,
        )
        visualization_names = list(visualization_channels)
        channels.update(visualization_channels)
    except Exception as exc:
        # A plotting-only dataset must never turn a completed optimization into
        # a failed fit. Preserve the fit and record the post-fit failure.
        visualization_error = str(exc)
    goodness: dict[str, Any] = {
        "status": (
            "cancelled"
            if result.cancelled or sampler_cancelled
            else ("converged" if result.success else "not converged")
        ),
        "message": (
            "emcee posterior sampling cancelled; partial posterior samples were saved."
            if sampler_cancelled
            else result.message
        ),
        "chi2": float(result.chi2),
        "reduced_chi2": float(result.reduced_chi2),
        "n_points": int(sum(result.dataset_sizes.values())),
        "n_variables": len(result.variable_names),
        "degrees_of_freedom": int(
            sum(result.dataset_sizes.values()) - len(result.variable_names)
        ),
        "parameters": {name: float(value) for name, value in result.params.items()},
        "stderr": (
            {name: float(value) for name, value in result.stderr.items()}
            if result.stderr
            else {}
        ),
        "covariance": _matrix_summary(result.covariance, result.variable_names),
        "covariance_mode": result.covariance_mode,
        "covariance_scale_factor": float(result.covariance_scale_factor),
        "dataset_chi2": {name: float(value) for name, value in result.dataset_chi2.items()},
        "dataset_reduced_chi2": {
            name: float(value) for name, value in result.dataset_reduced_chi2.items()
        },
        "dataset_n_points": {
            name: int(size) for name, size in result.dataset_sizes.items()
        },
        "skipped_datasets": list(compiled.skipped_datasets),
    }
    limit_hits = _fit_parameter_limit_hits(compiled.problem.parameter_specs, result.params)
    if limit_hits:
        goodness["parameters_at_limits"] = limit_hits
    metadata: dict[str, Any] = {}
    if visualization_names:
        metadata["visualization_only_datasets"] = visualization_names
    if visualization_error:
        metadata["visualization_only_error"] = visualization_error
    parameter_labels = _fit_parameter_labels_from_components(components, compiled, result.variable_names)
    if parameter_labels:
        metadata["parameter_labels"] = parameter_labels
    diagnostics = _fit_diagnostics_from_result(compiled, result, bundles, components)
    if diagnostics:
        metadata["diagnostics"] = diagnostics
    if progress_events:
        metadata["progress_log"] = progress_events
    if sampler_result is not None:
        posterior = _posterior_summary(sampler_result)
        goodness["posterior"] = posterior
        metadata["posterior_samples"] = _sampling_result_to_dict(sampler_result)
    return {
        "result": result,
        "compiled": compiled,
        "goodness": goodness,
        "channels": channels,
        "metadata": metadata,
    }


def _fit_parameter_limit_hits(specs: Any, params: dict[str, Any]) -> list[dict[str, Any]]:
    """Return optimized parameters that finish at or effectively pin a bound."""

    hits: list[dict[str, Any]] = []
    for spec in specs:
        if not bool(getattr(spec, "vary", False)):
            continue
        name = str(getattr(spec, "name", ""))
        if name not in params:
            continue
        try:
            value = float(params[name])
        except (TypeError, ValueError):
            continue
        lower = getattr(spec, "min", None)
        upper = getattr(spec, "max", None)
        for side, bound, other_bound in (
            ("lower", lower, upper),
            ("upper", upper, lower),
        ):
            if bound is None:
                continue
            try:
                bound_value = float(bound)
            except (TypeError, ValueError):
                continue
            if np.isfinite(bound_value) and _parameter_is_at_bound(
                value, bound_value, other_bound
            ):
                hits.append({"name": name, "side": side, "bound": bound_value})
                break
    return hits


def _parameter_is_at_bound(
    value: Any,
    bound: Any,
    other_bound: Any = None,
) -> bool:
    """Return whether a fitted value is effectively pinned to a finite bound.

    For two-sided bounds, proximity is measured against the allowed interval.
    This catches optimizer solutions that stop very close to a boundary without
    requiring bit-for-bit equality. One-sided bounds retain a small
    scale-aware numerical tolerance.
    """

    try:
        value_float = float(value)
        bound_float = float(bound)
    except (TypeError, ValueError):
        return False
    if not np.isfinite(value_float) or not np.isfinite(bound_float):
        return False
    tolerance = 1.0e-10 * max(1.0, abs(bound_float))
    try:
        other_float = float(other_bound)
    except (TypeError, ValueError):
        other_float = np.nan
    if np.isfinite(other_float):
        span = abs(other_float - bound_float)
        if span > 0.0:
            tolerance = max(tolerance, 1.0e-4 * span)
    return bool(abs(value_float - bound_float) <= tolerance)


def _fit_limit_hits_from_goodness(goodness: Any) -> dict[str, dict[str, Any]]:
    """Index saved fit-bound warnings by parameter name for GUI rendering."""

    if not isinstance(goodness, dict):
        return {}
    raw = goodness.get("parameters_at_limits")
    if not isinstance(raw, list):
        return {}
    return {
        str(hit["name"]): dict(hit)
        for hit in raw
        if isinstance(hit, dict) and isinstance(hit.get("name"), str)
    }


def _fit_limit_warning_text(limit_hits: Any) -> str:
    hits = _fit_limit_hits_from_goodness({"parameters_at_limits": limit_hits})
    if not hits:
        return ""
    descriptions = [f"{name} ({hit.get('side', 'bound')})" for name, hit in hits.items()]
    return "Warning: fit parameter limit reached: " + ", ".join(descriptions) + "."


# Overlay recomputation is dominated by rebuilding the fit bundles (rebinning
# the full volume) and the RPA phase geometry. Neither depends on model
# *parameter values*, so both are cached per group and reused when only a
# parameter changes -- turning an O(10 s) rebuild on every edit into an O(0.1 s)
# re-evaluation. The cache is keyed on a structural signature that excludes
# parameter values (see _overlay_cache_signature).
_MODEL_OVERLAY_CACHE: OrderedDict[int, dict[str, Any]] = OrderedDict()
_MODEL_OVERLAY_CACHE_LIMIT = 6
_MODEL_OVERLAY_CACHE_MAX_BYTES = 256 * 1024**2


def _overlay_cache_signature(group: DataGroup) -> str:
    """Structural fingerprint of a group's overlay inputs, excluding values.

    Everything that changes the bundles (data identity, masks, rebin,
    temperature, scale) or the model structure (types, config, sharing,
    applies-to, enablement) is included; per-parameter *values* are excluded so
    editing e.g. ``J2`` reuses the cached bundles and geometry.
    """

    datasets: list[Any] = []
    for dataset in group.iter_datasets():
        data_metadata = getattr(dataset.data, "metadata", {})
        data_rebin = data_metadata.get("rebin") if isinstance(data_metadata, dict) else None
        datasets.append(
            [
                dataset.name,
                bool(dataset.enabled),
                dataset.data_type,
                dataset.kind,
                dataset.id,
                dataset.data_cache_token,
                float(dataset.fit_weight),
                float(dataset.scale_factor),
                bool(dataset.scale_factor_vary),
                dataset.scale_factor_group,
                json.dumps(dataset.parameters, sort_keys=True, default=str),
                # Rebin settings and the output basis stored on a materialized
                # histogram both change physical HKLE coordinates. Either one
                # must rebuild cached fit points and model geometry.
                json.dumps(dataset.parameters.get(DATASET_REBIN_KEY), sort_keys=True, default=str),
                json.dumps(data_rebin, sort_keys=True, default=str),
                effective_dataset_temperature(group, dataset),
                [
                    [mask.type, bool(mask.enabled), bool(mask.invert), bool(mask.additive),
                     json.dumps(mask.parameters, sort_keys=True, default=str)]
                    for mask in effective_dataset_masks(group, dataset)
                ],
            ]
        )
    models: list[Any] = []
    for model in group.models.values():
        if not isinstance(model, ModelComponentSpec):
            continue
        models.append(
            [
                model.name,
                model.type,
                bool(model.enabled),
                list(model.applies_to) if model.applies_to is not None else None,
                json.dumps(model.config, sort_keys=True, default=str),
                json.dumps(model.sharing, sort_keys=True, default=str),
                json.dumps(model.constraints, sort_keys=True, default=str),
            ]
        )
    payload = [
        datasets,
        [
            [path, bool(subgroup.enabled)]
            for path, subgroup in _dataset_group_paths(group)
        ],
        models,
        json.dumps(group.lattice_parameters, sort_keys=True, default=str),
        group.spacegroup,
    ]
    return json.dumps(payload, sort_keys=True, default=str)


def _overlay_current_params(
    group: DataGroup, compiled: CompiledFitProblem
) -> dict[str, float]:
    """Map current component parameter values onto a compiled problem's specs.

    The compiled problem may be cached (its spec values are stale), so read the
    live values from the components through the instance bookkeeping. Derived
    (constraint) parameters keep their compiled default.
    """

    params = {spec.name: float(spec.value) for spec in compiled.problem.parameter_specs}
    for instance in compiled.parameter_instances.values():
        if instance.component == "dataset" and instance.parameter == "scale_factor":
            if not instance.datasets:
                continue
            try:
                dataset = group.get_dataset(instance.datasets[0])
            except KeyError:
                continue
            params[instance.name] = float(dataset.scale_factor)
            continue
        component = group.models.get(instance.component)
        if not isinstance(component, ModelComponentSpec):
            continue
        fitted_values = component.metadata.get("fitted_values", {})
        per_scope = (
            fitted_values.get(instance.parameter, {})
            if isinstance(fitted_values, dict)
            else {}
        )
        value = (
            per_scope.get(instance.scope)
            if instance.scope != "global" and isinstance(per_scope, dict)
            else component.parameters.get(instance.parameter)
        )
        if value is None:
            value = component.parameters.get(instance.parameter)
        if value is None:
            continue
        try:
            params[instance.name] = float(value)
        except (TypeError, ValueError):
            continue
    return params


def current_model_channels(
    group: DataGroup,
    *,
    force_masks: bool = False,
    unmask_model: bool = False,
) -> dict[str, dict[str, Any]]:
    """Evaluate enabled model components at their current parameter values.

    When ``unmask_model`` is true, model values are extrapolated over every
    finite HKLE coordinate in the prepared dataset rather than only fit-valid
    data points. Residuals are likewise retained wherever the underlying data
    and uncertainty are finite.
    """

    components = [
        model for model in group.models.values() if isinstance(model, ModelComponentSpec)
    ]
    if not any(component.enabled for component in components):
        _MODEL_OVERLAY_CACHE.pop(id(group), None)
        return {}
    signature = _overlay_cache_signature(group)
    cached = _MODEL_OVERLAY_CACHE.get(id(group))
    pending_masks = any(_dataset_mask_is_stale(dataset) for dataset in group.iter_datasets())
    if (
        cached is not None
        and cached["signature"] == signature
        and not (force_masks and pending_masks)
    ):
        _MODEL_OVERLAY_CACHE.move_to_end(id(group))
        compiled = cached["compiled"]
        bundles = cached["bundles"]
        subsets = cached["subsets"]
    else:
        inputs, bundles = fit_dataset_inputs(
            group,
            purpose="overlay",
            force_rebin=False,
            force_masks=force_masks,
        )
        if not inputs:
            _MODEL_OVERLAY_CACHE.pop(id(group), None)
            return {}
        try:
            compiled = compile_fit_problem(components, inputs, description=group.name)
        except Exception:
            return {}
        subsets = {}
        # Lazy loading during fit-data preparation increments dataset revisions.
        signature = _overlay_cache_signature(group)
        _lru_store(
            _MODEL_OVERLAY_CACHE,
            id(group),
            {
                "signature": signature,
                "compiled": compiled,
                "bundles": bundles,
                "subsets": subsets,
            },
            _MODEL_OVERLAY_CACHE_LIMIT,
            _MODEL_OVERLAY_CACHE_MAX_BYTES,
        )
    try:
        params = _overlay_current_params(group, compiled)
        return _fit_channels_from_params(
            compiled,
            params,
            bundles,
            subset_cache=subsets,
            evaluate_masked=unmask_model,
        )
    except Exception:
        return {}


def evaluate_current_state_model(
    group: DataGroup,
    current: FitTimelineEntry | None = None,
) -> FitTimelineEntry:
    """Evaluate live model channels and record them on a Current state entry."""

    ensure_fit_history(group)
    if current is None or current.kind != "current":
        current = _top_level_current_state_entry(group)
    if current is None:
        source = _last_result_at_level(group.fits) or group.fits[0]
        current = current_state_fit_entry(group, source)
        group.fits.append(current)
    error = ""
    try:
        channels = current_model_channels(group)
    except Exception as exc:
        channels = {}
        error = str(exc)
    current.channels = channels
    current.metadata = dict(current.metadata)
    current.metadata["model_evaluation_status"] = (
        "failed"
        if error
        else "evaluated" if channels else "no compatible model prediction"
    )
    current.metadata["model_evaluation_datasets"] = sorted(channels)
    if error:
        current.metadata["model_evaluation_error"] = error
    else:
        current.metadata.pop("model_evaluation_error", None)
    _set_fit_current_snapshot(current, group)
    return current


def _compiled_problem_for_fit_entry(
    group: DataGroup,
    fit_entry: FitTimelineEntry,
) -> CompiledFitProblem:
    """Compile the fitting problem from a stored fit snapshot without leaving state changed."""

    current_snapshot = snapshot_data_group_state(group)
    try:
        if fit_entry.snapshot:
            restore_data_group_state(group, fit_entry.snapshot)
        components = [
            model for model in group.models.values() if isinstance(model, ModelComponentSpec)
        ]
        inputs, _bundles = fit_dataset_inputs(group, purpose="fit")
        if not inputs:
            raise ValueError("no enabled dataset could be prepared for posterior sampling")
        return compile_fit_problem(components, inputs, description=group.name)
    finally:
        restore_data_group_state(group, current_snapshot)


def _matrix_summary(matrix: Any, names: list[str]) -> dict[str, Any]:
    if matrix is None:
        return {}
    arr = np.asarray(matrix, dtype=float)
    summary: dict[str, Any] = {"variables": list(names), "shape": list(arr.shape)}
    if arr.ndim == 2 and arr.shape[0] == arr.shape[1] and arr.shape[0] == len(names):
        summary["matrix"] = arr.tolist()
        summary["diagonal"] = {name: float(arr[index, index]) for index, name in enumerate(names)}
        denom = np.sqrt(np.outer(np.diag(arr), np.diag(arr)))
        with np.errstate(divide="ignore", invalid="ignore"):
            corr = np.divide(arr, denom, out=np.zeros_like(arr), where=denom > 0)
        summary["correlation"] = {
            name: {
                other: float(corr[i, j])
                for j, other in enumerate(names)
            }
            for i, name in enumerate(names)
        }
    return summary


def _progress_event_summary(event: dict[str, Any]) -> dict[str, Any]:
    summary: dict[str, Any] = {
        "stage": str(event.get("stage", "fit")),
        "message": str(event.get("message", "")),
    }
    for key in ("iteration", "total", "cost", "convergence", "elapsed_seconds", "seconds_per_step"):
        if event.get(key) is not None:
            value = event[key]
            summary[key] = (
                float(value)
                if key in {"cost", "convergence", "elapsed_seconds", "seconds_per_step"}
                else int(value)
            )
    params = event.get("parameters")
    if isinstance(params, dict):
        summary["parameters"] = {name: float(value) for name, value in params.items()}
    return summary


def _posterior_summary(result: SamplingResult) -> dict[str, Any]:
    samples = np.asarray(result.samples, dtype=float)
    summary: dict[str, Any] = dict(result.metadata)
    if samples.size == 0:
        summary["samples"] = 0
        return summary
    summary["samples"] = int(samples.shape[0])
    percentiles = np.percentile(samples, [16, 50, 84], axis=0)
    summary["parameters"] = {
        name: {
            "p16": float(percentiles[0, index]),
            "median": float(percentiles[1, index]),
            "p84": float(percentiles[2, index]),
        }
        for index, name in enumerate(result.variable_names)
    }
    if samples.shape[1] > 1:
        corr = np.corrcoef(samples, rowvar=False)
        summary["correlation"] = {
            name: {
                other: float(corr[i, j])
                for j, other in enumerate(result.variable_names)
            }
            for i, name in enumerate(result.variable_names)
        }
    return summary


def _sampling_result_to_dict(result: SamplingResult) -> dict[str, Any]:
    payload: dict[str, Any] = {
        "variable_names": list(result.variable_names),
        "samples": _encode_float_array(result.samples),
        "metadata": dict(result.metadata),
    }
    if result.log_probability is not None:
        payload["log_probability"] = _encode_float_array(result.log_probability)
    if result.chain is not None:
        payload["chain"] = _encode_float_array(result.chain)
    if result.log_probability_chain is not None:
        payload["log_probability_chain"] = _encode_float_array(result.log_probability_chain)
    return payload


def _sampling_result_from_dict(payload: Any) -> SamplingResult | None:
    if not isinstance(payload, dict):
        return None
    try:
        samples = _decode_float_array(payload["samples"])
    except Exception:
        return None
    log_probability = None
    if isinstance(payload.get("log_probability"), dict):
        try:
            log_probability = _decode_float_array(payload["log_probability"])
        except Exception:
            log_probability = None
    chain = None
    if isinstance(payload.get("chain"), dict):
        try:
            chain = _decode_float_array(payload["chain"])
        except Exception:
            chain = None
    log_probability_chain = None
    if isinstance(payload.get("log_probability_chain"), dict):
        try:
            log_probability_chain = _decode_float_array(payload["log_probability_chain"])
        except Exception:
            log_probability_chain = None
    return SamplingResult(
        samples=samples,
        variable_names=[str(name) for name in payload.get("variable_names", [])],
        log_probability=log_probability,
        metadata=dict(payload.get("metadata", {})),
        chain=chain,
        log_probability_chain=log_probability_chain,
    )


def _autocorrelation_progress_summary(result: SamplingResult | None) -> list[str]:
    """Return readable emcee convergence estimates for the progress log."""

    if result is None:
        return []
    metadata = result.metadata if isinstance(result.metadata, dict) else {}
    raw_tau = metadata.get("autocorrelation_time")
    if not isinstance(raw_tau, (list, tuple)):
        return []
    tau = []
    for value in raw_tau:
        try:
            numeric = float(value)
        except (TypeError, ValueError):
            continue
        if np.isfinite(numeric) and numeric > 0.0:
            tau.append(numeric)
    if not tau:
        return [
            "emcee integrated autocorrelation time is unavailable for this chain; "
            "run more steps before using it to estimate a chain length."
        ]
    recommended = metadata.get("autocorrelation_recommended_steps")
    additional = metadata.get("autocorrelation_recommended_additional_steps")
    tau_text = ", ".join(f"{value:.3g}" for value in tau)
    summary = f"emcee integrated autocorrelation time (steps): [{tau_text}]"
    if recommended is not None:
        summary += f"; recommended total chain length: at least {int(recommended):,} steps"
    if additional is not None:
        summary += f"; estimated additional steps: {int(additional):,}"
    return [summary + "."]


def _sampling_result_with_window(result: SamplingResult, burn_in: int, thin: int) -> SamplingResult:
    """Return a copy flattened with a different burn-in/thinning window."""

    if result.chain is None:
        raise ValueError("stored posterior does not include a raw emcee chain")
    chain = np.asarray(result.chain, dtype=float)
    if chain.ndim != 3 or chain.shape[0] == 0:
        raise ValueError("stored posterior chain is empty or malformed")
    burn = min(max(0, int(burn_in)), max(0, chain.shape[0] - 1))
    step = max(1, int(thin))
    sliced = chain[burn::step]
    samples = sliced.reshape((-1, chain.shape[2]))
    log_probability = None
    if result.log_probability_chain is not None:
        log_chain = np.asarray(result.log_probability_chain, dtype=float)
        if log_chain.shape[:2] == chain.shape[:2]:
            log_probability = log_chain[burn::step].reshape(-1)
    metadata = dict(result.metadata)
    metadata["burn_in"] = burn
    metadata["thin"] = step
    metadata["samples"] = int(samples.shape[0])
    metadata["n_steps"] = int(chain.shape[0])
    metadata["n_walkers"] = int(chain.shape[1])
    return SamplingResult(
        samples=samples,
        variable_names=list(result.variable_names),
        log_probability=log_probability,
        metadata=metadata,
        chain=chain,
        log_probability_chain=result.log_probability_chain,
    )


def _combined_sampling_result(
    original: SamplingResult,
    appended: SamplingResult,
    *,
    burn_in: int,
    thin: int,
) -> SamplingResult:
    """Concatenate two emcee chains and re-flatten them with the requested window."""

    if original.chain is None or appended.chain is None:
        raise ValueError("appending posterior samples requires raw emcee chains")
    if list(original.variable_names) != list(appended.variable_names):
        raise ValueError("appended posterior variables do not match the stored chain")
    chain = np.concatenate(
        [np.asarray(original.chain, dtype=float), np.asarray(appended.chain, dtype=float)],
        axis=0,
    )
    log_probability_chain = None
    if original.log_probability_chain is not None and appended.log_probability_chain is not None:
        log_probability_chain = np.concatenate(
            [
                np.asarray(original.log_probability_chain, dtype=float),
                np.asarray(appended.log_probability_chain, dtype=float),
            ],
            axis=0,
        )
    metadata = dict(original.metadata)
    metadata.update(dict(appended.metadata))
    metadata["n_steps"] = int(chain.shape[0])
    metadata["n_walkers"] = int(chain.shape[1])
    metadata["appended_steps"] = int(appended.chain.shape[0])
    result = SamplingResult(
        samples=np.empty((0, chain.shape[2]), dtype=float),
        variable_names=list(original.variable_names),
        log_probability=None,
        metadata=metadata,
        chain=chain,
        log_probability_chain=log_probability_chain,
    )
    return _sampling_result_with_window(result, burn_in=burn_in, thin=thin)


def _store_sampling_result_on_fit_entry(fit_entry: FitTimelineEntry, result: SamplingResult) -> None:
    fit_entry.metadata["posterior_samples"] = _sampling_result_to_dict(result)
    fit_entry.goodness["posterior"] = _posterior_summary(result)
    display = fit_entry.metadata.get(POSTERIOR_DISPLAY_KEY)
    if isinstance(display, dict) and display.get("use_best_sample"):
        best = _best_posterior_sample(result)
        if best is None:
            display["use_best_sample"] = False
            display.pop("best_sample", None)
        else:
            params, log_probability, location = best
            display["best_sample"] = {
                "parameters": params,
                "log_probability": log_probability,
                **location,
            }


def _posterior_display_options(fit_entry: FitTimelineEntry) -> dict[str, Any]:
    """Return the persisted choice of posterior-derived result values."""

    metadata = fit_entry.metadata if isinstance(fit_entry.metadata, dict) else {}
    stored = metadata.get(POSTERIOR_DISPLAY_KEY)
    return dict(stored) if isinstance(stored, dict) else {}


def _display_fit_parameters(fit_entry: FitTimelineEntry) -> dict[str, float]:
    """Return the parameter values selected for the active fit result."""

    goodness = fit_entry.goodness if isinstance(fit_entry.goodness, dict) else {}
    params = goodness.get("parameters") if isinstance(goodness.get("parameters"), dict) else {}
    displayed = {str(name): float(value) for name, value in params.items()}
    options = _posterior_display_options(fit_entry)
    best = options.get("best_sample") if options.get("use_best_sample") else None
    best_params = best.get("parameters") if isinstance(best, dict) else None
    if isinstance(best_params, dict):
        for name, value in best_params.items():
            try:
                displayed[str(name)] = float(value)
            except (TypeError, ValueError):
                continue
    return displayed


def _posterior_interval_errors(
    fit_entry: FitTimelineEntry,
    name: str,
    center: float,
) -> tuple[float, float] | None:
    """Return asymmetric 68% posterior errors about a displayed parameter value."""

    goodness = fit_entry.goodness if isinstance(fit_entry.goodness, dict) else {}
    posterior = goodness.get("posterior") if isinstance(goodness.get("posterior"), dict) else {}
    rows = posterior.get("parameters") if isinstance(posterior.get("parameters"), dict) else {}
    row = rows.get(name) if isinstance(rows.get(name), dict) else None
    if row is None:
        return None
    try:
        lower = float(row["p16"])
        upper = float(row["p84"])
    except (KeyError, TypeError, ValueError):
        return None
    if not np.isfinite(lower) or not np.isfinite(upper):
        return None
    return max(0.0, center - lower), max(0.0, upper - center)


def _posterior_correlation_matrix(
    fit_entry: FitTimelineEntry,
) -> tuple[np.ndarray, list[str]] | None:
    """Return the finite-sample emcee correlation matrix for display."""

    result = _sampling_result_from_dict(fit_entry.metadata.get("posterior_samples"))
    if result is None:
        return None
    samples = np.asarray(result.samples, dtype=float)
    names = list(result.variable_names)
    if samples.ndim != 2 or samples.shape[0] < 2 or samples.shape[1] != len(names):
        return None
    finite_rows = np.all(np.isfinite(samples), axis=1)
    samples = samples[finite_rows]
    if samples.shape[0] < 2:
        return None
    if samples.shape[1] == 1:
        return np.ones((1, 1), dtype=float), names
    correlation = np.asarray(np.corrcoef(samples, rowvar=False), dtype=float)
    if correlation.shape != (len(names), len(names)):
        return None
    return correlation, names


def _best_posterior_sample(
    result: SamplingResult,
) -> tuple[dict[str, float], float, dict[str, int]] | None:
    """Return the stored sample with the highest finite emcee log probability."""

    names = list(result.variable_names)
    if not names:
        return None
    if result.chain is not None and result.log_probability_chain is not None:
        chain = np.asarray(result.chain, dtype=float)
        log_probability = np.asarray(result.log_probability_chain, dtype=float)
        if chain.ndim == 3 and log_probability.shape == chain.shape[:2]:
            finite = np.isfinite(log_probability)
            if np.any(finite):
                masked = np.where(finite, log_probability, -np.inf)
                flat_index = int(np.argmax(masked))
                step, walker = np.unravel_index(flat_index, log_probability.shape)
                sample = chain[int(step), int(walker)]
                if sample.shape[0] == len(names):
                    return (
                        {name: float(sample[index]) for index, name in enumerate(names)},
                        float(log_probability[int(step), int(walker)]),
                        {"step": int(step), "walker": int(walker)},
                    )
    if result.log_probability is None:
        return None
    samples = np.asarray(result.samples, dtype=float)
    log_probability = np.asarray(result.log_probability, dtype=float)
    if samples.ndim != 2 or samples.shape[1] != len(names) or log_probability.shape != (samples.shape[0],):
        return None
    finite = np.isfinite(log_probability)
    if not np.any(finite):
        return None
    sample_index = int(np.argmax(np.where(finite, log_probability, -np.inf)))
    sample = samples[sample_index]
    return (
        {name: float(sample[index]) for index, name in enumerate(names)},
        float(log_probability[sample_index]),
        {"sample": int(sample_index)},
    )


def _log_probability_for_params(
    compiled: CompiledFitProblem,
    params: dict[str, float],
) -> float:
    """Evaluate the Gaussian log likelihood used by emcee for a parameter set."""

    trial = {spec.name: float(spec.value) for spec in compiled.problem.parameter_specs}
    trial.update({str(name): float(value) for name, value in params.items()})
    evaluation = _evaluate_problem(
        compiled.problem,
        trial,
        require_positive_sigma=True,
    )
    chi2 = float(np.dot(evaluation.residuals, evaluation.residuals))
    return -0.5 * chi2


def _best_posterior_promotion_candidate(
    fit_entry: FitTimelineEntry,
    compiled: CompiledFitProblem | None = None,
) -> tuple[dict[str, float], float, float, dict[str, int]] | None:
    """Return a best-sample candidate only when it improves on the fit result."""

    stored = _sampling_result_from_dict(fit_entry.metadata.get("posterior_samples"))
    if stored is None:
        return None
    best = _best_posterior_sample(stored)
    if best is None:
        return None
    sample_params, sample_log_probability, location = best
    try:
        baseline_log_probability = -0.5 * float(fit_entry.goodness["chi2"])
    except (KeyError, TypeError, ValueError):
        goodness_params = fit_entry.goodness.get("parameters")
        if compiled is None or not isinstance(goodness_params, dict):
            return None
        baseline_log_probability = _log_probability_for_params(compiled, goodness_params)
    if not np.isfinite(sample_log_probability) or not np.isfinite(baseline_log_probability):
        return None
    if sample_log_probability <= baseline_log_probability:
        return None
    return sample_params, sample_log_probability, baseline_log_probability, location


def _fit_parameter_labels_from_components(
    components: list[ModelComponentSpec],
    compiled: CompiledFitProblem,
    variable_names: list[str],
) -> dict[str, str]:
    by_component = {component.name: component for component in components}
    labels: dict[str, str] = {}
    for name in variable_names:
        instance = compiled.parameter_instances.get(name)
        if instance is None:
            continue
        component = by_component.get(instance.component)
        if component is None:
            continue
        parameter_labels = component.metadata.get("parameter_labels")
        if not isinstance(parameter_labels, dict):
            continue
        label = str(parameter_labels.get(instance.parameter, "")).strip()
        if label:
            labels[name] = label
    return labels


def _write_back_parameter_values(
    group: DataGroup,
    components: list[ModelComponentSpec],
    compiled: CompiledFitProblem,
    params: dict[str, float],
) -> None:
    """Store fit-problem parameter values on their model components.

    Globally shared (and constrained) parameters update the component's
    ``parameters`` directly. Per-dataset and grouped instances are stored per
    tie key under ``metadata["fitted_values"]`` because a single parameter
    box cannot display several values.
    """

    for component in components:
        for parameter in component_parameter_names(component):
            qualified = qualified_parameter_name(component.name, parameter)
            if qualified in params:
                component.parameters[parameter] = float(params[qualified])
                continue
            values = {
                instance.scope: float(params[instance.name])
                for instance in compiled.instances_for(component.name, parameter)
                if instance.name in params
            }
            if values:
                component.metadata.setdefault("fitted_values", {})[parameter] = values


def _write_back_fitted_parameters(
    group: DataGroup,
    components: list[ModelComponentSpec],
    compiled: CompiledFitProblem,
    result: Any,
) -> None:
    """Store optimized values on their model components."""

    _write_back_parameter_values(group, components, compiled, result.params)
    _write_back_dataset_scale_factors(group, compiled, result.params)


def _apply_displayed_fit_parameters(
    group: DataGroup,
    fit_entry: FitTimelineEntry,
) -> None:
    """Apply a result's selected parameter values to its restored live state.

    The fit snapshot is the least-squares state.  When the user selects the
    best emcee sample, its values are written on top of that state without
    changing the saved snapshot, so unselecting it can restore the exact LM
    result.
    """

    components = [
        model for model in group.models.values() if isinstance(model, ModelComponentSpec)
    ]
    if not components:
        return
    inputs, _bundles = fit_dataset_inputs(group, purpose="fit")
    if not inputs:
        return
    compiled = compile_fit_problem(components, inputs, description=group.name)
    params = {
        spec.name: float(spec.value)
        for spec in compiled.problem.parameter_specs
    }
    params.update(_display_fit_parameters(fit_entry))
    resolved = compiled.problem.resolve_parameters(params)
    _write_back_parameter_values(group, components, compiled, resolved)
    _write_back_dataset_scale_factors(group, compiled, resolved)


def _write_back_dataset_scale_factors(
    group: DataGroup,
    compiled: CompiledFitProblem,
    params: dict[str, float],
) -> None:
    """Store optimized dataset scale factors on their datasets."""

    for instance in compiled.parameter_instances.values():
        if instance.component != "dataset" or instance.parameter != "scale_factor":
            continue
        if instance.name not in params:
            continue
        for dataset_name in instance.datasets:
            try:
                dataset = group.get_dataset(dataset_name)
            except KeyError:
                continue
            dataset.scale_factor = float(params[instance.name])


def _visualization_only_channels(
    group: DataGroup,
    components: list[ModelComponentSpec],
    *,
    progress_callback: Any | None = None,
) -> dict[str, dict[str, Any]]:
    """Evaluate disabled and zero-weight datasets using the fitted state."""

    inputs, bundles = fit_dataset_inputs(
        group,
        purpose="visualization",
        progress_callback=progress_callback,
    )
    if not inputs:
        return {}
    if progress_callback is not None:
        progress_callback(
            {
                "stage": "visualization",
                "iteration": 0,
                "total": len(inputs),
                "message": "evaluating disabled and zero-weight datasets for display",
            }
        )
    compiled = compile_fit_problem(components, inputs, description=group.name)
    params = compiled.problem.resolve_parameters(_overlay_current_params(group, compiled))
    channels = _fit_channels_from_params(compiled, params, bundles)
    for payload in channels.values():
        payload["visualization_only"] = True
    return channels


def _fit_channels_from_result(
    compiled: CompiledFitProblem,
    result: Any,
    bundles: dict[str, FitDataBundle],
) -> dict[str, dict[str, Any]]:
    """Evaluate fit and residual channels over each fitted dataset's view."""

    return _fit_channels_from_params(compiled, result.params, bundles)


def _fit_diagnostics_from_result(
    compiled: CompiledFitProblem,
    result: Any,
    bundles: dict[str, FitDataBundle],
    components: list[ModelComponentSpec],
) -> dict[str, dict[str, Any]]:
    """Collect registered per-dataset physics diagnostics after a fit.

    Returns ``{dataset_name: {metric: value}}`` (metrics prefixed by the
    component name when a dataset carries more than one diagnostic component).
    Stored in the fit result's metadata, which round-trips as JSON. A component
    that cannot be evaluated on a dataset is skipped.
    """

    diagnostic_by_name = {
        component.name: component
        for component in components
        if component.enabled
        and component.type in MODEL_TYPE_REGISTRY
        and (
            MODEL_TYPE_REGISTRY[component.type].diagnostics is not None
            or MODEL_TYPE_REGISTRY[component.type].context_diagnostics is not None
        )
    }
    if not diagnostic_by_name:
        return {}
    resolved = compiled.problem.resolve_parameters(result.params)
    fitted_names = {dataset.name for dataset in compiled.problem.datasets}
    diagnostics: dict[str, dict[str, Any]] = {}
    for name, bundle in bundles.items():
        if name not in fitted_names:
            continue
        applicable = [
            diagnostic_by_name[component_name]
            for component_name in compiled.components_by_dataset.get(name, [])
            if component_name in diagnostic_by_name
        ]
        if not applicable:
            continue
        subset = _subset_points(bundle.points, bundle.points.valid_mask())
        if not subset.size:
            continue
        per_dataset: dict[str, Any] = {}
        for component in applicable:
            record = compute_component_diagnostics(
                component,
                subset,
                resolved,
                components={
                    item.name: item for item in components if item.enabled
                },
            )
            if not record:
                continue
            if len(applicable) == 1:
                per_dataset = copy.deepcopy(record)
            else:
                per_dataset.update(
                    {
                        f"{component.name}.{key}": copy.deepcopy(value)
                        for key, value in record.items()
                    }
                )
        if per_dataset:
            diagnostics[name] = per_dataset
    return diagnostics


def _fit_channels_from_params(
    compiled: CompiledFitProblem,
    params: dict[str, float],
    bundles: dict[str, FitDataBundle],
    subset_cache: dict[Any, tuple[np.ndarray, PointData4D]] | None = None,
    *,
    evaluate_masked: bool = False,
) -> dict[str, dict[str, Any]]:
    """Evaluate fit and residual channels for a compiled problem.

    ``subset_cache`` optionally memoizes each dataset's valid-point mask and
    subset across calls; reusing the same subset object also lets the model's
    per-dataset geometry cache hit, so repeated overlay refreshes at new
    parameter values skip both the mask scan and the RPA geometry rebuild.
    """

    channels: dict[str, dict[str, Any]] = {}
    fitted_names = {dataset.name for dataset in compiled.problem.datasets}
    for name, bundle in bundles.items():
        if name not in fitted_names:
            continue
        points = bundle.points
        # Normally evaluate only fit-valid data and scatter back with NaN
        # elsewhere. The viewer's explicit unmask option instead evaluates all
        # finite HKLE coordinates; keeping the paths separate avoids paying for
        # the often much larger masked volume during ordinary interaction.
        cache_key: Any = (name, "unmasked") if evaluate_masked else name
        cached_subset = subset_cache.get(cache_key) if subset_cache is not None else None
        if cached_subset is not None:
            keep, subset = cached_subset
        else:
            if evaluate_masked:
                keep = np.isfinite(points.H) & np.isfinite(points.K)
                keep &= np.isfinite(points.L) & np.isfinite(points.E)
                if isinstance(points.temperature, np.ndarray):
                    keep &= np.isfinite(points.temperature)
            else:
                keep = points.valid_mask()
            subset = _subset_points(points, keep)
            if subset_cache is not None:
                subset_cache[cache_key] = (keep, subset)
        fit_values = np.full(points.size, np.nan, dtype=float)
        if subset.size:
            fit_values[keep] = np.asarray(
                evaluate_problem_model(compiled.problem, name, params, data=subset),
                dtype=float,
            )
        fit_dataset = next(
            dataset for dataset in compiled.problem.datasets if dataset.name == name
        )
        intensity = np.asarray(points.intensity, dtype=float)
        sigma = np.asarray(points.sigma, dtype=float)
        if fit_dataset.data_scale_parameter:
            resolved = compiled.problem.resolve_parameters(params)
            scale = float(resolved[fit_dataset.data_scale_parameter])
            intensity = intensity * scale
            sigma = sigma * max(abs(scale), np.finfo(float).tiny)
        with np.errstate(divide="ignore", invalid="ignore"):
            residual_values = (intensity - fit_values) / sigma
        residual_values = np.where(
            np.isfinite(intensity) & np.isfinite(sigma) & (sigma > 0.0),
            residual_values,
            np.nan,
        )
        if bundle.grid_shape is not None:
            fit_values = fit_values.reshape(bundle.grid_shape)
            residual_values = residual_values.reshape(bundle.grid_shape)
        channels[name] = {
            "kind": "grid" if bundle.grid_shape is not None else "points",
            "fit": fit_values,
            "residual": residual_values,
            "fit_channel": str(points.metadata.get("fit_channel", "")),
        }
    return channels


def _subset_points(points: PointData4D, keep: np.ndarray) -> PointData4D:
    """Return the ``keep``-selected subset of ``points`` (order preserved)."""

    if isinstance(points.temperature, np.ndarray):
        temperature: Any = points.temperature[keep]
    else:
        temperature = points.temperature
    field = points.magnetic_field
    if isinstance(field, np.ndarray) and field.ndim == 2:
        magnetic_field: Any = field[keep]
    elif field is None:
        magnetic_field = None
    else:
        magnetic_field = np.array(field)
    return PointData4D(
        H=points.H[keep],
        K=points.K[keep],
        L=points.L[keep],
        E=points.E[keep],
        intensity=points.intensity[keep],
        sigma=points.sigma[keep],
        mask=np.ones(int(np.count_nonzero(keep)), dtype=bool),
        temperature=temperature,
        magnetic_field=magnetic_field,
        metadata=dict(points.metadata),
    )


def latest_fit_channels(group: DataGroup, dataset_name: str) -> dict[str, Any] | None:
    """Return the stored fit channels for a dataset from the newest fit result."""

    latest: dict[str, Any] | None = None
    for entry in _walk_fit_entries(group.fits):
        if entry.kind != "result":
            continue
        payload = entry.channels.get(dataset_name)
        if payload:
            latest = payload
    return latest


def _group_has_fit_channels(group: DataGroup) -> bool:
    """Return whether any dataset in the group has stored fit channels."""

    return any(entry.channels for entry in _walk_fit_entries(group.fits) if entry.kind == "result")


def _group_has_enabled_model_components(group: DataGroup) -> bool:
    """Return whether the group has a model that can be evaluated."""

    return any(
        isinstance(model, ModelComponentSpec) and model.enabled
        for model in group.models.values()
    )


def attach_fit_channels_to_view(
    group: DataGroup,
    dataset_name: str,
    view: MDHistoData | PointListData,
    *,
    fallback_payload: dict[str, Any] | None = None,
) -> MDHistoData | PointListData:
    """Return a view with live-model or saved fit/residual channels attached.

    Live current-model channels take precedence when available. Channels are
    only attached when their shape still matches the current view, so stale fits
    after mask or rebin changes are silently skipped rather than misaligned.
    """

    payload = fallback_payload or latest_fit_channels(group, dataset_name)
    if payload is None:
        return view
    arrays: dict[str, np.ndarray] = {}
    for channel_name in FIT_CHANNEL_NAMES:
        decoded = _fit_channel_array(payload.get(channel_name))
        if decoded is None:
            return view
        arrays[channel_name] = decoded
    if isinstance(view, MDHistoData):
        if any(array.shape != view.shape for array in arrays.values()):
            return view
        metadata = dict(view.metadata)
        metadata.update(arrays)
        return view.with_updates(metadata=metadata)
    if isinstance(view, PointListData):
        if any(array.shape != (view.size,) for array in arrays.values()):
            return view
        columns = dict(view.columns)
        channels = [dict(channel) for channel in view.channels]
        metadata = dict(view.metadata)
        existing = set(view.channel_labels)
        fit_channel = _point_fit_channel_label(group, dataset_name, view, payload)
        for channel_name, array in arrays.items():
            columns[channel_name] = array
            if channel_name not in existing:
                channels.append(
                    {"label": channel_name, "value": channel_name, "error": None}
                )
        for channel_name in FIT_CHANNEL_NAMES:
            key = f"viewer_{channel_name}_channel_map"
            stored = metadata.get(key, {})
            mapping = dict(stored) if isinstance(stored, dict) else {}
            mapping = {
                label: target
                for label, target in mapping.items()
                if target != channel_name
            }
            if fit_channel:
                mapping[fit_channel] = channel_name
            if mapping:
                metadata[key] = mapping
            else:
                metadata.pop(key, None)
        return view.with_updates(
            columns=columns,
            channels=channels,
            metadata=metadata,
        )
    return view


def _point_fit_channel_label(
    group: DataGroup,
    dataset_name: str,
    view: PointListData,
    payload: dict[str, Any],
) -> str:
    """Return the explicitly recorded data channel for a point-list fit."""

    explicit = str(payload.get("fit_channel", "")).strip()
    return explicit if explicit in view.channel_labels else ""


# Building a viewer view (loading, rebinning, and masking the full volume) is
# expensive on large datasets and is redone on every slice-viewer refresh --
# including when a fit result or "Current state" node is merely selected. The
# result depends only on the dataset's data, rebin config, and masks (not on the
# selection or model parameters), so it is cached and reused. The signature
# excludes the dataset scale factor, which is applied cheaply afterward.
_VIEWER_VIEW_CACHE: OrderedDict[str, tuple[str, Any]] = OrderedDict()
_VIEWER_VIEW_CACHE_LIMIT = 8
_VIEWER_VIEW_CACHE_MAX_BYTES = 256 * 1024**2
_COMPOSITE_DATA_CACHE: OrderedDict[int, tuple[str, Any]] = OrderedDict()
_COMPOSITE_DATA_CACHE_LIMIT = 4
_COMPOSITE_DATA_CACHE_MAX_BYTES = 256 * 1024**2


def _mask_signature(masks: list[MaskSpec] | None) -> list[Any]:
    return [
        [m.type, bool(m.enabled), bool(m.invert), bool(m.additive),
         json.dumps(m.parameters, sort_keys=True, default=str)]
        for m in (masks or [])
    ]


def _viewer_view_signature(
    dataset: DatasetEntry, extra_masks: list[MaskSpec] | None
) -> str:
    rebin = (
        json.dumps(dataset_rebin_config(dataset), sort_keys=True, default=str)
        if dataset_rebin_enabled(dataset)
        else None
    )
    payload = [
        dataset.data_cache_token,
        dataset.data_type,
        dataset.kind,
        rebin,
        _mask_signature(getattr(dataset, "masks", None)),
        _mask_signature(extra_masks),
        [
            [
                background.source_dataset_id,
                bool(background.enabled),
                float(background.scale),
                background.interpolation,
                (
                    background.source_entry.data_cache_token
                    if background.source_entry is not None
                    else None
                ),
            ]
            for background in dataset.backgrounds
        ],
    ]
    return json.dumps(payload, sort_keys=True, default=str)


def _viewer_data_before_scale(
    dataset: DatasetEntry,
    *,
    extra_masks: list[MaskSpec] | None = None,
    force_rebin: bool = True,
    force_masks: bool = True,
    progress_callback: Any | None = None,
) -> MDHistoData | PointListData | None:
    key = dataset.id
    signature = _viewer_view_signature(dataset, extra_masks)
    deferred_masks = _should_defer_dataset_masks(dataset, force_masks=force_masks)
    cached = _VIEWER_VIEW_CACHE.get(key)
    if cached is not None and cached[0] == signature:
        _VIEWER_VIEW_CACHE.move_to_end(key)
        if force_masks:
            dataset_mask_application_config(dataset)["stale"] = False
        return cached[1]
    if cached is not None and deferred_masks:
        return cached[1]
    if cached is not None and _should_defer_dataset_rebin(dataset, force_rebin=force_rebin):
        return cached[1]
    result = _viewer_data_before_scale_uncached(
        dataset,
        extra_masks=extra_masks,
        force_rebin=force_rebin,
        force_masks=force_masks,
        progress_callback=progress_callback,
    )
    if isinstance(result, MDHistoData) and dataset.backgrounds:
        result = _apply_dataset_backgrounds(dataset, result)
    if result is not None and not deferred_masks:
        # Recompute the signature: the uncached path may have lazily loaded the
        # data and incremented the dataset revision.
        signature = _viewer_view_signature(dataset, extra_masks)
        _lru_store(
            _VIEWER_VIEW_CACHE,
            key,
            (signature, result),
            _VIEWER_VIEW_CACHE_LIMIT,
            _VIEWER_VIEW_CACHE_MAX_BYTES,
        )
        dataset_mask_application_config(dataset)["stale"] = False
    return result


def _apply_dataset_backgrounds(
    dataset: DatasetEntry,
    data: MDHistoData,
) -> MDHistoData:
    result = data
    for background in dataset.backgrounds:
        if not background.enabled:
            continue
        source = background.source_entry
        if source is None:
            raise ValueError(
                f"background {background.name!r} refers to a missing dataset"
            )
        source_data = _viewer_data_before_scale_uncached(
            source,
            force_rebin=True,
            force_masks=True,
        )
        if not isinstance(source_data, MDHistoData):
            raise TypeError(
                f"background {background.name!r} must refer to gridded powder data"
            )
        result = subtract_powder_background(
            result,
            source_data,
            scale=background.scale,
            interpolation=background.interpolation,
        )
    return result


def _viewer_data_before_scale_uncached(
    dataset: DatasetEntry,
    *,
    extra_masks: list[MaskSpec] | None = None,
    force_rebin: bool = True,
    force_masks: bool = True,
    progress_callback: Any | None = None,
) -> MDHistoData | PointListData | None:
    loaded = _ensure_dataset_data_loaded(dataset)
    if data_type_container(dataset.data_type) == "point_list" or isinstance(
        loaded, PointListData
    ):
        if not isinstance(loaded, PointListData):
            return None
        if dataset_rebin_enabled(dataset):
            if _should_defer_dataset_rebin(dataset, force_rebin=force_rebin):
                return prepared_point_list_data(dataset)
            return rebinned_dataset_data(dataset, progress_callback=progress_callback)
        return prepared_point_list_data(dataset)
    if isinstance(loaded, MDHistoData):
        if _should_defer_dataset_masks(dataset, force_masks=force_masks):
            return _mdhisto_without_nfit_masks(loaded)
        if dataset_rebin_enabled(dataset):
            if _should_defer_dataset_rebin(dataset, force_rebin=force_rebin):
                return _mdhisto_with_nfit_masks(dataset, data=loaded, extra_masks=extra_masks)
            return rebinned_dataset_data(dataset, extra_masks=extra_masks, progress_callback=progress_callback)
        return _mdhisto_with_nfit_masks(dataset, data=loaded, extra_masks=extra_masks)
    if isinstance(loaded, PointData4D):
        if dataset_rebin_enabled(dataset):
            return rebinned_dataset_data(
                dataset, extra_masks=extra_masks, progress_callback=progress_callback
            )
        return _point_data_with_nfit_masks(dataset, loaded, extra_masks=extra_masks)
    return None


def _mdhisto_without_nfit_masks(data: MDHistoData) -> MDHistoData:
    """Return a cheap file-mask-only view while manual nfit masks are pending."""

    file_mask = np.asarray(data.mask, dtype=bool)
    metadata = dict(data.metadata)
    metadata["file_mask"] = file_mask
    metadata["nfit_mask"] = np.zeros(0, dtype=bool)
    metadata["file_mask_count"] = int(np.count_nonzero(file_mask))
    metadata["nfit_mask_count"] = 0
    metadata["combined_mask_count"] = metadata["file_mask_count"]
    metadata["mask_application_pending"] = True
    return replace(data, mask=file_mask, metadata=metadata)


def _apply_dataset_scale(
    dataset: DatasetEntry,
    data: MDHistoData | PointListData | PointData4D,
) -> MDHistoData | PointListData | PointData4D:
    """Multiply a dataset's signal and errors by its scale factor (both channels)."""

    scale = float(getattr(dataset, "scale_factor", 1.0) or 1.0)
    if scale == 1.0:
        return data
    if isinstance(data, MDHistoData):
        from dataclasses import replace

        return replace(
            data,
            signal=np.asarray(data.signal, dtype=float) * scale,
            errors=np.asarray(data.errors, dtype=float) * abs(scale),
        )
    if isinstance(data, PointListData):
        columns = {name: np.array(values, dtype=float) for name, values in data.columns.items()}
        for channel in data.channels:
            value_name = channel.get("value")
            error_name = channel.get("error")
            if value_name in columns:
                columns[value_name] = columns[value_name] * scale
            if error_name in columns:
                columns[error_name] = columns[error_name] * abs(scale)
        return PointListData(
            columns=columns,
            units=dict(data.units),
            coordinate_names=list(data.coordinate_names),
            channels=[dict(channel) for channel in data.channels],
            metadata=dict(data.metadata),
            quantity_types=dict(data.quantity_types),
        )
    if isinstance(data, PointData4D):
        return data.with_updates(
            intensity=np.asarray(data.intensity, dtype=float) * scale,
            sigma=np.asarray(data.sigma, dtype=float) * abs(scale),
        )
    return data


def dataset_rebin_config(dataset: DatasetEntry) -> dict[str, Any]:
    """Return a dataset rebin configuration, creating default axis settings if needed."""

    config = dataset.parameters.get(DATASET_REBIN_KEY)
    if not isinstance(config, dict):
        config = {}
        dataset.parameters[DATASET_REBIN_KEY] = config
    config.setdefault("enabled", False)
    config.setdefault("fractional", True)
    if not isinstance(config.get("symmetry"), dict):
        config["symmetry"] = symmetry_config(SymmetrySpec())
    if config.get(REBIN_RESOLUTION_MODE_KEY) not in {"step", "bins"}:
        config[REBIN_RESOLUTION_MODE_KEY] = "step"
    try:
        config["max_batch_mb"] = max(int(config.get("max_batch_mb", DEFAULT_REBIN_MAX_BATCH_MB)), 1)
    except (TypeError, ValueError):
        config["max_batch_mb"] = DEFAULT_REBIN_MAX_BATCH_MB
    if config.get("mean_weighting") not in {"inverse_variance", "uniform"}:
        config["mean_weighting"] = "inverse_variance"
    config["minimum_coverage"] = _rebin_minimum_coverage(config)
    config["normalize"] = True
    axes = config.get("axes")
    # Only materialize transformed coordinates when defaults are actually
    # needed. Existing axes already carry their complete saved basis.
    if isinstance(dataset.data, PointListData) and (not isinstance(axes, list) or not axes):
        default_axes = _default_rebin_axes(prepared_point_list_data(dataset))
    elif isinstance(dataset.data, PointListData):
        default_axes = []
    else:
        default_axes = _default_rebin_axes(dataset.data)
    if not isinstance(axes, list) or not axes:
        # A saved project may call this while its file-backed dataset is still
        # unloaded. Leave axes absent in that state so first data load can
        # create defaults, but never replace a saved non-empty basis.
        if default_axes:
            config["axes"] = default_axes
            if isinstance(dataset.data, MDHistoData) and len(dataset.data.axes) == 4:
                config["coordinate_basis_version"] = REBIN_COORDINATE_BASIS_VERSION
    else:
        sanitized_axes = list(axes)
        if len(axes) == len(default_axes):
            sanitized_axes = []
            for axis_config, default_axis in zip(axes, default_axes, strict=True):
                if not isinstance(axis_config, dict):
                    axis_config = {}
                for key, value in default_axis.items():
                    axis_config.setdefault(key, value)
                if isinstance(dataset.data, MDHistoData) and "vector" in axis_config:
                    axis_config["variable"] = str(
                        axis_config.get("variable") or default_axis.get("variable", "")
                    )
                    axis_config["name"] = _rebin_axis_name(
                        axis_config["variable"], axis_config.get("vector", [])
                    )
                sanitized_axes.append(_sanitize_rebin_axis_config(axis_config))
            config["axes"] = sanitized_axes
        if (
            len(axes) == len(default_axes)
            and isinstance(dataset.data, MDHistoData)
            and len(dataset.data.axes) == 4
        ):
            try:
                basis_version = int(config["coordinate_basis_version"])
            except (KeyError, TypeError, ValueError) as exc:
                raise ValueError(
                    "saved 4D rebin settings are missing a supported "
                    "coordinate_basis_version; recreate the rebin settings"
                ) from exc
            if basis_version != REBIN_COORDINATE_BASIS_VERSION:
                raise ValueError(
                    f"unsupported rebin coordinate basis version {basis_version}; "
                    "recreate the rebin settings"
                )
    if "auto_rebin" not in config:
        config["auto_rebin"] = not _dataset_rebin_is_large(dataset, config)
    config.setdefault("stale", False)
    return config


def _rebin_settings_clipboard_text(config: dict[str, Any]) -> str:
    """Serialize user-editable rebin settings for the system clipboard."""

    settings = {
        key: copy.deepcopy(config[key])
        for key in REBIN_SETTINGS_KEYS
        if key in config
    }
    return json.dumps(
        {
            "schema": REBIN_SETTINGS_CLIPBOARD_SCHEMA,
            "version": REBIN_SETTINGS_CLIPBOARD_VERSION,
            "settings": settings,
        },
        indent=2,
        sort_keys=True,
    )


def _rebin_config_from_clipboard_text(
    text: str,
    target_config: dict[str, Any],
) -> dict[str, Any]:
    """Return a pasted rebin config after validating target compatibility."""

    try:
        payload = json.loads(text)
    except (TypeError, json.JSONDecodeError) as exc:
        raise ValueError("The clipboard does not contain valid nfit rebin settings.") from exc
    if not isinstance(payload, dict) or payload.get("schema") != REBIN_SETTINGS_CLIPBOARD_SCHEMA:
        raise ValueError("The clipboard does not contain nfit rebin settings.")
    if payload.get("version") != REBIN_SETTINGS_CLIPBOARD_VERSION:
        raise ValueError("The clipboard rebin-settings version is not supported.")
    settings = payload.get("settings")
    if not isinstance(settings, dict):
        raise ValueError("The clipboard rebin settings are incomplete.")
    source_axes = settings.get("axes")
    target_axes = target_config.get("axes")
    if not isinstance(source_axes, list) or not source_axes:
        raise ValueError("The copied rebin settings do not contain any axes.")
    if isinstance(target_axes, list) and target_axes and len(source_axes) != len(target_axes):
        raise ValueError(
            f"The copied settings have {len(source_axes)} axes, but this rebin panel has "
            f"{len(target_axes)} axes."
        )
    for index, source_axis in enumerate(source_axes):
        if not isinstance(source_axis, dict):
            raise ValueError(f"Copied rebin axis {index + 1} is invalid.")
        source_vector = source_axis.get("vector")
        target_vector = (
            target_axes[index].get("vector")
            if isinstance(target_axes, list)
            and index < len(target_axes)
            and isinstance(target_axes[index], dict)
            else None
        )
        if isinstance(source_vector, list) and isinstance(target_vector, list):
            if len(source_vector) != len(target_vector):
                raise ValueError(
                    f"Copied rebin axis {index + 1} uses a {len(source_vector)}-component "
                    f"coordinate vector, but this panel expects {len(target_vector)} components."
                )
    pasted = copy.deepcopy(target_config)
    for key in REBIN_SETTINGS_KEYS:
        if key in settings:
            pasted[key] = copy.deepcopy(settings[key])
    pasted["normalize"] = True
    pasted["stale"] = True
    return pasted


def dataset_mask_application_config(dataset: DatasetEntry) -> dict[str, Any]:
    """Return persistent automatic/manual mask materialization settings."""

    config = dataset.metadata.get(DATASET_MASK_APPLICATION_KEY)
    if not isinstance(config, dict):
        config = {}
        dataset.metadata[DATASET_MASK_APPLICATION_KEY] = config
    if "auto_apply" not in config:
        config["auto_apply"] = not _dataset_mask_is_large(dataset)
    config.setdefault("stale", False)
    return config


def _dataset_mask_point_count(dataset: DatasetEntry) -> int:
    data = dataset.data
    if isinstance(data, MDHistoData):
        return int(np.asarray(data.signal).size)
    if isinstance(data, PointData4D):
        return int(data.size)
    if isinstance(data, PointListData):
        return int(data.size)
    return 0


def _dataset_mask_is_large(dataset: DatasetEntry) -> bool:
    return _dataset_mask_point_count(dataset) > MASK_AUTO_MAX_POINTS


def _dataset_mask_auto_enabled(dataset: DatasetEntry) -> bool:
    return bool(dataset_mask_application_config(dataset).get("auto_apply", True))


def _dataset_mask_is_stale(dataset: DatasetEntry) -> bool:
    config = dataset.metadata.get(DATASET_MASK_APPLICATION_KEY)
    return bool(isinstance(config, dict) and config.get("stale", False))


def _should_defer_dataset_masks(dataset: DatasetEntry, *, force_masks: bool) -> bool:
    # Manual mode only materializes masks at explicit synchronization points.
    # An exact cached view is still returned before this policy is consulted,
    # so a current manual result remains cheap to reuse. This also protects a
    # freshly loaded project, where no process-local masked cache exists yet.
    return bool(not force_masks and not _dataset_mask_auto_enabled(dataset))


def _dataset_mask_status_text(dataset: DatasetEntry) -> str:
    config = dataset_mask_application_config(dataset)
    size_note = "large dataset" if _dataset_mask_is_large(dataset) else "small dataset"
    if bool(config.get("auto_apply", True)):
        if bool(config.get("stale", False)):
            return f"Automatic mask application is on ({size_note}); pending masks apply on the next refresh."
        return f"Automatic mask application is on ({size_note}); applied masks are current."
    if bool(config.get("stale", False)) or dataset.id not in _VIEWER_VIEW_CACHE:
        return "Manual mask application pending; press Apply masks now or start a fit/open the data viewer."
    return f"Manual mask application is on ({size_note}); applied masks are current."


def dataset_rebin_enabled(dataset: DatasetEntry) -> bool:
    """Return whether this dataset should use its rebinned representation."""

    config = dataset.parameters.get(DATASET_REBIN_KEY)
    return bool(isinstance(config, dict) and config.get("enabled"))


def _dataset_rebin_source_points(dataset: DatasetEntry) -> int:
    data = dataset.data
    if isinstance(data, MDHistoData):
        return int(np.asarray(data.signal).size)
    if isinstance(data, PointData4D):
        return int(data.size)
    if isinstance(data, PointListData):
        return int(data.size)
    return 0


def _dataset_rebin_output_bins(config: dict[str, Any]) -> int:
    total = 1
    axes = config.get("axes")
    if not isinstance(axes, list) or not axes:
        return 0
    for axis in axes:
        if not isinstance(axis, dict):
            return 0
        total *= max(int(axis.get("num_bins", 1) or 1), 1)
    return int(total)


def _dataset_rebin_estimated_contributions(dataset: DatasetEntry, config: dict[str, Any]) -> int:
    source_points = _dataset_rebin_source_points(dataset)
    ndim = max(len(config.get("axes", []) or []), 1)
    multiplier = 2**ndim if bool(config.get("fractional", True)) else 1
    return int(source_points * multiplier * _rebin_symmetry_count(config, _dataset_lattice_parameters(dataset)))


def _dataset_lattice_parameters(dataset: DatasetEntry) -> dict[str, Any] | None:
    data = dataset.data
    metadata = getattr(data, "metadata", None)
    return metadata.get("lattice_parameters") if isinstance(metadata, dict) and isinstance(metadata.get("lattice_parameters"), dict) else None


def _rebin_symmetry_operations(
    config: dict[str, Any],
    lattice_parameters: dict[str, Any] | None = None,
) -> tuple:
    payload = config.get("symmetry")
    spec = symmetry_spec_from_config(payload)
    stored_lattice = payload.get("lattice_parameters") if isinstance(payload, dict) else None
    lattice = lattice_parameters if lattice_parameters is not None else stored_lattice
    return resolve_symmetry(spec, lattice_parameters=lattice)


def _rebin_symmetry_count(config: dict[str, Any], lattice_parameters: dict[str, Any] | None = None) -> int:
    try:
        return len(_rebin_symmetry_operations(config, lattice_parameters))
    except (ImportError, ValueError):
        return 1


def _rebin_symmetry_matrices(
    config: dict[str, Any], lattice_parameters: dict[str, Any] | None = None
) -> tuple[np.ndarray, ...] | None:
    operations = _rebin_symmetry_operations(config, lattice_parameters)
    if len(operations) == 1 and np.allclose(operations[0].matrix_hkl, np.eye(3)):
        return None
    return tuple(np.asarray(operation.matrix_hkl, dtype=float) for operation in operations)


def _rebin_symmetry_metadata(
    config: dict[str, Any], lattice_parameters: dict[str, Any] | None = None
) -> dict[str, Any] | None:
    spec = symmetry_spec_from_config(config.get("symmetry"))
    if not spec.enabled:
        return None
    operations = _rebin_symmetry_operations(config, lattice_parameters)
    return {
        "mode": spec.mode,
        "expression": spec.expression,
        "operation_count": len(operations),
        "operations_hkl": [np.asarray(operation.matrix_hkl, dtype=float).tolist() for operation in operations],
        "labels": [operation.label for operation in operations],
        "energy_unchanged": True,
    }


def _dataset_rebin_is_large(dataset: DatasetEntry, config: dict[str, Any]) -> bool:
    return (
        _dataset_rebin_estimated_contributions(dataset, config) > REBIN_AUTO_MAX_CONTRIBUTIONS
        or _dataset_rebin_output_bins(config) > REBIN_AUTO_MAX_OUTPUT_BINS
    )


def _dataset_rebin_status_text(dataset: DatasetEntry, config: dict[str, Any]) -> str:
    if not bool(config.get("enabled", False)):
        return "Rebinning is disabled."
    size_note = "large dataset" if _dataset_rebin_is_large(dataset, config) else "small dataset"
    if bool(config.get("auto_rebin", True)):
        if bool(config.get("stale", False)):
            return f"Automatic rebinning is on ({size_note}); pending edits will recompute on the next refresh."
        return f"Automatic rebinning is on ({size_note}); edits recompute the cached rebin."
    if bool(config.get("stale", False)):
        return "Manual rebin pending; press Rebin now or start a fit/view/export operation to compute it."
    return f"Manual rebinning is on ({size_note}); cached rebin is current."


def _dataset_rebin_auto_enabled(dataset: DatasetEntry) -> bool:
    config = dataset_rebin_config(dataset)
    return bool(config.get("auto_rebin", True))


def _dataset_rebin_is_stale(dataset: DatasetEntry) -> bool:
    config = dataset.parameters.get(DATASET_REBIN_KEY)
    return bool(isinstance(config, dict) and config.get("stale", False))


def _should_defer_dataset_rebin(dataset: DatasetEntry, *, force_rebin: bool) -> bool:
    return bool(
        dataset_rebin_enabled(dataset)
        and not force_rebin
        and _dataset_rebin_is_stale(dataset)
        and not _dataset_rebin_auto_enabled(dataset)
    )


def rebinned_dataset_data(
    dataset: DatasetEntry,
    *,
    extra_masks: list[MaskSpec] | None = None,
    progress_callback: Any | None = None,
) -> Any:
    """Return a rebinned copy of a supported dataset according to its configuration."""

    config = dataset_rebin_config(dataset)
    if isinstance(dataset.data, PointListData):
        result = _rebin_point_list_data(dataset, config)
        config["stale"] = False
        return result
    if isinstance(dataset.data, PointData4D):
        result = _rebin_point_data(
            _point_data_with_nfit_masks(dataset, dataset.data, extra_masks=extra_masks),
            config,
            progress_callback=progress_callback,
        )
        config["stale"] = False
        return result
    if not isinstance(dataset.data, MDHistoData):
        return dataset.data
    masked = _mdhisto_with_nfit_masks(dataset, data=dataset.data, extra_masks=extra_masks)
    result = _with_rebinned_mask_metadata(
        _rebin_mdhisto_data(masked, config, progress_callback=progress_callback),
        masked,
    )
    config["stale"] = False
    return result


def _with_rebinned_mask_metadata(rebinned: MDHistoData, source: MDHistoData) -> MDHistoData:
    """Annotate a rebinned MDHisto result whose source masks were applied up front."""

    metadata = dict(rebinned.metadata)
    rebin_metadata = dict(metadata.get("rebin", {}))
    for key in ("file_mask_count", "nfit_mask_count", "combined_mask_count"):
        if key in source.metadata:
            rebin_metadata[f"source_{key}"] = int(source.metadata[key])
    metadata["rebin"] = rebin_metadata
    output_mask = np.asarray(rebinned.mask, dtype=bool)
    metadata["file_mask"] = np.zeros(rebinned.shape, dtype=bool)
    metadata["nfit_mask"] = np.zeros(rebinned.shape, dtype=bool)
    metadata["file_mask_count"] = 0
    metadata["nfit_mask_count"] = 0
    metadata["combined_mask_count"] = int(np.count_nonzero(output_mask))
    return replace(rebinned, metadata=metadata)


def _rebin_point_list_data(dataset: DatasetEntry, config: dict[str, Any]) -> PointListData:
    """Rebin transformed point-list data over its coordinates into a histogram."""

    prepared = prepared_point_list_data(dataset)
    axes_config = [_sanitize_rebin_axis_config(axis) for axis in config.get("axes", [])]
    coordinate_names = [axis.get("name") for axis in axes_config if axis.get("name") in prepared.columns]
    if not coordinate_names:
        coordinate_names = list(prepared.coordinate_names)
    lower = [axis["lower"] for axis in axes_config[: len(coordinate_names)]] or None
    upper = [axis["upper"] for axis in axes_config[: len(coordinate_names)]] or None
    result = prepared.rebin_to_histogram(
        coordinate_names,
        lower=lower,
        upper=upper,
        **_rebin_grid_kwargs(config, axes_config[: len(coordinate_names)]),
        fractional=bool(config.get("fractional", False)),
        normalize=True,
        mean_weighting=_rebin_mean_weighting(config),
        max_batch_bytes=_rebin_max_batch_bytes(config),
        symmetry_operations=_rebin_symmetry_matrices(config, prepared.metadata.get("lattice_parameters")),
    )
    metadata = dict(result.metadata)
    symmetry_metadata = _rebin_symmetry_metadata(config, prepared.metadata.get("lattice_parameters"))
    if symmetry_metadata is not None:
        metadata.setdefault("rebin", {})["symmetry"] = symmetry_metadata
    return result.with_updates(metadata=metadata)


def _rebin_mean_weighting(config: dict[str, Any]) -> str:
    value = config.get("mean_weighting")
    return str(value) if value in {"inverse_variance", "uniform"} else "inverse_variance"


def _rebin_minimum_coverage(config: dict[str, Any]) -> float:
    try:
        value = float(config.get("minimum_coverage", DEFAULT_MINIMUM_COVERAGE))
    except (TypeError, ValueError):
        return DEFAULT_MINIMUM_COVERAGE
    return float(np.clip(value, 0.0, 1.0))


def _rebin_max_batch_mb(config: dict[str, Any]) -> int:
    try:
        return max(int(config.get("max_batch_mb", DEFAULT_REBIN_MAX_BATCH_MB)), 1)
    except (TypeError, ValueError):
        return DEFAULT_REBIN_MAX_BATCH_MB


def _rebin_max_batch_bytes(config: dict[str, Any]) -> int:
    return _rebin_max_batch_mb(config) * 1024 * 1024


def _rebin_resolution_mode(config: dict[str, Any]) -> str:
    """Return the active resolution control mode for a rebin panel."""

    return "bins" if config.get(REBIN_RESOLUTION_MODE_KEY) == "bins" else "step"


def _rebin_grid_kwargs(config: dict[str, Any], axes_config: list[dict[str, Any]]) -> dict[str, list[float] | list[int]]:
    """Return the active resolution without converting step-mode edges to equal bins."""

    if _rebin_resolution_mode(config) == "step":
        return {"step_size": [float(axis["step_size"]) for axis in axes_config]}
    return {"num_bins": [int(axis["num_bins"]) for axis in axes_config]}


def _composite_rebin_step_sizes(config: dict[str, Any]) -> list[float] | None:
    """Return composite step sizes only when the composite is in Step mode."""

    if _rebin_resolution_mode(config) != "step":
        return None
    return [
        float(axis["step_size"])
        for axis in (_sanitize_rebin_axis_config(axis) for axis in config.get("axes", []))
    ]


def create_rebinned_dataset(
    group: DataGroup,
    dataset: DatasetEntry,
    *,
    name: str | None = None,
    progress_callback: Any | None = None,
) -> DatasetEntry:
    """Materialize a dataset's rebinned view as an independent dataset."""

    data = rebinned_dataset_data(
        dataset,
        extra_masks=effective_dataset_masks(group, dataset),
        progress_callback=progress_callback,
    )
    parameters = {}
    for key in (
        "temperature",
        "magnetic_field",
        KINEMATIC_KF_KI_INCLUDED_KEY,
        SPECTRAL_CHANNEL_CONFIG_KEY,
    ):
        if key in dataset.parameters:
            parameters[key] = copy.deepcopy(dataset.parameters[key])
    new_entry = DatasetEntry(
        name=_unique_dataset_name(name or f"{dataset.name} rebinned", group.dataset_names),
        data=data,
        kind=dataset.kind,
        metadata={
            **copy.deepcopy(dataset.metadata),
            "source_dataset": dataset.name,
            "rebin_materialized": True,
        },
        parameters=parameters,
        masks=copy.deepcopy(dataset.masks),
    )
    new_entry.replace_data(data, source_backed=False)
    group.add_dataset(new_entry)
    return new_entry


def save_dataset_file(dataset: DatasetEntry, path: str | Path, *, use_view: bool = True) -> None:
    """Save a supported dataset to a portable, re-importable ``.npz`` file."""

    data = dataset_for_slice_viewer(dataset) if use_view else dataset.data
    if isinstance(data, PointListData):
        _save_point_list_file(data, path)
        return
    if not isinstance(data, MDHistoData):
        raise TypeError("dataset saving currently supports MDHistoData or PointListData datasets")
    saved_metadata = dict(data.metadata)
    saved_metadata.setdefault("signal_semantics", signal_semantics(data))
    payload: dict[str, Any] = {
        "nfit_dataset_format": np.asarray("nfit-dataset"),
        "nfit_dataset_version": np.asarray(3, dtype=int),
        "nfit_data_container": np.asarray("mdhisto"),
        "signal": data.signal,
        "errors": data.errors,
        "mask": data.mask,
        "num_events": data.num_events,
        "metadata_json": json.dumps(_json_safe_value(saved_metadata), sort_keys=True),
        "axis_count": np.asarray(len(data.axes), dtype=int),
        "coordinate_system": np.asarray(-1 if data.coordinate_system is None else data.coordinate_system),
        "visual_normalization": np.asarray(
            -1 if data.visual_normalization is None else data.visual_normalization
        ),
    }
    context = {
        key: copy.deepcopy(dataset.parameters[key])
        for key in (
            "temperature",
            "magnetic_field",
            KINEMATIC_KF_KI_INCLUDED_KEY,
            SPECTRAL_CHANNEL_CONFIG_KEY,
        )
        if key in dataset.parameters
    }
    observable = data.metadata.get("spectral_observable")
    if isinstance(observable, dict) and SPECTRAL_CHANNEL_CONFIG_KEY in context:
        saved_config = dict(context[SPECTRAL_CHANNEL_CONFIG_KEY])
        saved_config["source_representation"] = str(
            observable.get("fit_representation", saved_config["source_representation"])
        )
        saved_config["source_unit"] = (
            str(data.metadata.get("signal_unit", "arbitrary")) or "arbitrary"
        )
        saved_config["signal_per_mbarn"] = 0.0
        context[SPECTRAL_CHANNEL_CONFIG_KEY] = saved_config
    payload["dataset_context_json"] = np.asarray(json.dumps(_json_safe_value(context), sort_keys=True))
    for index, axis in enumerate(data.axes):
        payload[f"axis_{index}_values"] = axis.values
        payload[f"axis_{index}_name"] = np.asarray(axis.name)
        payload[f"axis_{index}_units"] = np.asarray(axis.units)
        payload[f"axis_{index}_kind"] = np.asarray(axis.kind)
        payload[f"axis_{index}_frame"] = np.asarray(axis.frame or "")
        payload[f"axis_{index}_path"] = np.asarray(axis.path or "")
        payload[f"axis_{index}_metadata_json"] = np.asarray(json.dumps(_json_safe_value(axis.metadata), sort_keys=True))
    payload["auxiliary_channel_names_json"] = np.asarray(json.dumps(list(data.auxiliary_channels)))
    for index, channel in enumerate(data.auxiliary_channels.values()):
        payload[f"auxiliary_{index}_values"] = channel.values
        if channel.errors is not None:
            payload[f"auxiliary_{index}_errors"] = channel.errors
        payload[f"auxiliary_{index}_label"] = np.asarray(channel.label)
        payload[f"auxiliary_{index}_unit"] = np.asarray(channel.unit)
        payload[f"auxiliary_{index}_quantity_type"] = np.asarray(
            channel.quantity_type
        )
    np.savez_compressed(path, **payload)


def _save_point_list_file(data: PointListData, path: str | Path) -> None:
    """Save point-list columns and roles to a script-readable ``.npz`` file."""

    payload: dict[str, Any] = {
        "nfit_dataset_format": np.asarray("nfit-dataset"),
        "nfit_dataset_version": np.asarray(1, dtype=int),
        "nfit_data_container": np.asarray("point_list"),
        "column_names_json": json.dumps(list(data.column_names)),
        "coordinate_names_json": json.dumps(list(data.coordinate_names)),
        "channels_json": json.dumps(_json_safe_value(data.channels)),
        "units_json": json.dumps(_json_safe_value(data.units)),
        "quantity_types_json": json.dumps(_json_safe_value(data.quantity_types)),
        "metadata_json": json.dumps(_json_safe_value(data.metadata), sort_keys=True),
    }
    for index, name in enumerate(data.column_names):
        payload[f"column_{index}"] = np.asarray(data.column(name), dtype=float)
    np.savez_compressed(path, **payload)


def _load_nfit_dataset_file(path: str | Path) -> tuple[MDHistoData | PointListData, dict[str, Any]]:
    """Load an nfit dataset archive written by :func:`save_dataset_file`."""

    source = Path(path)
    try:
        archive = np.load(source, allow_pickle=False)
    except (OSError, ValueError) as exc:
        raise ValueError(f"could not read nfit dataset archive {source}") from exc
    with archive:
        files = set(archive.files)
        if {"signal", "errors", "mask", "num_events", "axis_count"} <= files:
            data = _load_nfit_mdhisto_archive(archive, source)
        elif {"column_names_json", "coordinate_names_json", "channels_json", "units_json"} <= files:
            data = _load_nfit_point_list_archive(archive, source)
        else:
            raise ValueError(f"{source} is not an nfit dataset archive")
        context = _nfit_archive_json_mapping(archive, "dataset_context_json")
    return data, context


def _load_nfit_mdhisto_archive(archive: Any, source: Path) -> MDHistoData:
    axis_count = int(np.asarray(archive["axis_count"]).item())
    axes = []
    for index in range(axis_count):
        prefix = f"axis_{index}_"
        values_key = f"{prefix}values"
        if values_key not in archive:
            raise ValueError(f"{source} is missing {values_key}")
        axes.append(
            MDHistoAxis(
                name=_nfit_archive_text(archive, f"{prefix}name", f"Axis {index}"),
                values=np.asarray(archive[values_key], dtype=float),
                units=_nfit_archive_text(archive, f"{prefix}units"),
                kind=_nfit_archive_text(archive, f"{prefix}kind", "unknown"),
                frame=_nfit_archive_text(archive, f"{prefix}frame") or None,
                path=_nfit_archive_text(archive, f"{prefix}path") or None,
                metadata=_nfit_archive_json_mapping(archive, f"{prefix}metadata_json"),
            )
        )
    metadata = _nfit_archive_json_mapping(archive, "metadata_json")
    metadata["export_file"] = str(source)
    if "signal_semantics" not in metadata:
        raise ValueError(
            f"{source} is missing signal_semantics metadata; "
            "re-export it with a current nfit version"
        )
    channel_names = json.loads(_nfit_archive_text(archive, "auxiliary_channel_names_json", "[]"))
    auxiliary_channels = {
        str(name): MDHistoChannel(
            values=np.asarray(archive[f"auxiliary_{index}_values"], dtype=float),
            errors=(np.asarray(archive[f"auxiliary_{index}_errors"], dtype=float) if f"auxiliary_{index}_errors" in archive else None),
            label=_nfit_archive_text(archive, f"auxiliary_{index}_label", str(name)),
            unit=_nfit_archive_text(archive, f"auxiliary_{index}_unit"),
            quantity_type=_nfit_archive_text(
                archive, f"auxiliary_{index}_quantity_type", "unknown"
            ),
        )
        for index, name in enumerate(channel_names)
    }
    return MDHistoData(
        axes=tuple(axes),
        signal=np.asarray(archive["signal"], dtype=float),
        errors=np.asarray(archive["errors"], dtype=float),
        mask=np.asarray(archive["mask"], dtype=bool),
        num_events=np.asarray(archive["num_events"], dtype=float),
        coordinate_system=_nfit_archive_optional_int(archive, "coordinate_system"),
        visual_normalization=_nfit_archive_optional_int(archive, "visual_normalization"),
        metadata=metadata,
        auxiliary_channels=auxiliary_channels,
    )


def _load_nfit_point_list_archive(archive: Any, source: Path) -> PointListData:
    names = json.loads(_nfit_archive_text(archive, "column_names_json"))
    columns = {str(name): np.asarray(archive[f"column_{index}"], dtype=float) for index, name in enumerate(names)}
    metadata = _nfit_archive_json_mapping(archive, "metadata_json")
    metadata["export_file"] = str(source)
    return PointListData(
        columns=columns,
        units=_nfit_archive_json_mapping(archive, "units_json"),
        coordinate_names=json.loads(_nfit_archive_text(archive, "coordinate_names_json")),
        channels=json.loads(_nfit_archive_text(archive, "channels_json")),
        metadata=metadata,
        quantity_types=_nfit_archive_json_mapping(archive, "quantity_types_json"),
    )


def _nfit_archive_text(archive: Any, key: str, default: str = "") -> str:
    return str(np.asarray(archive[key]).item()) if key in archive else default


def _nfit_archive_optional_int(archive: Any, key: str) -> int | None:
    """Read an optional archive integer, where ``-1`` represents ``None``."""

    if key not in archive:
        return None
    value = int(np.asarray(archive[key]).item())
    return None if value < 0 else value


def _nfit_archive_json_mapping(archive: Any, key: str) -> dict[str, Any]:
    if key not in archive:
        return {}
    try:
        value = json.loads(_nfit_archive_text(archive, key))
    except json.JSONDecodeError as exc:
        raise ValueError(f"invalid JSON field {key!r} in nfit dataset archive") from exc
    return dict(value) if isinstance(value, dict) else {}


def _json_safe_value(value: Any) -> Any:
    if isinstance(value, dict):
        return {str(key): _json_safe_value(item) for key, item in value.items()}
    if isinstance(value, (list, tuple)):
        return [_json_safe_value(item) for item in value]
    if isinstance(value, np.ndarray):
        return value.tolist()
    if isinstance(value, np.generic):
        return value.item()
    if isinstance(value, (str, int, float, bool)) or value is None:
        return value
    return repr(value)


def _default_rebin_axes(data: Any) -> list[dict[str, Any]]:
    if isinstance(data, PointListData):
        axes = []
        coordinate_names = list(data.coordinate_names) or list(data.column_names)[:1]
        for name in coordinate_names:
            values = np.asarray(data.column(name), dtype=float)
            finite = values[np.isfinite(values)]
            lower = float(np.min(finite)) if finite.size else 0.0
            upper = float(np.max(finite)) if finite.size else 1.0
            num_bins = max(int(np.unique(finite).size), 1) if finite.size else 1
            num_bins = min(num_bins, 200)
            axes.append(
                {
                    "name": name,
                    "units": data.unit(name),
                    "lower": lower,
                    "upper": upper,
                    "num_bins": num_bins,
                    "step_size": _step_size_from_bounds(lower, upper, num_bins),
                }
            )
        return axes
    if isinstance(data, MDHistoData):
        axes: list[dict[str, Any]] = []
        ndim = len(data.axes)
        for index, (axis, size) in enumerate(zip(data.axes, data.shape, strict=True)):
            lower, upper = _axis_bounds(axis, size)
            num_bins = max(int(size), 1)
            vector = _mdhisto_rebin_axis_vector(axis, index, ndim)
            variable = _mdhisto_rebin_axis_variable(axis, index, ndim)
            axes.append(
                {
                    "name": _rebin_axis_name(variable, vector),
                    "variable": variable,
                    "units": axis.units,
                    "vector": vector,
                    "lower": lower,
                    "upper": upper,
                    "num_bins": num_bins,
                    "step_size": _step_size_from_bounds(lower, upper, num_bins),
                }
            )
        return axes
    if isinstance(data, PointData4D):
        axes = []
        for index, (name, units, values) in enumerate(
            (
                ("H", "rlu", data.H),
                ("K", "rlu", data.K),
                ("L", "rlu", data.L),
                ("E", "meV", data.E),
            )
        ):
            finite = np.asarray(values, dtype=float)
            finite = finite[np.isfinite(finite)]
            lower = float(np.min(finite)) if finite.size else 0.0
            upper = float(np.max(finite)) if finite.size else 1.0
            num_bins = max(int(np.unique(finite).size), 1) if finite.size else 1
            axes.append(
                {
                    "name": name,
                    "units": units,
                    "vector": _identity_vector(index, 4),
                    "lower": lower,
                    "upper": upper,
                    "num_bins": num_bins,
                    "step_size": _step_size_from_bounds(lower, upper, num_bins),
                }
            )
        return axes
    return []


def _axis_bounds(axis: MDHistoAxis, size: int) -> tuple[float, float]:
    values = np.asarray(axis.values, dtype=float)
    if values.size == size + 1:
        return float(values[0]), float(values[-1])
    centers = axis.centers
    if centers.size == 0:
        return 0.0, 1.0
    if centers.size == 1:
        return float(centers[0] - 0.5), float(centers[0] + 0.5)
    step = float(np.nanmedian(np.diff(centers)))
    return float(centers[0] - 0.5 * step), float(centers[-1] + 0.5 * step)


def _step_size_from_bounds(lower: float, upper: float, num_bins: int) -> float:
    if num_bins <= 0:
        return 0.0
    return float((float(upper) - float(lower)) / float(num_bins))


def _num_bins_from_step_size(lower: Any, upper: Any, step_size: float) -> int:
    width = abs(float(upper) - float(lower))
    if width == 0.0:
        return 1
    return max(int(np.ceil(width / float(step_size))), 1)


def _sanitize_rebin_axis_config(axis_config: dict[str, Any]) -> dict[str, Any]:
    lower = float(axis_config.get("lower", 0.0))
    upper = float(axis_config.get("upper", lower))
    num_bins = max(int(axis_config.get("num_bins", 1)), 1)
    try:
        step_size = float(axis_config.get("step_size"))
    except (TypeError, ValueError):
        step_size = 0.0
    if not np.isfinite(step_size) or step_size <= 0.0:
        step_size = _step_size_from_bounds(lower, upper, num_bins)
    sanitized = {
        **axis_config,
        "lower": lower,
        "upper": upper,
        "num_bins": num_bins,
        "step_size": step_size,
    }
    vector = axis_config.get("vector")
    if isinstance(vector, (list, tuple, np.ndarray)):
        sanitized["vector"] = [_clean_axis_weight(component) for component in vector]
    return sanitized


def _rebin_axis_vector(axis_config: dict[str, Any], index: int, ndim: int) -> np.ndarray:
    """Return the projection vector for a rebin output axis, falling back to identity."""

    vector = axis_config.get("vector")
    if isinstance(vector, (list, tuple, np.ndarray)) and len(vector) == ndim:
        candidate = np.asarray(vector, dtype=float)
        if np.all(np.isfinite(candidate)):
            return candidate
    return np.asarray(_identity_vector(index if 0 <= index < ndim else 0, ndim), dtype=float)


def _mdhisto_rebin_axis_variable(axis: MDHistoAxis, index: int, ndim: int) -> str:
    """Return the scalar variable used to parameterize one rebin axis row."""

    role_variables = {"h": "H", "k": "K", "l": "L", "energy_transfer": "E"}
    if axis.role in role_variables:
        return role_variables[axis.role]
    symbols = re.findall(r"[HKL]", str(axis.name).upper())
    if symbols:
        return symbols[0]
    if ndim == 4 and 0 <= index < 4:
        return ("H", "K", "L", "E")[index]
    return str(axis.name or f"Axis {index + 1}")


def _rebin_axis_name(variable: str, vector: Any) -> str:
    """Generate the plotted axis name from its variable and HKLE direction."""

    values = np.asarray(vector, dtype=float).reshape(-1)
    if values.size == 4 and str(variable).upper() == "E":
        coefficient = _clean_axis_weight(values[3])
        if coefficient == 1.0:
            return "DeltaE"
        return f"{coefficient:g}DeltaE"
    if values.size == 4:
        symbol = str(variable).upper()
        terms = []
        for value in values[:3]:
            coefficient = _clean_axis_weight(value)
            if coefficient == 0.0:
                terms.append("0")
            elif coefficient == 1.0:
                terms.append(symbol)
            elif coefficient == -1.0:
                terms.append(f"-{symbol}")
            else:
                terms.append(f"{coefficient:g}{symbol}")
        return f"[{','.join(terms)}]"
    return str(variable)


def _validate_mdhisto_rebin_basis(axes_config: list[dict[str, Any]], ndim: int) -> np.ndarray:
    """Validate and return the output basis represented by rebin axis rows."""

    basis = np.vstack(
        [_rebin_axis_vector(axis_config, index, ndim) for index, axis_config in enumerate(axes_config)]
    )
    if basis.shape != (ndim, ndim) or not np.all(np.isfinite(basis)):
        raise ValueError("coordinate axes must form a finite square basis")
    if ndim == 4:
        for index, (axis_config, vector) in enumerate(zip(axes_config, basis, strict=True)):
            variable = str(axis_config.get("variable", "")).upper()
            if variable == "E":
                if np.any(vector[:3] != 0.0) or vector[3] == 0.0:
                    raise ValueError(
                        f"axis row {index + 1} is the energy variable and must contain only a nonzero E component"
                    )
            elif vector[3] != 0.0:
                raise ValueError(
                    f"axis row {index + 1} is a momentum variable; momentum and energy components cannot be mixed"
                )
    if np.linalg.matrix_rank(basis) != ndim:
        raise ValueError("coordinate axis vectors must be linearly independent")
    return basis


def _mdhisto_rebin_basis_transform(
    data: MDHistoData,
    axes_config: list[dict[str, Any]],
) -> np.ndarray:
    """Map source bin coordinates into coordinates of the requested basis."""

    ndim = len(data.axes)
    output_basis = _validate_mdhisto_rebin_basis(axes_config, ndim)
    source_vectors = _mdhisto_rebin_source_axis_vectors(data)
    if any(vector is None for vector in source_vectors):
        raise ValueError("source axes do not define a complete coordinate basis")
    source_basis = np.vstack(source_vectors)
    if source_basis.shape != (ndim, ndim) or np.linalg.matrix_rank(source_basis) != ndim:
        raise ValueError("source coordinate axes must be linearly independent")
    return source_basis @ np.linalg.inv(output_basis)


def _mdhisto_rebin_basis_bounds(
    data: MDHistoData,
    axes_config: list[dict[str, Any]],
) -> list[tuple[float, float]]:
    """Return a bounding box containing the full source grid in a new basis."""

    transform = _mdhisto_rebin_basis_transform(data, axes_config)
    source_bounds = [_axis_bounds(axis, size) for axis, size in zip(data.axes, data.shape, strict=True)]
    bounds = []
    for output_index in range(transform.shape[1]):
        lower = 0.0
        upper = 0.0
        for (source_lower, source_upper), coefficient in zip(
            source_bounds, transform[:, output_index], strict=True
        ):
            endpoints = (coefficient * source_lower, coefficient * source_upper)
            lower += min(endpoints)
            upper += max(endpoints)
        bounds.append((float(lower), float(upper)))
    return bounds


def _update_mdhisto_rebin_basis(
    data: MDHistoData,
    axes_config: list[dict[str, Any]],
    index: int,
    vector: list[float],
) -> None:
    """Apply one basis edit, regenerating names and full-data output bounds."""

    candidate = [dict(axis) for axis in axes_config]
    candidate[index]["vector"] = list(vector)
    _validate_mdhisto_rebin_basis(candidate, len(data.axes))
    bounds = _mdhisto_rebin_basis_bounds(data, candidate)
    for axis_config, (lower, upper) in zip(candidate, bounds, strict=True):
        previous_step = float(axis_config.get("step_size", 0.0) or 0.0)
        axis_config["lower"] = lower
        axis_config["upper"] = upper
        if previous_step > 0.0 and np.isfinite(previous_step):
            axis_config["num_bins"] = _num_bins_from_step_size(lower, upper, previous_step)
        axis_config["name"] = _rebin_axis_name(
            str(axis_config.get("variable", "")), axis_config.get("vector", [])
        )
        axis_config.update(_sanitize_rebin_axis_config(axis_config))
    axes_config[:] = candidate


def _mdhisto_rebin_axis_vector(axis: MDHistoAxis, index: int, ndim: int) -> list[float]:
    """Return a default rebin vector that follows the displayed MDHisto axis."""

    if ndim == 4:
        role = axis.role
        role_vectors = {
            "h": [1.0, 0.0, 0.0, 0.0],
            "k": [0.0, 1.0, 0.0, 0.0],
            "l": [0.0, 0.0, 1.0, 0.0],
            "energy_transfer": [0.0, 0.0, 0.0, 1.0],
        }
        if role in role_vectors:
            return role_vectors[role]
        projection = _axis_projection_vector(axis.name)
        if projection is not None:
            return [_clean_axis_weight(value) for value in [*projection.tolist(), 0.0]]
    return _identity_vector(index, ndim)


def _mdhisto_rebin_source_axis_vectors(data: MDHistoData) -> list[np.ndarray | None]:
    vectors: list[np.ndarray | None] = []
    if len(data.axes) != 4:
        return [None for _axis in data.axes]
    for axis in data.axes:
        vectors.append(np.asarray(_mdhisto_rebin_axis_vector(axis, len(vectors), len(data.axes)), dtype=float))
    return vectors


def _mdhisto_rebin_component(
    data: MDHistoData,
    source_grids: list[np.ndarray],
    axis_config: dict[str, Any],
    index: int,
) -> np.ndarray:
    ndim = len(data.axes)
    vector = _rebin_axis_vector(axis_config, index, ndim)
    component = np.zeros(data.shape, dtype=float)
    if vector.size == 4:
        source_vectors = _mdhisto_rebin_source_axis_vectors(data)
        for source_vector, grid in zip(source_vectors, source_grids, strict=True):
            if source_vector is not None and np.allclose(vector, source_vector):
                return np.asarray(grid, dtype=float)
        coords = _mdhisto_coordinate_grids(data)
        if all(name in coords for name in ("H", "K", "L", "E")):
            for weight, name in zip(vector, ("H", "K", "L", "E"), strict=True):
                if weight:
                    component = component + float(weight) * coords[name]
            return component
    for weight, grid in zip(vector, source_grids, strict=True):
        if weight:
            component = component + float(weight) * grid
    return component


def _mdhisto_axis_edges(axis: MDHistoAxis, size: int) -> np.ndarray:
    values = np.asarray(axis.values, dtype=float)
    if values.size == size + 1:
        return values
    if values.size == size:
        if size == 1:
            return np.asarray([values[0] - 0.5, values[0] + 0.5])
        edges = np.empty(size + 1, dtype=float)
        edges[1:-1] = 0.5 * (values[:-1] + values[1:])
        edges[0] = values[0] - 0.5 * (values[1] - values[0])
        edges[-1] = values[-1] + 0.5 * (values[-1] - values[-2])
        return edges
    raise ValueError(f"axis {axis.name!r} does not define {size} bins")


def _mdhisto_cell_volumes(data: MDHistoData) -> np.ndarray:
    """Return native hypervolumes represented by MDHisto bin centers."""

    volume = np.ones(data.shape, dtype=float)
    for dim, (axis, size) in enumerate(zip(data.axes, data.shape, strict=True)):
        edges = _mdhisto_axis_edges(axis, size)
        widths = np.diff(edges)
        shape = [1] * data.signal.ndim
        shape[dim] = size
        volume *= widths.reshape(shape)
    return np.abs(volume)


def _output_bin_volumes(bins_list: Sequence[np.ndarray]) -> np.ndarray:
    shape = tuple(len(values) - 1 for values in bins_list)
    volume = np.ones(shape, dtype=float)
    for dim, values in enumerate(bins_list):
        widths = np.abs(np.diff(np.asarray(values, dtype=float)))
        reshape = [1] * len(shape)
        reshape[dim] = widths.size
        volume *= widths.reshape(reshape)
    return volume


def _rebin_mdhisto_coverage(
    data: MDHistoData,
    coords: np.ndarray,
    config: dict[str, Any],
    axes_config: Sequence[dict[str, Any]],
    bins_list: Sequence[np.ndarray],
    *,
    symmetry: Sequence[np.ndarray] | None = None,
    output_axes: np.ndarray | None = None,
) -> np.ndarray:
    """Map measured native-bin hypervolume into requested output bins."""

    source_coverage = mdhisto_coverage_fraction(data)
    usable = (
        np.isfinite(data.signal)
        & np.isfinite(data.errors)
        & ~np.asarray(data.mask, dtype=bool)
        & mdhisto_measured_bins(data)
    )
    source_coverage = np.where(usable, source_coverage, 0.0)
    source_volume = _mdhisto_cell_volumes(data)
    vectors = np.asarray(
        [
            _rebin_axis_vector(axis_config, index, data.signal.ndim)
            for index, axis_config in enumerate(axes_config)
        ],
        dtype=float,
    )
    mapping = (
        _mdhisto_rebin_basis_transform(data, list(axes_config))
        if data.signal.ndim == 4
        else vectors.T
    )
    if mapping.shape == (data.signal.ndim, data.signal.ndim):
        source_volume = source_volume * abs(float(np.linalg.det(mapping)))
    if (
        symmetry is None
        and mapping.shape == (data.signal.ndim, data.signal.ndim)
        and np.allclose(mapping, np.eye(data.signal.ndim))
    ):
        covered_volume = source_coverage
        for dim, (axis, size, output_edges) in enumerate(
            zip(data.axes, data.shape, bins_list, strict=True)
        ):
            source_edges = _mdhisto_axis_edges(axis, size)
            output_edges = np.asarray(output_edges, dtype=float)
            overlap = np.maximum(
                0.0,
                np.minimum(output_edges[1:, None], source_edges[None, 1:])
                - np.maximum(output_edges[:-1, None], source_edges[None, :-1]),
            )
            covered_volume = np.tensordot(
                overlap,
                covered_volume,
                axes=(1, dim),
            )
            covered_volume = np.moveaxis(covered_volume, 0, dim)
        output_volume = _output_bin_volumes(bins_list)
        coverage = np.zeros(output_volume.shape, dtype=float)
        np.divide(
            covered_volume,
            output_volume,
            out=coverage,
            where=output_volume > 0.0,
        )
        return np.clip(coverage, 0.0, 1.0)
    weights = (source_volume * source_coverage).ravel()
    kwargs = dict(
        data_weights=weights,
        lower=[float(np.asarray(values)[0]) for values in bins_list],
        upper=[float(np.asarray(values)[-1]) for values in bins_list],
        **_rebin_grid_kwargs(config, list(axes_config)),
        # Coverage is geometric even when the signal reducer uses nearest-bin
        # assignment. Cloud-in-cell deposition avoids assigning an entire
        # rotated native voxel to whichever output bin contains its center.
        fractional=True,
        normalize=False,
        mean_weighting="uniform",
        max_batch_bytes=_rebin_max_batch_bytes(config),
    )
    coverage_rebin = (
        rebin_nd_symmetry(
            np.ones(data.signal.size, dtype=float),
            np.asarray(coords, dtype=float).reshape(-1, data.signal.ndim),
            symmetry,
            axes=output_axes,
            **kwargs,
        )
        if symmetry is not None
        else rebin_nd(
            np.ones(data.signal.size, dtype=float),
            np.asarray(coords, dtype=float).reshape(-1, data.signal.ndim),
            **kwargs,
        )
    )
    if coverage_rebin.binned_data is None:
        raise RuntimeError("coverage rebinning did not produce binned data")
    output_volume = _output_bin_volumes(bins_list)
    coverage = np.zeros(output_volume.shape, dtype=float)
    np.divide(
        np.asarray(coverage_rebin.binned_data, dtype=float),
        output_volume,
        out=coverage,
        where=output_volume > 0.0,
    )
    return np.clip(coverage, 0.0, 1.0)


def _rebin_mdhisto_data(
    data: MDHistoData,
    config: dict[str, Any],
    *,
    progress_callback: Any | None = None,
) -> MDHistoData:
    axes_config = [_sanitize_rebin_axis_config(axis) for axis in config.get("axes", [])]
    if len(axes_config) != len(data.axes):
        axes_config = _default_rebin_axes(data)
    lower = [axis["lower"] for axis in axes_config]
    upper = [axis["upper"] for axis in axes_config]

    ndim = len(data.axes)
    source_grids = np.meshgrid(*(axis.centers for axis in data.axes), indexing="ij")
    if ndim == 4:
        transform = _mdhisto_rebin_basis_transform(data, axes_config)
        projected = []
        for output_index in range(ndim):
            component = np.zeros(data.shape, dtype=float)
            for source_grid, coefficient in zip(
                source_grids, transform[:, output_index], strict=True
            ):
                if coefficient:
                    component = component + float(coefficient) * source_grid
            projected.append(component)
    else:
        projected = [
            _mdhisto_rebin_component(data, list(source_grids), axis_config, index)
            for index, axis_config in enumerate(axes_config)
        ]
    coords = np.stack(projected, axis=-1)
    symmetry = _rebin_symmetry_matrices(config, data.metadata.get("lattice_parameters"))
    output_axes = None
    if symmetry is not None:
        if ndim != 4:
            raise ValueError("rebin symmetry requires a four-dimensional HKLE dataset")
        physical = _mdhisto_coordinate_grids(data)
        if not all(name in physical for name in ("H", "K", "L", "E")):
            raise ValueError("rebin symmetry requires reconstructable H, K, L, and energy coordinates")
        coords = np.stack([physical[name] for name in ("H", "K", "L", "E")], axis=-1)
        output_axes = _validate_mdhisto_rebin_basis(axes_config, ndim)
    valid = np.isfinite(data.signal) & np.isfinite(data.errors) & ~data.mask
    if data.num_events is not None:
        valid &= mdhisto_measured_bins(data)
    signal = data.signal[valid]
    errors = data.errors[valid]
    coords_valid = coords[valid]
    if signal.size == 0:
        raise ValueError("no valid data points remain before rebinning")
    kwargs = dict(
        data_errs=errors,
        lower=lower,
        upper=upper,
        **_rebin_grid_kwargs(config, axes_config),
        fractional=bool(config.get("fractional", False)),
        normalize=True,
        mean_weighting=_rebin_mean_weighting(config),
        max_batch_bytes=_rebin_max_batch_bytes(config),
        progress_callback=progress_callback,
    )
    result = (
        rebin_nd_symmetry(signal, coords_valid, symmetry, axes=output_axes, **kwargs)
        if symmetry is not None
        else rebin_nd(signal, coords_valid, **kwargs)
    )
    if result.binned_data is None or result.binned_data_errs is None or result.n_samples is None:
        raise RuntimeError("rebinning did not produce binned data")
    if result.bins_list is None:
        raise RuntimeError("rebinning did not produce bins")
    vectors = [_rebin_axis_vector(axis_config, index, ndim).tolist() for index, axis_config in enumerate(axes_config)]
    rebinned_axes = tuple(
        MDHistoAxis(
            name=str(axis_config.get("name") or source_axis.name),
            values=np.asarray(bins, dtype=float),
            units=str(axis_config.get("units") if axis_config.get("units") is not None else source_axis.units),
            kind=source_axis.kind,
            frame=source_axis.frame,
            path=source_axis.path,
            metadata=dict(source_axis.metadata),
        )
        for source_axis, axis_config, bins in zip(data.axes, axes_config, result.bins_list, strict=True)
    )
    mask = ~np.isfinite(result.binned_data) | ~np.isfinite(result.binned_data_errs)
    mask |= result.n_samples <= 0.0
    coverage = _rebin_mdhisto_coverage(
        data,
        coords,
        config,
        axes_config,
        result.bins_list,
        symmetry=symmetry,
        output_axes=output_axes,
    )
    coverage_mask = coverage < _rebin_minimum_coverage(config)
    mask |= coverage_mask
    metadata = dict(data.metadata)
    metadata["signal_semantics"] = "density"
    metadata["signal_semantics_source"] = "nfit_normalized_rebin"
    metadata["coverage_mask_count"] = int(np.count_nonzero(coverage_mask))
    metadata["rebin"] = {
        "lower": lower,
        "upper": upper,
        "step_size": np.asarray(result.step_size, dtype=float).tolist(),
        "num_bins": np.asarray(result.num_bins, dtype=int).tolist(),
        "vectors": vectors,
        "fractional": bool(config.get("fractional", False)),
        "normalize": True,
        "mean_weighting": _rebin_mean_weighting(config),
        "minimum_coverage": _rebin_minimum_coverage(config),
        "max_batch_mb": _rebin_max_batch_mb(config),
        "max_batch_bytes": _rebin_max_batch_bytes(config),
    }
    symmetry_metadata = _rebin_symmetry_metadata(config, data.metadata.get("lattice_parameters"))
    if symmetry_metadata is not None:
        metadata["rebin"]["symmetry"] = symmetry_metadata
    return MDHistoData(
        axes=rebinned_axes,
        signal=np.asarray(result.binned_data, dtype=float),
        errors=np.asarray(result.binned_data_errs, dtype=float),
        mask=np.asarray(mask, dtype=bool),
        num_events=np.asarray(result.n_samples, dtype=float),
        coordinate_system=data.coordinate_system,
        visual_normalization=data.visual_normalization,
        metadata=metadata,
        auxiliary_channels={
            "coverage_fraction": MDHistoChannel(
                coverage,
                label="Coverage",
                unit="fraction",
            )
        },
    )


def _rebin_point_data(
    data: PointData4D,
    config: dict[str, Any],
    *,
    progress_callback: Any | None = None,
) -> PointData4D:
    axes_config = [_sanitize_rebin_axis_config(axis) for axis in config.get("axes", [])]
    if len(axes_config) != 4:
        axes_config = _default_rebin_axes(data)
    lower = [axis["lower"] for axis in axes_config]
    upper = [axis["upper"] for axis in axes_config]
    symmetry = _rebin_symmetry_matrices(config, data.metadata.get("lattice_parameters"))
    result = rebin_point_data(
        data,
        lower=lower,
        upper=upper,
        **_rebin_grid_kwargs(config, axes_config),
        fractional=bool(config.get("fractional", False)),
        normalize=True,
        mean_weighting=_rebin_mean_weighting(config),
        max_batch_bytes=_rebin_max_batch_bytes(config),
        progress_callback=progress_callback,
        symmetry_operations=symmetry,
    )
    metadata = dict(result.metadata)
    symmetry_metadata = _rebin_symmetry_metadata(config, data.metadata.get("lattice_parameters"))
    if symmetry_metadata is not None:
        metadata.setdefault("rebin", {})["symmetry"] = symmetry_metadata
    return result.with_updates(metadata=metadata)


def _point_data_with_nfit_masks(
    dataset: DatasetEntry,
    data: PointData4D,
    *,
    extra_masks: list[MaskSpec] | None = None,
) -> PointData4D:
    reject = ~np.asarray(data.mask, dtype=bool)
    nfit_mask = _nfit_mask_for_point_data(dataset, data, extra_masks=extra_masks)
    combined_reject = reject | nfit_mask
    if not np.any(combined_reject) and np.all(np.asarray(data.mask, dtype=bool)):
        return data
    metadata = dict(data.metadata)
    metadata["nfit_mask_count"] = int(np.count_nonzero(nfit_mask))
    metadata["combined_mask_count"] = int(np.count_nonzero(combined_reject))
    temperature = data.temperature.copy() if isinstance(data.temperature, np.ndarray) else data.temperature
    return PointData4D(
        H=data.H.copy(),
        K=data.K.copy(),
        L=data.L.copy(),
        E=data.E.copy(),
        intensity=data.intensity.copy(),
        sigma=data.sigma.copy(),
        mask=~combined_reject,
        temperature=temperature,
        magnetic_field=None if data.magnetic_field is None else np.array(data.magnetic_field),
        metadata=metadata,
    )


def _nfit_mask_for_point_data(
    dataset: DatasetEntry,
    data: PointData4D,
    *,
    extra_masks: list[MaskSpec] | None = None,
) -> np.ndarray:
    combined = np.zeros(data.size, dtype=bool)
    for mask in [*(extra_masks or []), *dataset.masks]:
        if not mask.enabled:
            continue
        mask_values = _evaluate_point_data_mask(data, mask)
        if mask.invert:
            mask_values = ~mask_values
        if mask.additive:
            combined &= ~mask_values
        else:
            combined |= mask_values
    return combined


def _evaluate_point_data_mask(data: PointData4D, mask: MaskSpec) -> np.ndarray:
    if mask.type == "coordinate_range":
        return _point_data_coordinate_range_mask(data, mask.parameters)
    if mask.type == "energy_q_range":
        return _point_data_energy_q_range_mask(data, mask.parameters)
    if mask.type == "phonon_cone":
        return _point_data_phonon_cone_mask(data, mask.parameters)
    if mask.type == "box":
        return _point_data_box_mask(data, mask.parameters)
    if mask.type == "ellipsoid":
        return _point_data_ellipsoid_mask(data, mask.parameters)
    return np.zeros(data.size, dtype=bool)


def _point_data_coordinate_range_mask(data: PointData4D, parameters: dict[str, Any]) -> np.ndarray:
    reject = np.ones(data.size, dtype=bool)
    active = False
    coords = _point_data_coordinate_values(data)
    for name in COORDINATE_RANGE_PARAMETER_NAMES:
        bounds = _exclusion_parameter_range(parameters.get(name))
        if bounds is None or name not in coords:
            continue
        active = True
        reject &= _values_in_range(coords[name], bounds)
    return reject if active else np.zeros(data.size, dtype=bool)


def _point_data_energy_q_range_mask(data: PointData4D, parameters: dict[str, Any]) -> np.ndarray:
    reject = np.ones(data.size, dtype=bool)
    energy = _exclusion_parameter_range(parameters.get("energy"))
    q_modulus = _exclusion_parameter_range(parameters.get("q_modulus"))
    if energy is None and q_modulus is None:
        return np.zeros(data.size, dtype=bool)
    if energy is not None:
        reject &= _values_in_range(np.asarray(data.E, dtype=float), energy)
    if q_modulus is not None:
        reject &= _values_in_range(_point_data_q_modulus(data), q_modulus)
    return reject


def _point_data_box_mask(data: PointData4D, parameters: dict[str, Any]) -> np.ndarray:
    resolved = _point_data_projected_region_inputs(data, parameters, extent_key="width")
    if resolved is None:
        return np.zeros(data.size, dtype=bool)
    values, center, width = resolved
    half_widths = [0.5 * value for value in width]
    if any(half_width <= 0.0 for half_width in half_widths):
        return np.zeros(data.size, dtype=bool)
    reject = np.ones(data.size, dtype=bool)
    for value, coordinate, half_width in zip(values, center, half_widths, strict=True):
        reject &= np.abs(value - coordinate) <= half_width
    return reject


def _point_data_ellipsoid_mask(data: PointData4D, parameters: dict[str, Any]) -> np.ndarray:
    resolved = _point_data_projected_region_inputs(data, parameters, extent_key="radii")
    if resolved is None:
        return np.zeros(data.size, dtype=bool)
    values, center, radii = resolved
    if any(radius <= 0.0 for radius in radii):
        return np.zeros(data.size, dtype=bool)
    scaled_square = np.zeros(data.size, dtype=float)
    for value, coordinate, radius in zip(values, center, radii, strict=True):
        scaled = (value - coordinate) / radius
        scaled_square = scaled_square + scaled * scaled
    return scaled_square <= 1.0


def _point_data_projected_region_inputs(
    data: PointData4D,
    parameters: dict[str, Any],
    *,
    extent_key: str,
) -> tuple[list[np.ndarray], list[float], list[float]] | None:
    axes = _mask_axis_names(parameters)
    if not axes:
        return None
    center = _parameter_float_sequence(parameters.get("center"))
    extent = _parameter_float_sequence(parameters.get(extent_key))
    if center is None or extent is None:
        return None
    if not len(axes) == len(center) == len(extent):
        return None
    coords = _point_data_coordinate_values(data)
    values: list[np.ndarray] = []
    for name in axes:
        value = _resolve_projected_axis_grid(name, coords)
        if value is None:
            return None
        values.append(value)
    return values, center, extent


def _point_data_phonon_cone_mask(data: PointData4D, parameters: dict[str, Any]) -> np.ndarray:
    slope = _parameter_float(parameters.get("slope"))
    if slope is None or slope <= 0.0:
        return np.zeros(data.size, dtype=bool)
    centers = _coordinate_centers(parameters.get("center"), 3)
    if centers is None:
        return np.zeros(data.size, dtype=bool)
    radius = max(_parameter_float(parameters.get("radius")) or 0.0, 0.0)
    q_vectors = _point_data_q_vectors(data)
    cone_radius = np.abs(np.asarray(data.E, dtype=float)) / slope + radius
    masked = np.zeros(data.size, dtype=bool)
    matrix = _mdhisto_q_matrix(data.metadata)
    centers_q = centers if _metadata_coordinate_units_are_inv_angstrom_for_mdhisto(data.metadata) else centers @ matrix.T
    for center_q in centers_q:
        masked |= np.linalg.norm(q_vectors - center_q, axis=-1) <= cone_radius
    return masked


def _point_data_coordinate_values(data: PointData4D) -> dict[str, np.ndarray]:
    return {
        "H": np.asarray(data.H, dtype=float),
        "K": np.asarray(data.K, dtype=float),
        "L": np.asarray(data.L, dtype=float),
        "E": np.asarray(data.E, dtype=float),
    }


def _point_data_q_vectors(data: PointData4D) -> np.ndarray:
    hkl = np.column_stack([data.H, data.K, data.L])
    if _metadata_coordinate_units_are_inv_angstrom_for_mdhisto(data.metadata):
        return hkl
    return hkl @ _mdhisto_q_matrix(data.metadata).T


def _point_data_q_modulus(data: PointData4D) -> np.ndarray:
    return np.linalg.norm(_point_data_q_vectors(data), axis=1)


def _mdhisto_with_nfit_masks(
    dataset: DatasetEntry,
    *,
    data: MDHistoData | None = None,
    extra_masks: list[MaskSpec] | None = None,
) -> MDHistoData:
    data = dataset.data if data is None else data
    if not isinstance(data, MDHistoData):
        raise TypeError("dataset does not contain MDHistoData")
    file_mask = np.asarray(data.mask, dtype=bool)
    nfit_mask = _nfit_mask_for_mdhisto(dataset, data, extra_masks=extra_masks)
    combined_mask = file_mask | nfit_mask
    metadata = dict(data.metadata)
    metadata["file_mask"] = file_mask.copy()
    metadata["nfit_mask"] = nfit_mask.copy()
    metadata["nfit_mask_count"] = int(np.count_nonzero(nfit_mask))
    metadata["file_mask_count"] = int(np.count_nonzero(file_mask))
    metadata["combined_mask_count"] = int(np.count_nonzero(combined_mask))
    return MDHistoData(
        axes=data.axes,
        signal=data.signal,
        errors=data.errors,
        mask=combined_mask,
        num_events=data.num_events,
        coordinate_system=data.coordinate_system,
        visual_normalization=data.visual_normalization,
        metadata=metadata,
    )


def _nfit_mask_for_mdhisto(
    dataset: DatasetEntry,
    data: MDHistoData,
    *,
    extra_masks: list[MaskSpec] | None = None,
) -> np.ndarray:
    combined = np.zeros(data.shape, dtype=bool)
    # Ancestor group masks apply first, then the dataset's own masks.
    for mask in [*(extra_masks or []), *dataset.masks]:
        if not mask.enabled:
            continue
        mask_values = _evaluate_mdhisto_mask(data, mask)
        if mask.invert:
            mask_values = ~mask_values
        if mask.additive:
            combined &= ~mask_values
        else:
            combined |= mask_values
    return combined


def _evaluate_mdhisto_mask(data: MDHistoData, mask: MaskSpec) -> np.ndarray:
    if mask.type == "coordinate_range":
        return _mdhisto_coordinate_range_mask(data, mask.parameters)
    if mask.type == "energy_q_range":
        return _mdhisto_energy_q_range_mask(data, mask.parameters)
    if mask.type == "phonon_cone":
        return _mdhisto_phonon_cone_mask(data, mask.parameters)
    if mask.type == "box":
        return _mdhisto_box_mask(data, mask.parameters)
    if mask.type == "ellipsoid":
        return _mdhisto_ellipsoid_mask(data, mask.parameters)
    return np.zeros(data.shape, dtype=bool)


def _mdhisto_box_mask(data: MDHistoData, parameters: dict[str, Any]) -> np.ndarray:
    """Mask a projected box, mirroring :func:`nfit.fitting.mask_out_box`.

    ``axes`` names the projected coordinates, ``center`` locates the box, and
    ``width`` gives the full extent along each axis. A point is masked when it
    falls inside the box along every listed axis; the zero-width default (see
    MASK_TYPE_DEFINITIONS) therefore masks nothing.
    """

    resolved = _mdhisto_projected_region_inputs(data, parameters, extent_key="width")
    if resolved is None:
        return np.zeros(data.shape, dtype=bool)
    grids, center, width = resolved
    half_widths = [0.5 * value for value in width]
    if any(half_width <= 0.0 for half_width in half_widths):
        return np.zeros(data.shape, dtype=bool)
    reject = np.ones(data.shape, dtype=bool)
    for grid, coordinate, half_width in zip(grids, center, half_widths, strict=True):
        reject &= np.abs(grid - coordinate) <= half_width
    return reject


def _mdhisto_ellipsoid_mask(data: MDHistoData, parameters: dict[str, Any]) -> np.ndarray:
    """Mask a projected ellipsoid, mirroring :func:`nfit.fitting.mask_out_ellipsoid`.

    ``axes`` names the projected coordinates, ``center`` locates the ellipsoid,
    and ``radii`` gives the radius along each axis. The zero-radius default
    masks nothing.
    """

    resolved = _mdhisto_projected_region_inputs(data, parameters, extent_key="radii")
    if resolved is None:
        return np.zeros(data.shape, dtype=bool)
    grids, center, radii = resolved
    if any(radius <= 0.0 for radius in radii):
        return np.zeros(data.shape, dtype=bool)
    scaled_square = np.zeros(data.shape, dtype=float)
    for grid, coordinate, radius in zip(grids, center, radii, strict=True):
        scaled = (grid - coordinate) / radius
        scaled_square = scaled_square + scaled * scaled
    return scaled_square <= 1.0


def _mdhisto_projected_region_inputs(
    data: MDHistoData,
    parameters: dict[str, Any],
    *,
    extent_key: str,
) -> tuple[list[np.ndarray], list[float], list[float]] | None:
    """Resolve the projected axis grids, center, and extent for box/ellipsoid masks.

    Returns ``None`` when the parameters are incomplete, mismatched in length,
    or name coordinates that cannot be projected onto the dataset axes, so the
    caller can fall back to masking nothing.
    """

    axes = _mask_axis_names(parameters)
    if not axes:
        return None
    center = _parameter_float_sequence(parameters.get("center"))
    extent = _parameter_float_sequence(parameters.get(extent_key))
    if center is None or extent is None:
        return None
    if not len(axes) == len(center) == len(extent):
        return None
    # Range-axis grids supply projected/leftover axis names, but the true
    # reciprocal coordinates (H/K/L/E) must win when a name refers to them.
    coords = _mdhisto_coordinate_range_axis_grids(data, parameters)
    coords.update(_mdhisto_coordinate_grids(data))
    grids: list[np.ndarray] = []
    for name in axes:
        grid = _resolve_projected_axis_grid(name, coords)
        if grid is None:
            return None
        grids.append(grid)
    return grids, center, extent


def _mask_axis_names(parameters: dict[str, Any]) -> list[Any]:
    axes = parameters.get("axes")
    if isinstance(axes, str):
        axes = _parse_parameter_text(axes)
    if not isinstance(axes, (list, tuple)):
        return []
    return list(axes)


def _parameter_float_sequence(value: Any) -> list[float] | None:
    if isinstance(value, str):
        value = _parse_parameter_text(value)
    if not isinstance(value, (list, tuple, np.ndarray)):
        return None
    result: list[float] = []
    for item in value:
        number = _parameter_float(item)
        if number is None:
            return None
        result.append(number)
    return result


def _resolve_projected_axis_grid(name: Any, coords: dict[str, np.ndarray]) -> np.ndarray | None:
    """Resolve a projected axis name (or vector) to a coordinate grid."""

    if isinstance(name, str):
        key = name.strip()
        if key in coords:
            return coords[key]
        if key.upper() in coords:
            return coords[key.upper()]
        projection = _axis_projection_vector(key)
        if projection is not None:
            return _project_hkl_vector(projection, coords)
        parsed = _parse_parameter_text(key)
        if isinstance(parsed, (list, tuple)):
            return _project_hkle_vector(parsed, coords)
        return None
    if isinstance(name, (list, tuple, np.ndarray)):
        return _project_hkle_vector(name, coords)
    return None


def _project_hkl_vector(vector: np.ndarray, coords: dict[str, np.ndarray]) -> np.ndarray | None:
    if not {"H", "K", "L"}.issubset(coords):
        return None
    hkl = np.stack([coords["H"], coords["K"], coords["L"]], axis=-1)
    return hkl @ np.asarray(vector, dtype=float)


def _project_hkle_vector(vector: Any, coords: dict[str, np.ndarray]) -> np.ndarray | None:
    try:
        weights = np.asarray(vector, dtype=float)
    except (TypeError, ValueError):
        return None
    if not np.all(np.isfinite(weights)):
        return None
    if weights.shape == (3,):
        return _project_hkl_vector(weights, coords)
    if weights.shape == (4,) and {"H", "K", "L", "E"}.issubset(coords):
        hkle = np.stack([coords["H"], coords["K"], coords["L"], coords["E"]], axis=-1)
        return hkle @ weights
    return None


def _mdhisto_phonon_cone_mask(data: MDHistoData, parameters: dict[str, Any]) -> np.ndarray:
    slope = _parameter_float(parameters.get("slope"))
    if slope is None or slope <= 0.0:
        # A non-positive slope leaves the starter mask inert (see MASK_TYPE_DEFINITIONS).
        return np.zeros(data.shape, dtype=bool)
    centers = _coordinate_centers(parameters.get("center"), 3)
    if centers is None:
        return np.zeros(data.shape, dtype=bool)
    coords = _mdhisto_coordinate_grids(data)
    if not {"H", "K", "L", "E"}.issubset(coords):
        return np.zeros(data.shape, dtype=bool)
    radius = _parameter_float(parameters.get("radius")) or 0.0
    radius = max(radius, 0.0)

    hkl = np.stack([coords["H"], coords["K"], coords["L"]], axis=-1)
    if _metadata_coordinate_units_are_inv_angstrom_for_mdhisto(data.metadata):
        q_vectors = hkl
        centers_q = centers
    else:
        matrix = _mdhisto_q_matrix(data.metadata)
        q_vectors = np.einsum("ij,...j->...i", matrix, hkl)
        centers_q = centers @ matrix.T

    cone_radius = np.abs(coords["E"]) / slope + radius
    masked = np.zeros(data.shape, dtype=bool)
    for center_q in centers_q:
        masked |= np.linalg.norm(q_vectors - center_q, axis=-1) <= cone_radius
    return masked


def _coordinate_centers(value: Any, ndim: int) -> np.ndarray | None:
    """Parse one coordinate vector or a nonempty list of coordinate vectors."""

    if isinstance(value, str):
        value = _parse_parameter_text(value)
    try:
        centers = np.asarray(value, dtype=float)
    except (TypeError, ValueError):
        return None
    if centers.shape == (ndim,):
        centers = centers.reshape(1, ndim)
    if centers.ndim != 2 or centers.shape[0] == 0 or centers.shape[1] != ndim:
        return None
    return centers if np.all(np.isfinite(centers)) else None


def _parameter_float(value: Any) -> float | None:
    if isinstance(value, str):
        value = _parse_parameter_text(value)
    if value in (None, ""):
        return None
    try:
        result = float(value)
    except (TypeError, ValueError):
        return None
    return result if np.isfinite(result) else None


def _mdhisto_coordinate_range_mask(data: MDHistoData, parameters: dict[str, Any]) -> np.ndarray:
    reject = np.ones(data.shape, dtype=bool)
    active = False
    coords = _mdhisto_coordinate_grids(data)
    coords.update(_mdhisto_coordinate_range_axis_grids(data, parameters))
    for name in COORDINATE_RANGE_PARAMETER_NAMES:
        bounds = _exclusion_parameter_range(parameters.get(name))
        if bounds is None or name not in coords:
            continue
        active = True
        reject &= _values_in_range(coords[name], bounds)
    return reject if active else np.zeros(data.shape, dtype=bool)


def _mdhisto_energy_q_range_mask(data: MDHistoData, parameters: dict[str, Any]) -> np.ndarray:
    reject = np.ones(data.shape, dtype=bool)
    energy = _exclusion_parameter_range(parameters.get("energy"))
    q_modulus = _exclusion_parameter_range(parameters.get("q_modulus"))
    coords = _mdhisto_coordinate_grids(data)
    if energy is None and q_modulus is None:
        return np.zeros(data.shape, dtype=bool)
    if energy is not None:
        if "E" not in coords:
            if not _range_is_unrestricted(energy):
                return np.zeros(data.shape, dtype=bool)
        else:
            reject &= _values_in_range(coords["E"], energy)
    if q_modulus is not None:
        q_values = coords.get("q_modulus")
        if q_values is None:
            q_values = _mdhisto_q_modulus_grid(data, coords)
        reject &= _values_in_range(q_values, q_modulus)
    return reject


def _parameter_range(value: Any) -> tuple[float | None, float | None] | None:
    if value in (None, ""):
        return None
    if isinstance(value, str):
        value = _parse_parameter_text(value)
        if value in (None, ""):
            return None
    if not isinstance(value, (list, tuple)) or len(value) != 2:
        return None
    lower = None if value[0] in (None, "") else float(value[0])
    upper = None if value[1] in (None, "") else float(value[1])
    return lower, upper


def _exclusion_parameter_range(value: Any) -> tuple[float | None, float | None] | None:
    """Return an active exclusion interval; [0, 0] is the neutral GUI default."""

    bounds = _parameter_range(value)
    if bounds is None:
        return None
    if bounds[0] == 0.0 and bounds[1] == 0.0:
        return None
    return bounds


def _values_in_range(values: np.ndarray, bounds: tuple[float | None, float | None]) -> np.ndarray:
    lower, upper = bounds
    selected = np.ones(values.shape, dtype=bool)
    if lower is not None:
        selected &= values >= lower - _range_tolerance(lower)
    if upper is not None:
        selected &= values <= upper + _range_tolerance(upper)
    return selected


def _range_is_unrestricted(bounds: tuple[float | None, float | None]) -> bool:
    lower, upper = bounds
    return lower is None and upper is None


def _range_tolerance(value: float) -> float:
    return max(1.0, abs(float(value))) * 1.0e-12


def _mdhisto_coordinate_range_axis_grids(
    data: MDHistoData,
    parameters: dict[str, Any],
) -> dict[str, np.ndarray]:
    specs = _coordinate_range_axis_specs(data)
    if not specs:
        return {}
    axis_values = np.meshgrid(*(axis.centers for axis in data.axes), indexing="ij")
    source_vectors = _mdhisto_rebin_source_axis_vectors(data)
    coords: dict[str, np.ndarray] = {}
    for index, spec in enumerate(specs):
        key = f"{COORDINATE_RANGE_AXIS_PREFIX}{index}"
        vector = _coordinate_axis_vector(parameters.get(key), len(data.axes))
        if vector is None:
            vector = np.asarray(spec["vector"], dtype=float)
        matched_grid = next(
            (
                axis_grid
                for source_vector, axis_grid in zip(source_vectors, axis_values, strict=True)
                if source_vector is not None and np.allclose(vector, source_vector)
            ),
            None,
        )
        if matched_grid is not None:
            coords[str(spec["name"])] = np.asarray(matched_grid, dtype=float)
            continue
        values = np.zeros(data.shape, dtype=float)
        for axis_weight, axis_grid in zip(vector, axis_values, strict=True):
            if axis_weight:
                values = values + float(axis_weight) * axis_grid
        coords[str(spec["name"])] = values
    return coords


def _coordinate_range_axis_specs(data: Any) -> list[dict[str, Any]]:
    if isinstance(data, MDHistoData):
        return _mdhisto_coordinate_range_axis_specs(data)
    if isinstance(data, PointData4D):
        names = ["H", "K", "L", "E"]
        return [
            {"name": name, "vector": _identity_vector(index, len(names))}
            for index, name in enumerate(names)
        ]
    return []


def _mdhisto_coordinate_range_axis_specs(data: MDHistoData) -> list[dict[str, Any]]:
    ndim = len(data.axes)
    role_names = {"h": "H", "k": "K", "l": "L", "energy_transfer": "E"}
    assigned = {
        role_names[axis.role]
        for axis in data.axes
        if axis.role in role_names
    }
    remaining_names = iter(name for name in COORDINATE_RANGE_PARAMETER_NAMES if name not in assigned)
    specs = []
    for index, axis in enumerate(data.axes):
        name = role_names.get(axis.role)
        if name is None:
            name = next(remaining_names, str(axis.name or f"Axis {index}"))
        specs.append(
            {
                "name": name,
                "vector": _mdhisto_rebin_axis_vector(axis, index, ndim),
            }
        )
    return specs


def _identity_vector(index: int, ndim: int) -> list[float]:
    return [1.0 if axis_index == index else 0.0 for axis_index in range(ndim)]


def _clean_axis_weight(value: Any) -> float:
    """Round a coordinate-axis weight to drop floating-point noise (e.g. 0.5000000000000001 -> 0.5)."""

    rounded = round(float(value), 10)
    return rounded + 0.0  # normalize -0.0 to 0.0


def _coordinate_axis_vector(value: Any, ndim: int) -> np.ndarray | None:
    if isinstance(value, str):
        value = _parse_parameter_text(value)
    if not _is_vector_length(value, ndim):
        return None
    try:
        vector = np.asarray(value, dtype=float)
    except (TypeError, ValueError):
        return None
    if not np.all(np.isfinite(vector)):
        return None
    return vector


def _is_vector_length(value: Any, length: int) -> bool:
    if isinstance(value, str):
        value = _parse_parameter_text(value)
    return isinstance(value, (list, tuple, np.ndarray)) and len(value) == length


def _mdhisto_coordinate_grids(data: MDHistoData) -> dict[str, np.ndarray]:
    """Return physical HKLE grids, reconstructing them from any rebinned basis."""

    shape = data.shape
    axis_values = np.meshgrid(*(axis.centers for axis in data.axes), indexing="ij")
    coords: dict[str, np.ndarray] = {}
    hkle = np.zeros((*shape, 4), dtype=float)
    hkle_contributions = 0
    for index, (axis, values) in enumerate(zip(data.axes, axis_values, strict=True)):
        role = axis.role
        if role == "q_modulus":
            coords["q_modulus"] = values
            continue
        vector = _mdhisto_axis_coordinate_vector(data, index)
        if vector is None:
            vector = {
                "h": np.array([1.0, 0.0, 0.0, 0.0]),
                "k": np.array([0.0, 1.0, 0.0, 0.0]),
                "l": np.array([0.0, 0.0, 1.0, 0.0]),
                "energy_transfer": np.array([0.0, 0.0, 0.0, 1.0]),
            }.get(role)
        if vector is not None:
            hkle += values[..., np.newaxis] * vector
            hkle_contributions += 1
    if hkle_contributions:
        coords.update({"H": hkle[..., 0], "K": hkle[..., 1], "L": hkle[..., 2]})
        if len(data.axes) >= 4 or np.any(hkle[..., 3] != 0.0):
            coords["E"] = hkle[..., 3]
    return coords


def _mdhisto_axis_coordinate_vector(data: MDHistoData, index: int) -> np.ndarray | None:
    """Return an output-axis vector in physical HKLE coordinates when known."""

    rebin = data.metadata.get("rebin") if isinstance(data.metadata, dict) else None
    vectors = rebin.get("vectors") if isinstance(rebin, dict) else None
    if isinstance(vectors, (list, tuple)) and 0 <= index < len(vectors):
        try:
            vector = np.asarray(vectors[index], dtype=float).reshape(-1)
        except (TypeError, ValueError):
            vector = np.asarray([], dtype=float)
        if vector.size in {3, 4} and np.all(np.isfinite(vector)):
            return np.pad(vector, (0, 4 - vector.size))
    projection = _axis_projection_vector(data.axes[index].name)
    if projection is not None:
        return np.pad(projection, (0, 1))
    return None


def _axis_projection_vector(name: str) -> np.ndarray | None:
    match = re.search(r"\[([^\]]+)\]", str(name))
    if match is None:
        return None
    pieces = [piece.strip() for piece in match.group(1).split(",")]
    if len(pieces) != 3:
        return None
    return np.asarray([_projection_piece_value(piece) for piece in pieces], dtype=float)


def _projection_piece_value(piece: str) -> float:
    cleaned = piece.replace(" ", "")
    if cleaned in {"", "0"}:
        return 0.0
    if cleaned in {"H", "K", "L"}:
        return 1.0
    if cleaned in {"-H", "-K", "-L"}:
        return -1.0
    cleaned = re.sub(r"[HKL]", "", cleaned)
    if cleaned in {"", "+"}:
        return 1.0
    if cleaned == "-":
        return -1.0
    return float(cleaned)


def _mdhisto_q_modulus_grid(data: MDHistoData, coords: dict[str, np.ndarray]) -> np.ndarray:
    if not {"H", "K", "L"}.issubset(coords):
        raise ValueError("|Q| masks require H, K, and L coordinates")
    hkl = np.stack([coords["H"], coords["K"], coords["L"]], axis=-1)
    if _metadata_coordinate_units_are_inv_angstrom_for_mdhisto(data.metadata):
        q_vectors = hkl
    else:
        matrix = _mdhisto_q_matrix(data.metadata)
        q_vectors = np.einsum("ij,...j->...i", matrix, hkl)
    return np.linalg.norm(q_vectors, axis=-1)


def _metadata_coordinate_units_are_inv_angstrom_for_mdhisto(metadata: dict[str, Any]) -> bool:
    candidates = [metadata.get("coordinate_units"), metadata.get("momentum_units"), metadata.get("q_units")]
    return any("angstrom" in str(value).lower() and "rlu" not in str(value).lower() for value in candidates if value)


def _mdhisto_q_matrix(metadata: dict[str, Any]) -> np.ndarray:
    for key in ("rlu_to_inv_angstrom_matrix", "ub_matrix", "orientation_matrix"):
        if key in metadata:
            matrix = np.asarray(metadata[key], dtype=float)
            return matrix if key == "rlu_to_inv_angstrom_matrix" or _matrix_includes_2pi(metadata, key) else 2.0 * np.pi * matrix
    oriented_lattice = metadata.get("oriented_lattice")
    if isinstance(oriented_lattice, dict):
        for key in ("rlu_to_inv_angstrom_matrix", "ub_matrix", "orientation_matrix"):
            if key in oriented_lattice:
                matrix = np.asarray(oriented_lattice[key], dtype=float)
                return matrix if key == "rlu_to_inv_angstrom_matrix" or _matrix_includes_2pi(oriented_lattice, key) else 2.0 * np.pi * matrix
    lattice = metadata.get("lattice_parameters")
    if isinstance(lattice, dict):
        from .fitting import reciprocal_basis_from_lattice_parameters

        return reciprocal_basis_from_lattice_parameters(
            a=float(lattice["a"]),
            b=float(lattice["b"]),
            c=float(lattice["c"]),
            alpha=float(lattice.get("alpha", 90.0)),
            beta=float(lattice.get("beta", 90.0)),
            gamma=float(lattice.get("gamma", 90.0)),
            include_2pi=bool(lattice.get("include_2pi", True)),
        )
    raise ValueError("|Q| masks require inverse-angstrom coordinates or an attached lattice/UB matrix")


def _matrix_includes_2pi(metadata: dict[str, Any], key: str) -> bool:
    for flag_key in (f"{key}_includes_2pi", "q_matrix_includes_2pi", "include_2pi", "includes_2pi"):
        if flag_key in metadata:
            return bool(metadata[flag_key])
    lattice = metadata.get("lattice_parameters")
    return bool(isinstance(lattice, dict) and lattice.get("include_2pi"))


def next_data_group_name(groups: list[DataGroup]) -> str:
    """Return the first available WorkspaceN name for a top-level workspace."""

    taken = {group.name for group in groups}
    index = 1
    while f"Workspace{index}" in taken:
        index += 1
    return f"Workspace{index}"


def next_mask_name(masks: list[MaskSpec]) -> str:
    """Return the first available MaskN name."""

    taken = {mask.name for mask in masks}
    index = 1
    while f"Mask{index}" in taken:
        index += 1
    return f"Mask{index}"


def next_model_name(models: dict[str, Any]) -> str:
    """Return the first available ModelN name."""

    taken = set(models)
    index = 1
    while f"Model{index}" in taken:
        index += 1
    return f"Model{index}"


def next_fit_result_name(fits: list[FitTimelineEntry]) -> str:
    """Return the first available Fit ResultN name across a fit tree."""

    return _next_fit_tree_name(fits, "Fit Result")


def next_fit_timeline_name(fits: list[FitTimelineEntry]) -> str:
    """Return the first available TimelineN name across a fit tree."""

    return _next_fit_tree_name(fits, "Timeline")


def _next_fit_tree_name(fits: list[FitTimelineEntry], prefix: str) -> str:
    taken = {entry.name for entry in _walk_fit_entries(fits)}
    index = 1
    while f"{prefix}{index}" in taken:
        index += 1
    return f"{prefix}{index}"


def _walk_fit_entries(fits: list[FitTimelineEntry]):
    for entry in fits:
        yield entry
        yield from _walk_fit_entries(entry.children)


def _fit_entry_in_tree(fits: list[FitTimelineEntry], target: FitTimelineEntry | None) -> bool:
    if target is None:
        return False
    return any(entry is target for entry in _walk_fit_entries(fits))


def _fit_entry_path(
    fits: list[FitTimelineEntry],
    target: FitTimelineEntry | None,
) -> list[int] | None:
    """Return the list of child indices from the fit root to ``target``.

    Names are not unique across branches (every branch has a "Current state"),
    so a positional path is the stable identifier for persisting a selection.
    """

    if target is None:
        return None
    for index, entry in enumerate(fits):
        if entry is target:
            return [index]
        below = _fit_entry_path(entry.children, target)
        if below is not None:
            return [index, *below]
    return None


def _fit_entry_at_path(
    fits: list[FitTimelineEntry],
    path: list[int] | None,
) -> FitTimelineEntry | None:
    """Return the fit entry at a positional path, or ``None`` if it is gone."""

    if not path:
        return None
    entries = fits
    entry: FitTimelineEntry | None = None
    for index in path:
        if not (0 <= index < len(entries)):
            return None
        entry = entries[index]
        entries = entry.children
    return entry


def _fit_siblings(
    entries: list[FitTimelineEntry],
    target: FitTimelineEntry,
) -> list[FitTimelineEntry] | None:
    if target in entries:
        return entries
    for entry in entries:
        found = _fit_siblings(entry.children, target)
        if found is not None:
            return found
    return None


def _fit_parent(
    entries: list[FitTimelineEntry],
    target: FitTimelineEntry,
) -> FitTimelineEntry | None:
    for entry in entries:
        if target in entry.children:
            return entry
        found = _fit_parent(entry.children, target)
        if found is not None:
            return found
    return None


def _last_result_at_level(entries: list[FitTimelineEntry]) -> FitTimelineEntry | None:
    for entry in reversed(entries):
        if entry.kind == "result":
            return entry
    return None


def _current_state_at_level(entries: list[FitTimelineEntry]) -> FitTimelineEntry | None:
    for entry in reversed(entries):
        if entry.kind == "current":
            return entry
    return None


def _fit_entry_matches_current_state(entries: list[FitTimelineEntry], fit_entry: FitTimelineEntry) -> bool:
    current = _current_state_at_level(entries)
    return bool(current is not None and fit_entry.snapshot == current.snapshot)


def _current_state_after_result(group: DataGroup, result: FitTimelineEntry) -> FitTimelineEntry | None:
    siblings = _fit_siblings(group.fits, result)
    if siblings is None or result not in siblings:
        return None
    result_index = siblings.index(result)
    for entry in siblings[result_index + 1 :]:
        if entry.kind == "current":
            return entry
    return None


def _ensure_current_state_after_result(
    group: DataGroup,
    result: FitTimelineEntry,
) -> tuple[FitTimelineEntry | None, bool]:
    """Return/create the mutable current state immediately after ``result``."""

    siblings = _fit_siblings(group.fits, result)
    if siblings is None or result not in siblings:
        return None, False
    existing = _current_state_after_result(group, result)
    if existing is not None:
        return existing, False
    current = current_state_fit_entry(group, result)
    siblings.insert(siblings.index(result) + 1, current)
    return current, True


def _current_state_for_failed_fit(
    group: DataGroup,
    parent: FitTimelineEntry,
    result: FitTimelineEntry,
) -> FitTimelineEntry | None:
    """Return/create the current state that should stay active after failure."""

    siblings = _fit_siblings(group.fits, result)
    if siblings is None:
        return parent if parent.kind == "current" and _fit_entry_in_tree(group.fits, parent) else None
    if parent.kind == "current" and parent in siblings:
        _set_fit_current_snapshot(parent, group)
        siblings.remove(parent)
        siblings.insert(siblings.index(result) + 1, parent)
        return parent
    if parent.kind in {"initial", "result"}:
        current, _created = _ensure_current_state_after_result(group, result)
        if current is not None:
            _set_fit_current_snapshot(current, group)
        return current
    return None


def _fit_entry_to_select_after_run(
    group: DataGroup,
    parent: FitTimelineEntry,
    result: FitTimelineEntry,
) -> FitTimelineEntry:
    if str(result.goodness.get("status", "")) == "failed":
        current = _current_state_after_result(group, result)
        if current is not None:
            return current
        if parent.kind == "current" and _fit_entry_in_tree(group.fits, parent):
            return parent
    return result


def _is_editable_initial_baseline(
    group: DataGroup,
    fit_entry: FitTimelineEntry | None,
) -> bool:
    """Return whether edits should update Initial instead of creating a branch."""

    if fit_entry is None or fit_entry.kind != "initial":
        return False
    if group.fits != [fit_entry]:
        return False
    return not fit_entry.children


def _should_branch_fit_now(group: DataGroup, parent: FitTimelineEntry) -> bool:
    if parent.kind in {"initial", "current"}:
        return False
    siblings = _fit_siblings(group.fits, parent)
    if siblings is None:
        return True
    return parent is not _last_result_at_level(siblings)


def _replace_current_state(entries: list[FitTimelineEntry], group: DataGroup) -> None:
    del group
    entries[:] = [entry for entry in entries if entry.kind != "current"]


def _top_level_current_state_entry(group: DataGroup) -> FitTimelineEntry | None:
    for entry in reversed(group.fits):
        if entry.kind == "current":
            return entry
    return None


def _set_fit_current_snapshot(entry: FitTimelineEntry, group: DataGroup) -> None:
    entry.snapshot = snapshot_data_group_state(group)
    entry.created_at = _timestamp_now()


def _style_enabled_tree_item(item: Any, enabled: bool) -> None:
    from PySide6 import QtGui

    # Enabled items use the theme's default text color (bright in dark mode,
    # dark in light mode); disabled items use a medium gray readable on both.
    if enabled:
        item.setForeground(0, QtGui.QBrush())
    else:
        item.setForeground(0, QtGui.QBrush(QtGui.QColor("#8a8a8a")))


def _style_tree_hierarchy_item(item: Any, *, bold: bool = False, underline: bool = False) -> None:
    from PySide6 import QtGui

    font = QtGui.QFont(item.font(0))
    font.setBold(bold)
    font.setUnderline(underline)
    item.setFont(0, font)


def _style_active_fit_tree_item(item: Any) -> None:
    from PySide6 import QtGui

    font = QtGui.QFont(item.font(0))
    font.setBold(True)
    font.setItalic(True)
    item.setFont(0, font)
    item.setForeground(0, QtGui.QBrush(QtGui.QColor("#62b884")))
    item.setToolTip(0, "Active fit state currently applied to the workspace.")


_TREE_ICON_CACHE: dict[str, Any] = {}


def _tree_item_icon(kind: str) -> Any:
    from PySide6 import QtCore, QtGui

    if kind in _TREE_ICON_CACHE:
        return _TREE_ICON_CACHE[kind]

    colors = {
        "folder": "#5f8fa8",
        "mask_folder": "#a88fc5",
        "model_folder": "#c7a45b",
        "fit_folder": "#7cab80",
        "dataset": "#6d9fc7",
        "mask": "#a88fc5",
        "model": "#c7a45b",
        "fit_result": "#7cab80",
        "fit_initial": "#7cab80",
        "fit_current": "#7cab80",
    }
    accent = QtGui.QColor(colors.get(kind, "#9ca3ad"))
    line = QtGui.QColor("#c7ccd1")

    pixmap = QtGui.QPixmap(16, 16)
    pixmap.fill(QtCore.Qt.GlobalColor.transparent)
    painter = QtGui.QPainter(pixmap)
    painter.setRenderHint(QtGui.QPainter.RenderHint.Antialiasing)
    pen = QtGui.QPen(accent, 1.4)
    pen.setCapStyle(QtCore.Qt.PenCapStyle.RoundCap)
    pen.setJoinStyle(QtCore.Qt.PenJoinStyle.RoundJoin)
    painter.setPen(pen)
    painter.setBrush(QtCore.Qt.BrushStyle.NoBrush)

    if kind in {"folder", "mask_folder", "model_folder", "fit_folder"}:
        fill = QtGui.QColor(accent)
        fill.setAlpha(34)
        painter.setPen(QtGui.QPen(accent, 1.15))
        painter.setBrush(fill)
        path = QtGui.QPainterPath(QtCore.QPointF(2.5, 4.6))
        path.lineTo(QtCore.QPointF(5.7, 4.6))
        path.lineTo(QtCore.QPointF(7.0, 6.1))
        path.lineTo(QtCore.QPointF(13.5, 6.1))
        path.lineTo(QtCore.QPointF(13.5, 12.9))
        path.lineTo(QtCore.QPointF(2.5, 12.9))
        path.closeSubpath()
        painter.drawPath(path)
        painter.setBrush(QtCore.Qt.BrushStyle.NoBrush)
    elif kind == "dataset":
        painter.setPen(QtGui.QPen(line, 1.0))
        painter.drawRoundedRect(QtCore.QRectF(2.3, 4.0, 11.4, 8.7), 1.0, 1.0)
        painter.setPen(QtGui.QPen(accent, 1.0))
        for x in (6.1, 9.9):
            painter.drawLine(QtCore.QPointF(x, 4.3), QtCore.QPointF(x, 12.4))
        for y in (6.9, 9.8):
            painter.drawLine(QtCore.QPointF(2.6, y), QtCore.QPointF(13.4, y))
    elif kind == "mask":
        removed = QtGui.QColor(accent)
        removed.setAlpha(88)
        painter.setPen(QtGui.QPen(line, 1.0))
        painter.drawRoundedRect(QtCore.QRectF(3.0, 3.0, 10.0, 10.0), 1.2, 1.2)
        painter.setPen(QtGui.QPen(accent, 1.0))
        painter.setBrush(removed)
        painter.drawRect(QtCore.QRectF(3.4, 3.4, 4.0, 4.0))
        painter.setBrush(QtCore.Qt.BrushStyle.NoBrush)
        painter.drawLine(QtCore.QPointF(4.1, 4.1), QtCore.QPointF(6.7, 6.7))
        painter.drawLine(QtCore.QPointF(6.7, 4.1), QtCore.QPointF(4.1, 6.7))
    elif kind == "model":
        path = QtGui.QPainterPath(QtCore.QPointF(2.8, 10.8))
        path.cubicTo(QtCore.QPointF(5.0, 3.0), QtCore.QPointF(7.2, 13.0), QtCore.QPointF(10.0, 5.2))
        path.cubicTo(QtCore.QPointF(11.2, 2.0), QtCore.QPointF(12.8, 5.5), QtCore.QPointF(13.2, 8.0))
        painter.drawPath(path)
        painter.setBrush(accent)
        painter.drawEllipse(QtCore.QPointF(5.2, 7.0), 1.1, 1.1)
        painter.drawEllipse(QtCore.QPointF(10.0, 5.2), 1.1, 1.1)
    elif kind == "fit_result":
        painter.setPen(QtGui.QPen(line, 1.0))
        painter.drawLine(QtCore.QPointF(3.0, 12.0), QtCore.QPointF(13.0, 12.0))
        painter.drawLine(QtCore.QPointF(3.0, 12.0), QtCore.QPointF(3.0, 4.0))
        painter.setPen(QtGui.QPen(accent, 1.4))
        painter.drawPolyline(
            QtGui.QPolygonF(
                [
                    QtCore.QPointF(4.0, 10.5),
                    QtCore.QPointF(6.3, 8.4),
                    QtCore.QPointF(8.4, 9.3),
                    QtCore.QPointF(11.8, 5.0),
                ]
            )
        )
    elif kind == "fit_initial":
        painter.setPen(QtGui.QPen(accent, 1.4))
        painter.drawEllipse(QtCore.QPointF(8.0, 8.0), 4.2, 4.2)
        painter.drawLine(QtCore.QPointF(8.0, 3.8), QtCore.QPointF(8.0, 6.0))
    elif kind == "fit_current":
        painter.setPen(QtGui.QPen(line, 1.1))
        painter.drawEllipse(QtCore.QPointF(8.0, 8.0), 4.5, 4.5)
        painter.setPen(QtGui.QPen(accent, 1.3))
        painter.drawEllipse(QtCore.QPointF(8.0, 8.0), 2.1, 2.1)
        painter.setBrush(accent)
        painter.drawEllipse(QtCore.QPointF(8.0, 8.0), 0.9, 0.9)

    painter.end()
    icon = QtGui.QIcon(pixmap)
    _TREE_ICON_CACHE[kind] = icon
    return icon


def _set_tree_item_icon(item: Any, kind: str) -> None:
    item.setIcon(0, _tree_item_icon(kind))


def _enabled_state_for_role(
    role: str,
    entry: DatasetEntry | None,
    mask: MaskSpec | None,
    model: ModelComponentSpec | None,
) -> bool | None:
    if role == "dataset" and entry is not None:
        return bool(entry.enabled)
    if role == "mask" and mask is not None:
        return bool(mask.enabled)
    if role == "model" and model is not None:
        return bool(model.enabled)
    return None


def _timestamp_now() -> str:
    return datetime.now().isoformat(timespec="seconds")


def dataset_entry_from_path(
    path: str | Path,
    *,
    data_type: str | None = None,
    importer_name: str | None = None,
    importer_options: dict[str, Any] | None = None,
) -> DatasetEntry:
    """Create a dataset entry for a file selected in the GUI.

    Point-list types are loaded immediately; MDHisto/``.nxs`` types are created
    as lazy placeholders and loaded on first view.
    """

    source = Path(path)
    resolved_type = data_type or DEFAULT_DATA_TYPE
    entry = DatasetEntry(
        name=_unique_dataset_name(source.stem or source.name, []),
        data=None,
        kind=source.suffix.lstrip(".").lower(),
        data_type=resolved_type,
        metadata={"source_file": str(source), "import_status": "pending"},
    )
    if resolved_type in {"single_crystal_inelastic", "powder_inelastic"}:
        entry.parameters[SPECTRAL_CHANNEL_CONFIG_KEY] = default_spectral_channel_config()
    if importer_name is not None:
        entry.metadata["importer"] = importer_name
        if importer_options is not None:
            entry.metadata["import_options"] = copy.deepcopy(importer_options)
    if source.suffix.lower() == ".npz":
        data, parameters = _load_nfit_dataset_file(source)
        entry.replace_data(data, source_backed=True)
        entry.parameters.update(parameters)
        entry.metadata["import_status"] = "loaded"
        return entry
    chosen = importer_name or default_importer_for_data_type(resolved_type, source)
    if chosen is not None:
        entry.metadata["importer"] = chosen
        _load_registered_importer_dataset(entry)
    elif data_type_container(resolved_type) == "point_list":
        chosen = default_importer_for_data_type(resolved_type)
        if chosen is not None:
            entry.metadata["importer"] = chosen
        _load_point_list_dataset(entry)
    return entry


def save_project(project: NfitProject, path: str | Path) -> None:
    """Persist the GUI project as editable JSON."""

    Path(path).write_text(
        json.dumps(_project_to_dict(project), indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )


def _copy_analysis_assets_for_save_as(project: NfitProject, old_path: Path, new_path: Path) -> None:
    old_root = old_path.with_name(old_path.name + "-assets")
    new_root = new_path.with_name(new_path.name + "-assets")
    if old_root.exists():
        shutil.copytree(old_root, new_root, dirs_exist_ok=True)
    for group in project.data_groups:
        for analysis in group.analyses:
            if analysis.result is None:
                continue
            for output in analysis.result.outputs:
                if not output.artifact_path:
                    continue
                relative = Path(output.artifact_path)
                if relative.parts and relative.parts[0] == old_root.name:
                    output.artifact_path = str(Path(new_root.name, *relative.parts[1:]))
        for dataset in group.iter_datasets():
            if not dataset.metadata.get("derived_from_analysis"):
                continue
            source = dataset.metadata.get("source_file")
            if not source:
                continue
            source_path = Path(source)
            if not source_path.is_absolute() and source_path.parts and source_path.parts[0] == old_root.name:
                relative_source = str(Path(new_root.name, *source_path.parts[1:]))
                dataset.metadata["source_file"] = relative_source
                dataset.metadata["analysis_artifact_path"] = relative_source
            else:
                try:
                    relative = source_path.resolve().relative_to(old_root.resolve())
                except (OSError, ValueError):
                    continue
                dataset.metadata["source_file"] = str(new_root / relative)
                dataset.metadata["analysis_artifact_path"] = str(Path(new_root.name) / relative)


def _resolve_project_analysis_sources(project: NfitProject, project_path: Path) -> None:
    for group in project.data_groups:
        for dataset in group.iter_datasets():
            if not dataset.metadata.get("derived_from_analysis"):
                continue
            source = dataset.metadata.get("source_file")
            if source and not Path(source).is_absolute():
                dataset.metadata.setdefault("analysis_artifact_path", str(source))
                dataset.metadata["source_file"] = str(project_path.parent / source)


def load_project(path: str | Path) -> NfitProject:
    """Load a project saved by :func:`save_project`."""

    project_path = Path(path)
    project = _project_from_dict(json.loads(project_path.read_text(encoding="utf-8")))
    _resolve_project_analysis_sources(project, project_path)
    return project


def render_project_plot(
    project: NfitProject,
    plot_id: str,
    *,
    settings: dict[str, Any] | None = None,
):
    """Render a saved plot through project data preparation without opening Qt."""

    for group in project.data_groups:
        for plot in group.plots:
            if plot.id != plot_id:
                continue
            if settings is not None:
                plot = replace(plot, settings=dict(settings))
            if plot.type == "fit_covariance":
                fit_id = plot.sources[0].fit_id if plot.sources else None
                fit_entry = next((fit for fit in _walk_fit_entries(group.fits) if fit.id == fit_id), None)
                if fit_entry is None:
                    raise ValueError("saved plot source fit is missing")
                return render_plot(plot, fit_entry=fit_entry)
            source_ids = [
                source.dataset_id
                for source in plot.sources
                if source.dataset_id
            ]
            if not source_ids:
                raise ValueError("saved plot has no dataset source")
            entries_by_id = {
                item.id: item for item in group.iter_datasets()
            }
            datasets = [entries_by_id.get(source_id) for source_id in source_ids]
            if any(dataset is None for dataset in datasets):
                raise ValueError("saved plot source dataset is missing")
            views, names = slice_viewer_datasets(
                group,
                use_composite=False,
                unmask_model=bool(plot.settings.get("unmask_model", False)),
            )
            prepared = [
                views[names.index(dataset.name)]
                for dataset in datasets
                if dataset is not None and dataset.name in names
            ]
            if len(prepared) != len(datasets) or not all(
                isinstance(view, MDHistoData) for view in prepared
            ):
                raise TypeError("saved plots currently require MDHisto data")
            return render_plot(
                plot,
                prepared if plot.type == "mdhisto_waterfall" else prepared[0],
            )
    raise ValueError(f"unknown saved plot {plot_id!r}")


def _is_pytest_temporary_project(path: Path) -> bool:
    """Return whether *path* belongs to pytest's per-run temporary hierarchy."""

    parts = path.expanduser().parts
    return any(part.startswith("pytest-of-") for part in parts) and any(
        part.startswith("pytest-") for part in parts
    )


def recent_project_paths(settings: Any | None = None) -> list[Path]:
    """Return recently opened project paths from app settings.

    Pytest opens temporary projects through the ordinary GUI paths. Excluding
    those entries here also removes stale test entries created by older runs.
    """

    settings = _settings() if settings is None else settings
    value = settings.value(RECENT_PROJECTS_KEY, [])
    if isinstance(value, str):
        values = [value]
    else:
        values = list(value or [])
    recent = [Path(str(path)) for path in values]
    filtered = [path for path in recent if not _is_pytest_temporary_project(path)]
    if filtered != recent:
        settings.setValue(RECENT_PROJECTS_KEY, [str(path) for path in filtered])
    return filtered


def remember_recent_project(path: str | Path, settings: Any | None = None) -> list[Path]:
    """Record a project path as most-recent and return the updated list."""

    settings = _settings() if settings is None else settings
    resolved = Path(path).expanduser()
    recent = [existing for existing in recent_project_paths(settings) if existing != resolved]
    if _is_pytest_temporary_project(resolved):
        return recent
    recent.insert(0, resolved)
    recent = recent[:RECENT_PROJECT_LIMIT]
    settings.setValue(RECENT_PROJECTS_KEY, [str(path) for path in recent])
    return recent


def forget_missing_recent_projects(settings: Any | None = None) -> list[Path]:
    """Drop recent projects whose files are no longer present."""

    settings = _settings() if settings is None else settings
    recent = [path for path in recent_project_paths(settings) if path.exists()]
    settings.setValue(RECENT_PROJECTS_KEY, [str(path) for path in recent])
    return recent


class _FitProgressDialog:
    """Small live progress window for fits, analyses, and samplers."""

    def __init__(self, parent: Any) -> None:
        from PySide6 import QtCore, QtGui, QtWidgets

        self.dialog = QtWidgets.QDialog(parent.window if hasattr(parent, "window") else parent)
        self.dialog.setWindowTitle("Fit progress")
        self.dialog.setModal(False)
        self.dialog.resize(720, 520)
        self.close_shortcut = QtGui.QShortcut(QtGui.QKeySequence.StandardKey.Close, self.dialog)
        self.close_shortcut.activated.connect(self.dialog.close)
        layout = QtWidgets.QVBoxLayout(self.dialog)
        self.stage_label = QtWidgets.QLabel("Ready")
        stage_font = self.stage_label.font()
        stage_font.setBold(True)
        self.stage_label.setFont(stage_font)
        self.stage_label.setWordWrap(True)
        self.status_label = QtWidgets.QLabel("No fit is running.")
        self.status_label.setWordWrap(True)
        self.progress = QtWidgets.QProgressBar()
        self.progress.setRange(0, 0)
        self.parameter_table = QtWidgets.QTableWidget(0, 2)
        self.parameter_table.setObjectName("fit_progress_parameter_table")
        self.parameter_table.setToolTip("Current parameter values reported by the active optimizer or sampler stage.")
        self.parameter_table.setHorizontalHeaderLabels(["Parameter", "Current value"])
        self.parameter_table.setEditTriggers(QtWidgets.QAbstractItemView.EditTrigger.NoEditTriggers)
        self.parameter_table.setSelectionBehavior(QtWidgets.QAbstractItemView.SelectionBehavior.SelectRows)
        self.parameter_table.setAlternatingRowColors(True)
        self.parameter_table.verticalHeader().setVisible(False)
        self.parameter_table.horizontalHeader().setStretchLastSection(True)
        self.parameter_table.horizontalHeader().setDefaultAlignment(QtCore.Qt.AlignmentFlag.AlignLeft)
        self.parameter_table.setMinimumHeight(120)
        self.log = QtWidgets.QPlainTextEdit()
        self.log.setObjectName("fit_progress_log")
        self.log.setReadOnly(True)
        self.log.setMaximumBlockCount(200)
        self.log.setToolTip("Short live progress log. Current parameter values are shown in the table above.")
        self.panel_splitter = QtWidgets.QSplitter(QtCore.Qt.Orientation.Vertical)
        self.panel_splitter.setObjectName("fit_progress_panel_splitter")
        self.panel_splitter.setChildrenCollapsible(False)
        self.panel_splitter.addWidget(self.parameter_table)
        self.panel_splitter.addWidget(self.log)
        self.panel_splitter.setStretchFactor(0, 1)
        self.panel_splitter.setStretchFactor(1, 1)
        self.panel_splitter.setSizes([240, 220])
        self.cancel_button = QtWidgets.QPushButton("Terminate")
        self.cancel_button.setEnabled(False)
        self.cancel_button.setToolTip(
            "Terminate the active optimization or posterior sampler at its next progress update. "
            "Least squares keeps the lowest-objective parameter set evaluated so far; if emcee "
            "has recorded samples, its partial chain is also saved for inspection or continuation."
        )
        self.cancel_button.clicked.connect(self._cancel_requested)
        self.close_button = QtWidgets.QPushButton("Close")
        self.close_button.setEnabled(False)
        self.close_button.setToolTip("Close this progress window after the fit pipeline finishes.")
        self.close_button.clicked.connect(self.dialog.close)
        self._cancel_callback: Any | None = None
        layout.addWidget(self.stage_label)
        layout.addWidget(self.status_label)
        layout.addWidget(self.progress)
        layout.addWidget(self.panel_splitter, 1)
        button_row = QtWidgets.QHBoxLayout()
        button_row.addWidget(self.cancel_button)
        button_row.addWidget(self.close_button)
        layout.addLayout(button_row)

    def reset(self, title: str = "Starting fit pipeline...") -> None:
        from PySide6 import QtWidgets

        self.stage_label.setText(title)
        self.status_label.setStyleSheet("")
        self.status_label.setText("Preparing data and fit problem.")
        self.progress.setRange(0, 0)
        self.parameter_table.setRowCount(0)
        self.log.clear()
        self.cancel_button.setEnabled(False)
        self.close_button.setEnabled(False)
        self._cancel_callback = None
        QtWidgets.QApplication.processEvents()

    def set_cancel_callback(self, callback: Any | None) -> None:
        self._cancel_callback = callback
        self.cancel_button.setEnabled(callback is not None)

    def _cancel_requested(self) -> None:
        if self._cancel_callback is None:
            return
        self._cancel_callback()
        self.status_label.setText("Termination requested. Waiting for the active step to stop...")
        self.cancel_button.setEnabled(False)

    def show(self) -> None:
        from PySide6 import QtWidgets

        self.dialog.show()
        self.dialog.raise_()
        self.dialog.activateWindow()
        QtWidgets.QApplication.processEvents()

    def update_progress(self, event: dict[str, Any]) -> None:
        from PySide6 import QtWidgets

        stage = str(event.get("stage", "fit"))
        iteration = event.get("iteration", event.get("completed"))
        total = event.get("total")
        message = str(event.get("message", stage))
        stage_title = {
            "initialization": "Initialization: differential evolution",
            "bragg_integration": "Bragg integration",
            "rebin": "Rebinning data",
            "least_squares": "Least-squares fit",
            "emcee": "Posterior sampling: emcee",
        }.get(stage, stage.replace("_", " ").title())
        self.stage_label.setText(stage_title)
        status_parts: list[str] = []
        if iteration is not None:
            counter = "Reflection" if stage == "bragg_integration" else "Step"
            status_parts.append(f"{counter} {iteration}" + (f" of {total}" if total else ""))
        if event.get("accepted_count") is not None:
            status_parts.append(f"{event['accepted_count']} accepted")
        if event.get("rejected_count") is not None:
            status_parts.append(f"{event['rejected_count']} rejected")
        if event.get("cost") is not None:
            status_parts.append(f"cost {_format_number(float(event['cost']))}")
        if event.get("convergence") is not None:
            status_parts.append(f"convergence {_format_number(float(event['convergence']))}")
        if event.get("seconds_per_step") is not None:
            status_parts.append(f"{_format_seconds_per_step(float(event['seconds_per_step']))}/step")
        self.status_label.setText(" | ".join(status_parts) if status_parts else message)
        params = event.get("parameters")
        if isinstance(params, dict) and params:
            self._set_parameters(params)
        log_parts = [stage_title]
        if iteration is not None:
            counter = "reflection" if stage == "bragg_integration" else "step"
            log_parts.append(f"{counter} {iteration}" + (f"/{total}" if total else ""))
        if message and message != stage:
            log_parts.append(message)
        if event.get("accepted_count") is not None:
            log_parts.append(f"{event['accepted_count']} accepted")
        if event.get("rejected_count") is not None:
            log_parts.append(f"{event['rejected_count']} rejected")
        if event.get("cost") is not None:
            log_parts.append(f"cost {_format_number(float(event['cost']))}")
        if event.get("seconds_per_step") is not None:
            log_parts.append(f"{_format_seconds_per_step(float(event['seconds_per_step']))}/step")
        self.log.appendPlainText(" | ".join(log_parts))
        if total and iteration is not None:
            self.progress.setRange(0, int(total))
            self.progress.setValue(min(int(iteration), int(total)))
        else:
            self.progress.setRange(0, 0)
        QtWidgets.QApplication.processEvents()

    def _set_parameters(self, params: dict[str, Any], limit_hits: Any = None) -> None:
        from PySide6 import QtCore, QtGui, QtWidgets

        items = list(params.items())
        hits_by_name = _fit_limit_hits_from_goodness({"parameters_at_limits": limit_hits})
        self.parameter_table.setRowCount(len(items))
        for row, (name, value) in enumerate(items):
            name_item = QtWidgets.QTableWidgetItem(str(name))
            value_text = _format_number(value)
            value_item = QtWidgets.QTableWidgetItem(value_text)
            name_item.setToolTip(str(name))
            value_item.setToolTip(value_text)
            hit = hits_by_name.get(str(name))
            if hit is not None:
                warning = f"Reached the {hit.get('side', 'configured')} bound ({_format_number(hit.get('bound'))})."
                for item in (name_item, value_item):
                    item.setForeground(QtGui.QColor("#c0392b"))
                    font = item.font()
                    font.setBold(True)
                    item.setFont(font)
                    item.setToolTip(f"{item.toolTip()}\n{warning}")
            value_item.setTextAlignment(
                QtCore.Qt.AlignmentFlag.AlignRight | QtCore.Qt.AlignmentFlag.AlignVCenter
            )
            self.parameter_table.setItem(row, 0, name_item)
            self.parameter_table.setItem(row, 1, value_item)
        self.parameter_table.resizeColumnsToContents()

    def finish(
        self,
        message: str,
        *,
        parameters: dict[str, Any] | None = None,
        limit_hits: Any = None,
        summary_lines: Sequence[str] | None = None,
    ) -> None:
        from PySide6 import QtWidgets

        self.stage_label.setText(message)
        if parameters:
            self._set_parameters(parameters, limit_hits)
        warning = _fit_limit_warning_text(limit_hits)
        self.status_label.setStyleSheet("color: #c0392b; font-weight: bold;" if warning else "")
        self.status_label.setText(f"Done. {warning}" if warning else "Done.")
        if warning:
            self.log.appendPlainText(warning)
        for line in summary_lines or ():
            if str(line).strip():
                self.log.appendPlainText(str(line))
        self.progress.setRange(0, 1)
        self.progress.setValue(1)
        self.cancel_button.setEnabled(False)
        self._cancel_callback = None
        self.close_button.setEnabled(True)
        QtWidgets.QApplication.processEvents()

    def fail(self, message: str) -> None:
        """Show a fit failure and keep the window open for the user to read."""

        from PySide6 import QtWidgets

        self.stage_label.setText("Fit failed")
        self.status_label.setStyleSheet("color: #c0392b; font-weight: bold;")
        self.status_label.setText(message)
        self.log.appendPlainText(f"ERROR: {message}")
        self.progress.setRange(0, 1)
        self.progress.setValue(0)
        self.cancel_button.setEnabled(False)
        self._cancel_callback = None
        self.close_button.setEnabled(True)
        self.show()
        QtWidgets.QApplication.processEvents()

    def close(self) -> None:
        self.dialog.close()


class _FitDiagnosticsPlotWindow:
    """Dedicated Matplotlib window for fit covariance and posterior diagnostics."""

    def __init__(self, fit_entry: FitTimelineEntry, parent: Any) -> None:
        from PySide6 import QtCore, QtGui, QtWidgets

        self.fit_entry = fit_entry
        self.window = QtWidgets.QMainWindow(parent.window if hasattr(parent, "window") else parent)
        self.window.setWindowTitle("Fit diagnostics")
        self.close_shortcut = QtGui.QShortcut(QtGui.QKeySequence.StandardKey.Close, self.window)
        self.close_shortcut.activated.connect(self.window.close)
        central = QtWidgets.QWidget()
        layout = QtWidgets.QVBoxLayout(central)
        self.tabs = QtWidgets.QTabWidget()
        self.tabs.setToolTip("Fit diagnostics from covariance estimates and stored emcee samples.")
        self.label_table = self._make_label_table()
        self.plot_label_splitter = QtWidgets.QSplitter(QtCore.Qt.Orientation.Vertical)
        self.plot_label_splitter.setObjectName("fit_diagnostics_plot_label_splitter")
        self.plot_label_splitter.setToolTip(
            "Drag the divider to allocate space between diagnostic plots and editable parameter labels."
        )
        self.plot_label_splitter.setChildrenCollapsible(False)
        self.plot_label_splitter.addWidget(self.tabs)
        self.plot_label_splitter.addWidget(self.label_table)
        self.plot_label_splitter.setStretchFactor(0, 4)
        self.plot_label_splitter.setStretchFactor(1, 1)
        self.plot_label_splitter.setSizes([520, 180])
        layout.addWidget(self.plot_label_splitter, 1)
        self.window.setCentralWidget(central)
        self._redraw_plots()

    def _make_label_table(self) -> Any:
        from PySide6 import QtCore, QtWidgets

        names = _fit_entry_diagnostic_parameter_names(self.fit_entry)
        labels = _fit_parameter_plot_labels(self.fit_entry, names)
        table = QtWidgets.QTableWidget(len(names), 2)
        table.setObjectName("fit_diagnostics_label_table")
        table.setToolTip(
            "Edit plot labels for this fit result. Plain text or Matplotlib mathtext/LaTeX-style labels are accepted."
        )
        table.setHorizontalHeaderLabels(["Full parameter name", "Plot label"])
        table.setEditTriggers(
            QtWidgets.QAbstractItemView.EditTrigger.DoubleClicked
            | QtWidgets.QAbstractItemView.EditTrigger.EditKeyPressed
        )
        table.setAlternatingRowColors(True)
        table.verticalHeader().setVisible(False)
        table.horizontalHeader().setStretchLastSection(True)
        for row, name in enumerate(names):
            name_item = QtWidgets.QTableWidgetItem(name)
            name_item.setFlags(name_item.flags() & ~QtCore.Qt.ItemFlag.ItemIsEditable)
            label_item = QtWidgets.QTableWidgetItem(labels.get(name, f"p{row + 1}"))
            name_item.setToolTip(name)
            label_item.setToolTip("Editable plot label. Use p1-style names, plain text, or mathtext such as $\\Gamma$.")
            table.setItem(row, 0, name_item)
            table.setItem(row, 1, label_item)
        table.itemChanged.connect(self._label_table_changed)
        table.setMinimumHeight(90)
        table.resizeColumnsToContents()
        _tooltip_table_corner_buttons(table, "Select all parameter-label rows.")
        return table

    def _label_table_changed(self, item: Any) -> None:
        if item.column() != 1:
            return
        labels = dict(self.fit_entry.metadata.get("parameter_labels", {}))
        full_name_item = self.label_table.item(item.row(), 0)
        if full_name_item is None:
            return
        full_name = full_name_item.text()
        labels[full_name] = item.text().strip() or _compact_diagnostic_labels([full_name])[0]
        self.fit_entry.metadata["parameter_labels"] = labels
        self._redraw_plots()

    def _redraw_plots(self) -> None:
        from matplotlib.backends.backend_qtagg import FigureCanvasQTAgg as FigureCanvas
        from matplotlib.figure import Figure

        active_tab = self.tabs.tabText(self.tabs.currentIndex()) if self.tabs.count() else ""
        self.tabs.clear()

        covariance = _covariance_matrix_from_fit_entry(self.fit_entry)
        if covariance is not None:
            matrix, names, title = covariance
            labels = _fit_parameter_plot_labels(self.fit_entry, names)
            cov_fig = Figure(figsize=(max(7, 1.0 * len(names) + 4), max(5, 0.75 * len(names) + 3)))
            _draw_centered_matrix_heatmap(cov_fig, matrix, names, labels=labels, title=title)
            self.tabs.addTab(FigureCanvas(cov_fig), title)

        result = _sampling_result_from_dict(self.fit_entry.metadata.get("posterior_samples"))
        if result is None:
            self._restore_active_tab(active_tab)
            return

        samples = np.asarray(result.samples, dtype=float)
        names = list(result.variable_names)
        labels = _fit_parameter_plot_labels(self.fit_entry, names)
        summaries = _fit_parameter_summaries(self.fit_entry)

        trace_fig = Figure(figsize=(8, max(3, 1.4 * max(1, len(names)))))
        trace_axes = trace_fig.subplots(max(1, len(names)), 1, squeeze=False)
        for index, name in enumerate(names):
            ax = trace_axes[index, 0]
            _draw_trace_panel(
                ax,
                result,
                parameter_index=index,
                summary=summaries.get(name, {}),
            )
            ax.set_ylabel(labels.get(name, f"p{index + 1}"))
        trace_axes[-1, 0].set_xlabel("MCMC step" if result.chain is not None else "sample")
        trace_fig.subplots_adjust(left=0.18, right=0.98, bottom=0.1, top=0.95, hspace=0.28)
        self.tabs.addTab(FigureCanvas(trace_fig), "Trace")

        n = len(names)
        corner_fig = Figure(figsize=(max(6, 2.45 * max(1, n)), max(6, 2.45 * max(1, n))))
        axes = corner_fig.subplots(max(1, n), max(1, n), squeeze=False)
        for row in range(n):
            for col in range(n):
                ax = axes[row, col]
                if row == col:
                    _draw_corner_histogram_panel(
                        ax,
                        samples[:, col],
                        labels.get(names[col], f"p{col + 1}"),
                        summaries.get(names[col], {}),
                    )
                elif row > col:
                    _draw_corner_density_panel(ax, samples[:, col], samples[:, row])
                    _draw_corner_reference_lines(
                        ax,
                        summaries.get(names[col], {}),
                        summaries.get(names[row], {}),
                    )
                else:
                    ax.axis("off")
                _disable_axis_offset_text(ax)
                if row == n - 1:
                    ax.set_xlabel(labels.get(names[col], f"p{col + 1}"))
                if col == 0 and row > 0:
                    ax.set_ylabel(labels.get(names[row], f"p{row + 1}"))
                elif row == col and col == 0:
                    ax.set_ylabel("Count")
        corner_fig.subplots_adjust(
            left=0.18,
            right=0.98,
            bottom=0.18,
            top=0.9,
            hspace=0.48,
            wspace=0.48,
        )
        self.tabs.addTab(FigureCanvas(corner_fig), "Corner")
        self._restore_active_tab(active_tab)

    def _restore_active_tab(self, tab_text: str) -> None:
        if not tab_text:
            return
        for index in range(self.tabs.count()):
            if self.tabs.tabText(index) == tab_text:
                self.tabs.setCurrentIndex(index)
                return

    def show(self) -> None:
        self.window.resize(900, 700)
        self.window.show()


def _draw_matrix_heatmap(
    ax: Any,
    matrix: Any,
    names: list[str],
    *,
    labels: dict[str, str] | None = None,
    title: str,
    colorbar_ax: Any | None = None,
) -> None:
    """Draw a labeled covariance or correlation heatmap."""

    arr = np.asarray(matrix, dtype=float)
    if arr.size == 0:
        return
    plot_labels = labels or {
        name: label
        for name, label in zip(
            names,
            _compact_diagnostic_labels(names),
            strict=True,
        )
    }
    finite = arr[np.isfinite(arr)]
    if title.lower().startswith("correlation"):
        vmin, vmax = -1.0, 1.0
        cmap = "coolwarm"
    elif finite.size:
        limit = float(np.nanmax(np.abs(finite)))
        vmin, vmax = (-limit, limit) if limit > 0 else (-1.0, 1.0)
        cmap = "coolwarm"
    else:
        vmin, vmax = -1.0, 1.0
        cmap = "coolwarm"
    image = ax.imshow(arr, cmap=cmap, vmin=vmin, vmax=vmax)
    ax.set_title(title)
    ax.set_xticks(np.arange(len(names)))
    ax.set_yticks(np.arange(len(names)))
    ax.set_xticklabels([plot_labels.get(name, f"p{index + 1}") for index, name in enumerate(names)], rotation=0)
    ax.set_yticklabels([plot_labels.get(name, f"p{index + 1}") for index, name in enumerate(names)])
    for row in range(arr.shape[0]):
        for col in range(arr.shape[1]):
            value = arr[row, col]
            if np.isfinite(value):
                ax.text(col, row, _format_number(value), ha="center", va="center", fontsize=7)
    if colorbar_ax is None:
        ax.figure.colorbar(image, ax=ax, fraction=0.046, pad=0.04)
    else:
        ax.figure.colorbar(image, cax=colorbar_ax)


def _draw_centered_matrix_heatmap(
    fig: Any,
    matrix: Any,
    names: list[str],
    *,
    labels: dict[str, str] | None = None,
    title: str,
) -> Any:
    """Draw the covariance/correlation matrix centered in the diagnostics tab."""

    arr = np.asarray(matrix, dtype=float)
    label_count = max(1, len(names))
    square_size = min(0.66, max(0.42, 0.10 * label_count + 0.34))
    colorbar_width = 0.028
    gap = 0.025
    total_width = square_size + gap + colorbar_width
    left = max(0.08, (1.0 - total_width) / 2.0)
    bottom = max(0.14, (1.0 - square_size) / 2.0)
    ax = fig.add_axes([left, bottom, square_size, square_size])
    colorbar_ax = fig.add_axes([left + square_size + gap, bottom, colorbar_width, square_size])
    _draw_matrix_heatmap(ax, arr, names, labels=labels, title=title, colorbar_ax=colorbar_ax)
    return ax


def _compact_diagnostic_labels(names: list[str]) -> list[str]:
    return [f"p{index + 1}" for index in range(len(names))]


def _draw_trace_panel(
    ax: Any,
    result: SamplingResult,
    *,
    parameter_index: int,
    summary: dict[str, float],
) -> None:
    """Draw one posterior trace panel, preferring raw walker chains."""

    if result.chain is not None:
        chain = np.asarray(result.chain, dtype=float)
        if chain.ndim == 3 and parameter_index < chain.shape[2]:
            steps = np.arange(chain.shape[0])
            ax.plot(steps, chain[:, :, parameter_index], linewidth=0.55, alpha=0.75)
            burn_in = int(result.metadata.get("burn_in", 0) or 0)
            if 0 < burn_in < chain.shape[0]:
                ax.axvline(
                    burn_in,
                    color="black",
                    linestyle="--",
                    linewidth=1.0,
                    alpha=0.85,
                )
                top = ax.get_ylim()[1]
                ax.annotate(
                    "burn-in",
                    xy=(burn_in, top),
                    xytext=(4, -4),
                    textcoords="offset points",
                    ha="left",
                    va="top",
                    fontsize=8,
                    color="black",
                )
            if summary.get("best") is not None:
                ax.axhline(float(summary["best"]), color="red", linewidth=0.9, alpha=0.8)
            return

    samples = np.asarray(result.samples, dtype=float)
    if samples.ndim == 2 and parameter_index < samples.shape[1]:
        ax.plot(samples[:, parameter_index], linewidth=0.7)
    if summary.get("best") is not None:
        ax.axhline(float(summary["best"]), color="red", linewidth=0.9, alpha=0.8)


def _fit_entry_diagnostic_parameter_names(fit_entry: FitTimelineEntry) -> list[str]:
    names: list[str] = []
    covariance = _covariance_matrix_from_fit_entry(fit_entry)
    if covariance is not None:
        _matrix, cov_names, _title = covariance
        names.extend(cov_names)
    samples = _sampling_result_from_dict(fit_entry.metadata.get("posterior_samples"))
    if samples is not None:
        names.extend(samples.variable_names)
    goodness = fit_entry.goodness if isinstance(fit_entry.goodness, dict) else {}
    params = goodness.get("parameters") if isinstance(goodness.get("parameters"), dict) else {}
    names.extend(str(name) for name in params)
    return list(dict.fromkeys(names))


def _fit_parameter_plot_labels(
    fit_entry: FitTimelineEntry,
    names: list[str],
) -> dict[str, str]:
    stored = fit_entry.metadata.get("parameter_labels")
    labels = dict(stored) if isinstance(stored, dict) else {}
    out: dict[str, str] = {}
    defaults_changed = False
    for index, name in enumerate(names):
        label = str(labels.get(name, "")).strip()
        if not label:
            label = f"p{index + 1}"
            labels[name] = label
            defaults_changed = True
        out[name] = label
    if defaults_changed:
        fit_entry.metadata["parameter_labels"] = labels
    return out


def _fit_parameter_summaries(fit_entry: FitTimelineEntry) -> dict[str, dict[str, float]]:
    goodness = fit_entry.goodness if isinstance(fit_entry.goodness, dict) else {}
    params = _display_fit_parameters(fit_entry)
    stderr = goodness.get("stderr") if isinstance(goodness.get("stderr"), dict) else {}
    posterior = goodness.get("posterior") if isinstance(goodness.get("posterior"), dict) else {}
    posterior_params = (
        posterior.get("parameters")
        if isinstance(posterior.get("parameters"), dict)
        else {}
    )
    use_posterior_errors = bool(_posterior_display_options(fit_entry).get("use_posterior_uncertainties"))
    names = set(params) | set(stderr) | set(posterior_params)
    summaries: dict[str, dict[str, float]] = {}
    for name in names:
        summary: dict[str, float] = {}
        if name in params:
            summary["best"] = float(params[name])
        if name in stderr:
            err = float(stderr[name])
            summary["stderr"] = err
            if "best" in summary:
                summary.setdefault("low", summary["best"] - err)
                summary.setdefault("high", summary["best"] + err)
        posterior_row = posterior_params.get(name)
        if use_posterior_errors and isinstance(posterior_row, dict):
            for source, target in (("median", "median"), ("p16", "low"), ("p84", "high")):
                if source in posterior_row:
                    summary[target] = float(posterior_row[source])
        summaries[str(name)] = summary
    return summaries


def _draw_corner_histogram_panel(
    ax: Any,
    values: Any,
    name: str,
    summary: dict[str, float],
) -> None:
    arr = np.asarray(values, dtype=float)
    arr = arr[np.isfinite(arr)]
    ax.hist(arr, bins=40, histtype="step", color="0.1", linewidth=1.1)
    center = summary.get("best", summary.get("median"))
    low = summary.get("low")
    high = summary.get("high")
    if center is not None:
        ax.axvline(center, color="red", linewidth=1.0)
    if low is not None:
        ax.axvline(low, color="0.25", linestyle="--", linewidth=0.8)
    if high is not None:
        ax.axvline(high, color="0.25", linestyle="--", linewidth=0.8)
    ax.set_title(_corner_histogram_title(name, summary), fontsize=9, pad=8)


def _draw_corner_reference_lines(
    ax: Any,
    x_summary: dict[str, float],
    y_summary: dict[str, float],
) -> None:
    x_center = x_summary.get("best", x_summary.get("median"))
    y_center = y_summary.get("best", y_summary.get("median"))
    if x_center is not None:
        ax.axvline(x_center, color="red", linewidth=0.8, alpha=0.85)
    if y_center is not None:
        ax.axhline(y_center, color="red", linewidth=0.8, alpha=0.85)
    if x_center is not None and y_center is not None:
        ax.plot([x_center], [y_center], marker="o", color="red", markersize=3)


def _corner_histogram_title(name: str, summary: dict[str, float]) -> str:
    center = summary.get("best", summary.get("median"))
    if center is None:
        return name
    low = summary.get("low")
    high = summary.get("high")
    if low is None or high is None:
        return rf"${_mathtext_label(name)} = {_format_number(center)}$"
    plus = high - center
    minus = center - low
    return (
        rf"${_mathtext_label(name)} = {_format_number(center)}"
        rf"\,\pm^{{+{_format_number(plus)}}}_{{-{_format_number(minus)}}}$"
    )


def _mathtext_label(label: str) -> str:
    stripped = str(label).strip()
    if stripped.startswith("$") and stripped.endswith("$") and len(stripped) >= 2:
        return stripped[1:-1]
    if re.search(r"[\\{}_^]", stripped):
        return stripped
    return stripped.replace(" ", r"\ ")


def _disable_axis_offset_text(ax: Any) -> None:
    for axis in (ax.xaxis, ax.yaxis):
        formatter = axis.get_major_formatter()
        if hasattr(formatter, "set_useOffset"):
            formatter.set_useOffset(False)
        if hasattr(formatter, "set_scientific"):
            formatter.set_scientific(False)


def _covariance_matrix_from_fit_entry(
    fit_entry: FitTimelineEntry,
) -> tuple[np.ndarray, list[str], str] | None:
    if _posterior_display_options(fit_entry).get("use_posterior_uncertainties"):
        posterior = _posterior_correlation_matrix(fit_entry)
        if posterior is not None:
            matrix, names = posterior
            return matrix, names, "Posterior correlation"
    goodness = fit_entry.goodness if isinstance(fit_entry.goodness, dict) else {}
    covariance = goodness.get("covariance") if isinstance(goodness.get("covariance"), dict) else {}
    names = [str(name) for name in covariance.get("variables", [])]
    matrix = covariance.get("matrix")
    if matrix is not None:
        arr = np.asarray(matrix, dtype=float)
        if arr.ndim == 2 and arr.shape[0] == arr.shape[1]:
            if len(names) != arr.shape[0]:
                names = [f"p{index}" for index in range(arr.shape[0])]
            return arr, names, "Covariance"
    correlation = covariance.get("correlation")
    if isinstance(correlation, dict) and correlation:
        names = names or [str(name) for name in correlation]
        arr = np.asarray(
            [
                [float(dict(correlation.get(row_name, {})).get(col_name, np.nan)) for col_name in names]
                for row_name in names
            ],
            dtype=float,
        )
        if arr.ndim == 2 and arr.shape[0] == arr.shape[1]:
            return arr, names, "Correlation"
    return None


def _fit_entry_has_diagnostic_plots(fit_entry: FitTimelineEntry | None) -> bool:
    if fit_entry is None:
        return False
    if _covariance_matrix_from_fit_entry(fit_entry) is not None:
        return True
    return _sampling_result_from_dict(fit_entry.metadata.get("posterior_samples")) is not None


def _draw_corner_density_panel(ax: Any, x: Any, y: Any) -> None:
    """Draw a 2D posterior panel with density shading, contours, and samples."""

    x_arr = np.asarray(x, dtype=float)
    y_arr = np.asarray(y, dtype=float)
    finite = np.isfinite(x_arr) & np.isfinite(y_arr)
    x_arr = x_arr[finite]
    y_arr = y_arr[finite]
    if x_arr.size == 0 or np.ptp(x_arr) == 0.0 or np.ptp(y_arr) == 0.0:
        ax.scatter(x_arr, y_arr, s=2, alpha=0.25, color="tab:blue", linewidths=0)
        return

    counts, x_edges, y_edges = np.histogram2d(x_arr, y_arr, bins=48)
    counts = counts.T
    if np.any(counts > 0):
        positive = counts[counts > 0]
        image = ax.imshow(
            counts,
            origin="lower",
            extent=[x_edges[0], x_edges[-1], y_edges[0], y_edges[-1]],
            aspect="auto",
            cmap="Blues",
            alpha=0.6,
            interpolation="nearest",
        )
        del image
        if positive.size >= 4:
            levels = np.percentile(positive, [50.0, 75.0, 90.0])
            levels = np.unique(levels[levels > 0])
            if levels.size:
                x_centers = 0.5 * (x_edges[:-1] + x_edges[1:])
                y_centers = 0.5 * (y_edges[:-1] + y_edges[1:])
                ax.contour(
                    x_centers,
                    y_centers,
                    counts,
                    levels=levels,
                    colors="0.15",
                    linewidths=0.8,
                    alpha=0.85,
                )
    ax.scatter(x_arr, y_arr, s=1.4, alpha=0.12, color="tab:blue", linewidths=0)


