    def _details_group_box(self, title: str, lines: list[str]) -> Any:
        from PySide6 import QtCore, QtWidgets

        group_box = QtWidgets.QGroupBox(title)
        layout = QtWidgets.QVBoxLayout(group_box)
        layout.setContentsMargins(10, 8, 10, 8)
        text = "\n".join(lines) if lines else "-"
        label = QtWidgets.QLabel(text)
        label.setWordWrap(True)
        label.setAlignment(QtCore.Qt.AlignmentFlag.AlignTop | QtCore.Qt.AlignmentFlag.AlignLeft)
        label.setTextInteractionFlags(QtCore.Qt.TextInteractionFlag.TextSelectableByMouse)
        layout.addWidget(label)
        return group_box

    def _dataset_metadata_group_box(self, dataset: DatasetEntry) -> Any:
        metadata = dict(_dataset_metadata_mapping(dataset))
        if dataset.parameters:
            metadata["Parameters"] = dict(dataset.parameters)
        return self._metadata_tree_group_box(
            "Metadata",
            metadata,
            object_name="dataset_metadata_tree",
            empty_text="No additional metadata.",
        )

    def _set_analysis_output_details(self, output: AnalysisOutputRef) -> None:
        """Show persisted analysis table values and metadata in the project panel."""

        self.title_label.setText(output.label)
        self._clear_details_panel()
        summary = [f"Kind: {output.kind}", f"Output key: {output.key}"]
        if output.scalar_value is not None:
            summary.append(f"Value: {_format_number(output.scalar_value)} {output.unit}")
        self.details_layout.addWidget(self._details_group_box("Analysis output", summary))
        data = None
        if self.project_path is not None and output.artifact_path:
            try:
                data = read_dataset_artifact(self.project_path.parent / output.artifact_path)
            except (OSError, TypeError, ValueError) as exc:
                self.details_layout.addWidget(
                    self._details_group_box("Artifact", [f"Could not load output: {exc}"])
                )
        if isinstance(data, PointListData):
            self.details_layout.addWidget(self._analysis_table_group_box(data))
            metadata = {**dict(output.metadata), **dict(data.metadata)}
            self.details_layout.addWidget(
                self._metadata_tree_group_box(
                    "Metadata",
                    metadata,
                    object_name="analysis_output_metadata_tree",
                    empty_text="No output metadata.",
                )
            )
        elif isinstance(data, MDHistoData):
            axes, lines = _dataset_axes_and_data_lines(data)
            self.details_layout.addWidget(self._details_group_box("Axes", axes))
            self.details_layout.addWidget(self._details_group_box("Data", lines))
            self.details_layout.addWidget(
                self._metadata_tree_group_box(
                    "Metadata",
                    {**dict(output.metadata), **dict(data.metadata)},
                    object_name="analysis_output_metadata_tree",
                    empty_text="No output metadata.",
                )
            )
        self.details_layout.addStretch(1)

    def _analysis_table_group_box(self, data: PointListData) -> Any:
        from PySide6 import QtCore, QtGui, QtWidgets

        box = QtWidgets.QGroupBox("Results table")
        layout = QtWidgets.QVBoxLayout(box)
        table = QtWidgets.QTableWidget(data.size, len(data.column_names))
        table.setObjectName("analysis_output_table")
        table.setToolTip("Persisted analysis values. Rejected Bragg reflections are shown in red.")
        table.setHorizontalHeaderLabels(data.column_names)
        accepted = data.column("Accepted") if "Accepted" in data.columns else np.ones(data.size)
        for row in range(data.size):
            for column, name in enumerate(data.column_names):
                value = float(data.column(name)[row])
                item = QtWidgets.QTableWidgetItem(_format_number(value) if np.isfinite(value) else "-")
                item.setTextAlignment(
                    QtCore.Qt.AlignmentFlag.AlignRight | QtCore.Qt.AlignmentFlag.AlignVCenter
                )
                if not bool(accepted[row]):
                    item.setForeground(QtGui.QColor("#d94b45"))
                table.setItem(row, column, item)
        table.resizeColumnsToContents()
        table.setMinimumHeight(180)
        table.setMaximumHeight(420)
        layout.addWidget(table)
        return box

    def _dataset_signal_semantics_group_box(
        self, dataset: DatasetEntry, group: DataGroup | None
    ) -> Any:
        """Build the explicit signal-value convention control for histogram data."""

        from PySide6 import QtWidgets

        box = QtWidgets.QGroupBox("Signal convention")
        layout = QtWidgets.QFormLayout(box)
        layout.setContentsMargins(10, 8, 10, 8)
        combo = QtWidgets.QComboBox()
        combo.setObjectName("dataset_signal_semantics")
        combo.addItem("Density-valued signal", "density")
        combo.addItem("Bin-integral signal", "bin_integral")
        combo.addItem("Unspecified", "unknown")
        data = dataset.data
        semantics = (
            signal_semantics(data)
            if isinstance(data, MDHistoData)
            else "density"
        )
        combo.setCurrentIndex(max(combo.findData(semantics), 0))
        combo.setEnabled(isinstance(data, MDHistoData))
        combo.setToolTip(
            "Choose how each histogram signal value is interpreted. Density is the default for normalized, "
            "variance-weighted rebins and is weighted by reciprocal-space bin volume during integration. "
            "Use Bin-integral only when each stored value is already the total for its bin."
        )
        combo.currentIndexChanged.connect(
            lambda _index, selector=combo: self._set_dataset_signal_semantics(
                dataset, group, str(selector.currentData())
            )
        )
        layout.addRow("Signal values", combo)
        return box

    def _dataset_spectral_channel_config(
        self, dataset: DatasetEntry
    ) -> dict[str, Any]:
        """Return the normalized paired-channel INS configuration."""

        config = normalized_spectral_channel_config(
            dataset.parameters.get(SPECTRAL_CHANNEL_CONFIG_KEY)
        )
        if config["source_unit"] != "arbitrary":
            if config["normalization_basis"] == "per_magnetic_ion":
                label = str(config.get("normalization_label", "") or "").strip()
                suffix = f"/{label}" if label else "/magnetic ion"
            else:
                suffix = {
                    "per_formula_unit": "/f.u.",
                    "per_unit_cell": "/unit cell",
                    "unknown": "",
                }[config["normalization_basis"]]
            unit = str(config["source_unit"])
            prefix = next(
                (
                    candidate
                    for candidate in (
                        "mbarn/sr/meV",
                        "barn/sr/meV",
                        "mu_B^2/meV",
                        "spin^2/meV",
                        "1/meV",
                    )
                    if unit.startswith(candidate)
                ),
                unit,
            )
            config["source_unit"] = prefix + suffix
        for target, names in (
            ("incident_energy_meV", ("incident_energy_meV", "incident_energy", "Ei", "ei")),
            ("final_energy_meV", ("final_energy_meV", "final_energy", "Ef", "ef")),
        ):
            if config.get(target) not in (None, ""):
                continue
            for source in (dataset.metadata, getattr(dataset.data, "metadata", {})):
                if not isinstance(source, dict):
                    continue
                value = next((source[name] for name in names if name in source), None)
                try:
                    value = float(value)
                except (TypeError, ValueError):
                    continue
                if np.isfinite(value) and value > 0.0:
                    config[target] = value
                    break
        dataset.parameters[SPECTRAL_CHANNEL_CONFIG_KEY] = config
        return config

    def _set_dataset_spectral_channel_setting(
        self,
        dataset: DatasetEntry,
        group: DataGroup | None,
        key: str,
        value: Any,
    ) -> None:
        config = self._dataset_spectral_channel_config(dataset)
        if key == "source_representation" and value != config.get(key):
            config["source_unit"] = "arbitrary"
        if key == "source_unit":
            if str(value).startswith("spin^2/"):
                config["moment_unit"] = "spin_squared"
            elif str(value).startswith("mu_B^2/"):
                config["moment_unit"] = "mu_B_squared"
        if key == "normalization_basis" and config["source_unit"] != "arbitrary":
            if value == "per_magnetic_ion":
                label = str(config.get("normalization_label", "") or "").strip()
                suffix = f"/{label}" if label else "/magnetic ion"
            else:
                suffix = {
                    "per_formula_unit": "/f.u.",
                    "per_unit_cell": "/unit cell",
                    "unknown": "",
                }[str(value)]
            if config["source_representation"] == "cross_section":
                source_unit = str(config["source_unit"])
                if source_unit.startswith("1/meV"):
                    prefix = "1/meV"
                elif source_unit.startswith("mbarn/"):
                    prefix = "mbarn/sr/meV"
                else:
                    prefix = "barn/sr/meV"
            else:
                prefix = (
                    "spin^2/meV"
                    if str(config["source_unit"]).startswith("spin^2/")
                    else "mu_B^2/meV"
                )
            config["source_unit"] = prefix + suffix
        if key == "normalization_label" and config["source_unit"] != "arbitrary":
            suffix = f"/{str(value).strip()}" if str(value).strip() else "/magnetic ion"
            for prefix in (
                "mbarn/sr/meV",
                "barn/sr/meV",
                "mu_B^2/meV",
                "spin^2/meV",
                "1/meV",
            ):
                if str(config["source_unit"]).startswith(prefix):
                    config["source_unit"] = prefix + suffix
                    break
        if config.get(key) == value:
            return
        config[key] = value
        dataset.parameters[SPECTRAL_CHANNEL_CONFIG_KEY] = (
            normalized_spectral_channel_config(config)
        )
        if group is not None:
            self._record_data_group_state_change(group)
            self.refresh_slice_viewer(group)
        self._mark_dirty()
        self._set_dataset_details_preserving_scroll(dataset, group)

    def _dataset_spectral_channels_group_box(
        self,
        dataset: DatasetEntry,
        group: DataGroup | None,
    ) -> Any:
        """Build INS representation, unit, and correction controls."""

        from PySide6 import QtWidgets

        config = self._dataset_spectral_channel_config(dataset)
        box = QtWidgets.QGroupBox("INS representations")
        form = QtWidgets.QFormLayout(box)
        form.setContentsMargins(10, 8, 10, 8)
        form.setFieldGrowthPolicy(
            QtWidgets.QFormLayout.FieldGrowthPolicy.AllNonFixedFieldsGrow
        )

