    def _build_tight_binding_orbital_editor(
        self, model: ModelComponentSpec
    ) -> None:
        """Build editable site-attached orbital manifolds."""

        from PySide6 import QtWidgets

        from .electronic_builder import (
            ORBITAL_PRESETS,
            OrbitalManifold,
            site_point_group_symbol,
            site_symmetry_harmonic_submanifolds,
        )

        group = QtWidgets.QGroupBox("Orbitals")
        group.setObjectName("tight_binding_orbitals_group")
        layout = QtWidgets.QGridLayout(group)
        tooltip = (
            "Attach an ordered orbital manifold to a crystallographic site. "
            "Analytic spherical harmonics transform in the displayed local "
            "frame. Custom bases remain usable but automatic symmetry is "
            "disabled unless representation matrices are supplied in a later stage."
        )
        site_combo = QtWidgets.QComboBox()
        site_combo.setObjectName("tight_binding_orbital_site")
        site_combo.setToolTip(tooltip)
        for site in model_crystal_config(model).get("sites", ()):
            label = str(site.get("label", ""))
            if label:
                site_combo.addItem(label, label)
        preset_combo = QtWidgets.QComboBox()
        preset_combo.setObjectName("tight_binding_orbital_preset")
        preset_combo.setToolTip(
            "Choose an effective scalar, a complete real spherical-harmonic "
            "s, p, d, or f shell, or a custom numerical basis."
        )
        for preset in ORBITAL_PRESETS:
            preset_combo.addItem(preset, preset)
        symmetry_label = QtWidgets.QLabel()
        symmetry_label.setObjectName("tight_binding_orbital_site_symmetry")
        symmetry_label.setToolTip(
            "The crystallographic point group formed by the space-group "
            "operations that leave the selected site fixed."
        )
        use_site_symmetry = QtWidgets.QCheckBox("Select a site-symmetry subspace")
        use_site_symmetry.setObjectName(
            "tight_binding_orbital_use_site_symmetry"
        )
        use_site_symmetry.setToolTip(
            "Split the complete harmonic shell using the selected site's "
            "actual point-group representation, then add one symmetry-closed "
            "subspace. This is available for s, p, d, and f shells."
        )
        submanifold_combo = QtWidgets.QComboBox()
        submanifold_combo.setObjectName(
            "tight_binding_orbital_submanifold"
        )
        submanifold_combo.setToolTip(
            "Choose a symmetry-closed subspace calculated from the site point "
            "group in the crystal Cartesian frame. The dimension and dominant "
            "complete-shell orbitals are shown for identification."
        )
        symmetry_cache: dict[tuple[str, str], tuple[Any, ...]] = {}

        def refresh_site_symmetry(*_args: Any) -> None:
            site_label = str(site_combo.currentData() or "")
            shell = str(preset_combo.currentData() or "")
            available = bool(site_label and shell in {"s", "p", "d", "f"})
            use_site_symmetry.setEnabled(available)
            if not available:
                use_site_symmetry.setChecked(False)
            submanifold_combo.clear()
            if not site_label:
                symmetry_label.setText("Site symmetry: select a site")
            else:
                try:
                    point_group = site_point_group_symbol(
                        model_crystal_config(model),
                        site_label,
                    )
                    symmetry_label.setText(
                        f"Site symmetry: {point_group}"
                    )
                    if available:
                        cache_key = (site_label, shell)
                        if cache_key not in symmetry_cache:
                            symmetry_cache[cache_key] = (
                                site_symmetry_harmonic_submanifolds(
                                    model_crystal_config(model),
                                    site_label,
                                    shell,
                                )
                            )
                        for option in symmetry_cache[cache_key]:
                            submanifold_combo.addItem(
                                option.label,
                                option.identifier,
                            )
                except (RuntimeError, ValueError) as exc:
                    symmetry_label.setText(f"Site symmetry unavailable: {exc}")
                    use_site_symmetry.setChecked(False)
                    use_site_symmetry.setEnabled(False)
            submanifold_combo.setEnabled(
                use_site_symmetry.isChecked()
                and submanifold_combo.count() > 0
            )

        site_combo.currentIndexChanged.connect(refresh_site_symmetry)
        preset_combo.currentIndexChanged.connect(refresh_site_symmetry)
        use_site_symmetry.toggled.connect(refresh_site_symmetry)
        add_button = QtWidgets.QPushButton("Add manifold")
        add_button.setObjectName("tight_binding_orbital_add")
        add_button.setToolTip(
            "Add the complete selected shell, or the selected point-group "
            "subspace when site-symmetry selection is enabled. The crystal "
            "Cartesian frame is the default local frame."
        )
        add_button.setEnabled(site_combo.count() > 0)
        add_button.clicked.connect(
            lambda _checked=False, sites=site_combo, presets=preset_combo,
            use_symmetry=use_site_symmetry,
            submanifolds=submanifold_combo: self._add_tight_binding_manifold(
                str(sites.currentData() or ""),
                str(presets.currentData() or "effective"),
                (
                    str(submanifolds.currentData() or "")
                    if use_symmetry.isChecked()
                    else None
                ),
            )
        )
        refresh_site_symmetry()
        layout.addWidget(QtWidgets.QLabel("Site"), 0, 0)
        layout.addWidget(site_combo, 0, 1)
        layout.addWidget(QtWidgets.QLabel("Shell or basis"), 0, 2)
        layout.addWidget(preset_combo, 0, 3)
        layout.addWidget(add_button, 0, 4)
        layout.addWidget(symmetry_label, 1, 0, 1, 2)
        layout.addWidget(use_site_symmetry, 1, 2, 1, 2)
        layout.addWidget(submanifold_combo, 1, 4, 1, 4)

        headers = (
            "Site",
            "Manifold",
            "Basis",
            "Orbitals",
            "Local frame",
            "Degeneracy groups",
            "Correlated shell",
            "",
        )
        for column, text in enumerate(headers):
            layout.addWidget(QtWidgets.QLabel(text), 2, column)
        manifolds = [
            OrbitalManifold.from_dict(item)
            for item in model.config.get("orbital_manifolds", ())
        ]
        for index, manifold in enumerate(manifolds):
            row = index + 3
            site = QtWidgets.QLabel(manifold.site_label)
            site.setToolTip(tooltip)
            layout.addWidget(site, row, 0)
            label = QtWidgets.QLineEdit(manifold.label)
            label.setObjectName(f"tight_binding_manifold_label_{index}")
            label.setToolTip(
                "Stable, unique manifold label used in basis-state names, "
                "projection groups, scripts, and later interaction definitions."
            )
            label.editingFinished.connect(
                lambda index=index, editor=label: self._set_tight_binding_manifold_field(
                    index, "label", editor.text()
                )
            )
            layout.addWidget(label, row, 1)
            basis = QtWidgets.QLabel(
                f"{manifold.preset} ({manifold.basis_kind})"
            )
            basis.setToolTip(
                "The shell or basis choice is a convenience, while basis_kind "
                "determines how symmetry acts. A site-symmetry entry is a "
                "calculated subspace of the named complete shell."
            )
            layout.addWidget(basis, row, 2)
            orbitals = QtWidgets.QLineEdit(
                _parameter_to_text(list(manifold.orbitals))
            )
            orbitals.setObjectName(f"tight_binding_manifold_orbitals_{index}")
            orbitals.setReadOnly(manifold.basis_kind != "custom")
            orbitals.setToolTip(
                "Ordered basis labels. Built-in harmonic labels are fixed by "
                "their transformation convention; custom labels are editable JSON."
            )
            orbitals.editingFinished.connect(
                lambda index=index, editor=orbitals: self._set_tight_binding_manifold_field(
                    index, "orbitals", editor.text()
                )
            )
            layout.addWidget(orbitals, row, 3)
            frame = QtWidgets.QLineEdit(
                _parameter_to_text(np.asarray(manifold.local_frame).tolist())
            )
            frame.setObjectName(f"tight_binding_manifold_frame_{index}")
            frame.setToolTip(
                "Right-handed orthonormal local axes as a 3x3 JSON matrix whose "
                "columns are local x, y, z in crystal Cartesian coordinates. "
                "Identity is the crystal frame."
            )
            frame.editingFinished.connect(
                lambda index=index, editor=frame: self._set_tight_binding_manifold_field(
                    index, "local_frame", editor.text()
                )
            )
            layout.addWidget(frame, row, 4)
            degeneracy = QtWidgets.QLineEdit(
                _parameter_to_text(
                    [list(group) for group in manifold.degeneracy_groups]
                )
            )
            degeneracy.setObjectName(
                f"tight_binding_manifold_degeneracy_{index}"
            )
            degeneracy.setToolTip(
                "Optional JSON groups constrained to share one diagonal onsite "
                "energy, for example [[\"d_yz\", \"d_zx\"]]. Groups must remain "
                "compatible with the selected symmetry representation."
            )
            degeneracy.editingFinished.connect(
                lambda index=index, editor=degeneracy: self._set_tight_binding_manifold_field(
                    index, "degeneracy_groups", editor.text()
                )
            )
            layout.addWidget(degeneracy, row, 5)
            shell = QtWidgets.QLineEdit(manifold.correlated_shell)
            shell.setObjectName(f"tight_binding_manifold_shell_{index}")
            shell.setToolTip(
                "Optional correlated-shell identifier that later Hubbard-Hund "
                "and other interaction dressings will use."
            )
            shell.editingFinished.connect(
                lambda index=index, editor=shell: self._set_tight_binding_manifold_field(
                    index, "correlated_shell", editor.text()
                )
            )
            layout.addWidget(shell, row, 6)
            remove = QtWidgets.QPushButton("Remove")
            remove.setObjectName(f"tight_binding_manifold_remove_{index}")
            remove.setToolTip(
                "Remove this manifold and regenerate the remaining onsite basis."
            )
            remove.clicked.connect(
                lambda _checked=False, label=manifold.label: self._remove_tight_binding_manifold(
                    label
                )
            )
            layout.addWidget(remove, row, 7)
        status_text = (
            f"{sum(item.dimension for item in manifolds)} orbital(s) in "
            f"{len(manifolds)} manifold(s)."
            if manifolds
            else "Add an orbital manifold to begin constructing the electronic basis."
        )
        status = QtWidgets.QLabel(status_text)
        status.setObjectName("tight_binding_orbital_status")
        status.setToolTip(tooltip)
        status.setWordWrap(True)
        layout.addWidget(status, len(manifolds) + 3, 0, 1, len(headers))
        self.model_parameter_layout.addWidget(group, 5, 0, 1, 4)

    def _build_tight_binding_spin_editor(
        self,
        model: ModelComponentSpec,
    ) -> None:
        """Build compact opt-in spin and onsite SOC controls."""

        from PySide6 import QtWidgets

        from .electronic_builder import OrbitalManifold
        from .electronic_spin import SPIN_TREATMENTS, SpinOrbitTerm
        from .electronic_structure import electronic_energy_from_meV

        group = QtWidgets.QGroupBox("Spin and SOC")
        group.setObjectName("tight_binding_spin_group")
        group.setToolTip(
            "Spin remains an implicit twofold degeneracy unless collinear or "
            "spinor structure is requested. Active SOC promotes Auto to the "
            "full spinor basis."
        )
        layout = QtWidgets.QGridLayout(group)
        treatment_label = QtWidgets.QLabel("Spin treatment")
        treatment = QtWidgets.QComboBox()
        treatment.setObjectName("tight_binding_spin_treatment")
        treatment.setToolTip(
            "Auto keeps an N-orbital SU(2)-symmetric model implicit and only "
            "creates 2N basis states when SOC requires spin mixing. Collinear "
            "and spinor explicitly force the corresponding representation."
        )
        treatment_labels = {
            "auto": "Auto (efficient)",
            "implicit": "Implicit spin degeneracy",
            "collinear": "Explicit collinear",
            "spinor": "Full spinor",
        }
        for option in SPIN_TREATMENTS:
            treatment.addItem(treatment_labels[option], option)
        selected = str(model.config.get("spin_treatment", "auto"))
        treatment.setCurrentIndex(max(0, treatment.findData(selected)))
        treatment.currentIndexChanged.connect(
            lambda _index, combo=treatment: self._set_tight_binding_spin_treatment(
                str(combo.currentData())
            )
        )
        resolved = ""
        model_data = model.config.get("model_data")
        if isinstance(model_data, dict):
            provenance = model_data.get("provenance", {})
            if isinstance(provenance, dict):
                resolved = str(
                    provenance.get("resolved_spin_treatment", "")
                )
        if bool(model.config.get("model_stale", False)):
            resolved_text = "pending lazy rebuild"
        else:
            resolved_text = resolved or "not built"
        resolved_label = QtWidgets.QLabel(f"Resolved: {resolved_text}")
        resolved_label.setObjectName("tight_binding_spin_resolved")
        resolved_label.setToolTip(
            "The actual representation used by the canonical model. Implicit "
            "uses N basis states; collinear and spinor use 2N."
        )
        layout.addWidget(treatment_label, 0, 0)
        layout.addWidget(treatment, 0, 1, 1, 2)
        layout.addWidget(resolved_label, 0, 3, 1, 3)

        headers = (
            "Manifold",
            "Spatial orbitals",
            "SOC",
            "Prescription",
            "λ",
            "Lower",
            "Upper",
            "Fit",
            "Sharing",
            "Groups",
        )
        for column, text in enumerate(headers):
            label = QtWidgets.QLabel(text)
            label.setToolTip(group.toolTip())
            layout.addWidget(label, 1, column)
        manifolds = [
            OrbitalManifold.from_dict(item)
            for item in model.config.get("orbital_manifolds", ())
        ]
        terms = {
            term.manifold_label: term
            for term in (
                SpinOrbitTerm.from_dict(item)
                for item in model.config.get("soc_terms", ())
            )
        }
        unit = str(model.config.get("electronic_energy_unit", "eV"))
        for index, manifold in enumerate(manifolds):
            row = index + 2
            term = terms.get(manifold.label)
            supported = (
                manifold.basis_kind
                in {"real_harmonic", "complex_harmonic"}
                and manifold.l is not None
                and manifold.l > 0
            ) or (term is not None and term.orbital_operators is not None)
            manifold_name = QtWidgets.QLabel(manifold.label)
            manifold_name.setToolTip(
                "SOC is attached once to this spatial manifold and repeated "
                "on every symmetry-equivalent site."
            )
            layout.addWidget(manifold_name, row, 0)
            orbitals = QtWidgets.QLabel(
                f"{manifold.dimension}: {', '.join(manifold.orbitals)}"
            )
            orbitals.setToolTip(
                "Spatial orbitals before optional spinor expansion. The 3D "
                "geometry viewer does not duplicate these tokens for spin."
            )
            layout.addWidget(orbitals, row, 1)
            enabled = QtWidgets.QCheckBox()
            enabled.setObjectName(f"tight_binding_soc_enabled_{index}")
            enabled.setChecked(term is not None)
            enabled.setEnabled(supported)
            enabled.setToolTip(
                "Enable λ L·S for this manifold. Complete harmonic shells use "
                "atomic L; symmetry-selected subspaces use projected P L P. "
                "Custom bases require explicit operators through the API."
            )
            enabled.toggled.connect(
                lambda checked, label=manifold.label: self._toggle_tight_binding_soc(
                    label,
                    bool(checked),
                )
            )
            layout.addWidget(enabled, row, 2)
            prescription = QtWidgets.QComboBox()
            prescription.setObjectName(
                f"tight_binding_soc_prescription_{index}"
            )
            prescription.addItem("Auto", "auto")
            prescription.addItem("Atomic shell", "atomic")
            prescription.addItem("Projected subspace", "projected")
            prescription.addItem("Effective operators", "effective")
            prescription.setCurrentIndex(
                max(
                    0,
                    prescription.findData(
                        "auto" if term is None else term.prescription
                    ),
                )
            )
            prescription.setEnabled(term is not None)
            prescription.setToolTip(
                "Atomic requires a complete l shell. Projected uses P(L·S)P "
                "and may omit virtual coupling to excluded orbitals. Effective "
                "requires explicitly supplied Lx, Ly, and Lz matrices."
            )
            prescription.currentIndexChanged.connect(
                lambda _index, label=manifold.label,
                combo=prescription: self._set_tight_binding_soc_field(
                    label,
                    "prescription",
                    str(combo.currentData()),
                )
            )
            layout.addWidget(prescription, row, 3)
            value = QtWidgets.QLineEdit(
                ""
                if term is None
                else _parameter_to_text(
                    electronic_energy_from_meV(term.value_meV, unit)
                )
            )
            value.setObjectName(f"tight_binding_soc_value_{index}")
            value.setEnabled(term is not None)
            value.setToolTip(
                f"Spin-orbit coupling λ in {unit}; converted immediately to "
                "canonical meV."
            )
            value.editingFinished.connect(
                lambda label=manifold.label, editor=value: self._set_tight_binding_soc_field(
                    label,
                    "value",
                    editor.text(),
                )
            )
            layout.addWidget(value, row, 4)
            for column, (field, bound) in enumerate(
                zip(
                    ("lower", "upper"),
                    (None, None) if term is None else term.bounds_meV,
                    strict=True,
                ),
                start=5,
            ):
                editor = QtWidgets.QLineEdit(
                    ""
                    if bound is None
                    else _parameter_to_text(
                        electronic_energy_from_meV(bound, unit)
                    )
                )
                editor.setObjectName(f"tight_binding_soc_{field}_{index}")
                editor.setEnabled(term is not None)
                editor.setToolTip(
                    f"Optional fit bound for λ in {unit}; empty is unbounded."
                )
                editor.editingFinished.connect(
                    lambda label=manifold.label, field=field,
                    editor=editor: self._set_tight_binding_soc_field(
                        label,
                        field,
                        editor.text(),
                    )
                )
                layout.addWidget(editor, row, column)
            fit = QtWidgets.QCheckBox()
            fit.setObjectName(f"tight_binding_soc_fit_{index}")
            fit.setChecked(False if term is None else term.fit)
            fit.setEnabled(term is not None)
            fit.setToolTip(
                "Allow a compatible future electronic-response fit to vary λ."
            )
            fit.toggled.connect(
                lambda checked, label=manifold.label: self._set_tight_binding_soc_fit(
                    label,
                    bool(checked),
                )
            )
            layout.addWidget(fit, row, 7)
            if term is None:
                sharing = QtWidgets.QLabel("—")
                groups = QtWidgets.QLabel("")
            else:
                sharing, groups = self._tight_binding_sharing_controls(
                    model,
                    term.identifier,
                    object_prefix=f"tight_binding_soc_{index}",
                )
            layout.addWidget(sharing, row, 8)
            layout.addWidget(groups, row, 9)
        status = QtWidgets.QLabel(
            "Implicit spin avoids redundant diagonalization. SOC, transverse "
            "spin mixing, and noncollinear extensions use the full spinor basis."
        )
        status.setObjectName("tight_binding_spin_status")
        status.setWordWrap(True)
        status.setToolTip(group.toolTip())
        layout.addWidget(status, len(manifolds) + 2, 0, 1, len(headers))
        self.model_parameter_layout.addWidget(group, 6, 0, 1, 4)

    def _tight_binding_sharing_controls(
        self,
        model: ModelComponentSpec,
        identifier: str,
        *,
        object_prefix: str,
    ) -> tuple[Any, Any]:
        """Build common sharing controls for one orbital-aware parameter row."""

        from PySide6 import QtWidgets

        sharing = QtWidgets.QComboBox()
        sharing.setObjectName(f"{object_prefix}_sharing")
        sharing.addItem("Global", "global")
        sharing.addItem("Per dataset", "per_dataset")
        sharing.addItem("Grouped", "grouped")
        mode = sharing_mode(model, identifier)
        sharing.setCurrentIndex(max(sharing.findData(mode), 0))
        sharing.setToolTip(
            "Choose whether a compatible response fit uses one coefficient for "
            "all datasets, one per dataset, or values tied by named groups."
        )
        groups = QtWidgets.QLineEdit(_sharing_groups_text(model, identifier))
        groups.setObjectName(f"{object_prefix}_sharing_groups")
        groups.setPlaceholderText("scan1=A, scan2=A")
        groups.setVisible(mode == "grouped")
        groups.setToolTip(
            "For grouped sharing, enter comma-separated dataset=group pairs. "
            "Unlisted datasets remain independent."
        )
        sharing.currentIndexChanged.connect(
            lambda _index, identifier=identifier, combo=sharing: self._set_model_sharing_mode(
                identifier,
                str(combo.currentData()),
            )
        )
        groups.editingFinished.connect(
            lambda identifier=identifier, editor=groups: self._set_model_sharing_groups(
                identifier,
                editor.text(),
            )
        )
        return sharing, groups

    def _build_tight_binding_onsite_editor(
        self, model: ModelComponentSpec
    ) -> None:
        """Build generated onsite-energy and onsite-hybridization controls."""

        from PySide6 import QtWidgets

        from .electronic_builder import OnsiteInvariant
        from .electronic_structure import electronic_energy_from_meV

        group = QtWidgets.QGroupBox("Onsite terms")
        group.setObjectName("tight_binding_onsite_group")
        layout = QtWidgets.QGridLayout(group)
        unit = str(model.config.get("electronic_energy_unit", "eV"))
        terms = [
            OnsiteInvariant.from_dict(item)
            for item in model.config.get("onsite_terms", ())
        ]
        headers = (
            "Term",
            "Site",
            "Kind",
            f"Value ({unit})",
            f"Lower ({unit})",
            f"Upper ({unit})",
            "Fit",
            "Sharing",
            "Groups",
            "Matrix basis",
        )
        for column, text in enumerate(headers):
            header = QtWidgets.QLabel(text)
            layout.addWidget(header, 0, column)
        for index, term in enumerate(terms):
            row = index + 1
            layout.addWidget(QtWidgets.QLabel(term.label), row, 0)
            layout.addWidget(QtWidgets.QLabel(term.site_label), row, 1)
            layout.addWidget(QtWidgets.QLabel(term.kind), row, 2)
            value = QtWidgets.QLineEdit(
                _parameter_to_text(
                    electronic_energy_from_meV(term.value_meV, unit)
                )
            )
            value.setObjectName(f"tight_binding_onsite_value_{index}")
            value.setToolTip(
                f"Static one-electron onsite coefficient in {unit}. It is "
                "converted immediately to canonical meV. This is distinct from "
                "a future dynamical many-body self-energy Sigma(k,E)."
            )
            value.editingFinished.connect(
                lambda identifier=term.identifier, editor=value: self._set_tight_binding_onsite_field(
                    identifier, "value", editor.text()
                )
            )
            layout.addWidget(value, row, 3)
            for column, (field, bound) in enumerate(
                zip(("lower", "upper"), term.bounds_meV, strict=True), start=4
            ):
                editor = QtWidgets.QLineEdit(
                    ""
                    if bound is None
                    else _parameter_to_text(
                        electronic_energy_from_meV(bound, unit)
                    )
                )
                editor.setObjectName(
                    f"tight_binding_onsite_{field}_{index}"
                )
                editor.setToolTip(
                    f"Optional fit bound in {unit}. Empty means unbounded. "
                    "The value is stored in the component's common bounds state."
                )
                editor.editingFinished.connect(
                    lambda identifier=term.identifier, field=field, editor=editor: self._set_tight_binding_onsite_field(
                        identifier, field, editor.text()
                    )
                )
                layout.addWidget(editor, row, column)
            fit = QtWidgets.QCheckBox()
            fit.setObjectName(f"tight_binding_onsite_fit_{index}")
            fit.setChecked(term.fit)
            fit.setToolTip(
                "Vary this coefficient when a compatible electronic-response "
                "component supplies a dataset observable. Tight binding alone "
                "remains calculation-only."
            )
            fit.toggled.connect(
                lambda checked, identifier=term.identifier: self._set_tight_binding_onsite_fit(
                    identifier, checked
                )
            )
            layout.addWidget(fit, row, 6)
            sharing, groups = self._tight_binding_sharing_controls(
                model,
                term.identifier,
                object_prefix=f"tight_binding_onsite_{index}",
            )
            layout.addWidget(sharing, row, 7)
            layout.addWidget(groups, row, 8)
            matrix = QtWidgets.QLabel(
                f"{len(term.basis_labels)}x{len(term.basis_labels)}; {term.source}"
            )
            matrix.setToolTip(
                "Unit-Frobenius Hermitian matrix multiplying this coefficient. "
                f"Ordered local basis: {', '.join(term.basis_labels)}\n"
                f"Matrix:\n{np.array2string(term.matrix, precision=4)}"
            )
            layout.addWidget(matrix, row, 9)
        status_text = (
            f"{len(terms)} onsite invariant(s)."
            if terms
            else "No onsite invariants. Add orbitals, then regenerate."
        )
        status = QtWidgets.QLabel(status_text)
        status.setObjectName("tight_binding_onsite_status")
        status.setToolTip(
            "Onsite energies and symmetry-allowed onsite hybridizations form "
            "the static R=0 Hamiltonian."
        )
        status.setWordWrap(True)
        layout.addWidget(status, len(terms) + 1, 0, 1, len(headers))
        self.model_parameter_layout.addWidget(group, 7, 0, 1, 4)

    def _build_tight_binding_hopping_editor(
        self, model: ModelComponentSpec
    ) -> None:
        """Build generated hopping suggestions and active-term controls."""

        from PySide6 import QtCore, QtWidgets

        from .electronic_builder import (
            HoppingInvariant,
            hopping_endpoint_orbitals,
        )
        from .electronic_structure import electronic_energy_from_meV

        group = QtWidgets.QGroupBox("Hoppings")
        group.setObjectName("tight_binding_hopping_group")
        layout = QtWidgets.QGridLayout(group)
        parameterization_label = QtWidgets.QLabel("Parameterization")
        parameterization = QtWidgets.QComboBox()
        parameterization.setObjectName(
            "tight_binding_hopping_parameterization"
        )
        parameterization.addItem(
            "Slater–Koster integrals",
            "slater_koster",
        )
        parameterization.addItem(
            "General symmetry matrices",
            "general",
        )
        parameterization.setCurrentIndex(
            max(
                0,
                parameterization.findData(
                    str(
                        model.config.get(
                            "hopping_parameterization",
                            "slater_koster",
                        )
                    )
                ),
            )
        )
        parameterization_tooltip = (
            "Slater–Koster generates compact V_ll′σ, V_ll′π, V_ll′δ, and "
            "V_ll′φ coefficients for real-harmonic s, p, d, and f manifolds, "
            "including selected crystal-field subspaces and their local "
            "frames. General symmetry matrices span every real spinless "
            "hopping allowed by the bond stabilizer and support arbitrary "
            "declared bases. Changing convention regenerates suggestions; "
            "terms without the same stable identifier become inactive."
        )
        parameterization_label.setToolTip(parameterization_tooltip)
        parameterization.setToolTip(parameterization_tooltip)
        parameterization.currentIndexChanged.connect(
            lambda _index, combo=parameterization: self._set_tight_binding_hopping_parameterization(
                str(combo.currentData())
            )
        )
        layout.addWidget(parameterization_label, 0, 0)
        layout.addWidget(parameterization, 0, 1, 1, 3)
        cutoff_label = QtWidgets.QLabel("Cutoff (Å)")
        cutoff = QtWidgets.QLineEdit(
            _parameter_to_text(
                float(model.config.get("hopping_cutoff_angstrom", 0.0))
                or 5.0
            )
        )
        cutoff.setObjectName("tight_binding_hopping_cutoff")
        cutoff_tooltip = (
            "Maximum real-space distance used to generate symmetry-distinct "
            "bonds between every orbital-bearing site."
        )
        cutoff_label.setToolTip(cutoff_tooltip)
        cutoff.setToolTip(cutoff_tooltip)
        generate = QtWidgets.QPushButton("Generate suggestions")
        generate.setObjectName("tight_binding_hopping_generate")
        generate.setToolTip(
            "Generate spatial bond orbits and hopping candidates in the "
            "selected parameterization. Candidates do not enter the "
            "Hamiltonian until selected below."
        )
        generate.setEnabled(bool(model.config.get("orbital_manifolds")))
        generate.clicked.connect(
            lambda _checked=False, editor=cutoff: self._regenerate_tight_binding_hoppings(
                editor.text()
            )
        )
        layout.addWidget(cutoff_label, 1, 0)
        layout.addWidget(cutoff, 1, 1)
        layout.addWidget(generate, 1, 2, 1, 2)

        multiplicities = {
            str(item.get("label", "")): len(item.get("bonds", ()))
            for item in model.config.get("spatial_orbits", ())
        }
        sites = list(model.config.get("expanded_crystal_sites", ()))

        def endpoint_text(
            term: HoppingInvariant,
        ) -> tuple[str, str]:
            from_orbitals, to_orbitals = hopping_endpoint_orbitals(term)
            bond = term.representative_bond
            from_site = (
                str(sites[bond.site_j].get("label", f"site {bond.site_j}"))
                if bond.site_j < len(sites)
                else f"site {bond.site_j}"
            )
            to_site = (
                str(sites[bond.site_i].get("label", f"site {bond.site_i}"))
                if bond.site_i < len(sites)
                else f"site {bond.site_i}"
            )
            offset = tuple(int(value) for value in bond.offset)
            return (
                f"{from_site} + {offset}: {', '.join(from_orbitals)}",
                f"{to_site}: {', '.join(to_orbitals)}",
            )

        active = [
            HoppingInvariant.from_dict(item)
            for item in model.config.get("hopping_terms", ())
        ]
        active_ids = {item.identifier for item in active}
        candidates = [
            HoppingInvariant.from_dict(item)
            for item in model.config.get("hopping_candidates", ())
            if str(item.get("identifier", "")) not in active_ids
        ]
        suggestion_headers = (
            "Term",
            "Orbit",
            "Distance (Å)",
            "Multiplicity",
            "From orbital(s)",
            "To orbital(s)",
            "Matrix basis",
        )
        suggestion_table = QtWidgets.QTableWidget(
            len(candidates),
            len(suggestion_headers),
        )
        suggestion_table.setObjectName("tight_binding_hopping_suggestions")
        suggestion_table.setToolTip(
            "Symmetry-allowed candidates. T_ij(R) maps the listed source "
            "orbital(s) in cell R to the listed destination orbital(s) in the "
            "home cell. Select rows and add only the terms required by the model."
        )
        suggestion_table.setHorizontalHeaderLabels(suggestion_headers)
        suggestion_table.setSelectionBehavior(
            QtWidgets.QAbstractItemView.SelectionBehavior.SelectRows
        )
        suggestion_table.setSelectionMode(
            QtWidgets.QAbstractItemView.SelectionMode.ExtendedSelection
        )
        suggestion_table.setEditTriggers(
            QtWidgets.QAbstractItemView.EditTrigger.NoEditTriggers
        )
        for row, term in enumerate(candidates):
            from_text, to_text = endpoint_text(term)
            values = (
                term.label,
                term.orbit_label,
                f"{term.distance_angstrom:.5g}",
                str(multiplicities.get(term.orbit_label, 0)),
                from_text,
                to_text,
                f"{len(term.basis_i)}x{len(term.basis_j)}",
            )
            for column, text in enumerate(values):
                item = QtWidgets.QTableWidgetItem(text)
                item.setData(
                    QtCore.Qt.ItemDataRole.UserRole,
                    term.identifier,
                )
                if column == 6:
                    item.setToolTip(
                        "Unit-Frobenius representative matrix:\n"
                        f"{np.array2string(term.matrix, precision=4)}"
                    )
                suggestion_table.setItem(row, column, item)
        suggestion_table.resizeColumnsToContents()
        suggestion_table.resizeRowsToContents()
        visible_rows = min(max(len(candidates), 3), 9)
        row_height = max(
            suggestion_table.verticalHeader().defaultSectionSize(),
            24,
        )
        table_height = (
            suggestion_table.horizontalHeader().height()
            + visible_rows * row_height
            + 2 * suggestion_table.frameWidth()
            + 8
        )
        suggestion_table.setMinimumHeight(table_height)
        suggestion_table.setMaximumHeight(table_height)
        layout.addWidget(suggestion_table, 2, 0, 1, 10)
        add_selected = QtWidgets.QPushButton("Add selected hopping terms")
        add_selected.setObjectName("tight_binding_hopping_add_selected")
        add_selected.setToolTip(
            "Add the selected generated matrix terms to the active "
            "tight-binding Hamiltonian."
        )
        add_selected.setEnabled(bool(candidates))
        add_selected.clicked.connect(
            lambda _checked=False, table=suggestion_table: self._add_selected_tight_binding_hoppings(
                table
            )
        )
        layout.addWidget(add_selected, 3, 0, 1, 3)

        unit = str(model.config.get("electronic_energy_unit", "eV"))
        active_headers = (
            "Active term",
            "From orbital(s)",
            "To orbital(s)",
            "Distance (Å)",
            f"Value ({unit})",
            f"Lower ({unit})",
            f"Upper ({unit})",
            "Fit",
            "Sharing",
            "Groups",
            "Matrix basis",
            "",
        )
        for column, text in enumerate(active_headers):
            header = QtWidgets.QLabel(text)
            layout.addWidget(header, 4, column)
        for index, term in enumerate(active):
            row = index + 5
            from_text, to_text = endpoint_text(term)
            for column, text in enumerate(
                (term.label, from_text, to_text)
            ):
                label = QtWidgets.QLabel(text)
                label.setToolTip(text)
                label.setWordWrap(True)
                label.setMaximumWidth(280)
                layout.addWidget(label, row, column)
            layout.addWidget(
                QtWidgets.QLabel(f"{term.distance_angstrom:.5g}"),
                row,
                3,
            )
            value = QtWidgets.QLineEdit(
                _parameter_to_text(
                    electronic_energy_from_meV(term.value_meV, unit)
                )
            )
            value.setObjectName(f"tight_binding_hopping_value_{index}")
            value.setToolTip(
                f"Coefficient of this unit-Frobenius representative hopping "
                f"matrix in {unit}; converted immediately to canonical meV."
            )
            value.editingFinished.connect(
                lambda identifier=term.identifier, editor=value: self._set_tight_binding_hopping_field(
                    identifier,
                    "value",
                    editor.text(),
                )
            )
            layout.addWidget(value, row, 4)
            for column, (field, bound) in enumerate(
                zip(("lower", "upper"), term.bounds_meV, strict=True),
                start=5,
            ):
                editor = QtWidgets.QLineEdit(
                    ""
                    if bound is None
                    else _parameter_to_text(
                        electronic_energy_from_meV(bound, unit)
                    )
                )
                editor.setObjectName(
                    f"tight_binding_hopping_{field}_{index}"
                )
                editor.setToolTip(
                    f"Optional fit bound in {unit}; empty is unbounded. The "
                    "canonical bound is shared with the fitting machinery."
                )
                editor.editingFinished.connect(
                    lambda identifier=term.identifier, field=field,
                    editor=editor: self._set_tight_binding_hopping_field(
                        identifier,
                        field,
                        editor.text(),
                    )
                )
                layout.addWidget(editor, row, column)
            fit = QtWidgets.QCheckBox()
            fit.setObjectName(f"tight_binding_hopping_fit_{index}")
            fit.setChecked(term.fit)
            fit.setToolTip(
                "Vary this coefficient when a compatible electronic-response "
                "component supplies a dataset observable. Tight binding alone "
                "remains calculation-only."
            )
            fit.toggled.connect(
                lambda checked, identifier=term.identifier: self._set_tight_binding_hopping_fit(
                    identifier,
                    checked,
                )
            )
            layout.addWidget(fit, row, 7)
            sharing, groups = self._tight_binding_sharing_controls(
                model,
                term.identifier,
                object_prefix=f"tight_binding_hopping_{index}",
            )
            layout.addWidget(sharing, row, 8)
            layout.addWidget(groups, row, 9)
            matrix = QtWidgets.QLabel(
                f"{len(term.basis_i)}x{len(term.basis_j)}"
            )
            matrix.setToolTip(
                "Representative unit-Frobenius hopping matrix. Every "
                "symmetry-equivalent pathway is generated by orbital "
                "covariance, including Hermitian reversal.\n"
                f"Rows: {', '.join(term.basis_i)}\n"
                f"Columns: {', '.join(term.basis_j)}\n"
                f"Matrix:\n{np.array2string(term.matrix, precision=4)}"
            )
            layout.addWidget(matrix, row, 10)
            remove = QtWidgets.QPushButton("Remove")
            remove.setObjectName(f"tight_binding_hopping_remove_{index}")
            remove.setToolTip(
                "Remove this term from the Hamiltonian while retaining it in "
                "the generated suggestion list."
            )
            remove.clicked.connect(
                lambda _checked=False, identifier=term.identifier: self._remove_tight_binding_hopping(
                    identifier
                )
            )
            layout.addWidget(remove, row, 11)
        status = QtWidgets.QLabel(
            f"{len(candidates)} available suggestion(s); "
            f"{len(active)} active hopping coefficient(s) on "
            f"{len(multiplicities)} spatial orbit(s)."
        )
        status.setObjectName("tight_binding_hopping_status")
        status.setWordWrap(True)
        layout.addWidget(
            status,
            len(active) + 5,
            0,
            1,
            len(active_headers),
        )

        self.model_parameter_layout.addWidget(group, 8, 0, 1, 4)

    def _import_wannier90_model(self, model: ModelComponentSpec) -> bool:
        from PySide6 import QtWidgets

        from .electronic_structure import import_wannier90

        path, _selected_filter = QtWidgets.QFileDialog.getOpenFileName(
            self.window,
            "Import Wannier90 Hamiltonian",
            "",
            "Wannier90 Hamiltonians (*_tb.dat *_hr.dat);;All files (*)",
        )
        if not path:
            return False
        try:
            raw_axes = model.config.get("periodic_axes", [])
            imported = import_wannier90(
                path,
                periodic_axes=(
                    None
                    if not raw_axes
                    else tuple(int(value) for value in raw_axes)
                ),
            )
        except Exception as exc:
            QtWidgets.QMessageBox.warning(
                self.window,
                "Import Wannier90 Hamiltonian",
                f"Could not import the electronic model:\n{exc}",
            )
            return False
        model.config["source_path"] = str(Path(path).resolve())
        model.config["model_digest"] = imported.content_digest
        model.config["model_data"] = {}
        model.config["periodic_axes"] = list(imported.periodic_axes)
        model.config["orbital_manifolds"] = []
        model.config["spin_treatment"] = "auto"
        model.config["soc_terms"] = []
        model.config["onsite_terms"] = []
        model.config["hopping_cutoff_angstrom"] = 0.0
        model.config["hopping_candidates"] = []
        model.config["hopping_terms"] = []
        model.config["spatial_orbits"] = []
        model.config["site_positions"] = []
        model.config["expanded_crystal_sites"] = []
        from .electronic_builder import reconcile_tight_binding_parameters

        reconcile_tight_binding_parameters(model)
        owner = self._group_for_model(model)
        if owner is not None:
            self._record_data_group_state_change(owner)
        self._mark_dirty()
        self._rebuild_model_parameter_editor(model)
        return True

    def _group_for_model(self, model: ModelComponentSpec) -> DataGroup | None:
        return next(
            (
                group
                for group in self.project.data_groups
                if any(candidate is model for candidate in group.models.values())
            ),
            None,
        )

    def _tight_binding_plot_settings(
        self,
        model: ModelComponentSpec,
        plot_key: str,
    ) -> dict[str, Any]:
        """Return viewer-owned settings in their displayed electronic unit."""

        from .electronic_structure import (
            electronic_energy_from_meV,
            normalize_electronic_energy_unit,
        )

        config = model.config
        unit = normalize_electronic_energy_unit(
            config.get("electronic_energy_unit", "eV")
        )
        common = {"electronic_energy_unit": unit}
        if plot_key == "bands":
            return {
                **common,
                "band_path_convention": config.get(
                    "band_path_convention",
                    "hinuma",
                ),
                "band_path": _parameter_to_text(
                    config.get("band_path", [])
                ),
                "band_points_per_inv_angstrom": _parameter_to_text(
                    config.get("band_points_per_inv_angstrom", 80.0)
                ),
            }
        if plot_key == "dos":
            return {
                **common,
                "dos_method": config.get("dos_method", "gaussian"),
                "dos_sampling_status": (
                    self._tight_binding_dos_sampling_status(model)
                ),
                "dos_symmetry": config.get("dos_symmetry", "auto"),
                "dos_auto_energy_range": bool(
                    config.get("dos_auto_energy_range", False)
                ),
                "dos_energy_min_meV": _parameter_to_text(
                    electronic_energy_from_meV(
                        config.get("dos_energy_min_meV", -500.0),
                        unit,
                    )
                ),
                "dos_energy_max_meV": _parameter_to_text(
                    electronic_energy_from_meV(
                        config.get("dos_energy_max_meV", 500.0),
                        unit,
                    )
                ),
                "dos_energy_points": _parameter_to_text(
                    config.get("dos_energy_points", 600)
                ),
                "dos_broadening_meV": _parameter_to_text(
                    electronic_energy_from_meV(
                        config.get("dos_broadening_meV", 5.0),
                        unit,
                    )
                ),
            }
        if plot_key == "fermi_surface":
            resolved_mesh = config.get("fermi_mesh", [64, 64, 64])
            if str(config.get("fermi_mesh_mode", "spacing")) == "spacing":
                try:
                    from .electronic_structure import (
                        electronic_model_from_component,
                        reciprocal_mesh_shape_for_spacing,
                    )

                    resolved_mesh = reciprocal_mesh_shape_for_spacing(
                        electronic_model_from_component(model),
                        float(
                            config.get(
                                "fermi_spacing_inv_angstrom",
                                0.025,
                            )
                        ),
                    )
                except (ImportError, TypeError, ValueError):
                    pass
            return {
                **common,
                "fermi_mesh_mode": config.get(
                    "fermi_mesh_mode", "spacing"
                ),
                "fermi_spacing_inv_angstrom": _parameter_to_text(
                    config.get("fermi_spacing_inv_angstrom", 0.025)
                ),
                "fermi_mesh": _parameter_to_text(
                    resolved_mesh
                ),
                "fermi_energy_meV": _parameter_to_text(
                    electronic_energy_from_meV(
                        config.get(
                            "fermi_energy_meV",
                            config.get("chemical_potential_meV", 0.0),
                        ),
                        unit,
                    )
                ),
            }
        return common

    def _apply_tight_binding_plot_settings(
        self,
        model: ModelComponentSpec,
        plot_key: str,
        values: Mapping[str, str],
    ) -> bool:
        """Validate and store one viewer's calculation settings."""

        from PySide6 import QtWidgets

        from .electronic_structure import (
            electronic_energy_to_meV,
            normalize_electronic_energy_unit,
        )
        from .model_plots import configure_tight_binding_plot

        previous = copy.deepcopy(model.config)
        unit = normalize_electronic_energy_unit(
            model.config.get("electronic_energy_unit", "eV")
        )
        try:
            if plot_key == "bands":
                convention = str(
                    values.get("band_path_convention", "manual")
                )
                updates = {
                    "band_path_convention": convention,
                    "band_points_per_inv_angstrom": float(
                        _parse_parameter_text(
                            values["band_points_per_inv_angstrom"]
                        )
                    ),
                }
                if convention == "manual":
                    path = _parse_parameter_text(
                        values["band_path"]
                    )
                    if not isinstance(path, list) or len(path) < 2:
                        raise ValueError(
                            "manual band_path must contain at least two nodes"
                        )
                    updates["band_path"] = path
                configure_tight_binding_plot(
                    model,
                    plot_key,
                    **updates,
                )
            elif plot_key == "dos":
                method = str(values["dos_method"])
                automatic_energy_range = (
                    str(values.get("dos_auto_energy_range", "false"))
                    .strip()
                    .lower()
                    in {"1", "true", "yes", "on"}
                )
                symmetry = str(values["dos_symmetry"])
                energies: dict[str, float] = {}
                for name in (
                    "dos_energy_min_meV",
                    "dos_energy_max_meV",
                    "dos_broadening_meV",
                ):
                    energies[name] = float(
                        electronic_energy_to_meV(
                            float(_parse_parameter_text(values[name])),
                            unit,
                        )
                    )
                energy_points = int(
                    _parse_parameter_text(values["dos_energy_points"])
                )
                if energy_points < 2:
                    raise ValueError(
                        "dos_energy_points must be at least two"
                    )
                configure_tight_binding_plot(
                    model,
                    plot_key,
                    dos_method=method,
                    dos_symmetry=symmetry,
                    dos_auto_energy_range=automatic_energy_range,
                    dos_energy_points=energy_points,
                    **energies,
                )
            elif plot_key == "fermi_surface":
                mesh_mode = str(
                    values.get("fermi_mesh_mode", "spacing")
                )
                spacing = float(
                    _parse_parameter_text(
                        values.get(
                            "fermi_spacing_inv_angstrom",
                            "0.025",
                        )
                    )
                )
                mesh = _parse_parameter_text(
                    values["fermi_mesh"]
                )
                if (
                    not isinstance(mesh, (list, tuple))
                    or not mesh
                    or any(int(size) < 2 for size in mesh)
                ):
                    raise ValueError(
                        "fermi_mesh must contain integer sizes of at least two"
                    )
                if mesh_mode not in {"spacing", "size"}:
                    raise ValueError(
                        "fermi_mesh_mode must be spacing or size"
                    )
                if not np.isfinite(spacing) or spacing <= 0.0:
                    raise ValueError(
                        "Fermi-surface spacing must be positive and finite"
                    )
                energy = float(
                    electronic_energy_to_meV(
                        float(
                            _parse_parameter_text(
                                values["fermi_energy_meV"]
                            )
                        ),
                        unit,
                    )
                )
                configure_tight_binding_plot(
                    model,
                    plot_key,
                    fermi_mesh_mode=mesh_mode,
                    fermi_spacing_inv_angstrom=spacing,
                    fermi_mesh=mesh,
                    fermi_energy_meV=energy,
                )
            else:
                raise ValueError(
                    f"unsupported tight-binding plot settings {plot_key!r}"
                )
        except Exception as exc:
            model.config = previous
            QtWidgets.QMessageBox.warning(
                self.window,
                "Electronic plot settings",
                f"Could not apply the settings:\n{exc}",
            )
            return False

        if model.config == previous:
            return True
        group = self._group_for_model(model)
        branch_created = (
            self._record_data_group_state_change(group)
            if group is not None
            else False
        )
        self._mark_dirty()
        if group is not None:
            if branch_created:
                self._refresh_tree(select_group=group, select_model=model)
            self._request_overlay_refresh(group)
        return True

    def _lindhard_plot_settings(
        self,
        model: ModelComponentSpec,
        plot_key: str,
    ) -> dict[str, Any]:
        """Return the scientific settings owned by one Lindhard viewer."""

        names = {
            "complex_energy_scan": (
                "plot_q_reduced",
                "plot_energy_min_meV",
                "plot_energy_max_meV",
                "plot_energy_points",
                "plot_temperature_K",
            ),
            "convergence": (
                "plot_q_reduced",
                "plot_energy_min_meV",
                "plot_energy_max_meV",
                "plot_temperature_K",
                "convergence_mesh_scales",
                "convergence_broadening_scales",
                "convergence_energy_points",
            ),
        }.get(plot_key, ())
        return {
            name: _parameter_to_text(model.config.get(name, ""))
            for name in names
        }

    def _apply_lindhard_plot_settings(
        self,
        model: ModelComponentSpec,
        plot_key: str,
        values: Mapping[str, str],
    ) -> bool:
        """Validate and store one Lindhard viewer's calculation settings."""

        from PySide6 import QtWidgets

        from .model_plots import configure_lindhard_plot

        previous = copy.deepcopy(model.config)
        try:
            updates = {
                name: _parse_parameter_text(text)
                for name, text in values.items()
            }
            q = updates.get("plot_q_reduced")
            if q is not None and (
                not isinstance(q, (list, tuple)) or len(q) != 3
            ):
                raise ValueError(
                    "plot_q_reduced must contain three reduced coordinates"
                )
            configure_lindhard_plot(model, plot_key, **updates)
        except Exception as exc:
            model.config = previous
            QtWidgets.QMessageBox.warning(
                self.window,
                "Lindhard plot settings",
                f"Could not apply the settings:\n{exc}",
            )
            return False

        if model.config == previous:
            return True
        group = self._group_for_model(model)
        branch_created = (
            self._record_data_group_state_change(group)
            if group is not None
            else False
        )
        self._mark_dirty()
        if group is not None:
            if branch_created:
                self._refresh_tree(select_group=group, select_model=model)
            self._request_overlay_refresh(group)
        return True

    def _open_model_plot(self, model: ModelComponentSpec, plot_key: str) -> bool:
        from PySide6 import QtWidgets

        from .qt_electronic_viewer import show_electronic_figure

        plot = next(
            (
                candidate
                for candidate in model_plot_definitions(model.type)
                if candidate.key == plot_key
            ),
            None,
        )
        if plot is None or plot.render is None:
            return False
        window_holder: dict[str, Any] = {}

        def calculate_result() -> Any:
            owner = self._group_for_model(model)
            components = {} if owner is None else owner.models
            return (
                plot.context_calculate(model, components)
                if plot.context_calculate is not None
                else plot.calculate(model)
            )

        def apply_settings(values: dict[str, str]) -> None:
            applied = (
                self._apply_tight_binding_plot_settings(
                    model,
                    plot_key,
                    values,
                )
                if model.type == "tight_binding"
                else self._apply_lindhard_plot_settings(
                    model,
                    plot_key,
                    values,
                )
                if model.type == "lindhard"
                else False
            )
            if not applied:
                return
            current = window_holder.get("window")
            if current is None:
                return
            try:
                updated_result = calculate_result()
                if plot_key == "fermi_surface" and updated_result.dimension == 3:
                    current._nfit_replace_result(updated_result)
                else:
                    updated_figure, _axes = plot.render(updated_result)
                    current._nfit_replace_figure(updated_figure)
                if hasattr(current, "_nfit_update_calculation_settings"):
                    current._nfit_update_calculation_settings(
                        self._tight_binding_plot_settings(model, plot_key)
                        if model.type == "tight_binding"
                        else self._lindhard_plot_settings(model, plot_key)
                    )
            except Exception as exc:
                QtWidgets.QMessageBox.warning(
                    self.window,
                    "Model plot",
                    f"Could not recalculate the plot:\n{exc}",
                )

        try:
            result = calculate_result()
            if plot_key == "fermi_surface" and result.dimension == 3:
                from .qt_fermi_surface_viewer import show_fermi_surface_result

                window = show_fermi_surface_result(
                    result,
                    parent=self.window,
                    settings_config=self._tight_binding_plot_settings(
                        model,
                        plot_key,
                    ),
                    on_apply_settings=apply_settings,
                )
            else:
                figure, _axes = plot.render(result)
                viewer_keys = {
                    "bands": "band_structure",
                    "dos": "density_of_states",
                    "fermi_surface": "fermi_surface",
                    "complex_energy_scan": "susceptibility",
                    "convergence": "response_convergence",
                }
                settings_config = (
                    self._tight_binding_plot_settings(model, plot_key)
                    if model.type == "tight_binding"
                    else self._lindhard_plot_settings(model, plot_key)
                    if model.type == "lindhard"
                    else None
                )
                window = show_electronic_figure(
                    figure,
                    viewer_key=viewer_keys.get(plot_key, "model_plot"),
                    parent=self.window,
                    settings_config=settings_config,
                    on_apply_settings=(
                        apply_settings
                        if model.type in {"tight_binding", "lindhard"}
                        else None
                    ),
                )
        except Exception as exc:
            QtWidgets.QMessageBox.warning(
                self.window,
                "Model plot",
                f"Could not calculate the plot:\n{exc}",
            )
            return False
        window_holder["window"] = window
        self._plot_windows[f"model:{id(model)}:{plot_key}"] = window
        return True

    def _copy_model_plot_script(
        self, model: ModelComponentSpec, plot_key: str
    ) -> bool:
        from PySide6 import QtWidgets

        plot = next(
            (
                candidate
                for candidate in model_plot_definitions(model.type)
                if candidate.key == plot_key
            ),
            None,
        )
        if plot is None or plot.script is None:
            return False
        try:
            owner = self._group_for_model(model)
            components = {} if owner is None else owner.models
            script = (
                plot.context_script(model, components)
                if plot.context_script is not None
                else plot.script(model)
            )
        except Exception as exc:
            QtWidgets.QMessageBox.warning(
                self.window,
                "Model plot script",
                f"Could not create the script:\n{exc}",
            )
            return False
        QtWidgets.QApplication.clipboard().setText(script)
        return True

    def _copy_tight_binding_structure_script(
        self, model: ModelComponentSpec
    ) -> bool:
        from PySide6 import QtWidgets

        from .electronic_structure import (
            electronic_model_from_component,
            tight_binding_structure_script,
        )

        owner = self._group_for_model(model)
        try:
            electronic_model_from_component(model)
            script = tight_binding_structure_script(
                model_crystal_config(model),
                model.config.get("periodic_axes") or [0, 1, 2],
                group_name=owner.name if owner is not None else "Electronic",
                model_name=model.name,
                electronic_energy_unit=model.config.get(
                    "electronic_energy_unit", "eV"
                ),
                use_primitive_cell=bool(
                    model.config.get("use_primitive_cell", True)
                ),
                hopping_parameterization=str(
                    model.config.get(
                        "hopping_parameterization",
                        "slater_koster",
                    )
                ),
                band_path_nodes=model.config.get("band_path", ()),
                band_path_convention=str(
                    model.config.get("band_path_convention", "hinuma")
                ),
                band_path_metadata=model.config.get(
                    "band_path_metadata",
                    {},
                ),
                orbital_manifolds=model.config.get("orbital_manifolds", ()),
                onsite_terms=model.config.get("onsite_terms", ()),
                hopping_cutoff_angstrom=(
                    float(model.config.get("hopping_cutoff_angstrom", 0.0))
                    or None
                ),
                hopping_terms=model.config.get("hopping_terms", ()),
                spin_treatment=str(
                    model.config.get("spin_treatment", "auto")
                ),
                soc_terms=model.config.get("soc_terms", ()),
                parameter_values_meV=model.parameters,
                fit_parameters=model.fit_parameters,
                parameter_limits_meV=model.limits,
                parameter_sharing=model.sharing,
                expected_model_digest=str(model.config.get("model_digest", "")),
            )
        except Exception as exc:
            QtWidgets.QMessageBox.warning(
                self.window,
                "Tight-binding structure script",
                f"Could not create the script:\n{exc}",
            )
            return False
        QtWidgets.QApplication.clipboard().setText(script)
        return True

    def _build_model_crystal_editor(
        self, model: ModelComponentSpec, *, structure_only: bool = False
    ) -> None:
        """Structured crystal editor with optional magnetic interactions.

        Tight binding uses the shared lattice and site sections without
        magnetic selection or exchange bonds. Heisenberg RPA continues into
        the bond, interaction, and closure sections.
        """

        from PySide6 import QtWidgets

        crystal = model_crystal_config(model)
        lattice = crystal["lattice"]

        crystal_group = QtWidgets.QGroupBox("Crystal")
        crystal_group.setObjectName("model_crystal_group")
        crystal_layout = QtWidgets.QGridLayout(crystal_group)
        lattice_tooltip = (
            "Unit-cell parameter used for orbital locations and electronic "
            "wavevectors. Lengths in Angstrom, angles in degrees."
            if structure_only
            else "Unit-cell parameter used to build exchange bonds and convert "
            "HKL to |Q|. Lengths in Angstrom, angles in degrees."
        )
        for column, name in enumerate(("a", "b", "c", "alpha", "beta", "gamma")):
            label = QtWidgets.QLabel(name)
            label.setToolTip(lattice_tooltip)
            editor = QtWidgets.QLineEdit(_parameter_to_text(lattice.get(name, "")))
            editor.setObjectName(f"model_crystal_{name}")
            editor.setToolTip(lattice_tooltip)
            editor.setMaximumWidth(70)
            editor.editingFinished.connect(
                lambda name=name, editor=editor: self._set_model_crystal_lattice(name, editor.text())
            )
            crystal_layout.addWidget(label, 0, 2 * column)
            crystal_layout.addWidget(editor, 0, 2 * column + 1)
        spacegroup_label = QtWidgets.QLabel("Space group")
        spacegroup_tooltip = (
            "Hermann-Mauguin space group symbol (e.g. 'F d -3 m:2'). It will "
            "expand orbital-bearing sites and constrain onsite and hopping "
            "terms in later builder stages."
            if structure_only
            else "Hermann-Mauguin space group symbol (e.g. 'F d -3 m:2'). "
            "Used to expand the magnetic sites and to group bonds into "
            "symmetry-distinct orbits sharing one exchange constant."
        )
        spacegroup_label.setToolTip(spacegroup_tooltip)
        spacegroup_editor = QtWidgets.QLineEdit(str(crystal.get("spacegroup", "P 1")))
        spacegroup_editor.setObjectName("model_crystal_spacegroup")
        spacegroup_editor.setToolTip(spacegroup_tooltip)
        spacegroup_editor.editingFinished.connect(
            lambda editor=spacegroup_editor: self._set_model_crystal_spacegroup(editor.text())
        )
        crystal_layout.addWidget(spacegroup_label, 1, 0, 1, 2)
        crystal_layout.addWidget(spacegroup_editor, 1, 2, 1, 4)
        import_button = QtWidgets.QPushButton("Import CIF...")
        import_button.setObjectName("model_crystal_import_cif")
        import_button.setToolTip(
            "Load lattice, space group, and atomic sites from a CIF file into "
            "this model and its data group."
            + (
                " Sets periodic axes to all three lattice directions."
                if structure_only
                else " Clears previously generated bond orbits."
            )
        )
        import_button.clicked.connect(self._import_cif_into_selected_model)
        crystal_layout.addWidget(import_button, 1, 6, 1, 2)
        from_group_button = QtWidgets.QPushButton("Use group crystal")
        from_group_button.setObjectName("model_crystal_from_group")
        from_group_button.setToolTip(
            "Copy the crystal (lattice, space group, sites) stored on this "
            "dataset group into the model configuration."
        )
        from_group_button.clicked.connect(self._use_group_crystal_for_selected_model)
        crystal_layout.addWidget(from_group_button, 1, 8, 1, 2)
        geometry_button = QtWidgets.QPushButton("View model in 3D")
        geometry_button.setObjectName("model_geometry_viewer")
        geometry_button.setToolTip(
            "Inspect the unit cell, active and ghost sites, local orbital "
            "frames, orbital tokens, and representative or symmetry-equivalent "
            "hopping/exchange pathways in the shared model-geometry viewer."
        )
        geometry_button.clicked.connect(self._open_selected_model_geometry)
        crystal_layout.addWidget(geometry_button, 2, 0, 1, 3)
        geometry_script = QtWidgets.QPushButton("Copy 3D viewer script")
        geometry_script.setObjectName("model_geometry_script")
        geometry_script.setToolTip(
            "Copy editable Python that reconstructs the renderer-independent "
            "model-geometry scene and opens the same viewer without project widgets."
        )
        geometry_script.clicked.connect(self._copy_selected_model_geometry_script)
        crystal_layout.addWidget(geometry_script, 2, 3, 1, 3)
        self.model_parameter_layout.addWidget(crystal_group, 3, 0, 1, 4)

        sites_group = QtWidgets.QGroupBox("Atomic Sites")
        sites_group.setObjectName("model_crystal_sites_group")
        sites_layout = QtWidgets.QGridLayout(sites_group)
        magnetic_labels = {str(name) for name in model.config.get("magnetic_sites", [])}
        headers = (
            ("Label", "x", "y", "z", "Element", "")
            if structure_only
            else ("Label", "x", "y", "z", "Ion", "", "")
        )
        for header_column, header in enumerate(headers):
            if header:
                sites_layout.addWidget(QtWidgets.QLabel(header), 0, header_column)
        site_tooltip = (
            "Crystallographic site label, chemical element, and fractional "
            "coordinates. These sites become candidate orbital locations."
            if structure_only
            else "Wyckoff site of the crystal: label, fractional coordinates, "
            "and the magnetic ion for the <j0> form factor. Check 'Magnetic' "
            "to include the site in exchange-bond generation."
        )
        for index, site in enumerate(crystal["sites"]):
            row = index + 1
            label_editor = QtWidgets.QLineEdit(str(site.get("label", "")))
            label_editor.setObjectName(f"model_crystal_site_label_{index}")
            label_editor.setToolTip(site_tooltip)
            label_editor.editingFinished.connect(
                lambda index=index, editor=label_editor: self._set_model_crystal_site(index, "label", editor.text())
            )
            sites_layout.addWidget(label_editor, row, 0)
            position = site.get("position", [0.0, 0.0, 0.0])
            for axis in range(3):
                editor = QtWidgets.QLineEdit(_parameter_to_text(position[axis]))
                editor.setObjectName(f"model_crystal_site_{index}_{'xyz'[axis]}")
                editor.setToolTip(site_tooltip)
                editor.setMaximumWidth(70)
                editor.editingFinished.connect(
                    lambda index=index, axis=axis, editor=editor: self._set_model_crystal_site(index, axis, editor.text())
                )
                sites_layout.addWidget(editor, row, 1 + axis)
            if structure_only:
                element_editor = QtWidgets.QLineEdit(str(site.get("element", "")))
                element_editor.setObjectName(
                    f"model_crystal_site_element_{index}"
                )
                element_editor.setToolTip(site_tooltip)
                element_editor.setMaximumWidth(70)
                element_editor.editingFinished.connect(
                    lambda index=index, editor=element_editor: self._set_model_crystal_site(
                        index, "element", editor.text()
                    )
                )
                sites_layout.addWidget(element_editor, row, 4)
            else:
                ion_combo = QtWidgets.QComboBox()
                ion_combo.setObjectName(f"model_crystal_site_ion_{index}")
                ion_combo.setToolTip(
                    "Magnetic ion of this site; sets the tabulated <j0> form "
                    "factor key. '(none)' leaves the site without a form factor."
                )
                ion_combo.addItem("(none)", "")
                for ion in available_ions():
                    ion_combo.addItem(ion, ion)
                ion_combo.setCurrentIndex(
                    max(ion_combo.findData(str(site.get("ion", "") or "")), 0)
                )
                ion_combo.currentIndexChanged.connect(
                    lambda _index, index=index, combo=ion_combo: self._set_model_crystal_site(
                        index, "ion", str(combo.currentData() or "")
                    )
                )
                sites_layout.addWidget(ion_combo, row, 4)
                magnetic_check = QtWidgets.QCheckBox("Magnetic")
                magnetic_check.setObjectName(
                    f"model_crystal_site_magnetic_{index}"
                )
                magnetic_check.setToolTip(
                    "Include this site in magnetic-site expansion and exchange-"
                    "bond generation."
                )
                magnetic_check.setChecked(
                    str(site.get("label", "")) in magnetic_labels
                )
                magnetic_check.toggled.connect(
                    lambda checked, index=index: self._set_model_site_magnetic(
                        index, checked
                    )
                )
                sites_layout.addWidget(magnetic_check, row, 5)
            remove_button = QtWidgets.QPushButton("Remove")
            remove_button.setObjectName(f"model_crystal_site_remove_{index}")
            remove_button.setToolTip("Remove this atomic site from the crystal.")
            remove_button.clicked.connect(
                lambda _checked=False, index=index: self._remove_model_crystal_site(index)
            )
            sites_layout.addWidget(remove_button, row, 5 if structure_only else 6)
        add_site_button = QtWidgets.QPushButton("Add site")
        add_site_button.setObjectName("model_crystal_site_add")
        add_site_button.setToolTip("Append a new atomic site to the crystal.")
        add_site_button.clicked.connect(self._add_model_crystal_site)
        sites_layout.addWidget(add_site_button, len(crystal["sites"]) + 1, 0)
        if structure_only:
            status = QtWidgets.QLabel(
                "The crystal supplies candidate orbital sites. Add manifolds "
                "below to construct the Stage 3.2 onsite Hamiltonian."
            )
            status.setObjectName("tight_binding_structure_status")
            status.setToolTip(
                "Crystal geometry, orbital manifolds, onsite invariants, and "
                "the resolved canonical model are shared by the GUI and scripts."
            )
            status.setWordWrap(True)
            sites_layout.addWidget(
                status, len(crystal["sites"]) + 2, 0, 1, len(headers)
            )
        self.model_parameter_layout.addWidget(sites_group, 4, 0, 1, 4)

        if structure_only:
            return

        bonds_group = QtWidgets.QGroupBox("Exchange Bonds")
        bonds_group.setObjectName("model_bonds_group")
        bonds_layout = QtWidgets.QGridLayout(bonds_group)
        cutoff_label = QtWidgets.QLabel("Bond cutoff (A)")
        cutoff_tooltip = (
            "Maximum bond length in Angstrom when enumerating exchange "
            "paths. Each symmetry-distinct orbit within the cutoff becomes "
            "one exchange fit parameter (J1, J2, J3a, ...)."
        )
        cutoff_label.setToolTip(cutoff_tooltip)
        cutoff_editor = QtWidgets.QLineEdit(
            _parameter_to_text(model.config.get("bond_cutoff_angstrom", DEFAULT_BOND_CUTOFF_ANGSTROM))
        )
        cutoff_editor.setObjectName("model_bonds_cutoff")
        cutoff_editor.setToolTip(cutoff_tooltip)
        cutoff_editor.setMaximumWidth(70)
        cutoff_editor.editingFinished.connect(
            lambda editor=cutoff_editor: self._set_model_config_setting("bond_cutoff_angstrom", editor.text())
        )
        bonds_layout.addWidget(cutoff_label, 0, 0)
        bonds_layout.addWidget(cutoff_editor, 0, 1)
        generate_button = QtWidgets.QPushButton("Generate symmetry orbits")
        generate_button.setObjectName("model_bonds_generate")
        generate_button.setToolTip(
            "Expand the magnetic sites through the space group, enumerate "
            "bonds up to the cutoff, and group them into symmetry-distinct "
            "orbits. Each orbit becomes one exchange parameter; values of "
            "orbits whose labels persist are kept."
        )
        generate_button.clicked.connect(self._generate_selected_model_bond_orbits)
        bonds_layout.addWidget(generate_button, 0, 2)
        orbits = model.config.get("orbits") or []
        table = QtWidgets.QTableWidget(len(orbits), 4)
        table.setObjectName("model_bonds_table")
        table.setToolTip(
            "Symmetry-distinct bond orbits of the current crystal. Each row "
            "is one exchange fit parameter; multiplicity counts the bonds "
            "sharing that constant."
        )
        table.setHorizontalHeaderLabels(["Orbit", "Distance (A)", "Multiplicity", "Example bond"])
        table.setEditTriggers(QtWidgets.QAbstractItemView.EditTrigger.NoEditTriggers)
        for row, orbit in enumerate(orbits):
            bonds = orbit.get("bonds", [])
            example = ""
            if bonds:
                bond = bonds[0]
                example = (
                    f"site {bond.get('site_i')} -> site {bond.get('site_j')} "
                    f"+ {tuple(bond.get('offset', (0, 0, 0)))}"
                )
            for column, text in enumerate(
                (
                    str(orbit.get("label", "")),
                    _format_number(float(orbit.get("distance_angstrom", 0.0))),
                    str(len(bonds)),
                    example,
                )
            ):
                table.setItem(row, column, QtWidgets.QTableWidgetItem(text))
        table.resizeColumnsToContents()
        table.resizeRowsToContents()
        visible_rows = min(max(len(orbits), 4), 10)
        row_height = max(table.verticalHeader().defaultSectionSize(), 24)
        table_height = (
            table.horizontalHeader().height()
            + row_height * visible_rows
            + 2 * table.frameWidth()
            + 8
        )
        table.setMinimumHeight(table_height)
        table.setMaximumHeight(table_height)
        bonds_layout.addWidget(table, 1, 0, 1, 3)
        self.model_parameter_layout.addWidget(bonds_group, 5, 0, 1, 4)

        self._build_model_interactions_editor(model)

    def _build_model_interactions_editor(self, model: ModelComponentSpec) -> None:
        """Anisotropy / SIA / dipole / Zeeman toggles for the heisenberg_rpa model."""

        from PySide6 import QtWidgets

        group = QtWidgets.QGroupBox("Interactions")
        group.setObjectName("model_interactions_group")
        layout = QtWidgets.QGridLayout(group)

        has_orbits = bool(model.config.get("orbits"))
        has_sites = bool(model.config.get("magnetic_sites"))

        anisotropy = model.config.get("anisotropy") or {}
        n_aniso = sum(len(entry.get("basis", ())) for entry in anisotropy.values())
        sia = model.config.get("sia") or {}
        n_sia = sum(len(entry.get("basis", ())) for entry in sia.values())

        def add_toggle(row, kind, text, tooltip, checked, enabled, summary):
            box = QtWidgets.QCheckBox(text)
            box.setObjectName(f"model_interaction_{kind}")
            box.setToolTip(tooltip)
            box.setChecked(bool(checked))
            box.setEnabled(bool(enabled))
            box.toggled.connect(
                lambda state, k=kind: self._set_model_interaction(k, state)
            )
            layout.addWidget(box, row, 0)
            label = QtWidgets.QLabel(summary)
            label.setObjectName(f"model_interaction_{kind}_summary")
            label.setToolTip(tooltip)
            label.setWordWrap(True)
            layout.addWidget(label, row, 1)

        add_toggle(
            0,
            "anisotropy",
            "Anisotropic exchange",
            "Project the symmetry-allowed rank-2 exchange tensors (symmetric "
            "off-diagonal + Dzyaloshinskii-Moriya) of every bond orbit and fit "
            "one coefficient per allowed component (J1_S1, J1_D1, ...). The "
            "isotropic part stays the existing Heisenberg parameter. Requires "
            "generated bond orbits.",
            bool(anisotropy),
            has_orbits,
            (
                f"{n_aniso} tensor parameter(s) across {len(anisotropy)} orbit(s)."
                if anisotropy
                else (
                    "Enable to snapshot allowed exchange tensors."
                    if has_orbits
                    else "Generate bond orbits first."
                )
            ),
        )
        add_toggle(
            1,
            "sia",
            "Single-ion anisotropy",
            "Add the symmetry-allowed single-ion anisotropy (rank-2, "
            "traceless) for each magnetic site class, rotated per site by its "
            "generating operation. Fits one K coefficient per allowed "
            "component. Requires magnetic sites.",
            bool(sia),
            has_sites,
            (
                f"{n_sia} anisotropy parameter(s) across {len(sia)} site class(es)."
                if sia
                else (
                    "Enable to snapshot allowed on-site tensors."
                    if has_sites
                    else "Define magnetic sites first."
                )
            ),
        )
        add_toggle(
            2,
            "dipole",
            "Dipole-dipole (Ewald)",
            "Include long-range magnetic dipole-dipole coupling via Ewald "
            "summation. Fits one strength D_dip that multiplies the cached "
            "dipole tensor; its default is the physical (mu0/4pi)(g mu_B)^2 "
            "value. Pin (vary off) to keep the physical strength.",
            bool((model.config.get("dipole") or {}).get("enabled")),
            True,
            "Physical strength seeds D_dip; long-range, cached per geometry.",
        )
        add_toggle(
            3,
            "zeeman",
            "Zeeman (applied field)",
            "Enable the applied-field (Larmor) term. Uses the per-dataset "
            "magnetic field from Conditions and fits g_factor plus "
            "transverse chi/gamma ratios. Datasets fitted with this on must "
            "have a field set.",
            bool((model.config.get("zeeman") or {}).get("enabled")),
            True,
            "Needs a per-dataset field (Dataset details -> Conditions).",
        )

        self.model_parameter_layout.addWidget(group, 6, 0, 1, 4)

        self._build_model_closure_editor(model)

    def _build_model_closure_editor(self, model: ModelComponentSpec) -> None:
        """Self-consistency closure controls for the heisenberg_rpa model."""

        from PySide6 import QtWidgets

        closure = model.config.get("closure") or {}
        mode = str(closure.get("mode", "none")).lower()

        group = QtWidgets.QGroupBox("Self-consistency closure")
        group.setObjectName("model_closure_group")
        layout = QtWidgets.QGridLayout(group)

        mode_tooltip = (
            "Sum-rule closure that makes the local response self-consistent "
            "instead of freely fitted (see the theory notes). 'None' keeps the "
            "bare RPA. 'Onsager' solves a reaction field so the fluctuation "
            "moment hits a target; 'SCR' (Moriya) renormalizes chi0 through the "
            "mode-coupling u; 'TAC' (Takahashi) conserves the total zero-point "
            "plus thermal amplitude. Closures add their own fit parameters and "
            "use finite-difference gradients."
        )
        mode_label = QtWidgets.QLabel("Closure")
        mode_label.setToolTip(mode_tooltip)
        layout.addWidget(mode_label, 0, 0)
        mode_combo = QtWidgets.QComboBox()
        mode_combo.setObjectName("model_closure_mode")
        mode_combo.setToolTip(mode_tooltip)
        for label, value in (
            ("None (bare RPA)", "none"),
            ("Onsager reaction field", "onsager"),
            ("Moriya SCR", "scr"),
            ("Takahashi TAC", "tac"),
        ):
            mode_combo.addItem(label, value)
        mode_combo.setCurrentIndex(max(mode_combo.findData(mode), 0))
        mode_combo.currentIndexChanged.connect(
            lambda _idx, combo=mode_combo: self._set_model_closure(
                {"mode": combo.currentData()}
            )
        )
        layout.addWidget(mode_combo, 0, 1)

        if mode == "none":
            self.model_parameter_layout.addWidget(group, 7, 0, 1, 4)
            return

        def add_numeric(row, key, label_text, tooltip, value):
            label = QtWidgets.QLabel(label_text)
            label.setToolTip(tooltip)
            layout.addWidget(label, row, 0)
            editor = QtWidgets.QLineEdit(_parameter_to_text(value))
            editor.setObjectName(f"model_closure_{key}")
            editor.setToolTip(tooltip)
            editor.setMaximumWidth(90)
            editor.editingFinished.connect(
                lambda ed=editor, k=key: self._set_model_closure(
                    {k: _parse_parameter_text(ed.text())}
                )
            )
            layout.addWidget(editor, row, 1)

        add_numeric(
            1,
            "energy_cutoff_mev",
            "Energy cutoff (meV)",
            "Upper energy limit Lambda of the moment integral. Physically the "
            "bandwidth or crystal-field scale; the relaxational amplitude grows "
            "logarithmically with it, so it must be set deliberately.",
            closure.get("energy_cutoff_mev", 100.0),
        )
        if mode in ("onsager", "tac"):
            moment_tooltip = (
                "Expose the conserved moment budget as a model parameter "
                "(m2_total for Onsager or total_amplitude for TAC). When "
                "enabled, use its Fit checkbox in Fit Parameters above to let "
                "the optimizer vary it, or leave Fit unchecked to hold that "
                "parameter fixed. When disabled, the closure uses Target value."
            )
            moment_label = QtWidgets.QLabel("Fit moment target")
            moment_label.setToolTip(moment_tooltip)
            layout.addWidget(moment_label, 3, 0)
            moment_check = QtWidgets.QCheckBox("Expose fit parameter")
            moment_check.setObjectName("model_closure_moment_mode")
            moment_check.setToolTip(moment_tooltip)
            moment_check.setChecked(
                str(closure.get("moment_mode", "fixed")) == "fitted"
            )
            moment_check.toggled.connect(
                lambda checked: self._set_model_closure(
                    {"moment_mode": "fitted" if checked else "fixed"}
                )
            )
            layout.addWidget(moment_check, 3, 1)
            if str(closure.get("moment_mode", "fixed")) == "fixed":
                add_numeric(
                    4,
                    "moment_target",
                    "Target value",
                    "The conserved per-site amplitude <m^2> (Onsager) or total "
                    "zero-point + thermal amplitude (TAC), in model units. For a "
                    "rigid local moment this is ~ S(S+1).",
                    closure.get("moment_target", 1.0),
                )
        self.model_parameter_layout.addWidget(group, 7, 0, 1, 4)

    def _build_heisenberg_advanced_editor(
        self,
        model: ModelComponentSpec,
    ) -> None:
        """Build convergence controls used only by self-consistent RPA."""

        from PySide6 import QtWidgets

        closure = model.config.get("closure") or {}
        mode = str(closure.get("mode", "none")).lower()
        group = QtWidgets.QGroupBox("Numerical convergence")
        group.setObjectName("heisenberg_numerical_group")
        layout = QtWidgets.QFormLayout(group)

        if mode == "none":
            status = QtWidgets.QLabel(
                "Bare RPA evaluates the requested data points directly and "
                "does not use a Brillouin-zone integration grid."
            )
            status.setObjectName("heisenberg_numerical_status")
            status.setWordWrap(True)
            status.setToolTip(
                "A full-zone grid is introduced only by Onsager, SCR, or TAC "
                "self-consistency."
            )
            layout.addRow(status)
        else:
            grid_tooltip = (
                "Brillouin-zone sampling for the self-consistency integral, "
                "using an N x N x N grid over the reduced cell. Increase N "
                "until fitted values are converged; cost grows as N cubed."
            )
            grid_label = QtWidgets.QLabel("Closure BZ grid (N per axis)")
            grid_label.setToolTip(grid_tooltip)
            grid = QtWidgets.QLineEdit(
                _parameter_to_text(closure.get("bz_grid", 16))
            )
            grid.setObjectName("model_closure_bz_grid")
            grid.setToolTip(grid_tooltip)
            grid.setMaximumWidth(90)
            grid.editingFinished.connect(
                lambda editor=grid: self._set_model_closure(
                    {"bz_grid": _parse_parameter_text(editor.text())}
                )
            )
            layout.addRow(grid_label, grid)

            if (model.config.get("zeeman") or {}).get("enabled"):
                omega_tooltip = (
                    "Energy-quadrature points for the field-on closure moment "
                    "integral. Increase this together with the BZ grid until "
                    "the self-consistent result is stable."
                )
                omega_label = QtWidgets.QLabel("Field energy points")
                omega_label.setToolTip(omega_tooltip)
                omega = QtWidgets.QLineEdit(
                    _parameter_to_text(closure.get("omega_points", 200))
                )
                omega.setObjectName("model_closure_omega_points")
                omega.setToolTip(omega_tooltip)
                omega.setMaximumWidth(90)
                omega.editingFinished.connect(
                    lambda editor=omega: self._set_model_closure(
                        {"omega_points": _parse_parameter_text(editor.text())}
                    )
                )
                layout.addRow(omega_label, omega)

        self.model_parameter_layout.addWidget(group, 8, 0, 1, 4)

    def _add_tight_binding_manifold(
        self,
        site_label: str,
        preset: str,
        submanifold_id: str | None = None,
    ) -> None:
        from .electronic_builder import (
            add_tight_binding_orbital_manifold,
            orbital_manifold_from_site_symmetry,
            orbital_manifold_preset,
        )

        def mutate(model: ModelComponentSpec, _group: DataGroup | None) -> None:
            if model.type != "tight_binding":
                raise ValueError("orbital manifolds require a tight-binding model")
            if not site_label:
                raise ValueError("select a crystallographic site first")
            base = (
                f"{site_label}_{preset}_subspace"
                if submanifold_id
                else f"{site_label}_{preset}"
            )
            existing = {
                str(item.get("label", ""))
                for item in model.config.get("orbital_manifolds", ())
            }
            label = base
            suffix = 2
            while label in existing:
                label = f"{base}_{suffix}"
                suffix += 1
            add_tight_binding_orbital_manifold(
                model,
                (
                    orbital_manifold_from_site_symmetry(
                        model_crystal_config(model),
                        site_label,
                        preset,
                        submanifold_id,
                        label=label,
                    )
                    if submanifold_id
                    else orbital_manifold_preset(
                        site_label,
                        preset,
                        label=label,
                    )
                ),
            )

        self._mutate_selected_model(mutate)

    def _set_tight_binding_manifold_field(
        self, index: int, field: str, text: str
    ) -> None:
        from .electronic_builder import (
            OrbitalManifold,
            set_tight_binding_orbital_manifolds,
        )

        def mutate(model: ModelComponentSpec, _group: DataGroup | None) -> None:
            payloads = copy.deepcopy(model.config.get("orbital_manifolds", ()))
            if not (0 <= int(index) < len(payloads)):
                raise _NoChange()
            payload = payloads[int(index)]
            if field in {"label", "correlated_shell"}:
                value: Any = text.strip()
            else:
                value = _parse_parameter_text(text)
                if field == "orbitals" and not isinstance(value, list):
                    raise ValueError("custom orbitals must be entered as a JSON list")
                if field == "local_frame" and (
                    not isinstance(value, list)
                    or len(value) != 3
                    or any(
                        not isinstance(row, list) or len(row) != 3
                        for row in value
                    )
                ):
                    raise ValueError("local_frame must be a 3x3 JSON matrix")
                if field == "degeneracy_groups" and not isinstance(value, list):
                    raise ValueError(
                        "degeneracy_groups must be a JSON list of orbital-label lists"
                    )
            if payload.get(field) == value:
                raise _NoChange()
            payload[field] = value
            set_tight_binding_orbital_manifolds(
                model, [OrbitalManifold.from_dict(item) for item in payloads]
            )

        self._mutate_selected_model_quietly(mutate)

    def _remove_tight_binding_manifold(self, label: str) -> None:
        from .electronic_builder import remove_tight_binding_orbital_manifold

        self._mutate_selected_model(
            lambda model, _group: remove_tight_binding_orbital_manifold(
                model, label
            )
        )

